window.TALKS=[{"id": "2026-10-18 - Nomon Tim Burnett - Addicted to Clinging", "title": "Addicted to Clinging", "speaker": "Nomon Tim Burnett", "date": "2026-10-18", "series": "", "summary": "In a mid practice period sesshin talk, Nomon Tim Burnett takes up the shuso Juriki's choice to teach the 12 steps as practice and recasts each step in the language of Soto Zen: the power of ignorance and conditioning, turning toward Buddha, Dharma and Sangha, the precepts as a moral inventory, confession and amends, meditation, and the bodhisattva vow. Both paths begin by seeing that the \"I\" who wants to fix things is the problem. The root addiction, Nomon suggests, is clinging to a separate self, which is harder to see than alcohol because we look out through it; Dogen's Genjokoan points to forgetting the self. The talk closes with faith as the ground of practice, reading Shantideva's Training Anthology and its long quotation on faith from the Precious Lamp Dharani Sutra.", "themes": ["Ethics", "No-self", "Sangha", "Suffering"], "texts": ["Shōbōgenzō"], "minutes": 41}, {"id": "2026-09-13 - Nomon Tim Burnett - Remembering Les Kaye", "title": "Remembering Les Kaye", "speaker": "Nomon Tim Burnett", "date": "2026-09-13", "series": "", "summary": "The talk highlights the importance of community and connection in Zen practice, drawing from personal experiences with Les Kaye, who introduced the speaker to Soto Zen at age 18. The speaker reflects on how this experience shaped their understanding of the value of community and connection in deepening one's practice. This is contrasted with Suzuki Roshi's approach to teaching, which emphasized direct experience and immersion over intellectual understanding, trusting that students would learn through action and observation rather than explanation.", "themes": ["Sangha"], "texts": [], "minutes": 40}, {"id": "2026-09-07 - Kanho Chris Burkhart - Two Darts and One Arrow", "title": "Two Darts and One Arrow", "speaker": "Kanho Chris Burkhart", "date": "2026-09-07", "series": "", "summary": "The speaker shares a personal experience from an earthquake where they witnessed a man beating his car in rage, which taught them about the futility of trying to change what has already happened. This experience highlights the importance of recognizing the difference between our initial pain and subsequent reactions, thoughts, and emotions. By taking responsibility for our actions and responding to reality with compassion, we can create positive change even when faced with challenges that feel unacceptable.", "themes": ["Acceptance", "Impermanence", "Suffering"], "texts": [], "minutes": 41}, {"id": "2026-09-06 - Nomon Tim Burnett - Poems of Emptiness", "title": "Poems of Emptiness", "speaker": "Nomon Tim Burnett", "date": "2026-09-06", "series": "", "summary": "The speaker's main teaching emphasizes the importance of humility and recognizing one's own limitations in the spiritual journey, cautioning against idealizing teachers or students. They draw inspiration from traditional Chinese koans, which suggest that there are no inherent teachers of Zen, only individuals who guide others on their path. By embracing this perspective, we can approach our practice with a sense of curiosity, openness, and peer-to-peer dialogue, recognizing that everyone is both teacher and student in the dharma.", "themes": ["Emptiness", "Sangha"], "texts": [], "minutes": 65}, {"id": "2026-08-26 - Seishu John Wiley - Accepting Things as They Are", "title": "Accepting Things as They Are", "speaker": "Seishu John Wiley", "date": "2026-08-26", "series": "", "summary": "The speaker's talk emphasizes the importance of acceptance as a key aspect of Buddhist teachings, particularly in understanding and overcoming suffering. Acceptance is not about passively going along with difficult situations, but rather about turning towards them with clarity and awareness, acknowledging and feeling them without resistance or denial. By recognizing how our thoughts, words, and actions contribute to our suffering, we can begin to let go of resistance and instead see difficulties as opportunities for growth and transformation.", "themes": ["Acceptance", "Impermanence", "Suffering"], "texts": ["Shōbōgenzō"], "minutes": 20}, {"id": "2026-08-19 - Nomon Tim Burnett - Metta Sutta Talk 2", "title": "Metta Sutta Talk 2", "speaker": "Nomon Tim Burnett", "date": "2026-08-19", "series": "Metta Sutta", "summary": "The talk invites listeners to cultivate self-love and compassion through a practice called Metta Sutta, which involves repeating phrases that promote warmth and acceptance towards oneself and all aspects of their being. By doing so, individuals can let go of negative thoughts and emotions, and instead, develop a sense of loving-kindness that can be applied to meditation and daily life. This practice aims to create conditions for growth and awareness, allowing participants to tap into their innate capacity for love and kindness, and live with greater openness, curiosity, and compassion.", "themes": ["Compassion", "Interconnection"], "texts": ["Metta Sutta"], "minutes": 50}, {"id": "2026-08-12 - Nomon Tim Burnett - Metta Sutta Talk 1", "title": "Metta Sutta Talk 1", "speaker": "Nomon Tim Burnett", "date": "2026-08-12", "series": "Metta Sutta", "summary": "The speaker's talk emphasizes the importance of self-awareness, vulnerability, and letting go of ego, highlighting that sometimes stepping back can be more helpful than trying to control or dominate situations. This is reflected in the practice of metta (loving-kindness), which encourages cultivating peace and contentment by releasing attachment to material possessions and desires for status, and instead embracing a life of kindness and compassion towards all beings. By doing so, we can develop a deeper understanding of ourselves and others, and cultivate a sense of unconditional love and support that brings joy and happiness to ourselves and those around us.", "themes": ["Compassion", "Interconnection"], "texts": ["Metta Sutta"], "minutes": 39}, {"id": "2026-08-05 - IkuShun Desiree Webster - The Three Doors of Liberation", "title": "The Three Doors of Liberation", "speaker": "IkuShun Desiree Webster", "date": "2026-08-05", "series": "", "summary": "The talk's main teaching is that true liberation comes from understanding the interconnectedness of all things and letting go of our fixed notions about ourselves and the world. By recognizing that everything is empty of a separate self, we can transform and grow in the present moment, rather than getting stuck in past regrets or future desires. This involves stopping our striving for goals and desires, and instead cultivating mindfulness and presence to experience life more fully and authentically.", "themes": ["Emptiness", "Interconnection"], "texts": ["Diamond Sutra"], "minutes": 27}, {"id": "2026-07-29 - IkuShun Desiree Webster - The Three Dharma Seals", "title": "The Three Dharma Seals", "speaker": "IkuShun Desiree Webster", "date": "2026-07-29", "series": "", "summary": "The talk explores the concept of the Two Truths in Buddhism, which reveals that our everyday reality is interconnected with a deeper, unconditioned reality. Understanding this interrelation can help us uncover the truth about ourselves and the world around us. By recognizing the impermanence of all things, including our own sense of self, we can begin to let go of attachments and perceptions that cause suffering, ultimately leading to freedom and peace.", "themes": ["Impermanence", "No-self", "Suffering"], "texts": ["Heart Sutra"], "minutes": 53}, {"id": "2026-07-22 - Kanho Chris Burkhart and Seiu Hannah Sullivan - Entering the Mirror Part 5", "title": "Entering the Mirror Part 5", "speaker": "Kanho Chris Burkhart and Seiu Hannah Sullivan", "date": "2026-07-22", "series": "Entering the Mirror", "summary": "The talk emphasizes the importance of approaching experiences with curiosity and openness, letting go of preconceptions and judgment. By embracing life as it is, without evaluation or comparison, we can find freedom in the present moment and connect more deeply with ourselves and the world around us. This approach encourages us to release attachment to our individual perspectives and instead cultivate a non-dual mind that sees all things as interconnected and worthy of understanding.", "themes": ["Buddha-nature", "No-self"], "texts": ["Platform Sutra", "Shōbōgenzō"], "minutes": 28}, {"id": "2026-07-15 - Kanho Chris Burkhart and Seiu Hannah Sullivan - Entering the Mirror Part 4", "title": "Entering the Mirror Part 4", "speaker": "Kanho Chris Burkhart and Seiu Hannah Sullivan", "date": "2026-07-15", "series": "Entering the Mirror", "summary": "The main teaching of the Soto Zen dharma talk emphasizes that true freedom and awakening arise from embracing our own Buddha nature without external rules or restrictions. This means letting go of the idea that following precepts is about achieving enlightenment through self-improvement, but rather seeing the precepts as an expression of the awakened state itself. By cultivating connection and intimacy with ourselves and others, we can tap into a deeper freedom and naturally embody compassion, honesty, and generosity.", "themes": ["Buddha-nature", "Compassion", "Ethics"], "texts": ["Platform Sutra", "Shōbōgenzō"], "minutes": 29}, {"id": "2026-07-08 - Kanho Chris Burkhart and Seiu Hannah Sullivan - Entering the Mirror Part 3", "title": "Entering the Mirror Part 3", "speaker": "Kanho Chris Burkhart and Seiu Hannah Sullivan", "date": "2026-07-08", "series": "Entering the Mirror", "summary": "The speaker's main teaching is that true wisdom and enlightenment come not from intellectual understanding or chanting, but from cultivating a non-abiding heart and mind. This means letting go of attachment to thoughts, emotions, and concepts, and instead being present in the moment, unfiltered by our ego's commentary. By observing our thoughts without engaging with them, we can break free from the cycle of attachment and aversion, and experience reality directly, unobstructed by our own mental constructs.", "themes": ["Wisdom"], "texts": ["Diamond Sutra", "Platform Sutra", "Shōbōgenzō"], "minutes": 42}, {"id": "2026-07-01 - Kanho Chris Burkhart and Seiu Hannah Sullivan - Entering the Mirror Part 2", "title": "Entering the Mirror Part 2", "speaker": "Kanho Chris Burkhart and Seiu Hannah Sullivan", "date": "2026-07-01", "series": "Entering the Mirror", "summary": "The talk's main teaching emphasizes the importance of taking action in the present moment to awaken, rather than waiting for a perfected self. This involves letting go of intellectual thinking and embracing reality as it is, without trying to improve or escape it. By doing so, we can find awakening in every moment, not just in special circumstances, and live a whole and authentic life that is free from hypocrisy and division between our words and actions.", "themes": ["No-self", "Wisdom"], "texts": ["Diamond Sutra", "Platform Sutra", "Shōbōgenzō"], "minutes": 43}, {"id": "2026-06-24 - Kanho Chris Burkhart and Seiu Hannah Sullivan - Entering the Mirror Part 1", "title": "Entering the Mirror Part 1", "speaker": "Kanho Chris Burkhart and Seiu Hannah Sullivan", "date": "2026-06-24", "series": "Entering the Mirror", "summary": "The talk's main teaching is that true awakening isn't about striving to become a better version of oneself through self-improvement, but rather about embracing the present moment and letting go of our need to control or perfect it. This approach, inspired by Huineng and Dogen, encourages us to recognize that our true nature has always been present, and that practice is not about achieving something external, but about finding freedom from our own self-doubt and striving. By slowing down and examining our motivations, we can begin to awaken to the reality of our emotions and experiences, rather than trying to fix or change them.", "themes": ["Buddha-nature", "Wisdom"], "texts": ["Diamond Sutra", "Platform Sutra"], "minutes": 35}, {"id": "2026-06-19 - Nomon Tim Burnett - Mountains Waters and Sesshin Part 4", "title": "Mountains, Waters and Sesshin, Part 4", "speaker": "Nomon Tim Burnett", "date": "2026-06-19", "series": "Mountains, Waters and Sesshin", "summary": "The speaker reflects on how their experiences with various ceremonies and encounters have taught them the importance of being present and open-minded in their spiritual practice. They've learned to appreciate the value of silence, trust, and letting go of seeking validation from others, rather than trying to control or understand everything. This approach has helped them cultivate a sense of warmth, presence, and interconnectedness with all beings, including those who may be different from themselves.", "themes": ["Interconnection", "Sangha", "Social engagement"], "texts": ["Shōbōgenzō"], "minutes": 70}, {"id": "2026-06-18 - Kanho Chris Burkhart - The Reality of All Things", "title": "The Reality of All Things", "speaker": "Kanho Chris Burkhart", "date": "2026-06-18", "series": "", "summary": "The speaker's talk highlights the importance of embracing our everyday experiences as part of our spiritual practice, rather than trying to separate them from it. By recognizing that everything belongs to our practice, we can let go of resistance and approach life with curiosity and care, cultivating intimacy with reality and a deeper understanding of ourselves and others. This perspective encourages us to explore our own storehouse of emotions and experiences, rather than seeking external spiritual goals or attainments.", "themes": ["Acceptance", "Interconnection"], "texts": ["Shōbōgenzō"], "minutes": 31}, {"id": "2026-06-17 - Nomon Tim Burnett - Mountains Waters and Sesshin Part 3", "title": "Mountains, Waters and Sesshin, Part 3", "speaker": "Nomon Tim Burnett", "date": "2026-06-17", "series": "Mountains, Waters and Sesshin", "summary": "The talk emphasizes the importance of appreciating and showing respect for others, particularly in leadership roles, by practicing sesshin (bowing). This act can help create a more harmonious community and foster a sense of gratitude for the support and care that others provide. The speaker reflects on their own experiences with Norman Fischer's approach to teaching, which prioritized everyday life and community, and how this approach has helped them grow as a practitioner and find a sense of purpose outside of formal practice.", "themes": ["Interconnection", "Sangha"], "texts": ["Shōbōgenzō"], "minutes": 64}, {"id": "2026-06-16 - Kanho Chris Burkhart - Insentient Beings Speaking Dharma", "title": "Insentient Beings Speaking Dharma", "speaker": "Kanho Chris Burkhart", "date": "2026-06-16", "series": "", "summary": "In this Soto Zen teaching, Dogen explores the idea that even seemingly ordinary objects like mountains, rivers, and stones can convey spiritual truths if one is able to hear them in a certain way. This type of hearing isn't about listening to separate entities, but rather an intimate understanding that arises from participating with reality itself. Through meditation practice, we come to realize that the world is already teaching us valuable lessons about patience, impermanence, and awakening, and by embracing our interconnectedness with all phenomena, we can discover the dharma in every moment.", "themes": ["Impermanence", "Interconnection", "Wisdom"], "texts": ["Shōbōgenzō"], "minutes": 35}, {"id": "2026-06-15 - Nomon Tim Burnett - Mountains Waters and Sesshin Part 2", "title": "Mountains, Waters and Sesshin, Part 2", "speaker": "Nomon Tim Burnett", "date": "2026-06-15", "series": "Mountains, Waters and Sesshin", "summary": "The speaker reflects on their teacher Norman's approach to Zen practice, which emphasized simplicity, humility, and trust in the process. This approach encouraged students to let go of conceptual thinking and instead focus on being present and doing their best with what they already had, creating a relaxed yet serious atmosphere for learning and growth. By embracing this perspective, students can awaken to their true nature and continue the Buddha's way, mirroring the responsibility that lies within each individual.", "themes": ["Acceptance", "Sangha"], "texts": ["Shōbōgenzō"], "minutes": 52}, {"id": "2026-06-13 - Nomon Tim Burnett - Mountains Waters and Sesshin Part 1", "title": "Mountains, Waters and Sesshin, Part 1", "speaker": "Nomon Tim Burnett", "date": "2026-06-13", "series": "Mountains, Waters and Sesshin", "summary": "The speaker's talk emphasizes the importance of embracing the present moment without attachment or preconception, much like the fluid and dynamic nature of a mountain. This \"mountain walking\" practice encourages practitioners to let go of limitations and instead embody solidity and freedom, allowing for direct experience and understanding that transcends conceptual views. By approaching their practice with seriousness, relaxation, and openness, individuals can tap into the reality of the present moment and find guidance in Dogen's teachings.", "themes": ["Impermanence", "Sangha", "Wisdom"], "texts": ["Shōbōgenzō"], "minutes": 54}, {"id": "2026-06-10 - Nomon Tim Burnett - Sandokai Part 2", "title": "Sandokai Part 2", "speaker": "Nomon Tim Burnett", "date": "2026-06-10", "series": "Sandokai", "summary": "The teacher's talk emphasizes the importance of meeting ourselves in a deeper way, rather than trying to find answers or solutions outside of ourselves. This can be achieved through practices like Dokusan, where we meet with our own mind and emotions in a private interview, without expectation of answers or outcomes. By embracing this process, we can cultivate compassion and understanding for ourselves and others, and deepen our connection with the present moment, letting go of dualistic thinking and ego's need to control.", "themes": ["Compassion", "Interconnection"], "texts": ["Shōbōgenzō"], "minutes": 37}, {"id": "2026-06-07 - Joden Bob Rose - The Six Paramitas", "title": "The Six Paramitas", "speaker": "Joden Bob Rose", "date": "2026-06-07", "series": "Paramitas", "summary": "The talk's main teaching emphasizes the importance of integrating Bodhidharma's principles into daily life, rather than just meditating on them. By practicing virtue in everyday actions, such as generosity, ethics, patience, energy, meditation, and wisdom, one can cultivate a sense of stability and freedom, even in the midst of changing circumstances. This approach encourages listeners to let go of craving and attachment, recognizing that seeking something always leads to suffering, and instead find peace in what is already present.", "themes": ["Acceptance", "Impermanence", "Suffering"], "texts": [], "minutes": 31}, {"id": "2026-06-04 - Nomon Tim Burnett - Sandokai Part 1", "title": "Sandokai Part 1", "speaker": "Nomon Tim Burnett", "date": "2026-06-04", "series": "Sandokai", "summary": "The main teaching of the Soto Zen dharma talk is that true understanding and connection can be found in the present moment, without needing to think or conceptualize. By paying attention to everyday experiences, such as the sights, sounds, and sensations around us, we can cultivate a deeper awareness of ourselves and the world. This approach encourages us to let go of judgment and attachment, allowing things to be as they are, rather than trying to control or manipulate them.", "themes": ["Acceptance", "Interconnection"], "texts": ["Shōbōgenzō"], "minutes": 52}, {"id": "2026-05-28 - Nomon Tim Burnett - Hymn to the Perfection of Wisdom", "title": "Hymn to the Perfection of Wisdom", "speaker": "Nomon Tim Burnett", "date": "2026-05-28", "series": "", "summary": "The speaker emphasizes the importance of balancing healing and transformation in one's spiritual journey, recognizing that both are essential for growth and self-awareness. They encourage embracing nurturing and care as a vital part of the practice, rather than solely focusing on personal growth or transformation. This approach is rooted in Buddhist wisdom, particularly in the concept of prajnaparamita, which embodies the wisdom that goes beyond wisdom itself.", "themes": ["Emptiness", "Wisdom"], "texts": ["Diamond Sutra", "Heart Sutra"], "minutes": 36}, {"id": "2026-05-24 - Nomon Tim Burnett - Prajna Paramita", "title": "Prajna Paramita", "speaker": "Nomon Tim Burnett", "date": "2026-05-24", "series": "Paramitas", "summary": "The speaker emphasizes that all aspects of ourselves are already holy and more than what we can know, encouraging listeners to let go of fixed ideas and concepts in order to make space for a deeper understanding of reality. This understanding arises from cultivating the six practices of Buddhism, which are interconnected like the fingers on one's hand, and involves being open, curious, joyful, and present in daily life. By embracing these qualities, we can create space for wisdom to arise, leading to a sense of peace, openness, and remembering who we truly are.", "themes": ["Acceptance", "Impermanence", "Wisdom"], "texts": [], "minutes": 43}, {"id": "2026-05-18 - Junka Ken Oates - Muscle Memory and the Practice of Daily Life", "title": "Muscle Memory and the Practice of Daily Life", "speaker": "Junka Ken Oates", "date": "2026-05-18", "series": "", "summary": "The talk's main teaching emphasizes the importance of applying Buddhist principles in everyday life, rather than just intellectual understanding or memorization. By focusing on basic practices and letting go of mental analysis, one can cultivate a deeper sense of mindfulness and compassion that guides their actions in daily life. This approach allows for a more natural and instinctive response to challenges, like developing muscle memory through martial arts training, where the goal is not sudden enlightenment but gradual refinement of character.", "themes": ["Ethics", "Wisdom"], "texts": [], "minutes": 13}, {"id": "2026-05-14 - Kanho Chris Burkhart - Jewel Mirror Samadhi Part 4", "title": "Jewel Mirror Samadhi Part 4", "speaker": "Kanho Chris Burkhart", "date": "2026-05-14", "series": "Jewel Mirror Samadhi", "summary": "The teacher's main teaching emphasizes the importance of embracing the present moment and letting go of ego and control in spiritual development. This means showing up fully and being open to life's unfolding, rather than trying to manipulate or control experiences. By doing so, we can cultivate wisdom and understanding that goes beyond intellectual concepts, and instead find what serves us in each situation with intention and awareness.", "themes": ["Acceptance", "Wisdom"], "texts": [], "minutes": 28}, {"id": "2026-05-11 - IkuShun Desiree Webster - The Ground of Energetic Joy", "title": "The Ground of Energetic Joy", "speaker": "IkuShun Desiree Webster", "date": "2026-05-11", "series": "", "summary": "Here is a summary of the talk's main teaching in plain language:\n\nThe speaker emphasizes the importance of cultivating \"virya,\" or joyful effort, which involves recognizing and overcoming obstacles such as laziness, procrastination, and self-doubt to develop sustained inner power and enthusiasm. This requires developing bodhicitta, or the mind of love, which is essential for sustaining motivation and bringing about positive change in one's life and work. By cultivating virya, we can overcome our limitations and respond with greater freedom and energy, leading to a more joyful and meaningful life.", "themes": ["Interconnection", "No-self", "Wisdom"], "texts": [], "minutes": 20}, {"id": "2026-05-07 - Ben Connelly - Flower Garden Buddhism", "title": "Flower Garden Buddhism", "speaker": "Ben Connelly", "date": "2026-05-07", "series": "", "summary": "The talk's main teaching emphasizes the importance of recognizing our interconnectedness and interdependence with others and the world around us. This understanding is rooted in Buddhist teachings such as the Four Noble Truths and Hawaiian teachings on karma, which suggest that every individual has the capacity to contribute to liberation from suffering for everyone else. By acknowledging and working with difficult emotions like anger, and by trusting our own capacity for growth and transformation, we can create conditions for freedom and flourishing for ourselves and others.", "themes": ["Emptiness", "Interconnection", "Social engagement"], "texts": [], "minutes": 61}, {"id": "2026-05-07 - Myoki Raizelah Bayen - Responding to the Cries of the World Retreat", "title": "Responding to the Cries of the World Retreat", "speaker": "Myoki Raizelah Bayen", "date": "2026-05-07", "series": "", "summary": "The speaker's talk emphasizes the importance of cultivating compassion within ourselves before taking action towards helping others. They suggest starting by practicing loving-kindness towards oneself, which can help build a foundation for compassionate action towards others. By accepting and breathing into difficult emotions, we can develop greater self-awareness and learn to care for our own pain, allowing us to be more effective in caring for the suffering of others.", "themes": ["Acceptance", "Compassion", "Vulnerability"], "texts": [], "minutes": 43}, {"id": "2026-05-07 - Seiu Hannah Sullivan - Compassion", "title": "Compassion", "speaker": "Seiu Hannah Sullivan", "date": "2026-05-07", "series": "", "summary": "The speaker teaches that true spiritual practice is rooted in cultivating compassion, which is the foundation for all the paramitas or virtues. Without compassion, even well-intentioned practices become rigid and unyielding. By recognizing and understanding our own biases and motivations, we can transform our anger into empathy and develop a sense of humanity, allowing us to cultivate genuine compassion for others.", "themes": ["Compassion", "Wisdom"], "texts": [], "minutes": 25}, {"id": "2026-05-07 - Seiu Hannah Sullivan - Responding to the Cries of the World Retreat", "title": "Responding to the Cries of the World Retreat", "speaker": "Seiu Hannah Sullivan", "date": "2026-05-07", "series": "", "summary": "The talk emphasizes the importance of cultivating compassion and responding to the needs of others, drawing on the archetype of Avalokiteshvara, the embodiment of infinite compassion in Buddhism and other traditions. By recognizing our interconnectedness with all beings, we can begin to understand suffering and tragedy as a shared human experience that requires kindness and care. The speaker encourages embracing uncomfortable feelings and finding solace in the power of compassion, particularly when it comes to those we may not naturally feel empathy towards, in order to cultivate true and expansive kindness.", "themes": ["Compassion", "Interconnection"], "texts": [], "minutes": 22}, {"id": "2026-04-29 - Kanho Chris Burkhart - Jewel Mirror Samadhi Part 3", "title": "Jewel Mirror Samadhi Part 3", "speaker": "Kanho Chris Burkhart", "date": "2026-04-29", "series": "Jewel Mirror Samadhi", "summary": "The speaker invites listeners to explore the idea that there are aspects of reality that cannot be grasped by our ordinary thinking and conceptual frameworks. Instead, they suggest experiencing these \"naturally real\" yet \"inconceivable\" concepts directly, allowing us to tap into their transformative power without analysis or interpretation. This approach requires a willingness to let go of our need for understanding and instead simply be present with the experience, embracing its complexity and uncertainty.", "themes": ["Acceptance", "Interconnection"], "texts": [], "minutes": 34}, {"id": "2026-04-23 - Kanho Chris Burkhart - Jewel Mirror Samadhi Part 2", "title": "Jewel Mirror Samadhi Part 2", "speaker": "Kanho Chris Burkhart", "date": "2026-04-23", "series": "Jewel Mirror Samadhi", "summary": "The teacher encourages listeners to approach spiritual understanding not through intellectual analysis, but by directly experiencing and noticing reality as it is, rather than trying to grasp a specific concept or definition. This \"noticing\" approach seeks to transcend our usual tendency to see things in contrast and labels, instead revealing the interconnectedness of all phenomena. By embracing this direct recognition, listeners can begin to see their own experience and the world around them in a new light, dissolving the boundaries between self and other.", "themes": ["Interconnection", "Wisdom"], "texts": [], "minutes": 39}, {"id": "2026-04-17 - Kanho Chris Burkhart - the Jewel Mirror Samadhi", "title": "The Jewel Mirror Samādhi", "speaker": "Kanho Chris Burkhart", "date": "2026-04-17", "series": "Jewel Mirror Samadhi", "summary": "The teacher invites participants to approach the Jumira Samadhi poem as a living question that can be experienced and allowed to work in their lives, rather than being intellectually understood or solved. By chanting the poem without interpretation for four weeks, they aim to tap into its beauty and resonance, allowing it to guide them towards a deeper sense of awareness and intimacy with themselves and the world around them.", "themes": ["Emptiness", "Interconnection"], "texts": [], "minutes": 42}, {"id": "2026-04-12 - Heigaku Talus Latona - Joyful Effort and the Energy of Sangha", "title": "Joyful Effort and the Energy of Sangha", "speaker": "Heigaku Talus Latona", "date": "2026-04-12", "series": "", "summary": "The speaker shares their personal experience of struggling with anger and frustration while working on an important task, but recognizes that they can tap into a natural energy and joyful effort when they let go of their individual self and connect with others as a Sangha. This energy is not something to be generated from within, but rather it arises naturally in the world when we are in touch with everything. By embracing this energy and letting it guide us, we can find joy and fulfillment in our efforts, rather than striving for perfection or satisfaction that inevitably leads to dissatisfaction.", "themes": ["Compassion", "Sangha", "Suffering"], "texts": [], "minutes": 35}, {"id": "2026-04-09 - Nomon Tim Burnett - Heart Sutra Part 7 The Good News", "title": "Heart Sutra, Part 7: The Good News", "speaker": "Nomon Tim Burnett", "date": "2026-04-09", "series": "Heart Sutra", "summary": "The teacher's main teaching is that true freedom and peace come from letting go of our attachments and preconceived notions about reality. By embracing emptiness, we can transcend our tendency to cling to things that are ultimately empty and unfulfilling, and instead find liberation in the present moment. This involves cultivating a sense of openness and curiosity, rather than trying to grasp or achieve something, and is rooted in the wisdom of the Prajnaparamita Mantra, which can be chanted to help cultivate mindfulness and awareness.", "themes": ["Emptiness", "Suffering", "Wisdom"], "texts": ["Heart Sutra"], "minutes": 39}, {"id": "2026-04-06 - Myoki Raizelah Bayen - Dhyana Paramita", "title": "Dhyana Paramita", "speaker": "Myoki Raizelah Bayen", "date": "2026-04-06", "series": "Paramitas", "summary": "The main teaching of the dharma talk emphasizes the importance of direct experience through meditation practice, particularly concentration (dhyana). The teacher invites listeners to explore the teachings of the Anupasati Sutra and Dogen's Phukham Zazengi by putting them into practice, rather than just reading about them. By cultivating awareness of the breath and body, one can access their true nature and reconnect with reality, even in the midst of life's challenges.", "themes": ["Buddha-nature"], "texts": [], "minutes": 49}, {"id": "2026-03-30 - Seishu John Wiley - The Paramitas in Daily Life", "title": "The Paramitas in Daily Life", "speaker": "Seishu John Wiley", "date": "2026-03-30", "series": "Paramitas", "summary": "The talk emphasizes the importance of cultivating happiness and character through Buddhist practice, particularly by developing self-care and kindness towards oneself. Drawing on teachings such as the paramitas, the speaker encourages listeners to focus on making a positive impact in their daily lives, even if it's just \"shining one corner of the world\" with mindfulness and compassion. By applying these principles, individuals can reduce suffering and bring joy to themselves and others, ultimately returning the gift of life that the earth provides.", "themes": ["Acceptance", "Compassion"], "texts": [], "minutes": 23}, {"id": "2026-03-25 - Nomon Tim Burnett - Heart Sutra Part 6 Empty Marks Empty Chains", "title": "Heart Sutra, Part 6: Empty Marks, Empty Chains", "speaker": "Nomon Tim Burnett", "date": "2026-03-25", "series": "Heart Sutra", "summary": "The speaker reflects on the wisdom of the Heart Sutra, which teaches that all phenomena are empty of inherent existence and marked by impermanence, helping us let go of attachments and find freedom from suffering. This understanding can help us see through our limited views and perceptions, recognizing that everything is interconnected and not separate from ourselves or each other. By embracing this emptiness, we can cultivate a deeper understanding of reality and begin to heal the mind.", "themes": ["Emptiness", "Impermanence", "No-self", "Suffering"], "texts": ["Heart Sutra"], "minutes": 48}, {"id": "2026-03-18 - Nomon Tim Burnett - Heart Sutra Part 5 Making Friends with Emptiness", "title": "Heart Sutra, Part 5: Making Friends with Emptiness", "speaker": "Nomon Tim Burnett", "date": "2026-03-18", "series": "Heart Sutra", "summary": "The speaker's main teaching emphasizes the importance of embracing the interconnectedness and impermanence of life, recognizing that our concepts and words cannot fully capture reality. This understanding, known as \"emptiness,\" allows us to approach experience with a more open and receptive mindset, cultivating flexibility, acceptance, and love in our relationships with others. By letting go of our need for fixed identities and separate selves, we can develop a deeper appreciation for the fluid and dynamic nature of life, leading to greater freedom and connection.", "themes": ["Emptiness", "Impermanence", "Interconnection", "No-self"], "texts": ["Heart Sutra"], "minutes": 34}, {"id": "2026-03-15 - Joden Bob Rose - Manifesting Kanzeon", "title": "Manifesting Kanzeon", "speaker": "Joden Bob Rose", "date": "2026-03-15", "series": "", "summary": "The speaker emphasizes that true generosity is not about achieving a specific goal, but about cultivating awareness and response to suffering through compassion and mindfulness. By letting go of mental processes and obstacles, we can embody dana in our daily lives, recognizing the interconnectedness of all phenomena and offering genuine support to others without condition or expectation. This approach requires self-care and recognition of one's own limitations, allowing us to receive help when needed and truly offer generosity from a place of openness and receptivity.", "themes": ["Compassion", "Interconnection"], "texts": ["Heart Sutra"], "minutes": 37}, {"id": "2026-03-12 - Nomon Tim Burnett - Heart Sutra Part 4 Form is Emptiness", "title": "Heart Sutra, Part 4: Form is Emptiness", "speaker": "Nomon Tim Burnett", "date": "2026-03-12", "series": "Heart Sutra", "summary": "The teacher's main teaching is that our understanding of reality is shaped by concepts and language, but true reality lies beyond these constructs. Emptiness, or the lack of inherent existence, means that everything is interconnected and free from suffering, including the five aggregates (form, sensations, perceptions, mental formations, and consciousness). By exploring this emptiness, we can let go of our fixed notions of self and reality, and instead experience a sense of freedom and openness.", "themes": ["Emptiness"], "texts": ["Heart Sutra"], "minutes": 43}, {"id": "2026-03-08 - Junka Ken Oates - Interconnectedness of the Paramitas", "title": "Interconnectedness of the Paramitas", "speaker": "Junka Ken Oates", "date": "2026-03-08", "series": "", "summary": "The talk's main teaching is that our tendency to categorize and separate concepts can actually be a hindrance to understanding the interconnectedness of reality, particularly in Buddhist philosophy. The speaker suggests that instead of listing individual practices like patience or precepts as separate entities, we should recognize how they are all interdependent and empty of inherent existence. By embracing this understanding, we can cultivate greater mindfulness and wisdom by revisiting our own struggles with qualities like laziness, anger, and patience, and integrating them into a more holistic practice.", "themes": ["Emptiness", "Interconnection", "No-self", "Wisdom"], "texts": [], "minutes": 21}, {"id": "2026-03-01 - Heigaku Talus Latona - Dana Paramita", "title": "Dana Paramita", "speaker": "Heigaku Talus Latona", "date": "2026-03-01", "series": "", "summary": "The talk's main teaching emphasizes the importance of approaching others' actions with generosity and intellectual empathy, recognizing that we don't have all the information and that our understanding is limited by our own perspectives. This involves going beyond forgiveness to cultivate a more open-minded and compassionate approach, drawing on Buddhist teachings such as the paramitas and \"Buddha-like\" intentions. By cultivating this mindset through meditation and perfection of concentration, we can develop a greater sense of calm and non-judgmental awareness in daily life, allowing us to embody bodhisattva qualities such as loving kindness and letting go of harm.", "themes": ["Compassion", "Ethics", "Interconnection"], "texts": [], "minutes": 26}, {"id": "2026-02-25 - Nomon Tim Burnett - Heart Sutra Part 3 The Skandhas", "title": "Heart Sutra, Part 3: The Skandhas", "speaker": "Nomon Tim Burnett", "date": "2026-02-25", "series": "Heart Sutra", "summary": "The main teaching of this Soto Zen dharma talk emphasizes the importance of directly experiencing reality without relying on conceptual models or pre-existing categories. By observing our experiences without judgment or interpretation, we can gain a more accurate understanding of the world and ourselves, and begin to let go of attachments and limitations that create suffering. This approach encourages us to cultivate patience, curiosity, and openness, allowing us to see our experiences as mere moments of perception rather than fixed identities.", "themes": ["Emptiness", "No-self", "Wisdom"], "texts": ["Heart Sutra"], "minutes": 53}, {"id": "2026-02-23 - Kanho Chris Burkhart - Practicing the Six Perfections", "title": "Practicing the Six Perfections", "speaker": "Kanho Chris Burkhart", "date": "2026-02-23", "series": "", "summary": "The speaker's talk emphasizes that the practice of the Six Perfections is not about achieving perfection, but rather about cultivating virtues such as generosity, patience, effort, and wisdom in daily life. By focusing on these qualities, we can become more trustworthy, flexible, and present in difficult situations, even if our efforts don't feel flawless or perfect. This approach allows us to see how our practice is already changing us, and to develop a more compassionate and humane approach to life through the process of growth and self-cultivation.", "themes": ["Acceptance", "Suffering", "Wisdom"], "texts": [], "minutes": 30}, {"id": "2026-02-19 - Nomon Tim Burnett - Heart Sutra Part 2 Avalokiteshvara", "title": "Heart Sutra, Part 2: Avalokiteshvara", "speaker": "Nomon Tim Burnett", "date": "2026-02-19", "series": "Heart Sutra", "summary": "The main teaching of this Soto Zen dharma talk emphasizes the importance of finding peace within oneself through mindfulness and practice, rather than relying on external sources. The story of Avalokiteshvara, a bodhisattva who embodies compassion and wisdom, serves as a reminder that true peace is not something we can find in others or in external circumstances, but rather it arises from our own inner transformation. By cultivating compassion, forgiveness, and mindfulness, we can create a more peaceful life for ourselves and those around us.", "themes": ["Compassion", "Emptiness"], "texts": ["Heart Sutra"], "minutes": 58}, {"id": "2026-02-15 - Myoki Raizelah Bayen - Paramita of Ethical Conduct Metta", "title": "Paramita of Ethical Conduct: Metta", "speaker": "Myoki Raizelah Bayen", "date": "2026-02-15", "series": "Paramitas", "summary": "The speaker invites listeners to approach their spiritual practice with an open and beginner's mind, recognizing that growth and learning are always possible regardless of one's level of experience. This mindset can be cultivated through practices such as metta (loving-kindness meditation), which involves sending kindness and compassion to oneself and others, and Tonglen, a practice that involves breathing in suffering while exhaling love and compassion. By embracing these practices with an open heart and mind, listeners can deepen their understanding of themselves and the world around them, and cultivate greater mindfulness and empathy in the present moment.", "themes": ["Compassion", "Ethics", "Suffering"], "texts": [], "minutes": 42}, {"id": "2026-02-09 - Seiu Hannah Sullivan - The Second Paramita Sila", "title": "The Second Paramita: Sila", "speaker": "Seiu Hannah Sullivan", "date": "2026-02-09", "series": "Paramitas", "summary": "The talk's main teaching emphasizes the importance of cultivating a compassionate and generous heart through the practice of ethics, rather than simply avoiding wrongdoing. By studying the 16 Bodhisattva precepts, practitioners can develop a more nuanced understanding of ethics that prioritizes kindness, respect, and love towards all beings. This approach encourages flexibility and discernment in applying the precepts, letting go of grudges and old stories to live ethically with greater ease and freedom.", "themes": ["Compassion", "Ethics"], "texts": [], "minutes": 19}, {"id": "2026-02-04 - Nomon Tim Burnett - Heart Sutra Part 1 Overview", "title": "Heart Sutra, Part 1: Overview", "speaker": "Nomon Tim Burnett", "date": "2026-02-04", "series": "Heart Sutra", "summary": "Here is a summary paragraph in plain language:\n\nThe talk emphasized the importance of cultivating mindfulness through walking meditation, which can be a transformative experience that helps us appreciate life's simple miracles. The speaker also touched on the concept of \"emptiness\" from Buddhist teachings, suggesting that it's not just about being empty, but rather recognizing what we're truly empty of - our preconceptions and ego - in order to access a more open and boundless reality. This understanding can lead to greater compassion, freedom, and wholeness, and the speaker encouraged listeners to explore this concept further through practice and study.", "themes": ["Compassion", "Emptiness", "Interconnection"], "texts": ["Diamond Sutra", "Heart Sutra"], "minutes": 49}, {"id": "2026-01-25 - IkuShun Desiree Webster - Is Patience a FourLetter Word", "title": "Is Patience a Four-Letter Word?", "speaker": "IkuShun Desiree Webster", "date": "2026-01-25", "series": "", "summary": "The talk's main teaching is that patience is not about enduring or tolerating suffering, but rather about cultivating confidence and stability to hold what is, allowing us to be present with our experiences without judgment or resistance. This involves developing mindfulness and awareness of our thoughts, emotions, and physical sensations, as well as letting go of our need to control or share our stories. By doing so, we can experience a sense of freedom and spaciousness, and develop the virtues of patience and compassion that bring inner peace and loving kindness to ourselves and others.", "themes": ["Acceptance", "Buddha-nature", "Compassion"], "texts": [], "minutes": 26}, {"id": "2026-01-22 - Kanho Chris Burkhart - Living in a world we Did Not Design", "title": "Living in a world we Did Not Design", "speaker": "Kanho Chris Burkhart", "date": "2026-01-22", "series": "", "summary": "The speaker encourages listeners to cultivate patience as a way to take radical responsibility for their lives, rather than getting caught up in anger and outrage about things that can't be changed. By being intimate with reality as it is, without resistance or anger, we can find the courage to act on our own values and intentions, transforming ourselves and the world around us. This involves staying grounded in our bodies and responding with wisdom, rather than reacting impulsively from a place of anger or frustration.", "themes": ["Acceptance", "Ethics", "Social engagement"], "texts": [], "minutes": 37}, {"id": "2026-01-18 - Myoki Raizelah Bayen - Dana Paramita", "title": "Dana Paramita", "speaker": "Myoki Raizelah Bayen", "date": "2026-01-18", "series": "Paramitas", "summary": "The talk's main teaching emphasizes the importance of letting go of our limited individual selves to cultivate a sense of interconnectedness and generosity. By recognizing our inherent openness and receptivity, we can transcend feelings of \"not enough-ness\" and inadequacy, and instead discover the abundance and gifts that are always present in life. Through Zazen practice, we learn to allow things to arise and pass away without attachment or resistance, allowing us to receive life's gifts with an open heart and mind.", "themes": ["Emptiness", "Interconnection", "No-self"], "texts": ["Shōbōgenzō"], "minutes": 25}, {"id": "2026-01-15 - Nomon Tim Burnett - With our Whole Hearts Taking Refuge", "title": "With our Whole Hearts - Taking Refuge", "speaker": "Nomon Tim Burnett", "date": "2026-01-15", "series": "", "summary": "The teacher's talk emphasizes the importance of taking refuge in the Buddha, Dharma, and Sangha, highlighting the need for right discernment when seeking protection and guidance. He shares his own experience with chanting the three refuges, finding it beautiful and meaningful, and encourages listeners to reflect on what taking refuge means to them personally. The goal is not to find a definitive answer, but rather to explore and understand the meaning behind the words in a personal and intimate way, cultivating awareness and understanding of one's own path.", "themes": ["Sangha"], "texts": [], "minutes": 35}, {"id": "2026-01-12 - Zenshin Florence Caplow - Tend to Your Spirit", "title": "Tend to Your Spirit", "speaker": "Zenshin Florence Caplow", "date": "2026-01-12", "series": "", "summary": "The speaker shares their personal experience with chronic illness as a catalyst for deepening their Zen practice, highlighting the importance of cultivating energy, faith, and gratitude despite physical limitations. They reflect on how their practice has evolved to accommodate their needs, finding creative ways to continue exploring spiritual teachings even in the face of adversity. Through this journey, they have come to see their life with illness as a path to growth, acceptance, and spiritual depth, inviting others to explore the intersections between suffering and awakening.", "themes": ["Acceptance", "Gratitude", "Impermanence", "Suffering"], "texts": [], "minutes": 32}, {"id": "2026-01-07 - Nomon Tim Burnett - Joyfully Impossible The Bodhisattva Vows", "title": "Joyfully Impossible - The Bodhisattva Vows", "speaker": "Nomon Tim Burnett", "date": "2026-01-07", "series": "", "summary": "The speaker invites listeners to contemplate the Bodhisattva vows as a means of cultivating wisdom, compassion, and interconnectedness, rather than solely focusing on individual salvation. They propose a revised interpretation that emphasizes mutual support and facilitation, encouraging participants to approach their personal vows with patience, self-generosity, and a willingness to listen deeply to others. By doing so, the speaker hopes to foster a sense of community and shared understanding among those who participate in this practice.", "themes": ["Interconnection"], "texts": ["Lotus Sutra", "Platform Sutra"], "minutes": 33}, {"id": "2025-12-18 - IkuShun Desiree Webster - The Three RefugesComing Home and Living by Vow", "title": "The Three Refuges—Coming Home and Living by Vow", "speaker": "IkuShun Desiree Webster", "date": "2025-12-18", "series": "", "summary": "The speaker's main teaching is that taking refuge in the Buddha, Dharma, and Sangha is not about seeking external solutions, but rather about trusting in one's own awakened nature and recognizing the interconnectedness of all beings. This commitment to follow the path of wisdom and compassion involves cultivating compassion, understanding, and love through community support, which is essential for deepening our practice and vow. By taking refuge, we acknowledge our interdependence with others and ourselves, and vow to hold this sense of refuge with reverence and love.", "themes": ["Buddha-nature", "Interconnection", "Sangha"], "texts": [], "minutes": 16}, {"id": "2025-12-11 - Seiu Hannah Sullivan - Vow of Repentance", "title": "Vow of Repentance", "speaker": "Seiu Hannah Sullivan", "date": "2025-12-11", "series": "", "summary": "The speaker emphasizes the importance of taking responsibility for one's past actions by acknowledging and transforming their own karma, rather than seeking external forgiveness or blame. This practice, known as the vow of repentance, involves recognizing and letting go of self-loathing and delusion, allowing us to move forward with renewed awareness and compassion. By embracing this practice, we can transcend our dualistic thinking and return to a state of original nature, free from the burdens of good and bad actions.", "themes": ["Ethics", "Wisdom"], "texts": [], "minutes": 27}, {"id": "2025-12-07 - Kanho Chris Burkhart - Rohatsu", "title": "Rohatsu", "speaker": "Kanho Chris Burkhart", "date": "2025-12-07", "series": "", "summary": "The speaker invites listeners to sit with the uncertainty and stillness of spiritual practice, embracing the reality that everything belongs together, including our fears, doubts, and limitations. By trusting in simplicity and tradition, we can find courage and belonging in the midst of uncertainty, just as the Buddha did, and awaken to the realization that we have never been separate from anything at all. This approach allows us to let go of external influences and rise above our difficulties, becoming more grounded in the truth of interconnectedness and finding love and self-awareness in the process.", "themes": ["Buddha-nature", "Interconnection", "Vulnerability"], "texts": ["Shōbōgenzō"], "minutes": 17}, {"id": "2025-11-28 - Nomon Tim Burnett - Opening the Dharma", "title": "Opening the Dharma", "speaker": "Nomon Tim Burnett", "date": "2025-11-28", "series": "", "summary": "The main teaching of the Soto Zen dharma talk emphasizes the importance of approaching reality with an open mind and heart, rather than trying to grasp or explain complex concepts. The teacher encourages listeners to be present with reality as it is, embracing both its subtlety and vastness, and to approach the dharma with a sense of humility and recognition of its complexity. By doing so, one can tap into the true nature of the Buddha's teachings, which are considered precious treasures with deep spiritual significance.", "themes": ["Wisdom"], "texts": ["Lotus Sutra"], "minutes": 34}, {"id": "2025-11-24 - Nomon Tim Burnett - Taking Refuge", "title": "Taking Refuge", "speaker": "Nomon Tim Burnett", "date": "2025-11-24", "series": "", "summary": "The main teaching of the Soto Zen dharma talk emphasizes the importance of embracing a universal reality beyond our individual egos and desires. By taking refuge in Buddha and the Dharma, we can experience transformation and growth, and discover that our true nature is not separate from that of the Buddha. This involves letting go of control and manipulation, and instead embracing our authentic selves, much like the natural world does.", "themes": ["Buddha-nature", "Sangha", "Wisdom"], "texts": [], "minutes": 34}, {"id": "2025-11-20 - Nomon Tim Burnett - Sutra Book 2 Dedication of Merit", "title": "Sutra Book 2 - Dedication of Merit", "speaker": "Nomon Tim Burnett", "date": "2025-11-20", "series": "", "summary": "The speaker's main teaching emphasizes that our individual reality is interconnected with the world around us, and that our thoughts and actions have consequences on this web of energy. This understanding allows us to cultivate positive energy and make a greater impact through our daily actions, rather than seeing ourselves as separate from others and the environment. By embracing this interconnectedness, we can transcend our limited Western perspective and tap into a deeper sense of wisdom and compassion that encompasses all beings trying to awaken.", "themes": ["Emptiness", "Ethics", "Interconnection", "Wisdom"], "texts": [], "minutes": 34}, {"id": "2025-11-13 - Nomon Tim Burnett - Chanting the Robe Chant", "title": "Chanting the Robe Chant", "speaker": "Nomon Tim Burnett", "date": "2025-11-13", "series": "", "summary": "The main teaching of this Soto Zen dharma talk emphasizes the importance of shedding our individual attachments and conditioning to become more liberated and present in life. The speaker highlights the significance of wearing Buddhist robes as a symbol of vulnerability and healing, but also cautions against using them as a barrier or exclusive marker of spiritual status. Ultimately, the talk encourages practitioners to cultivate mindfulness, community, and devotion to the teachings, with the goal of becoming immersed in living beings everywhere and helping all beings rather than trying to save or free them from their suffering.", "themes": ["Gratitude", "Interconnection"], "texts": [], "minutes": 36}, {"id": "2025-11-11 - Junka Ken Oates - Fall SesshinBuddha Occam Danish ArchitectsBritish Grandmothers", "title": "Fall Sesshin-Buddha, Occam, Danish Architects&British Grandmothers", "speaker": "Junka Ken Oates", "date": "2025-11-11", "series": "", "summary": "The talk's main teaching emphasizes the enduring relevance of Buddhism's core principles, despite its evolution over time through cultural adaptation. The speaker highlights the importance of laypeople playing a vital role in sharing and practicing Buddhism, taking the teachings into their daily lives and using compassion to positively impact others. This involves distinguishing between related concepts like love, kindness, and compassion, and recognizing that sometimes compassion requires allowing someone to experience pain or discomfort as part of their growth.", "themes": ["Compassion", "Impermanence", "No-self", "Suffering"], "texts": [], "minutes": 22}, {"id": "2025-11-11 - Nomon Tim Burnett - Fall Sesshin", "title": "Fall Sesshin", "speaker": "Nomon Tim Burnett", "date": "2025-11-11", "series": "", "summary": "The teacher invites the audience to practice a way of being that allows them to let go of control and ego, embracing instead a sense of \"not controlling anything.\" This means releasing attachment to specific outcomes or opinions, and instead allowing things to unfold naturally. By doing so, we can create space for others to be their true selves, and support each other in living authentic lives.", "themes": ["Gratitude", "No-self", "Sangha"], "texts": ["Shōbōgenzō"], "minutes": 43}, {"id": "2025-10-30 - Kanho Chris Burkhart - Finding Zen in the Ordinary", "title": "Finding Zen in the Ordinary", "speaker": "Kanho Chris Burkhart", "date": "2025-10-30", "series": "", "summary": "The speaker's main teaching emphasizes the importance of direct experience and slow practice in understanding the Dharma, encouraging listeners to trust their own experience rather than relying on external explanations or concepts. By sitting with an open mind and heart, one can develop a deeper understanding that reveals itself from within, allowing for a more authentic and spontaneous expression of awakening. This approach views practice and realization as intertwined, and invites listeners to apply this awareness to daily life, cultivating clarity, compassion, and gentle strength in every moment.", "themes": ["Acceptance", "Buddha-nature", "No-self"], "texts": ["Shōbōgenzō"], "minutes": 34}, {"id": "2025-10-29 - Nomon Tim Burnett - Dogens Genjokoan at Bozeman Zen Group", "title": "Dogen's Genjokoan - at Bozeman Zen Group", "speaker": "Nomon Tim Burnett", "date": "2025-10-29", "series": "", "summary": "Here's a summary paragraph in plain language:\n\nThe talk emphasizes the importance of approaching spiritual practice with an open mind and a willingness to let go of attachments and preconceptions. By doing so, we can allow ourselves to be fully present and connected to our experiences, rather than trying to achieve some kind of enlightenment or understanding. This means embracing our true nature as it is, without trying to grasp or control anything, and simply being with what is in the moment.", "themes": ["Buddha-nature", "Impermanence", "No-self"], "texts": ["Lotus Sutra", "Shōbōgenzō"], "minutes": 45}, {"id": "2025-10-29 - Nomon Tim Burnett - Dogens Vow at Bozeman Zen Group", "title": "Dogen's Vow - at Bozeman Zen Group", "speaker": "Nomon Tim Burnett", "date": "2025-10-29", "series": "", "summary": "The speaker emphasizes that true spiritual growth is not about achieving some external goal, but rather about cultivating wisdom and compassion for all beings, regardless of their individual circumstances or actions. This involves taking formal vows and steps towards personal growth, while also acknowledging our interconnectedness with others who may not have taken similar steps. By embracing this perspective, we can work towards creating positive change in the world and finding peace in the midst of challenges.", "themes": ["Buddha-nature", "Compassion", "Social engagement"], "texts": ["Shōbōgenzō"], "minutes": 66}, {"id": "2025-10-24 - Nomon Tim Burnett - Exploring Four Themes of Dogens Teachings", "title": "Exploring Four Themes of Dogen's Teachings", "speaker": "Nomon Tim Burnett", "date": "2025-10-24", "series": "", "summary": "In this Soto Zen dharma talk, the main teaching emphasizes the importance of integrating with reality in the present moment, rather than getting caught up in past experiences or future expectations. This is rooted in Dogen's philosophy, which encourages compassion, care, and harmony among practitioners, both in formal practices like meditation and in everyday actions. By embracing all phenomena as interconnected and equal, we can awaken to our true nature as love and interconnectedness, leading to a more inclusive and compassionate society.", "themes": ["Buddha-nature", "Compassion", "Interconnection"], "texts": ["Shōbōgenzō"], "minutes": 41}, {"id": "2025-10-24 - Nomon Tim Burnett - Finding Your Middle Way", "title": "Finding Your Middle Way", "speaker": "Nomon Tim Burnett", "date": "2025-10-24", "series": "", "summary": "The talk explores the tension between intense spiritual practices and accessibility, suggesting that there may be value in balancing both approaches without problematic elements like misogyny and guru worship. The speaker notes that exploring this balance requires trust, patience, curiosity, and openness, encouraging the community to consider their own experiences and needs in finding a path that works for them. This approach can help navigate the complexities of spiritual practice, avoiding harm while still offering profound insights and healing.", "themes": ["Suffering"], "texts": ["Lotus Sutra"], "minutes": 51}, {"id": "2025-10-23 - Kanho Chris Burkhart - Zazen", "title": "Zazen", "speaker": "Kanho Chris Burkhart", "date": "2025-10-23", "series": "", "summary": "The talk's main teaching is that Zazen is not about achieving a specific state or escaping discomfort, but rather about stopping our tendency to run away from life and meeting it with awareness and openness. By turning towards what we'd rather avoid, we can discover peace and intimacy in the present moment, and cultivate a clear and open heart through gentle stability and relaxation of the body. This involves embracing difficulty and uncertainty, rather than trying to escape or control them, and instead finding tenderness and compassion by simply being with what is.", "themes": ["Acceptance", "Compassion"], "texts": [], "minutes": 45}, {"id": "2025-10-21 - Nomon Tim Burnett - No Gaining Idea", "title": "No Gaining Idea", "speaker": "Nomon Tim Burnett", "date": "2025-10-21", "series": "", "summary": "The main teaching of this Soto Zen dharma talk is about the importance of cultivating awareness and freedom in the present moment, without attachment to specific outcomes or goals. It emphasizes the need to let go of dualistic thinking and expectations, and instead, focus on simply being and giving generously to others. By doing so, we can find clarity and understanding that arises from within, and experience a sense of care and compassion for ourselves and others.", "themes": ["Emptiness"], "texts": ["Heart Sutra"], "minutes": 42}, {"id": "2025-10-01 - Hoka Chris Fortin - Sesshin Opening Sesshin", "title": "Sesshin Opening Sesshin", "speaker": "Hoka Chris Fortin", "date": "2025-10-01", "series": "", "summary": "The speaker reflects on their upcoming ordination and shares insights from various sources, including the Vimalakirti Sutra, to emphasize the importance of cultivating love, acceptance, and gratitude in the face of uncertainty and complexity. They encourage listeners to stay present and focused on their practice, just as Suzuki Roshi's story about Oka Sotan Roshi highlights the need to let go of distractions and stay mindful. By embracing humility, service, and kindness towards all beings, we can embody the true spirit of Buddha's way and bring benefit to all sentient beings.", "themes": ["Buddha-nature", "Compassion", "Sangha", "Social engagement"], "texts": ["Shōbōgenzō"], "minutes": 40}, {"id": "2025-09-27 - Nomon Tim Burnett - Practice Period Opening Sesshin at SansuiJi Temple", "title": "Practice Period Opening Sesshin at Sansui-Ji Temple", "speaker": "Nomon Tim Burnett", "date": "2025-09-27", "series": "", "summary": "The talk's main teaching emphasizes the importance of embracing one's own inherent wisdom and being present in the moment, rather than trying to achieve a specific state or goal. This approach encourages lay practitioners to take refuge in the Three Jewels with the intention of becoming like them, not seeking external validation, but rather remembering their true nature as Buddha. By cultivating curiosity, acceptance, and non-judgment, individuals can deepen their practice and find wisdom in everyday life, regardless of their background or circumstances.", "themes": ["Acceptance", "Buddha-nature", "Impermanence", "Sangha"], "texts": [], "minutes": 45}, {"id": "2025-09-19 - Nomon Tim Burnett - Self Power and Other Power", "title": "Self Power and Other Power", "speaker": "Nomon Tim Burnett", "date": "2025-09-19", "series": "", "summary": "The talk highlights the importance of recognizing the role of mystery and otherness in Zen practice, particularly when it comes to understanding Buddhist texts. Rather than relying solely on individual effort or self-power, Zen encourages us to acknowledge the larger forces at work, such as compassion and the interconnectedness of all phenomena. By embracing this perspective, we can deepen our understanding of the text and cultivate a more authentic and compassionate practice.", "themes": ["Compassion", "Interconnection"], "texts": [], "minutes": 48}, {"id": "2025-09-01 - Nomon Tim Burnett - A Temple of Paramitas", "title": "A Temple of Paramitas", "speaker": "Nomon Tim Burnett", "date": "2025-09-01", "series": "Paramitas", "summary": "The talk emphasizes the importance of generosity in Buddhist practice, not just as an external act of giving, but also as a way of cultivating inner qualities such as acceptance, understanding, and effort. This generosity is about reconnection and healing, recognizing that giving and receiving are part of a natural flow of energy and non-differentness. By embracing this practice, we can work towards a deeper sense of freedom, kindness, and awakening, even in the face of challenges and imperfections.", "themes": ["Ethics", "Interconnection", "Wisdom"], "texts": [], "minutes": 37}, {"id": "2025-08-24 - Nomon Tim Burnett - What are your intentions Opening the Temple", "title": "What are your intentions? (Opening the Temple)", "speaker": "Nomon Tim Burnett", "date": "2025-08-24", "series": "", "summary": "The speaker's main teaching is that true freedom and peace come from letting go of our attachment to specific outcomes and instead embracing the beauty of impermanence and uncertainty. By practicing mindfulness and presence, we can learn to be fully engaged with the present moment, taking care of ourselves and others with kindness and compassion, without striving for some idealized state or expectation. This approach encourages us to find peace in the midst of change and uncertainty, rather than trying to control or manipulate our experiences.", "themes": ["Buddha-nature", "Impermanence"], "texts": ["Lotus Sutra"], "minutes": 23}, {"id": "2025-08-12 - IkuShun Desiree Webster - Despair and the Bodisattva Vow", "title": "Despair and the Bodisattva Vow", "speaker": "IkuShun Desiree Webster", "date": "2025-08-12", "series": "", "summary": "The talk's main teaching is that despair can be a powerful catalyst for growth and freedom when acknowledged and worked through, rather than suppressed or avoided. By embracing our own wounds and hardships, we can cultivate compassion and connect with our greater selves, finding joy and healing in the midst of suffering. This approach is inspired by Joanna Macy's work on \"despair work,\" which recognizes that despair is a natural response to injustice and suffering, but also offers a path forward towards transformation and liberation.", "themes": ["Acceptance", "Compassion", "Social engagement", "Suffering"], "texts": [], "minutes": 25}, {"id": "2025-08-12 - Seiu Hannah Sullivan - a Tribute to Joanna Macy", "title": "A Tribute to Joanna Macy", "speaker": "Seiu Hannah Sullivan", "date": "2025-08-12", "series": "", "summary": "The talk's main teaching is that our spiritual practice should not be focused solely on opposing destructive actions, but rather on cultivating a deeper understanding of the interconnectedness of all beings and the world around us. By embracing the beauty and life even in the midst of destruction, we can develop a more nuanced and compassionate response to environmental degradation and social injustice. This approach encourages mindfulness, self-control, and a willingness to work for positive change without perpetuating harm, ultimately leading to a more harmonious relationship between ourselves and the world.", "themes": ["Emptiness", "Interconnection", "Social engagement"], "texts": [], "minutes": 29}, {"id": "2025-08-04 - Myoki Raizelah Bayen - Precept Eight NonBeing Stingy", "title": "Precept Eight - Non-Being Stingy", "speaker": "Myoki Raizelah Bayen", "date": "2025-08-04", "series": "", "summary": "The talk's main teaching invites listeners to explore the concept of \"non-being stingy\" by recognizing how we often hold onto things we perceive as lacking or scarce, such as tension, contraction, or scarcity of resources. By softening our hearts and embracing openness, we can cultivate a sense of generosity and receive freely, letting go of ignorance and interdependence. This practice is rooted in the precept of generosity, which encourages us to turn away from isolation and self-restriction, and instead embody kindness and relatedness in every moment.", "themes": ["Ethics", "Gratitude", "Interconnection"], "texts": [], "minutes": 27}, {"id": "2025-08-04 - Nomon Tim Burnett - Precept Ten NonAbusing the Three Treasures", "title": "Precept Ten - Non-Abusing the Three Treasures", "speaker": "Nomon Tim Burnett", "date": "2025-08-04", "series": "", "summary": "The speaker's main teaching emphasizes the importance of understanding reality as interconnected and interdependent, rather than trying to control or manipulate it through our thoughts and actions. This is reflected in the final precept of the 16 Bodhisattva Precepts, \"non-abusing the three treasures,\" which encourages us to recognize and release our own conditioning and biases. By letting go of these attachments, we can cultivate a sense of openness, acceptance, and trust, allowing us to be present and aware in the moment without judgment or distinction between ourselves and others.", "themes": ["Ethics", "Gratitude", "Interconnection"], "texts": [], "minutes": 22}, {"id": "2025-07-24 - Kanho Chris Burkhart - Invisible Scars and the Dharma of Women", "title": "Invisible Scars and the Dharma of Women", "speaker": "Kanho Chris Burkhart", "date": "2025-07-24", "series": "", "summary": "The talk's main teaching is that our perceptions and experiences are often influenced by internalized stories and conditioning, which can lead to self-doubt and disconnection from our true nature. By recognizing and challenging these projections, we can break free from delusion and reclaim our authentic selves through practices like zazen, allowing us to see reality as it truly is rather than what our brains expect based on our conditioning. This requires embracing our experiences and power, including those of women, without trying to soften or hide them, in order to embody the dharma and live a more authentic life.", "themes": ["No-self", "Suffering", "Vulnerability"], "texts": [], "minutes": 29}, {"id": "2025-07-12 - Kanho Chris Burkhart - The Womb and the Sword", "title": "The Womb and the Sword", "speaker": "Kanho Chris Burkhart", "date": "2025-07-12", "series": "", "summary": "The talk highlights the importance of recognizing and honoring the courage and strength of women throughout history who have defied societal norms and expectations to live lives of defiance, challenging traditional notions of femininity and the bodhisattva spirit. These stories serve as a counterpoint to traditional Buddhist narratives that often emphasize male practitioners' achievements, instead emphasizing the complexity and diversity of human experience. By honoring these women's experiences, we can cultivate compassion, clarity, and balance in our own lives, acknowledging both the violence and stillness that exist within us all.", "themes": ["No-self", "Social engagement"], "texts": ["Heart Sutra"], "minutes": 49}, {"id": "2025-07-07 - Myoki Raizelah Bayen - Precept Six Nontalking about Others Errors and Faults", "title": "Precept Six - Non-talking about Others' Errors and Faults", "speaker": "Myoki Raizelah Bayen", "date": "2025-07-07", "series": "", "summary": "The talk's main teaching is about cultivating awareness and compassion for ourselves and others, particularly when it comes to speaking negatively about or judging others. By practicing non-disparaging speech and approaching ourselves with kindness and compassion, we can see beyond our own biases and separateness, and develop a deeper understanding of the interconnected nature of all beings. This practice allows us to let go of our need for protection from others and instead find support in everyone and everything, leading to greater trust and peace.", "themes": ["Compassion", "Ethics", "Interconnection"], "texts": [], "minutes": 21}, {"id": "2025-07-07 - Nomon Tim Burnett - Precept Seven NonElevating Ones Self and Blaming Others", "title": "Precept Seven - Non-Elevating One's Self and Blaming Others", "speaker": "Nomon Tim Burnett", "date": "2025-07-07", "series": "", "summary": "The talk emphasizes the importance of embracing our imperfections and limitations, rather than trying to avoid or escape them. By cultivating humility, kindness, and acceptance towards ourselves and others, we can find true freedom and transformation. This involves letting go of ego and comparison, and instead recognizing that everyone is acting out their karma, including us.", "themes": ["Acceptance", "Ethics", "No-self"], "texts": [], "minutes": 30}, {"id": "2025-07-03 - Kanho Chris Burkhart - Reflections of the Mind", "title": "Reflections of the Mind", "speaker": "Kanho Chris Burkhart", "date": "2025-07-03", "series": "", "summary": "The speaker invites listeners to consider the idea that their experiences may be reflections of their own mind rather than objective reality, a concept rooted in Yogacara Buddhism. This understanding suggests that our perceptions are shaped by mental constructs, or \"projections,\" which can lead to suffering when we mistake them for reality and react instead of responding with compassion. By recognizing and letting go of these projections, listeners can cultivate a more open and clear perception of the world, leading to greater compassion and freedom.", "themes": ["Compassion", "Suffering", "Wisdom"], "texts": [], "minutes": 61}, {"id": "2025-07-02 - Kanho Chris Burkhart - Taking the Backward Step", "title": "Taking the Backward Step", "speaker": "Kanho Chris Burkhart", "date": "2025-07-02", "series": "", "summary": "The speaker encourages listeners to take a \"backward step\" in meditation, turning their attention inward to let go of external distractions and conditioning, and instead experience life more mindfully and authentically. By doing so, they can see the world and themselves in a new light, revealing the unity and interdependence that lies beneath dualistic thinking. This practice allows for a direct realization of reality, unencumbered by concepts and attachments, and reveals the true nature of the self as a luminous ground of being.", "themes": ["Interconnection", "No-self"], "texts": ["Shōbōgenzō"], "minutes": 37}, {"id": "2025-06-17 - Nomon Tim Burnett - Blanche Hartman Woman Ancestor", "title": "Blanche Hartman, Woman Ancestor", "speaker": "Nomon Tim Burnett", "date": "2025-06-17", "series": "", "summary": "The speaker shares a story about Blanche Greengold, a renowned sewing teacher and Dharma heir of Suzuki Roshi, who embodied the principles of Zen through her life and teachings. Blanche's approach to Zazen emphasized embracing imperfection and letting go of ego, rather than seeking personal comfort or friendliness. Through her guidance, the speaker reflects on the importance of cultivating mindfulness and awareness in everyday life, appreciating the beauty and love that surrounds us, and finding joy in the present moment.", "themes": ["Compassion", "Interconnection"], "texts": [], "minutes": 33}, {"id": "2025-06-17 - Zoketsu Norman Fischer - The Wisdom of Kanzeon", "title": "The Wisdom of Kanzeon", "speaker": "Zoketsu Norman Fischer", "date": "2025-06-17", "series": "", "summary": "The speaker's talk emphasizes the importance of cultivating gratitude and appreciation for the world around us, recognizing that everything has been given to us without expectation or entitlement. This mindset allows us to find peace, compassion, and bliss in the present moment, and recognizes that all thoughts, perceptions, and moments of consciousness are interconnected with the universe itself. By embracing this perspective, we can transcend our attachment to things and find freedom from suffering, and ultimately, death is not an end, but a transition to a new journey, where our loved ones continue to live on through us and others who remember them.", "themes": ["Emptiness", "Gratitude", "Impermanence"], "texts": ["Heart Sutra"], "minutes": 56}, {"id": "2025-06-16 - Zoketsu Norman Fischer - Opening the Hand of Thought", "title": "Opening the Hand of Thought", "speaker": "Zoketsu Norman Fischer", "date": "2025-06-16", "series": "", "summary": "The speaker's talk highlights how our perceptions of reality are shaped by our words, imagination, and technology, suggesting that there may be multiple kinds of \"real\" beyond what we can see and touch. They draw parallels between the complexities of Ireland's history and politics with the complexities of the world we live in today, emphasizing the importance of being present in the moment to find clarity and understanding. By letting go of our preconceptions and embracing impermanence, we can cultivate a sense of freedom and interconnectedness that transcends our individual experiences.", "themes": ["No-self", "Suffering"], "texts": ["Lotus Sutra"], "minutes": 49}, {"id": "2025-06-15 - Myoki Raizelah Bayen - Miaozhong on Silence", "title": "Miaozhong on Silence", "speaker": "Myoki Raizelah Bayen", "date": "2025-06-15", "series": "", "summary": "The main teaching of the Soto Zen dharma talk emphasizes the importance of letting go and studying the self to forget the self, encouraging listeners to cultivate awareness and openness through Zazen practice. By releasing attachment to thoughts and concepts, we can meet life's challenges with greater clarity and compassion, and find refuge in silence when needed. This approach invites us to explore our relationship with silence as a doorway to knowing the unknowable, rather than relying on words or intellectual understanding.", "themes": ["No-self"], "texts": [], "minutes": 31}, {"id": "2025-06-15 - Zoketsu Norman Fischer - What do you call the world", "title": "What do you call the world?", "speaker": "Zoketsu Norman Fischer", "date": "2025-06-15", "series": "", "summary": "The talk's main teaching emphasizes the importance of embracing unity, interconnectedness, and complete action in spiritual practice. It encourages listeners to let go of intellectual understanding and instead focus on doing one thing completely, without strategy or holding back, which includes all aspects of human activity. By cultivating a sense of purpose and meaning in everyday life, we can use our energy to make a positive impact on the world and find fulfillment in quiet, committed acts of kindness and compassion.", "themes": ["Compassion", "Emptiness", "Social engagement"], "texts": [], "minutes": 51}, {"id": "2025-06-14 - Nomon Tim Burnett - Breathing Deeply Master Zhiyis Meditation Instructions", "title": "Breathing Deeply, Master Zhiyi's Meditation Instructions", "speaker": "Nomon Tim Burnett", "date": "2025-06-14", "series": "", "summary": "The teacher emphasizes that true understanding of Buddhist teachings and practices requires a deep study and practice of meditation techniques, including breathing exercises like counting breaths. Simply memorizing enough to overcome obstacles is not enough; one must also cultivate a profound understanding of the scriptures and develop a genuine connection with their own mind and body through consistent practice. By doing so, practitioners can access deeper states of consciousness and gain new insights into the nature of reality.", "themes": [], "texts": ["Lotus Sutra"], "minutes": 46}, {"id": "2025-06-02 - Nomon Tim Burnett - Precept Five NonMisusing Intoxicants", "title": "Precept Five - Non-Misusing Intoxicants", "speaker": "Nomon Tim Burnett", "date": "2025-06-02", "series": "", "summary": "The talk's main teaching is that our perceptions of reality are often clouded by our own mental patterns, which can lead us astray from what is truly present in the moment. This can happen when we become \"hooked\" on certain thoughts or desires, causing us to overlook other states of being and miss out on opportunities for growth and understanding. By becoming more aware of these mental patterns and letting go of our attachment to them, we can begin to see things more clearly and cultivate a greater sense of presence and freedom in our daily lives.", "themes": ["Ethics", "No-self", "Suffering"], "texts": [], "minutes": 22}, {"id": "2025-05-23 - Seishu John Wiley - Moshan Liaoran", "title": "Moshan Liaoran", "speaker": "Seishu John Wiley", "date": "2025-05-23", "series": "", "summary": "The talk highlights the importance of approaching life with an open and non-judgmental mind, letting go of preconceptions and expectations. This is illustrated through stories of three women who have practiced Zen for many years, including Moshan Lioran, a 9th-century Chinese nun who taught that true understanding comes from personal experience and practice, rather than forced comprehension. By embracing life as it presents itself, we can cultivate equanimity and mindfulness in the face of challenges, leading to a more compassionate and authentic approach to everyday life.", "themes": ["Acceptance"], "texts": [], "minutes": 23}, {"id": "2025-05-15 - Joden Bob Rose - Kisa Gotami and Patacara Grief Suffering and the Path Forward", "title": "Kisa Gotami and Patacara – Grief, Suffering and the Path Forward", "speaker": "Joden Bob Rose", "date": "2025-05-15", "series": "", "summary": "The speaker explores the stories of two early Buddhist women, Kisagotami and Patakara, who exemplify a path to freedom from suffering and impermanence. Through their experiences, the Buddha reveals that attachment to things we love can lead to even more pain when they are lost, but by embracing impermanence, we can find peace and liberation. By examining these stories, we can gain insights into how to cultivate detachment, resilience, and inner freedom in the face of life's challenges and tragedies.", "themes": ["Compassion", "Impermanence", "Suffering"], "texts": [], "minutes": 29}, {"id": "2025-05-10 - Reizan Bob Penny - Life Death Time Place", "title": "Life, Death, Time, Place", "speaker": "Reizan Bob Penny", "date": "2025-05-10", "series": "", "summary": "The talk's main teaching is that true freedom and understanding come from being present in the moment and acknowledging our place in the world. By letting go of attachments and ego, we can tap into a deeper sense of compassion and connection with others and the natural world. The speaker encourages listeners to cultivate this awareness through meditation and mindfulness, reminding them that it's not about achieving some specific state or outcome, but rather about embracing the present moment with an open heart and mind.", "themes": ["Impermanence", "Sangha"], "texts": [], "minutes": 27}, {"id": "2025-05-05 - Myoki Raizelah Bayen - Precept Two NonStealing", "title": "Precept Two - Non-Stealing", "speaker": "Myoki Raizelah Bayen", "date": "2025-05-05", "series": "", "summary": "The speaker's main teaching emphasizes the importance of embracing a mindset of non-stealing, where giving and receiving are seen as two sides of the same coin, and there is no separation between entities. This understanding allows us to let go of feelings of entitlement and scarcity, and instead cultivate an openness to what is present in the moment. By adopting this mindset, we can accept more freely what is given and give more freely, leading to a sense of liberation and satisfaction that arises from embracing the present moment without attachment or expectation.", "themes": ["Acceptance", "Ethics", "Interconnection", "No-self"], "texts": [], "minutes": 25}, {"id": "2025-05-05 - Nomon Tim Burnett - Precept Three NonMisusing Sex", "title": "Precept Three - Non-Misusing Sex", "speaker": "Nomon Tim Burnett", "date": "2025-05-05", "series": "", "summary": "The talk explores the complexities of non-misusing sexuality, acknowledging that it's influenced by powerful forces like biology, fear, and avoidance, which can affect people regardless of their level of activity. The speaker encourages a nuanced understanding of this precept, urging listeners to cultivate self-awareness, kindness, and generosity in their relationships. By approaching sex and relationships with mindfulness and openness, individuals can develop a more grounded sensibility about their own sexuality over time, allowing them to navigate these complex forces with greater ease and positivity.", "themes": ["Acceptance", "Ethics", "Suffering"], "texts": [], "minutes": 27}, {"id": "2025-04-24 - Shin-yu Scott Allen - Chinoyo", "title": "Chinoyo", "speaker": "Shin-yu Scott Allen", "date": "2025-04-24", "series": "", "summary": "The talk's main teaching is that true understanding and connection arise when we let go of preconceived notions about others and instead see them as they truly are - not through labels or judgments, but by embracing their shared humanity. By doing so, we can transcend our individual selves and experience a sense of oneness with all things, just as the stories of Chiano and Nyazin demonstrate that enlightenment can arise in everyday life, even in mundane activities like carrying water or chopping wood. This approach allows us to connect more deeply with others and see reality as it truly is, without being limited by our own ego or preconceptions.", "themes": ["Buddha-nature", "Interconnection", "No-self"], "texts": ["Heart Sutra"], "minutes": 34}, {"id": "2025-04-20 - IkuShun Desiree Webster - Miaoxin and the Characteristic of Confidence", "title": "Miaoxin and the Characteristic of Confidence", "speaker": "IkuShun Desiree Webster", "date": "2025-04-20", "series": "", "summary": "The speaker emphasizes the importance of trusting our innate wisdom and experience, rather than relying on intellectual thinking. This trust allows us to break free from conceptual patterns and tap into a deeper sense of confidence and awareness, which can help us overcome fear and live more authentically. By cultivating this trust, we can deepen our connection to the present moment and keep ancient teachings relevant in our daily lives.", "themes": ["Buddha-nature", "Wisdom"], "texts": ["Shōbōgenzō"], "minutes": 24}, {"id": "2025-04-07 - Nomon Tim Burnett - Precept One NonKilling", "title": "Precept One - Non-Killing", "speaker": "Nomon Tim Burnett", "date": "2025-04-07", "series": "", "summary": "The talk emphasizes the importance of cultivating compassion and awareness in our daily lives by exploring the ten clear mind precepts. These precepts encourage us to consider how our actions can harm or kill not just living beings, but also people's spirits through judgment and separation. By embracing a more nuanced and compassionate approach, we can learn to nourish life rather than killing it, and deepen our connection with ourselves and others by recognizing and accepting our own patterns of suffering.", "themes": ["Acceptance", "Ethics", "Interconnection"], "texts": [], "minutes": 17}, {"id": "2025-03-31 - Myoki Raizelah Bayen - Maiozongs Fearlessness and Vulnerability", "title": "Maiozong's Fearlessness and Vulnerability", "speaker": "Myoki Raizelah Bayen", "date": "2025-03-31", "series": "", "summary": "The talk emphasizes the importance of cultivating a balanced and embodied awareness, letting go of boundaries and societal expectations to reveal one's true nature. This is reflected in Miao Zong's teachings on the \"Zazen body,\" which embodies qualities like openness, compassion, and strength. By embracing our fullness and presence, we can develop fearlessness and take responsibility for ourselves, allowing us to share our authentic selves with others and live more authentically.", "themes": ["Buddha-nature", "Vulnerability"], "texts": [], "minutes": 22}, {"id": "2025-03-28 - IkuShun Desiree Webster - The Warrior in All of Us", "title": "The Warrior in All of Us", "speaker": "IkuShun Desiree Webster", "date": "2025-03-28", "series": "", "summary": "The talk's main teaching is that true courage is not just about making a decision to act, but also about having clarity and understanding of what needs to be done in the moment. This clarity can arise from a deeper place within us, beyond our individual choices, and is often linked to a sense of being forced into action or responding to circumstances without hesitation. The speaker invites the audience to explore this idea further, suggesting that courage may not always come from making a conscious choice, but rather from a more profound understanding of what needs to be done in order to act with courage.", "themes": ["Social engagement", "Wisdom"], "texts": [], "minutes": 24}, {"id": "2025-03-28 - Seiu Hannah Sullivan - Baddha Kundalakesa", "title": "Baddha Kundalakesa", "speaker": "Seiu Hannah Sullivan", "date": "2025-03-28", "series": "", "summary": "The talk's main teaching is that true understanding and confidence come not from being able to answer all questions with certainty, but from embracing the mystery and uncertainty of life. The story of Bada Kundalakesa serves as a reminder that even in our most confident moments, we can be humbled by the limits of our knowledge. This experience can lead us to seek out new perspectives and wisdom, just as Bada did when she turned to the Buddha for guidance. By acknowledging our own uncertainty, we can cultivate a deeper sense of compassion and understanding for ourselves and others.", "themes": ["Impermanence", "Wisdom"], "texts": [], "minutes": 18}, {"id": "2025-03-06 - Kanho Chris Burkhart - Women Ancestors Known and Unknown", "title": "Women Ancestors, Known and Unknown", "speaker": "Kanho Chris Burkhart", "date": "2025-03-06", "series": "", "summary": "The speaker shares stories about women who found profound awakening through their struggles with loss and impermanence, illustrating the importance of cultivating compassion, understanding, and wisdom in the face of suffering. These stories highlight the impermanence of all things, including physical beauty and loved ones, and encourage listeners to find liberation by letting go of attachment and embracing the present moment. Through these tales, the speaker invites listeners to explore their own experiences with grief and loss, finding comfort in the understanding that true essence remains despite physical change.", "themes": ["Acceptance", "Impermanence", "Suffering"], "texts": [], "minutes": 53}, {"id": "2025-03-03 - Nomon Tim Burnett and Myoki Raizelah Bayen - The Three Pure Precepts", "title": "The Three Pure Precepts", "speaker": "Nomon Tim Burnett and Myoki Raizelah Bayen", "date": "2025-03-03", "series": "", "summary": "The main teaching of the Soto Zen dharma talk emphasizes embracing all aspects of ourselves, including our flaws and weaknesses, as a means of realizing awakened reality and cultivating compassion for ourselves and others. By welcoming and accepting our true nature, we can break free from self-clinging and rigid rules, and instead embody kindness, awareness, and harmony with the world around us. This practice is not about suppressing or overcoming our imperfections, but rather about embracing them as an opportunity to grow and deepen our connection with ourselves and others.", "themes": ["Acceptance", "Ethics", "Interconnection"], "texts": [], "minutes": 51}, {"id": "2025-02-23 - Kanho Chris Burkhart - Women in Zen Mahaprajapati Gautami", "title": "Women in Zen: Mahāprajāpatī Gautamī", "speaker": "Kanho Chris Burkhart", "date": "2025-02-23", "series": "", "summary": "The talk highlights the importance of recognizing and honoring the contributions of female monastics throughout Buddhist history, who played a significant role in spreading the Buddha's teachings and creating a rich tradition of monastic life for women. The Therigata, an ancient collection of poems, preserves the voices and experiences of early Buddhist nuns who achieved enlightenment through their practice, offering profound insights into the transformative power of the Dharma regardless of gender or social status. These women's stories show that true freedom can be found by letting go of attachments and embracing impermanence, a message that is still relevant today for all practitioners.", "themes": ["Impermanence", "Suffering", "Wisdom"], "texts": [], "minutes": 30}, {"id": "2025-02-15 - Myoki Raizelah Bayen - Taking Refuge in the Triple Treasures", "title": "Taking Refuge in the Triple Treasures", "speaker": "Myoki Raizelah Bayen", "date": "2025-02-15", "series": "", "summary": "The speaker's main teaching emphasizes the importance of cultivating a deep sense of unity and commitment within oneself by embracing the triple treasures of Soto Zen: the Buddha (our true nature), Dharma (the teachings that guide us), and Sangha (the community that supports us). This involves not just external practices, but also an inner transformation that allows us to live as vow, embodying the values of compassion, wisdom, and interconnectedness. By taking refuge in these three treasures, we can find peace, comfort, and connection with others, while also working to preserve and protect all beings through our daily lives.", "themes": ["Buddha-nature", "Interconnection", "Sangha"], "texts": [], "minutes": 22}, {"id": "2025-02-15 - Seiu Hannah Sullivan - Everyday Vowing Renunciation and Repentance", "title": "Everyday Vowing: Renunciation and Repentance", "speaker": "Seiu Hannah Sullivan", "date": "2025-02-15", "series": "", "summary": "The speaker's main teaching emphasizes the importance of cultivating compassion and kindness in the face of suffering, whether it comes from within or from the world around us. By prioritizing our own well-being and practicing mindfulness, we can better navigate life's challenges and find ways to live with greater ease and understanding. This involves embracing our humanity and imperfections, rather than trying to achieve perfection, and instead focusing on working with what we have to recover our original self through devotion to kindness and support of others.", "themes": ["Acceptance", "Compassion", "Ethics"], "texts": [], "minutes": 20}, {"id": "2025-02-03 - Nomon Tim Burnett - Practicing in Troubled Times", "title": "Practicing in Troubled Times", "speaker": "Nomon Tim Burnett", "date": "2025-02-03", "series": "", "summary": "The speaker shares a personal story about visiting a rural village in Kenya where community support led to a profound impact on the villagers' lives, highlighting the importance of local knowledge and collective action in addressing global issues like poverty and climate change. This experience is reflected upon as a reminder that true change starts at home and requires self-care and compassion. The speaker encourages listeners to consider their own role in responding to suffering and promoting kindness, suggesting that even small acts can have a significant impact when guided by wisdom and awareness.", "themes": ["Compassion", "Social engagement", "Wisdom"], "texts": [], "minutes": 35}, {"id": "2025-01-26 - Nomon Tim Burnett - Ananda Says Yes Keizans Denkoroku talk3", "title": "Ananda Says Yes! Keizan's Denkoroku, talk3", "speaker": "Nomon Tim Burnett", "date": "2025-01-26", "series": "", "summary": "The talk highlights the importance of embracing the present moment and letting go of attachments and ego. A story from Buddhist history illustrates that true understanding comes from within and is not dependent on external authorities or transmission of knowledge. By sharing this story, the speaker aims to convey the value of releasing one's need for control or validation and cultivating a sense of presence and engagement in the current moment.", "themes": ["No-self", "Vulnerability"], "texts": [], "minutes": 44}, {"id": "2025-01-22 - Nomon Tim Burnett - Everyday Tea and Rice", "title": "Everyday Tea and Rice", "speaker": "Nomon Tim Burnett", "date": "2025-01-22", "series": "", "summary": "The main teaching of this Soto Zen dharma talk emphasizes the importance of approaching everyday activities with mindfulness and awareness, rather than getting stuck in intellectual analysis or preconceived notions about spiritual practice. By rediscovering the wonder and magic in mundane tasks like eating and drinking, we can cultivate a deeper sense of connection to ourselves and the world around us. This approach is rooted in Dogen's concept of \"everyday activity,\" which suggests that even ordinary activities can be a form of spiritual practice when done with intention and awareness.", "themes": ["Acceptance", "Compassion"], "texts": ["Shōbōgenzō"], "minutes": 31}, {"id": "2025-01-19 - Nomon Tim Burnett - Our Ancestor Keizan", "title": "Our Ancestor, Keizan", "speaker": "Nomon Tim Burnett", "date": "2025-01-19", "series": "", "summary": "The talk's main teaching is that true awakening and harmony with others is not something we achieve through individual effort or thought, but rather it is an inherent and interconnected aspect of all phenomena. By letting go of our attachments to concepts and thoughts, we can come to see the world and ourselves as part of a larger web of relationships, where distinctions between \"I\" and \"others\" are not fixed or separate. This understanding allows us to embody the qualities of Buddha in our daily lives, cultivating a more open, kind, and compassionate heart.", "themes": ["Interconnection", "No-self"], "texts": ["Shōbōgenzō"], "minutes": 47}, {"id": "2024-12-12 - Kanho Chris Burkhart - Valley Sounds Mountain Colors", "title": "Valley Sounds, Mountain Colors", "speaker": "Kanho Chris Burkhart", "date": "2024-12-12", "series": "", "summary": "The talk invites practitioners to transcend dualistic thinking by embracing the world as an ongoing manifestation of awakening itself, where practice is not something separate from reality but rather an expression of it. By fully engaging with each moment without striving for something beyond it, we can align ourselves with the flow of Dharma and experience the living teachings of Buddha nature. This means transforming our daily experiences into opportunities for spiritual growth, doing everything with a sense of wonder and openness, and recognizing that awakening is already present in this moment.", "themes": ["Buddha-nature", "Interconnection"], "texts": ["Shōbōgenzō"], "minutes": 29}, {"id": "2024-12-08 - Nomon Tim Burnett - Practicing with Love in a Broken World", "title": "Practicing with Love in a Broken World", "speaker": "Nomon Tim Burnett", "date": "2024-12-08", "series": "", "summary": "The talk's main teaching is that by cultivating a big view of reality, understanding our place within it, and responding with calmness and kindness in the present moment, we can reduce suffering and find meaning in life. This involves acknowledging the challenges that every life faces, including difficult situations and choices, and being aware of how our actions may contribute to suffering. By embracing this approach, we can navigate complex issues like economic inequality and trauma with greater clarity and compassion, and find fulfillment on our own unique path, free from comparison or pressure to conform to traditional expectations.", "themes": ["Compassion", "Social engagement", "Wisdom"], "texts": [], "minutes": 32}, {"id": "2024-12-04 - Nomon Tim Burnett - Practice is Everywhere Fall Samish Sesshin talk two", "title": "Practice is Everywhere (Fall Samish Sesshin talk two)", "speaker": "Nomon Tim Burnett", "date": "2024-12-04", "series": "", "summary": "The talk emphasizes the importance of integrating Zen practice into everyday life, rather than just focusing on zendo activities. This can be done through rituals like dokusan and oryoki, which offer opportunities to connect with others and learn about impermanence and relative truth. By engaging in these practices and finding ways to apply them in daily life, individuals can cultivate mindfulness, awareness, and compassion, and embody the qualities of bodhisattvas.", "themes": ["Compassion", "Impermanence", "Sangha"], "texts": [], "minutes": 50}, {"id": "2024-12-02 - Nomon Tim Burnett - Practicing with Whats Here Fall Samish Sesshin talk one", "title": "Practicing with What's Here (Fall Samish Sesshin talk one)", "speaker": "Nomon Tim Burnett", "date": "2024-12-02", "series": "", "summary": "The talk emphasizes the importance of embracing impermanence and uncertainty, rather than trying to control or predict the future. True fulfillment comes from cultivating kindness, warmth, and love in the present moment, rather than striving for some idealized state. By letting go of attachments and judgments, we can truly appreciate the beauty of life as it is, and find peace and connection with others.", "themes": ["Acceptance", "Impermanence", "Vulnerability"], "texts": ["Shōbōgenzō"], "minutes": 40}, {"id": "2024-11-27 - Nomon Tim Burnett - Dogens Japan Journals Part 3", "title": "Dogen's Japan Journals, Part 3", "speaker": "Nomon Tim Burnett", "date": "2024-11-27", "series": "Dogen's Japan Journals", "summary": "Master Dogen shared teachings from his Chinese teacher Rujing on practical aspects of zazen practice, emphasizing the importance of maintaining awareness without attachment while letting go of all ideas of who we are. This \"dropping off body and mind\" concept allows for a more authentic and compassionate practice, where one can cultivate flexibility of mind and heart. By releasing attachments to our conceptual selves, we can tap into a deeper understanding of ourselves and the world, recognizing impermanence as a fundamental aspect of reality that leads to compassion and interconnectedness.", "themes": ["Compassion", "Emptiness", "Interconnection"], "texts": [], "minutes": 36}, {"id": "2024-11-26 - Nomon Tim Burnett - Dogens Japan Journals Part 2", "title": "Dogen's Japan Journals, Part 2", "speaker": "Nomon Tim Burnett", "date": "2024-11-26", "series": "Dogen's Japan Journals", "summary": "The talk's main teaching emphasizes the importance of cultivating mindfulness and awareness in everyday life, particularly by letting go of external expectations and binary thinking. Rather than focusing on what we should or shouldn't do, we can learn to be present with ourselves and others, embracing both light and darkness without judgment. By doing so, we can tap into our inner spark and find true peace and fulfillment, rather than relying on external circumstances or trying to fix or avoid certain aspects of life.", "themes": ["Acceptance", "Buddha-nature"], "texts": [], "minutes": 47}, {"id": "2024-10-17 - Nomon Tim Burnett - Dogens Japan Journals Part 1", "title": "Dogen's Japan Journals, Part 1", "speaker": "Nomon Tim Burnett", "date": "2024-10-17", "series": "Dogen's Japan Journals", "summary": "The speaker discusses Master Dogen's writings and introduces the concept of \"Hōkyōki,\" which highlights the importance of asking for guidance and support in one's spiritual practice, rather than relying solely on self-study or memorization of scriptures. This approach is rooted in the idea that true understanding and healing come from recognizing our own wholeness and imperfection, and that practice can help us cultivate this awareness. By embracing a humble and open-minded approach to spiritual growth, we can move beyond nihilistic views of Buddhism as achieving nothing, and instead find meaning and purpose in the present moment.", "themes": ["Buddha-nature", "Impermanence", "Vulnerability"], "texts": ["Shōbōgenzō"], "minutes": 59}, {"id": "2024-09-26 - Kanho Chris Burkhart - If It Is Without Love It Is Not The Precepts", "title": "If It Is Without Love, It Is Not The Precepts", "speaker": "Kanho Chris Burkhart", "date": "2024-09-26", "series": "", "summary": "The speaker's main teaching emphasizes the importance of understanding and applying Buddhist precepts in a genuine and compassionate way, rather than simply following rules or external expectations. By grasping the true meaning behind these precepts, practitioners can cultivate a deeper sense of awareness and mindfulness in their daily lives. This understanding is also facilitated through practices like koan study, which help to reveal the complexities of the self and others, leading to greater compassion and wisdom.", "themes": ["Compassion", "Ethics"], "texts": ["Shōbōgenzō"], "minutes": 30}, {"id": "2024-09-21 - Seiu Hannah Sullivan - Opening to Joy", "title": "Opening to Joy", "speaker": "Seiu Hannah Sullivan", "date": "2024-09-21", "series": "", "summary": "The speaker's main teaching is that cultivating joy and positivity in our lives can shift our experience of challenges, helping us to approach difficulties with a more hopeful and well-being-oriented attitude. By reflecting on what brings us joy and practicing daily reminders of positivity, we can develop an inner state that allows us to appreciate the good fortune of others and find happiness even in difficult circumstances. This approach is rooted in the concept of mudita, or sympathetic joy, which requires overcoming self-preoccupation and envy to cultivate true appreciation for others' good fortune.", "themes": ["Compassion", "Interconnection"], "texts": [], "minutes": 32}, {"id": "2024-09-19 - Myoki Raizelah Bayen - The Verse of Repentance", "title": "The Verse of Repentance", "speaker": "Myoki Raizelah Bayen", "date": "2024-09-19", "series": "", "summary": "In this dharma talk, the main teaching is that true repentance involves acknowledging and taking responsibility for our own and others' suffering caused by greed, hate, and delusion - the fundamental causes of our conditioned self. It's not just about apologizing or feeling remorse, but rather about embracing the regret, grief, and sorrow that arises from recognizing our interconnectedness with all beings. This requires a non-judgmental and open-hearted approach, acknowledging our humanness and the imperfections that come with it, while also taking full responsibility for our actions and their impact on others.", "themes": ["Ethics", "Suffering", "Vulnerability"], "texts": [], "minutes": 18}, {"id": "2024-09-12 - Nomon Tim Burnett - Mountains and Waters", "title": "Mountains and Waters", "speaker": "Nomon Tim Burnett", "date": "2024-09-12", "series": "", "summary": "The speaker shares a Native American story called \"Jumping Mouse\" about a mouse who discovers new insights and perspectives through exploration and understanding, illustrating the idea that our perceptions can be expanded beyond our individual limits. The story teaches us to approach life with humility and openness, recognizing that our experiences are interconnected and that we have the power to transform ourselves and others. By embracing this perspective, we can heal and connect with one another, ultimately realizing our shared nature as \"eagles\" in spirit.", "themes": ["Buddha-nature", "Compassion"], "texts": ["Shōbōgenzō"], "minutes": 25}, {"id": "2024-08-29 - Kanho Chris Burkhart - Dogens Places", "title": "Dogen's Places", "speaker": "Kanho Chris Burkhart", "date": "2024-08-29", "series": "", "summary": "The main teaching of this Soto Zen dharma talk is that true spiritual growth and understanding come from embracing a simple, authentic way of life that allows for continuous practice and connection with one's original nature. Dogen's journey, marked by his departure from traditional Buddhist practices and establishment of new temples in natural environments, illustrates the importance of finding a conducive setting for spiritual growth. By letting go of attachments and distractions, we can tap into our true nature and find meaning in everyday moments, just as Dogen did before his passing at age 53.", "themes": ["Impermanence"], "texts": ["Shōbōgenzō"], "minutes": 36}, {"id": "2024-08-22 - Joden Bob Rose - Dogens Instructions to the Cook", "title": "Dogen's Instructions to the Cook", "speaker": "Joden Bob Rose", "date": "2024-08-22", "series": "", "summary": "The speaker emphasizes the importance of fully engaging with each moment and object, regardless of its nature, as a means to cultivate mindfulness, compassion, and true Buddha joy. This approach is not limited to meditation or spiritual practices, but can be applied to all aspects of life, including ordinary activities like cooking, which should be done with devotion, responsibility, and a non-discriminating attitude. By embracing this practice, one can realize the self becoming the self in full engagement with the relative world and achieve a sense of freedom from anxiety and compassion.", "themes": ["Compassion", "Gratitude", "Sangha"], "texts": ["Shōbōgenzō"], "minutes": 25}, {"id": "2024-08-15 - Seishu John Wiley - Fascicle Number 93 Birth and Death", "title": "Fascicle Number 93 - Birth and Death", "speaker": "Seishu John Wiley", "date": "2024-08-15", "series": "", "summary": "The talk's main teaching emphasizes the importance of embracing birth and death as an integral part of life, rather than trying to avoid or escape them. By letting go of attachments and desires, we can cultivate a present-moment awareness that allows us to face challenges with equanimity and compassion. This approach is seen as a path to enlightenment and becoming a Buddha, free from the constraints of birth and death, and it's illustrated through personal reflections on the speaker's own experiences with loss and their father's life story.", "themes": ["Acceptance", "Compassion", "Impermanence"], "texts": ["Shōbōgenzō"], "minutes": 23}, {"id": "2024-08-01 - IkuShun Desiree Webster - The Self That is Only the Self", "title": "The Self That is Only the Self", "speaker": "IkuShun Desiree Webster", "date": "2024-08-01", "series": "", "summary": "In a Soto Zen dharma talk, the speaker emphasizes the importance of direct experience and mindfulness practice to reveal our true nature. By letting go of conceptualization and embracing upright posture in zazen, we can tap into a deeper sense of self that is connected with everything, beyond individual preferences and opinions. This understanding is not about achieving enlightenment, but rather about embracing the present moment and allowing reality to unfold as it is, without gap or separation between appearance and reality.", "themes": ["Buddha-nature", "No-self", "Vulnerability"], "texts": ["Heart Sutra", "Shōbōgenzō"], "minutes": 25}, {"id": "2024-07-25 - Kanho Chris Burkhart - Zazen Nonduality and Interconnectedness", "title": "Zazen, Non-duality and Interconnectedness", "speaker": "Kanho Chris Burkhart", "date": "2024-07-25", "series": "", "summary": "The talk's main teaching emphasizes the importance of cultivating mindfulness and awareness in everyday life through Zazen practice, which is not just about achieving enlightenment but also about transcending intellectual understanding and ritualistic behavior. Dogen's teachings on non-dual nature and interconnectedness highlight that all aspects of existence are intertwined, cutting through delusions to reveal a deeper reality. By embracing this perspective, one can transcend dualistic thinking and recognize the interconnectedness of all beings, leading to a more profound understanding of oneself and the world.", "themes": ["Buddha-nature", "Interconnection", "Sangha"], "texts": ["Shōbōgenzō"], "minutes": 39}, {"id": "2024-07-18 - Seiu Hannah Sullivan - Mountains and Waters", "title": "Mountains and Waters", "speaker": "Seiu Hannah Sullivan", "date": "2024-07-18", "series": "", "summary": "The talk's main teaching invites listeners to let go of their preconceptions and connect with reality as it is, without conceptual thinking or interpretation. By embracing the present moment and finding unity with all things, including nature, we can discover freedom and completeness. This involves recognizing that the observer and observed are one and the same, and honoring life's impermanence by being fully engaged and mindful in the current moment.", "themes": ["Impermanence", "Interconnection"], "texts": ["Diamond Sutra", "Shōbōgenzō"], "minutes": 28}, {"id": "2024-07-11 - Myoki Raizelah Bayen - Limitation is a Doorway to the Unbound Self", "title": "Limitation is a Doorway to the Unbound Self", "speaker": "Myoki Raizelah Bayen", "date": "2024-07-11", "series": "", "summary": "The talk's main teaching emphasizes the importance of embracing limitations and letting go of attachment and aversion in order to connect with a more unbound experience of life. This can be achieved by recognizing that our struggles and frustrations are not obstacles to overcome, but rather doorways to a deeper understanding of ourselves and the world around us. By surrendering our need for control and perfection, we can break open to new possibilities and find home and compassion in the present moment.", "themes": ["Acceptance", "Vulnerability"], "texts": ["Shōbōgenzō"], "minutes": 26}, {"id": "2024-06-27 - Kanho Chris Burkhart - Dogens Time and Reality", "title": "Dogen's Time and Reality", "speaker": "Kanho Chris Burkhart", "date": "2024-06-27", "series": "", "summary": "In Soto Zen teachings, Dogen challenges our conventional understanding of time as a linear progression by suggesting that reality and time are intertwined and inseparable. This means that every moment is a complete manifestation of existence, and our actions in each present moment resonate throughout time, affecting past and future. By embracing this non-dualistic understanding through meditation and mindfulness practices like Zazen, we can experience the fluid nature of reality and cultivate a deeper sense of interconnectedness with all things.", "themes": ["Impermanence", "Interconnection"], "texts": ["Shōbōgenzō"], "minutes": 21}, {"id": "2024-06-21 - Zoketsu Norman Fischer - Trust in Mind Part 3", "title": "Trust in Mind - Part 3", "speaker": "Zoketsu Norman Fischer", "date": "2024-06-21", "series": "Trust in Mind", "summary": "The main teaching of this Soto Zen dharma talk emphasizes the importance of letting go of our limited perspectives and preferences in order to live reality as it truly is. By cultivating mindfulness and presence, we can transcend our conceptualized understanding of the world and instead see life with fresh eyes, free from judgment or attachment. This allows us to navigate life's challenges with greater ease, comfort, and wisdom, rather than trying to force ourselves towards some external goal of enlightenment.", "themes": ["Emptiness", "No-self"], "texts": ["Heart Sutra"], "minutes": 50}, {"id": "2024-06-20 - Nomon Tim Burnett - Points to Watch in Practicing the Way Part 3", "title": "Points to Watch in Practicing the Way - Part 3", "speaker": "Nomon Tim Burnett", "date": "2024-06-20", "series": "Points to Watch in Practicing the Way", "summary": "The speaker's talk emphasizes the importance of confronting painful histories and acknowledging one's own privilege and responsibility as a Bodhisattva practitioner. This involves learning from and listening to marginalized voices, rather than seeking personal gain or recognition. By doing so, we can cultivate compassion, trust, and understanding, creating space for others to find their own healing and depth.", "themes": ["Compassion", "Emptiness", "Social engagement"], "texts": ["Heart Sutra", "Shōbōgenzō"], "minutes": 57}, {"id": "2024-06-19 - Zoketsu Norman Fischer - Trust in Mind Part 2", "title": "Trust in Mind - Part 2", "speaker": "Zoketsu Norman Fischer", "date": "2024-06-19", "series": "Trust in Mind", "summary": "The talk's main teaching is that true understanding and freedom come from letting go of dualistic thinking and attachments, and instead embracing the present moment without preconceptions or expectations. By stopping our tendency to analyze and judge, we can tap into a deeper sense of clarity and equanimity that transcends words and concepts. This presence allows us to transform our lives and the world around us, and is always available when we let go of our dualistic thinking and simply be with what is.", "themes": ["Acceptance", "Impermanence", "Suffering"], "texts": [], "minutes": 51}, {"id": "2024-06-18 - Nomon Tim Burnett - Points to Watch in Practicing the Way Part 2", "title": "Points to Watch in Practicing the Way - Part 2", "speaker": "Nomon Tim Burnett", "date": "2024-06-18", "series": "Points to Watch in Practicing the Way", "summary": "The speaker shares that true understanding and awakening come from letting go of preconceived notions and ego, and instead embracing the present moment as it is. This involves cultivating a mindset that sees impermanence and interdependence, rather than trying to control or manipulate situations. By doing so, we can develop a sense of compassion and wisdom that allows us to navigate life's challenges with greater ease and clarity.", "themes": ["Acceptance", "Impermanence"], "texts": [], "minutes": 51}, {"id": "2024-06-17 - Zoketsu Norman Fischer - Trust in Mind Part 1", "title": "Trust in Mind - Part 1", "speaker": "Zoketsu Norman Fischer", "date": "2024-06-17", "series": "Trust in Mind", "summary": "The talk's main teaching emphasizes the importance of trusting one's true nature and letting go of grasping and rejecting, which is rooted in recognizing the subtle tendency to cling and reject. By embracing this reality and practicing equanimity, we can awaken to a more authentic and peaceful way of living, where every moment is accepted as it is without resistance or attachment. This involves seeing things as they are, without judgment or attachment, and cultivating a mind that is stable, flexible, and free from discrimination.", "themes": ["Acceptance", "Compassion", "Suffering"], "texts": ["Blue Cliff Record"], "minutes": 51}, {"id": "2024-06-16 - Kanho Chris Burkhart - Eihei Dogens Kindness and Compassion", "title": "Eihei Dogen's Kindness and Compassion", "speaker": "Kanho Chris Burkhart", "date": "2024-06-16", "series": "", "summary": "The talk emphasizes the importance of integrating mindfulness and compassion into daily life, inspired by Dogen Zenji's teachings. By cultivating awareness and non-judgmental acceptance, one can bring clarity and peace to their inner state, effectively ending internal conflict. This approach encourages a universal awakening, where individual existence is seen as interconnected with others, fostering compassion and compassionate action in all aspects of life.", "themes": ["Buddha-nature", "Compassion", "Interconnection"], "texts": ["Shōbōgenzō"], "minutes": 48}, {"id": "2024-06-15 - Nomon Tim Burnett - Points to Watch in Practicing the Way Part 1", "title": "Points to Watch in Practicing the Way - Part 1", "speaker": "Nomon Tim Burnett", "date": "2024-06-15", "series": "Points to Watch in Practicing the Way", "summary": "The speaker encourages participants to approach their Soto Zen practice with humility and awareness, recognizing that even small actions can be opportunities for mindfulness and growth. They emphasize the importance of letting go of attachments to roles and identities within the sangha, and instead cultivating flexibility and kindness towards oneself and others. By embracing impermanence and the complexity of human experience, practitioners can develop a more authentic and compassionate approach to their practice, one that is grounded in acceptance and patience rather than rigid thinking or attachment.", "themes": ["Acceptance", "Impermanence"], "texts": [], "minutes": 56}, {"id": "2024-06-13 - Nomon Tim Burnett - The Dharma of Zen Poetry", "title": "The Dharma of Zen Poetry", "speaker": "Nomon Tim Burnett", "date": "2024-06-13", "series": "", "summary": "The talk explores how Zen poetry conveys the essence of Zen through simple and direct language, revealing the realization of its writers through their writings. The poems often express fundamental Buddhist concepts such as impermanence, suffering, and non-self, encouraging readers to slow down and experience the present moment. By embracing these themes, we can cultivate mindfulness, presence, and connection with nature, ultimately letting go of worldly attachments and distractions that distract us from our spiritual practice.", "themes": ["Impermanence", "No-self", "Suffering"], "texts": [], "minutes": 26}, {"id": "2024-05-27 - Kanho Chris Burkhart and IkuShun Desiree Webster - The Surangama Sutra Class Part 6", "title": "The Surangama Sutra (Class Part 6)", "speaker": "Kanho Chris Burkhart and IkuShun Desiree Webster", "date": "2024-05-27", "series": "The Surangama Sutra", "summary": "The talk emphasizes the importance of recognizing and transcending the ego and its attachments in Buddhist practice, rather than becoming overly identified with spiritual experiences or states. This includes being aware of the \"demonic\" tendencies that can arise from advanced practice, which are not external entities but rather manifestations of one's own nature. By cultivating a clear understanding of reality and letting go of attachment to specific states or identities, practitioners can move beyond ego-based limitations and achieve true liberation.", "themes": ["No-self", "Wisdom"], "texts": [], "minutes": 39}, {"id": "2024-05-19 - Nomon Tim Burnett - Dogens Heart of the Way", "title": "Dogen's Heart of the Way", "speaker": "Nomon Tim Burnett", "date": "2024-05-19", "series": "", "summary": "The main teaching of this Soto Zen dharma talk emphasizes the importance of cultivating a genuine, non-dualistic mind that embodies the true nature of reality, as explored through Dogen's teachings. This involves embracing interconnectedness and impermanence, and finding practical ways to cultivate wholesome qualities such as mindfulness, devotion, and humility. By doing so, one can deepen their understanding of the Buddha way and realize a more authentic expression of themselves.", "themes": ["Impermanence", "Sangha"], "texts": ["Lotus Sutra", "Shōbōgenzō"], "minutes": 39}, {"id": "2024-05-13 - Kanho Chris Burkhart and IkuShun Desiree Webster - The Surangama Sutra Class Part 4", "title": "The Surangama Sutra (Class Part 4)", "speaker": "Kanho Chris Burkhart and IkuShun Desiree Webster", "date": "2024-05-13", "series": "The Surangama Sutra", "summary": "The speaker emphasizes the importance of turning inward and listening to one's own nature, rather than being distracted by external sounds or desires. This is a key principle taught by Bodhisattva Avalokiteshvara, who embodies the power of compassion and wisdom. By cultivating this inner awareness, we can transcend ordinary limitations and find freedom from our attachments and distractions, allowing us to embody the qualities of compassion and wisdom in our daily lives.", "themes": ["Compassion", "Ethics"], "texts": [], "minutes": 35}, {"id": "2024-05-06 - Kanho Chris Burkhart and IkuShun Desiree Webster - The Surangama Sutra Class Part 3", "title": "The Surangama Sutra (Class Part 3)", "speaker": "Kanho Chris Burkhart and IkuShun Desiree Webster", "date": "2024-05-06", "series": "The Surangama Sutra", "summary": "The main teaching of the Soto Zen dharma talk is that true understanding and liberation from suffering arise not from adding new knowledge or concepts, but from recognizing and transcending our fundamental misconceptions about reality. Our perceptions are inherently clouded by our ego and delusions, but by cultivating awareness and concentration, we can see through these distortions and reveal the true nature of reality, which is interconnected and interdependent. This understanding allows us to let go of our attachments and limitations, and find freedom from the cycle of birth and death.", "themes": ["Buddha-nature", "No-self"], "texts": [], "minutes": 85}, {"id": "2024-04-29 - Kanho Chris Burkhart and IkuShun Desiree Webster - The Surangama Sutra Class Part 2", "title": "The Surangama Sutra (Class Part 2)", "speaker": "Kanho Chris Burkhart and IkuShun Desiree Webster", "date": "2024-04-29", "series": "The Surangama Sutra", "summary": "The talk's main teaching is that our true nature is not something we can grasp or conceptualize, but rather it is beyond all dualities and limitations. By cultivating awareness and seeing things as they truly are, we can let go of our preconceptions and distinctions, revealing a deeper understanding of reality that is empty yet full, interconnected yet independent. This understanding allows us to see the world with fresh eyes, unencumbered by our conditioned perceptions, and connect with the ultimate reality that lies beyond all conceptual thinking.", "themes": ["Buddha-nature", "Emptiness"], "texts": ["Heart Sutra", "Shōbōgenzō"], "minutes": 68}, {"id": "2024-04-25 - Nomon Tim Burnett - Just As It Is", "title": "Just As It Is", "speaker": "Nomon Tim Burnett", "date": "2024-04-25", "series": "", "summary": "The talk's main teaching emphasizes the importance of cultivating \"suchness\" or appreciation for things as they truly are, rather than trying to grasp them intellectually. This is achieved through direct experience and engagement with ordinary experiences, such as nature or everyday objects, which can help awaken us to their true nature. By letting go of our preconceptions and embracing reality as it is, we can develop a deeper sense of awareness and understanding that transcends intellectual comprehension.", "themes": ["Buddha-nature"], "texts": [], "minutes": 24}, {"id": "2024-04-22 - Kanho Chris Burkhart and IkuShun Desiree Webster - The Surangama Sutra Class Part 1", "title": "The Surangama Sutra (Class Part 1)", "speaker": "Kanho Chris Burkhart and IkuShun Desiree Webster", "date": "2024-04-22", "series": "The Surangama Sutra", "summary": "The teacher invites listeners to consider whether their perceptions of reality may be an illusion, and if they are willing to explore this understanding through practices like meditation and ethical conduct. This exploration can lead to a transformation of one's understanding and way of life, potentially revealing the inherent potential for enlightenment within themselves. By examining their own mind and letting go of attachments to temporary mental processes, listeners may discover a more profound reality that lies beyond perceived distinctions.", "themes": ["Buddha-nature", "No-self"], "texts": [], "minutes": 89}, {"id": "2024-04-18 - Kanho Chris Burkhart - Opening The Heart", "title": "Opening The Heart", "speaker": "Kanho Chris Burkhart", "date": "2024-04-18", "series": "", "summary": "The speaker's talk centered around the Heart Sutra, a Buddhist teaching that emphasizes the interconnectedness of all phenomena and the lack of a separate self. By exploring the concept of emptiness, which is central to the sutra, listeners can gain insight into how our perceptions of form, sensation, perception, and consciousness are not independent entities, but rather intertwined aspects of reality. This understanding can bring relief from suffering by dissolving the notion of a heavy burden or separate self, allowing us to experience life in a more authentic and liberated way.", "themes": ["Compassion", "Emptiness", "Suffering"], "texts": ["Heart Sutra"], "minutes": 20}, {"id": "2024-04-11 - Kanho Chris Burkhart - Declaration of Interdependence", "title": "Declaration of Interdependence", "speaker": "Kanho Chris Burkhart", "date": "2024-04-11", "series": "", "summary": "The talk's main teaching is that true freedom and peace come from embracing impermanence and letting go of fixed ideas and fear. By acknowledging our interconnectedness with all beings and accepting the natural unfolding of life, we can cultivate a deeper appreciation for its beauty and find comfort in the present moment. This includes embracing pain and grief as opportunities for growth, rather than trying to avoid or suppress them, and finding solace in the gentle guidance of death that brings us back to our true nature.", "themes": ["Gratitude", "Impermanence", "Interconnection"], "texts": [], "minutes": 17}, {"id": "2024-04-04 - Seishu John Wiley - The Teachings of Sojun Mel Weitsman", "title": "The Teachings of Sojun Mel Weitsman", "speaker": "Seishu John Wiley", "date": "2024-04-04", "series": "", "summary": "The speaker finds value in structured forms within Soto Zen practice, which they believe helps them cultivate a deeper meditation experience by limiting choices and forcing them to respond mindfully to limitations. This approach allows their mind to soften and conform to the practice, becoming more authentic. By embracing this structure, they can balance active effort with passive openness, allowing for greater clarity and calm in both meditation and daily life.", "themes": ["Acceptance", "Suffering"], "texts": [], "minutes": 26}, {"id": "2024-03-21 - Nomon Tim Burnett - Fukanzazengi pt 1", "title": "Fukanzazengi, Part 1", "speaker": "Nomon Tim Burnett", "date": "2024-03-21", "series": "", "summary": "The speaker emphasizes that Dogen's teachings on zazen (meditation) are not about achieving a specific state through concentration or intellectual understanding, but rather about embracing the present moment with openness and acceptance. This approach encourages us to let go of our preconceptions and preferences, allowing us to experience our true nature as it is, unencumbered by thoughts and concepts. By turning our attention inward and letting go of distractions, we can access a deeper understanding of ourselves and the world around us, revealing our inherent interconnectedness and unity.", "themes": ["Acceptance", "Buddha-nature"], "texts": [], "minutes": 53}, {"id": "2024-03-16 - Hoka Chris Fortin - Closing Sesshin Reflection", "title": "Closing Sesshin Reflection", "speaker": "Hoka Chris Fortin", "date": "2024-03-16", "series": "", "summary": "The talk's main teaching emphasizes the importance of living in harmony with the present moment, embracing imperfection, and cultivating kindness and forgiveness. It encourages listeners to look beyond intellectual understanding and instead embody direct experience, letting go of self-concept to reveal the true nature of reality. By doing so, we can find fulfillment and satisfaction by aligning ourselves with the interconnectedness of all things and living in harmony with everyday life.", "themes": ["Buddha-nature", "Compassion", "Interconnection", "Sangha"], "texts": ["Shōbōgenzō"], "minutes": 47}, {"id": "2024-03-15 - Myoki Raizelah Bayen - Closing Sesshin Reflection", "title": "Closing Sesshin Reflection", "speaker": "Myoki Raizelah Bayen", "date": "2024-03-15", "series": "", "summary": "The talk's main teaching emphasizes the importance of transcending dualities and conceptual thinking in Zen practice, encouraging listeners to open their minds and experience the present moment as it truly is. By letting go of intellectual understanding and embracing embodiment, practitioners can manifest their true nature through action and presence, aligning with Dogen Zenji's teachings on the Genjokoan. This approach recognizes that awakening and bodhisattva nature are already present within all beings, and invites individuals to embody this reality without striving or attachment.", "themes": ["Buddha-nature", "Gratitude", "Interconnection", "Sangha"], "texts": ["Shōbōgenzō"], "minutes": 37}, {"id": "2024-03-14 - Nomon Tim Burnett - Closing Sesshin ReflectionBirth and Death", "title": "Closing Sesshin Reflection/Birth and Death", "speaker": "Nomon Tim Burnett", "date": "2024-03-14", "series": "", "summary": "The talk highlights the transformative power of Zen practice, particularly in the context of birth, death, and letting go. Through personal stories and anecdotes, the speaker illustrates how embracing the impermanence of life can lead to a deeper appreciation for its beauty and complexity. By sharing the experiences of individuals who have found refuge and peace through mindfulness and community, the talk encourages listeners to cultivate a sense of wonder and acceptance in the face of uncertainty.", "themes": ["Impermanence", "Sangha", "Social engagement", "Suffering"], "texts": [], "minutes": 49}, {"id": "2024-03-11 - Myoki Raizelah Bayen - Discovering Your Genjokoan Talk 7", "title": "Discovering Your Genjokoan Talk 7", "speaker": "Myoki Raizelah Bayen", "date": "2024-03-11", "series": "Discovering Your Genjokoan", "summary": "The speaker's talk emphasizes the importance of embracing humility and letting go of self-clinging as we explore the Genjokoan, a classic Soto Zen teaching that encourages us to uncover our true nature by actualizing our present awareness through practice and awareness. By reflecting on lines from the koan that resonate with us, we can discover new insights into ourselves and the world around us. Ultimately, the goal is not to achieve some specific state or outcome, but rather to cultivate a deeper sense of awareness and connection to our true nature.", "themes": ["Acceptance", "Buddha-nature", "No-self"], "texts": ["Shōbōgenzō"], "minutes": 24}, {"id": "2024-03-04 - Myoki Raizelah Bayen - Discovering Your Genjokoan Talk 6", "title": "Discovering Your Genjokoan Talk 6", "speaker": "Myoki Raizelah Bayen", "date": "2024-03-04", "series": "Discovering Your Genjokoan", "summary": "The speaker shares that Dogen's teachings encourage us to let go of our conditioned beliefs and identities, and instead fully inhabit our bodies and lives, finding our place and way in life not through external circumstances but by being present and authentic in the moment. This means embracing our true nature as part of a larger reality and letting go of dualistic thinking. By practicing zazen, we can connect with our true selves in every moment and \"actualize the fundamental point\" that is already present within us.", "themes": ["Buddha-nature", "Interconnection", "Vulnerability"], "texts": ["Shōbōgenzō"], "minutes": 34}, {"id": "2024-03-03 - Ryushin Andrea Thach - Zen Alive", "title": "Zen Alive!", "speaker": "Ryushin Andrea Thach", "date": "2024-03-03", "series": "", "summary": "The speaker shares personal stories from their experience studying Genjokoan, a key koan in Soto Zen, which explores how to live an examined life. Through reflecting on specific lines from the koan, they've gained insights that have helped them live more authentically and find freedom from trying to change or hide who they are. By embracing their unique nature and allowing themselves to fully experience difficult emotions, the speaker has discovered a sense of clarity and kindness that allows them to navigate life with greater ease and compassion. This understanding is meant to be shared with the audience, encouraging them to reflect on how Genjokoan has impacted their own lives and find freedom from self-identification.", "themes": ["Acceptance", "No-self", "Suffering", "Vulnerability"], "texts": ["Shōbōgenzō"], "minutes": 29}, {"id": "2024-02-26 - Myoki Raizelah Bayen - Discovering Your Genjokoan Talk 5", "title": "Discovering Your Genjokoan Talk 5", "speaker": "Myoki Raizelah Bayen", "date": "2024-02-26", "series": "Discovering Your Genjokoan", "summary": "The talk's main teaching emphasizes the importance of integrating non-dualistic awareness into daily life through the practice of taking precepts. This involves recognizing that enlightenment is not something separate from our everyday experiences, but rather is reflected in every moment, like a moon reflected in water. By embracing this understanding and incorporating it into our actions, we can \"leap clear\" of dualistic thinking and actualize Buddha's life in our daily lives, leading to a sense of completion and fulfillment.", "themes": ["Buddha-nature", "Emptiness", "Ethics", "Interconnection"], "texts": ["Shōbōgenzō"], "minutes": 34}, {"id": "2024-02-19 - Myoki Raizelah Bayen - Discovering Your Genjokoan Talk 4", "title": "Discovering Your Genjokoan Talk 4", "speaker": "Myoki Raizelah Bayen", "date": "2024-02-19", "series": "Discovering Your Genjokoan", "summary": "The teacher's talk emphasizes the importance of cultivating acceptance and awareness through mindfulness practices, such as working with koans like \"Sunface Buddha, Moonface Buddha.\" By letting go of preconceptions and focusing on the present moment, we can align ourselves with what's truly essential in our lives and tap into a deeper sense of reality. This practice is rooted in the understanding that our conventional views of time and reality are illusions, and that true understanding can only be accessed by embracing the present moment as it is.", "themes": ["Acceptance", "Impermanence", "No-self", "Vulnerability"], "texts": ["Shōbōgenzō"], "minutes": 42}, {"id": "2024-02-12 - Myoki Raizelah Bayen - Discovering Your Genjokoan Talk 3", "title": "Discovering Your Genjokoan Talk 3", "speaker": "Myoki Raizelah Bayen", "date": "2024-02-12", "series": "Discovering Your Genjokoan", "summary": "The teacher invites the group to explore their own self-awareness by asking themselves \"who am I right now?\" without attachment or expectation, encouraging them to become intimate with themselves in the present moment. This practice involves letting go of preconceptions and embracing the current state of being, allowing for a deeper understanding of oneself and one's place in the world. By doing so, individuals can experience freedom from conditioned thinking and ego, ultimately revealing their true nature or \"Buddha nature.\"", "themes": ["Buddha-nature", "Interconnection", "No-self", "Vulnerability"], "texts": ["Shōbōgenzō"], "minutes": 40}, {"id": "2024-02-05 - Myoki Raizelah Bayen - Discovering Your Genjokoan Talk 2", "title": "Discovering Your Genjokoan Talk 2", "speaker": "Myoki Raizelah Bayen", "date": "2024-02-05", "series": "Discovering Your Genjokoan", "summary": "The speaker's talk emphasizes the importance of cultivating mindfulness and self-acceptance, particularly during times of challenge or limitation, to find liberation from attachment and conceptual thinking. By embracing imperfection and letting go of expectations, we can transcend our fixed sense of self and experience a deeper understanding of ourselves and the world. This is reflected in the Genjokoan, which encourages us to leap beyond dualistic thinking and instead embody both our ordinary human experience and our Buddha nature.", "themes": ["Acceptance", "Buddha-nature", "No-self", "Vulnerability"], "texts": ["Shōbōgenzō"], "minutes": 53}, {"id": "2024-02-04 - Nomon Tim Burnett - Dogens Points of Practice", "title": "Dōgen's Points of Practice", "speaker": "Nomon Tim Burnett", "date": "2024-02-04", "series": "", "summary": "Here is a summary paragraph summarizing the main teaching of the Soto Zen dharma talk:\n\nThe talk emphasizes that true practice of Buddhism involves embracing both aspiration and acceptance of impermanence, finding balance between striving for growth and letting go of attachment to stability and order. By cultivating humility, selfless generosity, and compassion, practitioners can find freedom from suffering and rest in the Buddha way. This approach encourages a genuine desire to benefit others without expectation of reward, rather than seeking praise or recognition, and instead focuses on inspiring and guiding others through one's own practice and service.", "themes": ["Compassion", "Impermanence", "No-self", "Social engagement", "Vulnerability"], "texts": ["Shōbōgenzō"], "minutes": 46}, {"id": "2024-02-03 - Myoki Raizelah Bayen - Discovering Your Genjokoan Workshop", "title": "Discovering Your Genjokoan Workshop", "speaker": "Myoki Raizelah Bayen", "date": "2024-02-03", "series": "Discovering Your Genjokoan", "summary": "The talk explores the nature of reality and the self, encouraging participants to let go of fixed perceptions and ego boundaries. Through various exercises, including writing, sharing, and collaboration, the teacher invites participants to touch reality and actualize the fundamental point that lies beyond conceptual thinking. By embracing impermanence and interconnectedness, participants can experience a deeper understanding of themselves and the world around them, and show up fully in the present moment.", "themes": ["Emptiness", "Impermanence", "Interconnection", "No-self"], "texts": ["Shōbōgenzō"], "minutes": 80}, {"id": "2024-01-29 - Myoki Raizelah Bayen - Discovering Your Genjokoan Talk 1", "title": "Discovering Your Genjokoan Talk 1", "speaker": "Myoki Raizelah Bayen", "date": "2024-01-29", "series": "Discovering Your Genjokoan", "summary": "The teacher invites students to embark on a seven-week exploration of the Genjokoan with them, using it as a tool for discovering the meaning of individuality and universality. Rather than imparting new knowledge, they will facilitate a collective discovery process, encouraging students to let go of conceptual thinking and instead focus on their embodied experience. By doing so, they aim to help students \"show up\" authentically in each moment, free from attachments and aversions that can prevent us from being our true selves.", "themes": ["Emptiness", "Interconnection", "No-self"], "texts": ["Shōbōgenzō"], "minutes": 52}, {"id": "2024-01-19 - Hoka Chris Fortin - We Have Everything We Need", "title": "We Have Everything We Need", "speaker": "Hoka Chris Fortin", "date": "2024-01-19", "series": "", "summary": "The talk's main teaching is that true freedom and awakening come from embracing our imperfections and uncertainties, rather than trying to overcome or achieve something specific. By letting go of our need for control and perfection, we can cultivate inner love and tenderness towards ourselves and others, and embody intimacy and presence in every moment. This approach encourages us to trust ourselves, stay present, and find wonder and connection in the simplicity of life.", "themes": ["Buddha-nature", "Compassion", "Interconnection", "Vulnerability"], "texts": ["Shōbōgenzō"], "minutes": 50}, {"id": "2024-01-07 - Kanho Chris Burkhart - The Tripitika", "title": "The Tripitika", "speaker": "Kanho Chris Burkhart", "date": "2024-01-07", "series": "", "summary": "The speaker's talk highlights the interconnectedness of pain and joy in life, using personal experiences as a catalyst to explore the Buddhist concept of the Tripitaka, or Three Baskets. Specifically, they will delve into the Vinaya basket, which contains the monastic code governing behavior for monks and nuns, created over 2500 years ago to promote fairness, accountability, and community harmony in daily life within the sangha.", "themes": ["Ethics", "Sangha"], "texts": [], "minutes": 27}, {"id": "2023-12-21 - Nomon Tim Burnett - If Only You Do Not Pick and Choose", "title": "If Only You Do Not Pick and Choose", "speaker": "Nomon Tim Burnett", "date": "2023-12-21", "series": "", "summary": "The speaker encourages us to look beyond our habitual ways of categorizing reality, such as light vs. dark, and instead cultivate a mindset that allows things to be as they are, without judgment or attachment. This means embracing the present moment with an open and non-conceptual mind, letting go of dualistic thinking and the need to understand or solve problems. By doing so, we can experience a state of oneness and freedom from the burdens of the mind, and discover that true understanding lies beyond language and conceptual distinctions.", "themes": ["Emptiness", "Interconnection", "Vulnerability"], "texts": [], "minutes": 33}, {"id": "2023-12-14 - Seishu John Wiley - Impermanence", "title": "Impermanence", "speaker": "Seishu John Wiley", "date": "2023-12-14", "series": "", "summary": "The speaker's main teaching is that everything in life is constantly changing and impermanent, including our thoughts, emotions, and experiences. This understanding can help us let go of attachment to things that are fleeting and unchanging, such as possessions or relationships, and instead cultivate a sense of acceptance and calm in the face of loss or change. By practicing mindfulness and meditation, we can develop a greater awareness of impermanence and respond to life's challenges with clarity and openness. This allows us to live more authentically and fully present in the moment, rather than being controlled by our attachments and expectations.", "themes": ["Impermanence", "Suffering"], "texts": [], "minutes": 22}, {"id": "2023-12-07 - Nomon Tim Burnett - The Silent Woman", "title": "The Silent Woman", "speaker": "Nomon Tim Burnett", "date": "2023-12-07", "series": "", "summary": "The talk's main teaching emphasizes the importance of humility and recognizing one's limitations in spiritual practice, particularly when it comes to awakening others from deep states of meditation or personal growth. A traditional Koan story about Manjushri highlights this point, suggesting that even with great wisdom and effort, some individuals may remain unresponsive or \"snared\" by their own flaws. The speaker invites the audience to welcome their own \"messy selves\" and explore themes such as jealousy, trying to impress others, and practicing restraint in daily life, encouraging a more authentic and compassionate approach to spiritual growth.", "themes": ["Vulnerability", "Wisdom"], "texts": ["Gateless Barrier"], "minutes": 36}, {"id": "2023-12-03 - Nomon Tim Burnett - More Stories Women in Buddhism", "title": "More Stories - Women in Buddhism", "speaker": "Nomon Tim Burnett", "date": "2023-12-03", "series": "", "summary": "The talk touches on the complex history of women's inclusion in Buddhism, highlighting the story of Maha Prajapati's request to be ordained as a monk, which was eventually granted by the Buddha with certain restrictions. This anecdote serves as a reminder that even in ancient times, women were capable of spiritual awakening and leadership, and is used to challenge traditional misogyny in Buddhism. The speaker believes that greater inclusivity and balance between men and women are essential for authentic Zen practice, and notes that their own tradition has made significant strides towards this goal.", "themes": ["Ethics", "Social engagement"], "texts": ["Lotus Sutra", "Shōbōgenzō"], "minutes": 53}, {"id": "2023-12-02 - Nomon Tim Burnett - Swimming in a Sea of Stories", "title": "Swimming in a Sea of Stories", "speaker": "Nomon Tim Burnett", "date": "2023-12-02", "series": "", "summary": "The talk highlights the importance of stories in Buddhism, particularly in understanding the Buddha's journey and teachings. The traditional narratives surrounding the Buddha's enlightenment are just one part of a rich tapestry of stories that reveal his humanity, imperfection, and compassion. By embracing these stories with curiosity and respect, we can learn to tell our own more compassionate and wise stories about ourselves and others, leading to positive change in our lives.", "themes": ["Compassion"], "texts": ["Lotus Sutra"], "minutes": 44}, {"id": "2023-11-20 - Nomon Tim Burnett - The Lotus Sutra Fall Class Part 6", "title": "The Lotus Sutra (Fall Class Part 6)", "speaker": "Nomon Tim Burnett", "date": "2023-11-20", "series": "The Lotus Sutra (fall class)", "summary": "In a Soto Zen dharma talk, the teacher invites listeners to embark on a symbolic journey of self-discovery, leaving behind feelings of incompleteness or dissatisfaction with their life. Along the way, they encounter challenges and doubts, but are guided by a compassionate presence that helps them see that true fulfillment was within them all along. Ultimately, this journey reveals that our true nature is already awakened, and that the path to awakening requires patience, guidance, and self-reflection.", "themes": ["Buddha-nature"], "texts": ["Lotus Sutra"], "minutes": 91}, {"id": "2023-11-13 - Nomon Tim Burnett - The Lotus Sutra Fall Class Part 5", "title": "The Lotus Sutra (Fall Class Part 5)", "speaker": "Nomon Tim Burnett", "date": "2023-11-13", "series": "The Lotus Sutra (fall class)", "summary": "The talk explores the concept of spiritual growth and awakening, encouraging listeners to reflect on their own limitations and desires. It introduces the idea of becoming more aware of one's own potential and how this awareness relates to the Buddhist concept of Bodhisattvas, who strive to awaken others. The speaker shares parables that illustrate the importance of skillful means in teaching the Dharma, highlighting the need for nuanced approaches that balance wisdom with compassion and understanding.", "themes": ["Buddha-nature"], "texts": ["Lotus Sutra"], "minutes": 105}, {"id": "2023-11-09 - Nomon Tim Burnett - Not Making Things Worse", "title": "Not Making Things Worse", "speaker": "Nomon Tim Burnett", "date": "2023-11-09", "series": "", "summary": "The speaker reflects on how participating in the evening's service has reminded them that they enjoy doing so, and how this experience has sparked their desire to share teachings from early Buddhism with the group. They discuss the Salata Sutta, which distinguishes between two groups of people: those who have not yet understood the Buddha's teachings and those who have practiced for a long time. The key difference between these two groups is how they relate to unpleasant emotions - well-taught noble disciples experience their emotions without adding extra thoughts or reactions, allowing them to navigate difficult situations with greater ease.", "themes": ["Acceptance", "Suffering"], "texts": ["Lotus Sutra"], "minutes": 55}, {"id": "2023-11-05 - Sokaku Kathie Fischer - Master Shitou", "title": "Master Shitou", "speaker": "Sokaku Kathie Fischer", "date": "2023-11-05", "series": "", "summary": "The talk invites listeners to experience reality directly, without conceptual thinking or attachment, by embracing the fluidity and interconnectedness of all things. This means letting go of fixed notions of identity and reality, and instead responding with compassion and understanding to the present moment. By doing so, we can tap into a deeper sense of unity and harmony that underlies all existence.", "themes": ["Compassion", "Interconnection", "No-self"], "texts": [], "minutes": 46}, {"id": "2023-11-04 - Kanho Chris Burkhart - History of the Precepts", "title": "History of the Precepts", "speaker": "Kanho Chris Burkhart", "date": "2023-11-04", "series": "", "summary": "The speaker's main teaching is that taking the precepts is not just about following rules or avoiding specific behaviors, but rather about cultivating a deep understanding of the true nature of reality and one's place within it. By investigating what it means to take the precepts personally, we can ground our lives in the fundamental truth of being itself, which is the ultimate expression of Dharma. This approach encourages us to see practice as a continuous process of realization, where every moment of sitting zazen reenacts the Buddha's enlightenment and helps us deepen our understanding of reality.", "themes": ["Ethics"], "texts": [], "minutes": 27}, {"id": "2023-11-03 - Nomon Tim Burnett - Holding Opposites", "title": "Holding Opposites", "speaker": "Nomon Tim Burnett", "date": "2023-11-03", "series": "", "summary": "The speaker's talk emphasizes the importance of cultivating compassion and understanding for all beings, recognizing that our individual struggles and suffering are interconnected with those of others. They encourage listeners to let go of fixed notions and separation, embracing a boundless nature of love and compassion that transcends individual boundaries. By doing so, we can transform conflicts and create unity and connection, starting from within ourselves and extending outward to include all beings.", "themes": ["Compassion", "Gratitude", "Interconnection", "Social engagement"], "texts": ["Lotus Sutra"], "minutes": 58}, {"id": "2023-10-30 - Nomon Tim Burnett - The Lotus Sutra Fall Class Part 3", "title": "The Lotus Sutra (Fall Class Part 3)", "speaker": "Nomon Tim Burnett", "date": "2023-10-30", "series": "The Lotus Sutra (fall class)", "summary": "The teacher invites participants to explore the contrast between two types of experiences: one that evokes a sense of solidity and permanence, and another that is ephemeral and fleeting. By imagining themselves in each scenario, participants can notice how their emotional tone changes and what they find beautiful or inspiring about each experience. This exercise encourages us to cultivate awareness of impermanence and the importance of embracing both stability and fluidity in our lives.", "themes": ["Acceptance", "Compassion", "Impermanence"], "texts": ["Lotus Sutra"], "minutes": 115}, {"id": "2023-10-23 - Nomon Tim Burnett - The Lotus Sutra Fall Class Part 2", "title": "The Lotus Sutra (Fall Class Part 2)", "speaker": "Nomon Tim Burnett", "date": "2023-10-23", "series": "The Lotus Sutra (fall class)", "summary": "The speaker discusses the concept of \"other power\" or \"buddha-nature,\" which suggests that true understanding and realization can only be achieved through collaboration with others, rather than individual effort. They argue that the idea of self-power is flawed, as it implies that one person can achieve enlightenment on their own, whereas in reality, realization comes from beyond the individual self. This perspective is reflected in various Buddhist teachings, including the Lotus Sutra, which emphasizes cultivating a sense of community and connection with others to attain true understanding and practice.", "themes": ["Buddha-nature", "Impermanence"], "texts": ["Lotus Sutra", "Shōbōgenzō"], "minutes": 94}, {"id": "2023-10-19 - Nomon Tim Burnett - Mindfulness and Peace", "title": "Mindfulness and Peace", "speaker": "Nomon Tim Burnett", "date": "2023-10-19", "series": "", "summary": "The speaker encourages listeners to approach complex issues like global conflict with mindfulness and awareness, rather than trying to solve them with easy answers or taking sides. They emphasize the importance of cultivating love and compassion in response to suffering, and encourage a focus on inner transformation through practices like meditation and self-reflection. By paying attention to our own emotions and thoughts as they arise, we can develop greater peace, happiness, and awareness, rather than getting caught up in judgment or reaction.", "themes": ["Compassion", "Social engagement", "Suffering"], "texts": [], "minutes": 47}, {"id": "2023-10-16 - Nomon Tim Burnett - The Lotus Sutra Fall Class Part 1", "title": "The Lotus Sutra (Fall Class Part 1)", "speaker": "Nomon Tim Burnett", "date": "2023-10-16", "series": "The Lotus Sutra (fall class)", "summary": "The talk emphasizes the importance of approaching Buddhist teachings, such as the Lotus Sutra, with a devotional and personal mindset, rather than just intellectual curiosity. By engaging with the text in a more embodied and emotional way, we can gain deeper insights into its teachings and their relevance to our daily lives. This approach also encourages humility and openness to learning, recognizing that each individual's understanding is unique and may require adaptation and transformation through guidance from others.", "themes": ["Buddha-nature"], "texts": ["Diamond Sutra", "Lotus Sutra", "Shōbōgenzō"], "minutes": 107}, {"id": "2023-10-12 - IkuShun Desiree Webster - Advice Given to Anathapindika", "title": "Advice Given to Anathapindika", "speaker": "IkuShun Desiree Webster", "date": "2023-10-12", "series": "", "summary": "The talk's main teaching centers on understanding the interconnectedness of all phenomena, encouraging listeners to see that everything arises and ceases due to causes and conditions. This understanding is rooted in the concept of \"emptiness,\" which refers to the lack of inherent existence or self-nature in all things. By recognizing this emptiness, practitioners can cultivate a deeper sense of freedom and joy, and ultimately find liberation from suffering.", "themes": ["Emptiness", "No-self"], "texts": [], "minutes": 25}, {"id": "2023-10-01 - Heigaku Talus Latona - Mountains and Rivers Sutra", "title": "Mountains and Rivers Sutra", "speaker": "Heigaku Talus Latona", "date": "2023-10-01", "series": "", "summary": "The talk explores how studying Buddhism can sometimes lead to confusion and a shallow understanding of reality, rather than true insight. This is because our minds tend to focus on specific details and concepts, missing the bigger picture of interconnectedness and the present moment. To overcome this, the speaker encourages us to approach spiritual teachings with humility and an open mind, embracing simplicity and freedom in order to tap into timeless awareness and find liberation.", "themes": ["Emptiness", "Interconnection", "No-self"], "texts": ["Shōbōgenzō"], "minutes": 40}, {"id": "2023-09-23 - Nomon Tim Burnett - One Day Sitting Perfect Just As You Are", "title": "One Day Sitting - Perfect Just As You Are", "speaker": "Nomon Tim Burnett", "date": "2023-09-23", "series": "", "summary": "The speaker emphasizes the importance of cultivating mindfulness, self-acceptance, and humility in daily life, encouraging listeners to let go of attachment to their experiences and imperfections. By practicing traditional techniques like breath counting and \"just sitting,\" individuals can cultivate a sense of presence and simplicity, allowing them to appreciate the beauty of being alive without expectation or desire for change. This approach is rooted in the idea that our true nature is already complete and perfect, and by embracing this reality, we can find peace and calmness in the present moment.", "themes": ["Acceptance", "Buddha-nature", "Sangha"], "texts": ["Lotus Sutra"], "minutes": 44}, {"id": "2023-09-21 - Nomon Tim Burnett - Foundations of Mindfulness", "title": "Foundations of Mindfulness", "speaker": "Nomon Tim Burnett", "date": "2023-09-21", "series": "", "summary": "The main teaching of this Soto Zen dharma talk emphasizes the importance of cultivating mindfulness and awareness in daily life through embodied practice, exploring early Buddhist teachings, and developing qualities such as gratitude, motivation, and equanimity. The speaker highlights the value of physical presence and embodiment in Buddhist practice, noting that it's not just about intellectual understanding but also about direct experience and connection with one's own body. By incorporating mindfulness practices into daily life, individuals can develop a greater sense of purposefulness, stability, and clarity, leading to a more fulfilling and meaningful existence.", "themes": ["Gratitude", "Impermanence"], "texts": [], "minutes": 32}, {"id": "2023-09-14 - Kanho Chris Burkhart - Trungpas Path of Liberation and Right Mindfulness", "title": "Trungpa's Path of Liberation and Right Mindfulness", "speaker": "Kanho Chris Burkhart", "date": "2023-09-14", "series": "", "summary": "Here is a summary of the talk's main teaching in plain language:\n\nThe speaker emphasizes the importance of cultivating mindfulness as part of the Buddhist path, highlighting its connection to the Eightfold Noble Path and the Four Noble Truths. They encourage listeners to approach their practice with a nuanced understanding of the complexities of the teacher and the limitations of individual wisdom, instead embracing a path that prioritizes compassion, selflessness, and personal growth through mindfulness and meditation. By trusting in one's own inner guidance and taking action towards awakening, individuals can cultivate a more authentic and meaningful spiritual journey.", "themes": ["Compassion", "No-self", "Suffering"], "texts": [], "minutes": 34}, {"id": "2023-09-03 - Kanho Chris Burkhart - Kaizen and Zen", "title": "Kaizen and Zen", "speaker": "Kanho Chris Burkhart", "date": "2023-09-03", "series": "", "summary": "The talk emphasizes the importance of embracing life's experiences with an open and present mind, encouraging listeners to let go of expectations for rapid insight and instead cultivate a willingness to be vulnerable and kind through consistent practice. This approach is likened to the Japanese philosophy of Kaizen, which advocates for continuous improvement through small, daily actions that lead to gradual progress towards one's goals. By taking intentional steps each day, individuals can make meaningful changes in their lives and contribute to creating a better world around them.", "themes": ["Buddha-nature"], "texts": ["Shōbōgenzō"], "minutes": 21}, {"id": "2023-08-31 - Seiu Hannah Sullivan - Right Speech", "title": "Right Speech", "speaker": "Seiu Hannah Sullivan", "date": "2023-08-31", "series": "", "summary": "The talk emphasizes the importance of speaking truthfully, kindly, and beneficially, without engaging in gossip, idle chatter, or negativity. By choosing our words carefully, we can create positive interactions and connections with others, rather than perpetuating harm or division. This practice is rooted in the Buddha's teachings on language as a powerful tool that requires mindfulness and sensitivity to use effectively.", "themes": ["Compassion", "Ethics"], "texts": [], "minutes": 30}, {"id": "2023-08-24 - Joden Bob Rose - Right Livelihood", "title": "Right Livelihood", "speaker": "Joden Bob Rose", "date": "2023-08-24", "series": "", "summary": "To cultivate right livelihood, we must align our work with our values of love and compassion, being mindful of how our choices impact ourselves and others. This involves cultivating contentment and acceptance, rather than constantly seeking more, and making choices that promote harmony and well-being in nature and society. By reflecting on our own work and considering whether it benefits or harms others, we can make changes to align more closely with the principle of right livelihood.", "themes": ["Acceptance", "Ethics"], "texts": [], "minutes": 69}, {"id": "2023-08-17 - Reizan Bob Penny - The Social Psychology of Compassion", "title": "The Social Psychology of Compassion", "speaker": "Reizan Bob Penny", "date": "2023-08-17", "series": "", "summary": "The talk's main teaching emphasizes the importance of cultivating compassion and awareness in the face of overwhelming suffering, such as climate disasters and tragedies like mass shootings. By recognizing how our numbness to suffering can be both a personal response and a societal issue, we can take small actions every day to stay engaged and compassionate. Through Zen practice, we can develop the qualities needed to create positive change, including empathy and hope, and work towards creating a more compassionate society.", "themes": ["Compassion", "Social engagement", "Suffering"], "texts": [], "minutes": 54}, {"id": "2023-08-11 - Shin-yu Scott Allen - Right Livelihood", "title": "Right Livelihood", "speaker": "Shin-yu Scott Allen", "date": "2023-08-11", "series": "", "summary": "The speaker explores how Buddhist principles can inform daily life and decision-making, particularly through the lens of the Four Noble Truths and the Eightfold Path. They reflect on how a career rooted in Buddhist values could have shaped their choices differently, and consider how these teachings can guide us towards a path of liberation from suffering. By examining right livelihood and wholesome actions, the speaker aims to encourage practitioners to cultivate compassion and make decisions that benefit both themselves and others, even when faced with challenging or imperfect circumstances.", "themes": ["Ethics", "Sangha", "Suffering"], "texts": [], "minutes": 45}, {"id": "2023-08-06 - IkuShun Desiree Webster - Right View and the Three Doors of Liberation", "title": "Right View and the Three Doors of Liberation", "speaker": "IkuShun Desiree Webster", "date": "2023-08-06", "series": "", "summary": "The speaker's main teaching emphasizes the importance of cultivating a clear understanding of reality beyond our thoughts and concepts, which is known as Right View. This involves recognizing that everything is impermanent and interconnected, and that we are not fixed entities but rather non-self elements. By letting go of our perceptions and labels, we can respond to situations in a more authentic way and find freedom from our attachments and striving for a deeper existence.", "themes": ["Emptiness", "Impermanence", "No-self"], "texts": ["Heart Sutra"], "minutes": 20}, {"id": "2023-07-27 - Shuko Edie Norton - Right Understanding", "title": "Right Understanding", "speaker": "Shuko Edie Norton", "date": "2023-07-27", "series": "", "summary": "The main teaching of Edie's Soto Zen dharma talk emphasizes the importance of embracing impermanence and letting go of resistance in order to cultivate true understanding of reality. This involves adopting a gentle approach to Zazen, where one sits in stillness without trying to achieve enlightenment through thinking or doing, allowing for a deeper understanding of interconnectedness and emptiness. By releasing preconceptions and habitual responses, one can experience the present moment more fully and embody the Buddha's teachings, leading to a profound sense of inner being and reality.", "themes": ["Emptiness", "Impermanence", "Interconnection", "No-self"], "texts": ["Heart Sutra"], "minutes": 22}, {"id": "2023-07-20 - IkuShun Desiree Webster - Right Effort", "title": "Right Effort", "speaker": "IkuShun Desiree Webster", "date": "2023-07-20", "series": "", "summary": "The talk's main teaching emphasizes the importance of balance and pacing in sustaining a spiritual practice, highlighting how finding a sense of inner equilibrium allows one to approach their path with clarity and motivation. This balance is not about achieving perfection, but rather about cultivating patience, stamina, and joy in one's daily life and spiritual practice. By recognizing the interconnectedness of aspiration, commitment, inspiration, and joy/ease/love, individuals can sustain right effort and momentum, even in the face of challenges and obstacles.", "themes": ["Vulnerability"], "texts": [], "minutes": 27}, {"id": "2023-07-13 - Seishu John Wiley - Right Effort on the Eightfold Path", "title": "Right Effort on the Eightfold Path", "speaker": "Seishu John Wiley", "date": "2023-07-13", "series": "", "summary": "The talk's main teaching is that Right Effort in Soto Zen involves being aware of and working with our thoughts, feelings, and impulses to cultivate a more mindful and compassionate approach to life. This requires paying attention to negative influences and recognizing when we're stuck in unskillful states of mind, such as prejudice or frustration. By shifting our focus towards the beauty in the world, practicing gratitude, and acknowledging difficulties head-on, we can develop greater self-awareness and abandon patterns that lead to suffering, ultimately cultivating a more skillful and peaceful way of being.", "themes": ["Acceptance", "Gratitude"], "texts": [], "minutes": 34}, {"id": "2023-07-09 - Kanho Chris Burkhart - Precepts and the Path", "title": "Precepts and the Path", "speaker": "Kanho Chris Burkhart", "date": "2023-07-09", "series": "", "summary": "In this Soto Zen dharma talk, the teacher reflects on the importance of cultivating peace and presence in the face of uncertainty, using the example of Tony Long's embodiment of \"peaceful way\" despite his physical illness. They share a koan about Jin Yuan, who lets go of attachment to labels like \"life\" or \"death,\" finding freedom in the present moment. This teaching invites listeners to consider what it means to be fully present and at peace, even when faced with challenges or uncertainty.", "themes": ["Acceptance", "Impermanence"], "texts": [], "minutes": 17}, {"id": "2023-06-15 - Kanho Chris Burkhart - The Intersection of the Noble Eightfold Path and the Precepts", "title": "The Intersection of the Noble Eight-fold Path and the Precepts", "speaker": "Kanho Chris Burkhart", "date": "2023-06-15", "series": "", "summary": "The speaker's talk highlights the importance of integrating Buddhist teachings into daily life through two complementary frameworks: the Eightfold Path and the Zen Presets. These frameworks emphasize the interconnectedness of mindfulness, compassion, wisdom, and love, encouraging practitioners to cultivate wholesome intentions and act with kindness towards themselves and others. By embracing these principles, individuals can develop a more compassionate and awakened way of living, grounded in a deep understanding of the interconnectedness of all beings.", "themes": ["Compassion", "Ethics", "Suffering"], "texts": ["Lotus Sutra"], "minutes": 30}, {"id": "2023-05-15 - Nomon Tim Burnett - The Lotus Sutra part 5", "title": "The Lotus Sutra, Part 5", "speaker": "Nomon Tim Burnett", "date": "2023-05-15", "series": "The Lotus Sutra (spring class)", "summary": "The Soto Zen dharma talk explores how the Buddha's teachings can help us rediscover our inner wealth and dignity through mindfulness and practice, particularly by cultivating great forgiveness and acceptance of ourselves and others. The Lotus Sutra is highlighted as a key text that encourages us to see true freedom lies not in achieving a specific goal, but in the journey itself. By embracing imperfections and cultural limitations, we can find inspiration and guidance for living a more authentic and compassionate life.", "themes": ["Compassion", "Impermanence", "Wisdom"], "texts": ["Diamond Sutra", "Lotus Sutra"], "minutes": 117}, {"id": "2023-05-11 - Nomon Tim Burnett - Katagiri Roshis Peaceful Life", "title": "Katagiri Roshi's Peaceful Life", "speaker": "Nomon Tim Burnett", "date": "2023-05-11", "series": "", "summary": "The teacher encourages the audience to question their assumptions about what it means to be part of a community and how continuity is defined, highlighting that practice can take many forms and that commitment to the path is not limited by external circumstances or expectations. The importance of embracing uncertainty and living in vow, or making a commitment to practice despite any perceived limitations, is emphasized through Katagiri Roshi's teachings on Right View and the Buddha's way. This approach involves cultivating humility, openness, and trust, rather than striving for achievement or perfection.", "themes": ["Impermanence", "Sangha", "Vulnerability"], "texts": [], "minutes": 48}, {"id": "2023-05-08 - Nomon Tim Burnett - The Lotus Sutra part 4", "title": "The Lotus Sutra, Part 4", "speaker": "Nomon Tim Burnett", "date": "2023-05-08", "series": "The Lotus Sutra (spring class)", "summary": "In this Soto Zen dharma talk, the teacher invites participants to reflect on times when they felt awe or wonder, exploring how these moments can impact our lives and contribute to transformations. They discuss the importance of experiencing awe as a positive emotion that shifts our attention away from ourselves and connects us to something greater. This theme is woven throughout the talk, which also touches on stories from Buddhist teachings, such as the radical inclusion of women in Buddhism, highlighting the potential for anyone to attain enlightenment through devotion and practice.", "themes": ["Social engagement"], "texts": ["Lotus Sutra"], "minutes": 120}, {"id": "2023-04-28 - Heigaku Talus Latona - Great Expectations Or Not So Great", "title": "Great Expectations - Or Not So Great", "speaker": "Heigaku Talus Latona", "date": "2023-04-28", "series": "", "summary": "The speaker's main teaching emphasizes the importance of releasing expectations and dualistic thinking in meditation, encouraging listeners to focus on being present in each moment rather than striving for a specific state or outcome. By letting go of attachments and preconceptions, we can awaken to life as it truly is, experiencing surprises and growth, and cultivating a deeper understanding of impermanence through the practice of sitting meditation with patience and persistence. This approach allows us to find comfort in our spiritual journey, even when faced with challenges and uncertainties.", "themes": ["Acceptance", "Impermanence", "Vulnerability"], "texts": [], "minutes": 25}, {"id": "2023-04-27 - Nomon Tim Burnett - Right Effort Action", "title": "Right Effort & Action", "speaker": "Nomon Tim Burnett", "date": "2023-04-27", "series": "", "summary": "The speaker emphasizes the importance of finding balance in our daily lives, cultivating effort and intention while also being open and accepting. This can be achieved by practicing mindfulness and self-awareness, recognizing when we are acting unwholesomely and making a conscious effort to change our behavior. By doing so, we can develop greater compassion and wisdom, and navigate the world with greater awareness and kindness.", "themes": ["Ethics"], "texts": [], "minutes": 63}, {"id": "2023-04-20 - Nomon Tim Burnett - Right Speech", "title": "Right Speech", "speaker": "Nomon Tim Burnett", "date": "2023-04-20", "series": "", "summary": "The speaker emphasizes the importance of using wise speech in our interactions with others, particularly when we may feel superior or have a tendency to diminish those around us. They encourage listeners to consider three key factors before speaking: is what I'm saying true, will it be beneficial, and is this a good time? By being mindful of our words and intentions, we can communicate more kindly and compassionately, even in difficult situations, and cultivate a deeper understanding of ourselves and others.", "themes": ["Ethics"], "texts": [], "minutes": 60}, {"id": "2023-04-18 - Nomon Tim Burnett - The Lotus Sutra part 3", "title": "The Lotus Sutra, Part 3", "speaker": "Nomon Tim Burnett", "date": "2023-04-18", "series": "The Lotus Sutra (spring class)", "summary": "The main teaching of this Soto Zen dharma talk is that cultivating kindness and acceptance towards oneself by imagining a warm relationship with someone else can help develop self-compassion and understanding. By letting go of judgment and separation, we can break down distinctions between ourselves and others, leading to greater connection and understanding. This practice can also help us recognize our own limitations and imperfections, allowing us to approach life with humility and dedication to the Buddha's way.", "themes": ["Acceptance", "Wisdom"], "texts": ["Diamond Sutra", "Lotus Sutra"], "minutes": 114}, {"id": "2023-04-11 - Nomon Tim Burnett - The Lotus Sutra part 2", "title": "The Lotus Sutra, Part 2", "speaker": "Nomon Tim Burnett", "date": "2023-04-11", "series": "The Lotus Sutra (spring class)", "summary": "In this Soto Zen dharma talk, the teacher invites participants to cultivate mindfulness and acceptance by focusing on their physical body with each exhale, gently bringing their attention back to the present moment whenever it wanders. The goal is not to achieve a specific state but to develop awareness and acceptance of all experiences as they arise. By doing so, participants can begin to let go of distractions and attachments, allowing them to approach life's challenges with greater clarity and freedom.", "themes": ["Suffering"], "texts": ["Lotus Sutra"], "minutes": 115}, {"id": "2023-04-03 - Nomon Tim Burnett - The Lotus Sutra part 1", "title": "The Lotus Sutra, Part 1", "speaker": "Nomon Tim Burnett", "date": "2023-04-03", "series": "The Lotus Sutra (spring class)", "summary": "The speaker invites the audience to participate in a guided meditation, imagining themselves on a mountaintop with the Buddha and other bodhisattvas, where they can feel a sense of deep peace, compassion, and connection. As the meditation progresses, the scene shifts to a Hatsu ceremony, where flowers fall from the sky and the earth moves, but the speaker remains calm and present. The goal of the meditation is not to achieve a specific state, but to cultivate a sense of groundedness and release, allowing the audience to feel more settled and connected to the Dharma.", "themes": ["Wisdom"], "texts": ["Diamond Sutra", "Lotus Sutra", "Platform Sutra"], "minutes": 117}, {"id": "2023-03-23 - Nomon Tim Burnett - The First Noble Truth is About Happiness", "title": "The First Noble Truth is About Happiness", "speaker": "Nomon Tim Burnett", "date": "2023-03-23", "series": "", "summary": "The main teaching of this Soto Zen dharma talk emphasizes the importance of living in harmony with others and cultivating happiness through awareness, openness, and experimentation. The speaker explores the concept of the Eightfold Path as a way to reduce suffering and achieve freedom from the self, highlighting the interconnectedness of its eight steps and encouraging individuals to focus on one aspect deeply rather than trying to memorize all of them at once. Ultimately, this approach aims to soften our sense of separateness and cultivate compassion, love, and connection with others through warm relationships and Zen practice.", "themes": ["Compassion", "Interconnection", "No-self", "Suffering"], "texts": [], "minutes": 49}, {"id": "2023-03-16 - Nomon Tim Burnett - The Path of Relationship", "title": "The Path of Relationship", "speaker": "Nomon Tim Burnett", "date": "2023-03-16", "series": "", "summary": "The talk's main teaching emphasizes the importance of cultivating equanimity and mindfulness in daily life, drawing inspiration from the changing seasons and the concept of practice period in Zen Buddhism. The speaker encourages listeners to reflect on their own experiences of being supported and nurtured, whether through relationships, nature, or spiritual practices. By embracing this sense of support and interconnectedness, one can deepen their understanding of themselves and the world around them.", "themes": ["Sangha"], "texts": [], "minutes": 54}, {"id": "2023-03-12 - Kanho Chris Burkhart - The Satipatthana Mindfulness Sutra", "title": "The Satipatthana (Mindfulness) Sutra", "speaker": "Kanho Chris Burkhart", "date": "2023-03-12", "series": "", "summary": "The teacher invites listeners to explore the Satipatthana Sutta, a foundational Buddhist teaching on mindfulness, by cultivating awareness of the present moment without attachment or aversion. This practice is meant to lead to greater self-understanding and wisdom, allowing individuals to see things as they truly are, rather than being clouded by preconceptions or biases. By embracing this approach, one can begin to shed illusions that hinder spiritual growth and move closer to embodying the Buddha's teachings in their own lives.", "themes": ["Suffering", "Wisdom"], "texts": ["Shōbōgenzō"], "minutes": 35}, {"id": "2023-03-11 - IkuShun Desiree Webster - Bringing the Dharma Home", "title": "Bringing the Dharma Home", "speaker": "IkuShun Desiree Webster", "date": "2023-03-11", "series": "", "summary": "The speaker emphasizes the importance of cultivating awareness and acceptance in everyday life, particularly during challenging moments. They share their personal experience of letting go of rigid thinking and attachment, which allowed them to find freedom and clarity. By embracing imperfection and impermanence, one can develop wisdom and compassion, leading to a more courageous and objective approach to life's difficulties.", "themes": ["Acceptance", "No-self", "Vulnerability"], "texts": [], "minutes": 33}, {"id": "2023-03-10 - Ryushin Andrea Thach - Noble Truth", "title": "Noble Truth", "speaker": "Ryushin Andrea Thach", "date": "2023-03-10", "series": "", "summary": "The speaker's talk emphasizes the importance of redefining nobility beyond traditional notions of wealth or status, instead highlighting inner qualities like wisdom, poise, and kindness as the true markers of a noble life. They suggest that this understanding can be applied to our daily experiences, particularly when faced with challenging circumstances, by embracing our own \"ordinary mind\" - the present moment and our personal experience - rather than seeking external validation or solutions. By letting go of reactions and expectations, we can cultivate trust in ourselves and life, leading to balance, openness, and stability.", "themes": ["Acceptance", "Interconnection"], "texts": [], "minutes": 35}, {"id": "2023-02-26 - Nomon Tim Burnett - The Three Doors of Liberation", "title": "The Three Doors of Liberation", "speaker": "Nomon Tim Burnett", "date": "2023-02-26", "series": "", "summary": "The speaker shares that true understanding of Buddhist teachings lies not in intellectual comprehension, but in direct experience and embodiment. They reflect on how the Dharma is often presented as a path of healing and liberation, but ultimately reveals itself to be about embracing imperfection, letting go of ego, and cultivating intimacy with nature and the present moment. By tuning into their surroundings and allowing themselves to be present with whatever arises, one can deepen their understanding of the three doors of liberation and find freedom from attachment and expectation.", "themes": ["Emptiness"], "texts": [], "minutes": 48}, {"id": "2023-02-19 - Ryushin Andrea Thach - The Buddha Taught Nirvana", "title": "The Buddha Taught Nirvana", "speaker": "Ryushin Andrea Thach", "date": "2023-02-19", "series": "", "summary": "The speaker's main teaching is that true freedom from suffering lies not in changing external circumstances, but rather in transforming our own inner experience of it. This involves recognizing how our thoughts and perceptions add layers of suffering to what would otherwise be a natural part of life, and learning to let go of these burdens through mindfulness and meditation. By doing so, we can cultivate a sense of understanding and compassion that allows us to approach challenges like racism and suffering with wisdom and hope, rather than feeling overwhelmed or hopeless.", "themes": ["Impermanence", "No-self", "Suffering"], "texts": [], "minutes": 40}, {"id": "2023-01-30 - Jonathan Prescott - Effort and Ease", "title": "Effort and Ease", "speaker": "Jonathan Prescott", "date": "2023-01-30", "series": "", "summary": "The speaker emphasizes the importance of finding a balanced approach in Zen practice, where diligence is neither too much nor too little. This balance allows for progress on the path to enlightenment without solidifying ego or becoming complacent. By cultivating concentration and ease simultaneously, one can develop a sense of freedom and liberation from ego-driven striving, ultimately leading to a more authentic and effortless spiritual practice.", "themes": ["Buddha-nature", "No-self"], "texts": [], "minutes": 22}, {"id": "2023-01-13 - Ryushin Andrea Thach - Getting to Zero", "title": "Getting to Zero", "speaker": "Ryushin Andrea Thach", "date": "2023-01-13", "series": "", "summary": "The main teaching of the Soto Zen dharma talk emphasizes the importance of cultivating a sense of aspiration or longing for spiritual growth through mindfulness and dedication to practice. This involves setting aside distractions and being present in all aspects of life, including daily tasks, by embracing a \"zero\" state where there is no preconceived notion or attachment. By doing so, individuals can tap into their true nature, experience life fully and authentically, and find peace and harmony within themselves and with others.", "themes": ["Acceptance"], "texts": [], "minutes": 43}, {"id": "2022-05-22 - Ben Connelly - Show up in a good way On Zen and Solidarity with Indigenous Water Protectors", "title": "Show up in a good way – On Zen and Solidarity with Indigenous Water Protectors", "speaker": "Ben Connelly", "date": "2022-05-22", "series": "", "summary": "The talk's main teaching is that showing up in a good way means approaching each moment with intentionality, care, and compassion for all beings. This involves being fully present and engaged, without judgment or control, and recognizing our interconnectedness with others and the environment. By embracing this mindset, we can cultivate freedom from frustration and find empowerment in our choices and actions, rather than trying to control external events.", "themes": ["Interconnection", "Social engagement"], "texts": [], "minutes": 32}, {"id": "2022-05-12 - Seishu John Wiley - Meditation Revisiting the Basics", "title": "Meditation - Revisiting the Basics", "speaker": "Seishu John Wiley", "date": "2022-05-12", "series": "", "summary": "Here is a summary of the main teaching in plain language:\n\nThe speaker emphasizes the importance of approaching meditation with kindness and acceptance towards oneself, letting go of critical judgments and instead cultivating a friendly attention that acknowledges and accepts one's experiences as they are. By recognizing and returning to the present moment, particularly when distracted or lost in thought, one can break repetitive patterns and establish new pathways in the brain. This practice allows for greater flexibility and openness, leading to a more positive experience of difficult emotions and daily life.", "themes": ["Acceptance", "Compassion"], "texts": [], "minutes": 22}, {"id": "2022-04-17 - Kanho Chris Burkhart - Ancestor Bodhidharma", "title": "Ancestor Bodhidharma", "speaker": "Kanho Chris Burkhart", "date": "2022-04-17", "series": "", "summary": "The talk highlights the importance of embracing reality without conceptual thinking, a key teaching of Bodhidharma, an Indian monk who founded Zen Buddhism. Through his famous koan \"empty, no holiness,\" Bodhidharma challenges us to look beyond our preconceptions and understand that true meaning lies in the present moment, unencumbered by notions of good or bad. This teaching is meant to be a direct experience, rather than a intellectual understanding, allowing us to tap into the true nature of reality and find freedom from suffering.", "themes": ["Emptiness", "Suffering"], "texts": ["Blue Cliff Record"], "minutes": 41}, {"id": "2022-04-14 - Nomon Tim Burnett - Reflections on Our Practice", "title": "Reflections on Our Practice", "speaker": "Nomon Tim Burnett", "date": "2022-04-14", "series": "", "summary": "The main teaching of the Soto Zen dharma talk emphasizes the importance of embracing an active and embodied approach to meditation (zazen), rather than trying to achieve a specific state or understanding through intellectual means. Dogen's teachings encourage us to let go of conceptual frameworks and expectations, instead cultivating a \"no-thinking\" approach that allows us to tap into our true nature and engage with the world in a way that sees everything as inherently complete and Buddha-like. By embracing this approach, we can make space for our true nature to express itself freely, without attachment or expectation.", "themes": ["Buddha-nature"], "texts": ["Shōbōgenzō"], "minutes": 44}, {"id": "2022-04-10 - Kanho Chris Burkhart - On Precepts", "title": "On Precepts", "speaker": "Kanho Chris Burkhart", "date": "2022-04-10", "series": "", "summary": "The main teaching of the Soto Zen dharma talk emphasizes the importance of cultivating wisdom, compassion, and awareness in daily life through the practice of mindfulness and self-reflection. The speaker encourages listeners to approach spiritual practices with an open and non-judgmental mind, recognizing that true growth and transformation come from embracing imperfection and uncertainty. By doing so, we can develop greater kindness, wisdom, and awareness, leading to a more authentic and compassionate way of living.", "themes": ["Compassion", "Ethics"], "texts": [], "minutes": 31}, {"id": "2022-04-03 - Heigaku Talus Latona - Three Ways To Practice With Emptiness", "title": "Three Ways To Practice With Emptiness", "speaker": "Heigaku Talus Latona", "date": "2022-04-03", "series": "", "summary": "The talk's main teaching emphasizes the importance of approaching life with an open and non-judgmental mind, recognizing that all phenomena are empty of inherent existence or meaning. This understanding is not just intellectual knowledge, but a lived experience that can lead to dispassion, liberation, and ultimately enlightenment. By letting go of dualistic thinking and embracing a sense of unity and interconnectedness with all beings and things, one can cultivate compassion, wisdom, and freedom from suffering.", "themes": ["Emptiness", "Interconnection", "No-self"], "texts": [], "minutes": 26}, {"id": "2022-03-31 - Kanho Chris Burkhart - How Do We Practice in the Middle of Hellfire", "title": "How Do We Practice in the Middle of Hellfire?", "speaker": "Kanho Chris Burkhart", "date": "2022-03-31", "series": "", "summary": "The speaker emphasizes the importance of taking complete responsibility for one's actions and emotions, rather than trying to control or change external circumstances. They encourage a mindset of willingness and abundance, focusing on helping others without expectation of reward or outcome, in order to cultivate transformation from within. By letting go of autopilot responses and outcomes, we can tap into our own capacity for compassion and wisdom, leading to deeper understanding and positive change.", "themes": ["Ethics", "Gratitude", "Social engagement"], "texts": [], "minutes": 26}, {"id": "2022-03-27 - Sokaku Kathie Fischer - Prajna Paramita", "title": "Prajna Paramita", "speaker": "Sokaku Kathie Fischer", "date": "2022-03-27", "series": "", "summary": "The speaker's main teaching emphasizes the importance of understanding the interconnectedness of all things, particularly in relation to language and human suffering. They argue that by recognizing how our fixed notions about reality trap us in suffering, we can begin to see beyond these constructs and experience a deeper sense of connection with ourselves, others, and the universe. This understanding is rooted in the concept of love and compassion, which reveals our inherent oneness with all existence and offers a path to freedom and transcendence.", "themes": ["Compassion", "Emptiness", "Interconnection", "No-self"], "texts": ["Heart Sutra"], "minutes": 19}, {"id": "2022-03-17 - Nomon Tim Burnett - Faith and Our Practice", "title": "Faith and Our Practice", "speaker": "Nomon Tim Burnett", "date": "2022-03-17", "series": "", "summary": "The talk highlights the importance of exploring faith in a more fundamental way, rather than seeking a single key or understanding that explains life's mysteries. Instead, faith can be cultivated through practice, such as zazen, where one embodies Buddha's law and enacts the Dharma for the benefit of all beings. By letting go of fixed views and self-concept, and trusting ourselves, each other, and the practice itself, we can allow Buddha's expression to flow through us and awaken to a deeper understanding of reality.", "themes": ["Acceptance", "Buddha-nature", "Sangha"], "texts": ["Diamond Sutra", "Shōbōgenzō"], "minutes": 52}, {"id": "2022-03-13 - Nomon Tim Burnett - Great Faith Great Doubt Great Determination", "title": "Great Faith, Great Doubt, Great Determination", "speaker": "Nomon Tim Burnett", "date": "2022-03-13", "series": "", "summary": "The talk's main teaching emphasizes the importance of embracing faith, doubt, and determination as essential elements on the path to spiritual awakening. These qualities, attributed to 18th-century Japanese Zen monk Torai Enji, involve recognizing the sacred nature of all things and letting go of delusions, including our sense of self. By cultivating faith in practice, trusting in the Dharma wheel's functioning, and embracing uncertainty with openness, one can find strength and resilience from within, ultimately leading to awakening and a deeper connection with all beings.", "themes": ["Acceptance", "Buddha-nature", "Compassion"], "texts": [], "minutes": 42}, {"id": "2022-03-06 - Kanho Chris Burkhart - How Does it All Fit Together", "title": "How Does it All Fit Together?", "speaker": "Kanho Chris Burkhart", "date": "2022-03-06", "series": "", "summary": "The speaker reflects on how various Buddhist teachings and practices from different cultures and traditions don't necessarily fit together seamlessly, but instead form a rich tapestry shaped by cultural exchange and adaptation over time. They explore how Buddhism has evolved in new contexts, incorporating local customs and influences, and how the six perfections (generosity, discipline, patience, energy, meditation, and wisdom) relate to the Noble Eightfold Path, highlighting the importance of wisdom as a foundation for spiritual practice.", "themes": ["Wisdom"], "texts": ["Heart Sutra"], "minutes": 16}, {"id": "2022-03-05 - Nomon Tim Burnett - Conversations With the Buddha and Our Mind", "title": "Conversations With the Buddha and Our Mind", "speaker": "Nomon Tim Burnett", "date": "2022-03-05", "series": "", "summary": "The teacher encourages us to approach life and conversations with an open mind and heart, rather than trying to control or manage our thoughts. This means being willing to step into uncertainty and embracing the changes that arise, much like a conversation unfolds naturally. By doing so, we can cultivate courage, love, and non-attachment, which are key to liberation from wrong views and finding freedom in the present moment.", "themes": ["Compassion", "Suffering", "Vulnerability"], "texts": ["Diamond Sutra"], "minutes": 52}, {"id": "2022-03-04 - Sokaku Kathie Fischer - The Diamond Sutra", "title": "The Diamond Sutra", "speaker": "Sokaku Kathie Fischer", "date": "2022-03-04", "series": "", "summary": "The main teaching of the dharma talk emphasizes the importance of understanding emptiness and non-attachment, encouraging listeners to cultivate compassion and activism by living in the present moment and letting go of attachments. This approach is rooted in the Prajnaparamita sutras and is illustrated through stories like that of Huineng and Daowu, who demonstrated that true practice involves bringing awareness to life as it is, rather than trying to achieve a specific state. By embracing the present moment and trusting in one's own life, we can find freedom and love, allowing us to engage with others without judgment or expectation.", "themes": ["Acceptance", "Emptiness", "Social engagement"], "texts": ["Blue Cliff Record", "Diamond Sutra"], "minutes": 41}, {"id": "2022-03-03 - Seiu Hannah Sullivan - Zazen on the Road and in the Zendo", "title": "Zazen on the Road and in the Zendo", "speaker": "Seiu Hannah Sullivan", "date": "2022-03-03", "series": "", "summary": "Through their personal experience with zazen practice, the speaker has come to understand that sitting with others in community can deepen our connection and understanding of ourselves and the world around us. By participating in group sittings, they've developed a sense of spaciousness and unity, even in challenging situations, and have found comfort in the unknown through repetition and silence. This experience has taught them the importance of compassion and mindfulness towards others, particularly in times of conflict and suffering, and has inspired them to cultivate non-separation, impermanence, and kindness.", "themes": ["Compassion", "Impermanence", "Interconnection", "Sangha"], "texts": ["Diamond Sutra"], "minutes": 20}, {"id": "2022-02-06 - Nomon Tim Burnett - Jizo Bodhisattva", "title": "Jizo Bodhisattva", "speaker": "Nomon Tim Burnett", "date": "2022-02-06", "series": "", "summary": "The talk explores the concept of Bodhisattvas in Mahayana Buddhism, specifically focusing on Jizo, a Japanese Buddhist deity who embodies compassion and helps beings overcome negative karma. Through his teachings, Jizo emphasizes the importance of understanding and liberation, offering protection and blessings to travelers and those in need. By embracing our obligations and showing up with a sense of duty, we can cultivate a consistent practice and bring joy and delight to our spiritual journey.", "themes": ["Compassion", "Suffering"], "texts": ["Diamond Sutra"], "minutes": 45}, {"id": "2022-01-21 - Seiu Hannah Sullivan - The Diamond Sutra Part I", "title": "The Diamond Sutra, Part I", "speaker": "Seiu Hannah Sullivan", "date": "2022-01-21", "series": "", "summary": "The speaker's talk emphasizes the importance of letting go of attachments and perceptions of a self when giving gifts or engaging in generosity. This means not creating mental labels or concepts about objects or attributes, but instead allowing them to be given freely without attachment. By doing so, we can accumulate infinite merit and gain clarity of mind, ultimately leading to liberation from suffering.", "themes": ["No-self"], "texts": ["Diamond Sutra", "Heart Sutra"], "minutes": 57}, {"id": "2022-01-16 - Kanho Chris Burkhart - The Flower Ornament Scripture", "title": "The Flower Ornament Scripture", "speaker": "Kanho Chris Burkhart", "date": "2022-01-16", "series": "", "summary": "The talk's main teaching is that true enlightenment is not about personal achievement or ego, but rather about cultivating a deep and selfless love that transcends individual boundaries. This loving mind, known as Bodhicitta, can be developed through practice periods and spiritual exercise, allowing us to embody the qualities of compassion and wisdom embodied by figures like Samantabhadra, who exemplify the bodhisattva ideal of helping all sentient beings achieve enlightenment. By embracing this mindset, we can take action in the world with greater kindness and understanding, ultimately benefiting not just ourselves, but all beings.", "themes": ["Compassion", "Interconnection"], "texts": [], "minutes": 30}, {"id": "2022-01-09 - Kanho Chris Burkhart - Continuous Mistake", "title": "Continuous Mistake", "speaker": "Kanho Chris Burkhart", "date": "2022-01-09", "series": "", "summary": "The talk's main teaching is that imperfection and mistakes are an inherent part of life, and it's through embracing these flaws that we can develop greater awareness, self-love, and acceptance. By letting go of our attachment to certain narratives and expectations, we can cultivate a more open and loving mind, allowing us to connect with something greater than ourselves and find freedom in the present moment. This process is not about achieving perfection, but rather about embracing the beauty and complexity of life as it unfolds.", "themes": ["Acceptance", "No-self"], "texts": [], "minutes": 38}, {"id": "2022-01-08 - Seiu Hannah Sullivan - Way Seeking Mind", "title": "Way Seeking Mind", "speaker": "Seiu Hannah Sullivan", "date": "2022-01-08", "series": "", "summary": "The speaker's talk emphasizes the importance of cultivating a deep sense of connection and purpose through spiritual practice, drawing from their own journey of self-discovery and exploration. They share how their experiences, both challenging and transformative, have helped them develop a deeper understanding of themselves and the world around them, ultimately leading to a greater commitment to their Buddhist practice. Through their story, they invite listeners to reflect on their own path and find meaning in their own spiritual journey.", "themes": ["Interconnection", "Sangha"], "texts": [], "minutes": 22}, {"id": "2021-12-23 - Heigaku Talus Latona - Diamond in the Rough", "title": "Diamond in the Rough", "speaker": "Heigaku Talus Latona", "date": "2021-12-23", "series": "", "summary": "The speaker shares a story about their sailing adventure as a metaphor for Buddhist practice, highlighting how often we look outside ourselves for answers when the solution lies within. This experience is meant to encourage us to pay attention to our own experiences and perceptions, rather than relying on external sources or distractions. By doing so, we can discover our true nature and overcome obstacles that prevent us from understanding and practicing the Dharma, such as desire, aversion, dullness, restlessness, and doubt.", "themes": ["Buddha-nature", "Wisdom"], "texts": [], "minutes": 22}, {"id": "2021-12-19 - Joden Bob Rose - Bodhidharmas Outline of Practice", "title": "Bodhidharma's Outline of Practice", "speaker": "Joden Bob Rose", "date": "2021-12-19", "series": "", "summary": "The main teaching of Joden Bob Rose's dharma talk emphasizes the importance of direct experience and non-conceptual thinking in Zen practice, as embodied by Bodhidharma's unique approach. By letting go of attachment and craving, we can see our true nature and live an ordinary, everyday life as a form of spiritual practice. This involves embracing the present moment, adapting to circumstances, and seeking nothing, allowing us to find freedom and joy in the here and now.", "themes": ["Acceptance", "Suffering"], "texts": [], "minutes": 31}, {"id": "2021-12-16 - Shin-yu Scott Allen - Thoughts on Ego", "title": "Thoughts on Ego", "speaker": "Shin-yu Scott Allen", "date": "2021-12-16", "series": "", "summary": "The main teaching of this Soto Zen dharma talk is about the nature of the ego and how it contributes to suffering. The ego, or sense of self, is a deeply ingrained pattern that can lead to fear, defensiveness, and separation from others, causing us to create walls around ourselves and perpetuate painful emotions. By recognizing the characteristics of ego and cultivating a sense of selflessness, we can begin to let go of this entity and develop greater kindness, compassion, and understanding towards ourselves and others.", "themes": ["No-self", "Suffering"], "texts": [], "minutes": 52}, {"id": "2021-12-12 - Kanho Chris Burkhart - Thoughts on Rohatsu and the Condition of the Nations Welfare", "title": "Thoughts on Rohatsu and the Condition of the Nation's Welfare", "speaker": "Kanho Chris Burkhart", "date": "2021-12-12", "series": "", "summary": "The talk's main teaching emphasizes the importance of cultivating compassion and understanding in the face of challenges and conflicts, drawing on the Buddha's wisdom from the Pali Canon. The speaker encourages listeners to consider how their own experiences and values align with the Buddha's teachings, which prioritize peace and respect over division and aggression. By approaching problems with a calm and open mind, we can work towards growth and understanding rather than conflict and destruction.", "themes": ["Ethics", "Social engagement"], "texts": [], "minutes": 28}, {"id": "2021-12-09 - Reizan Bob Penny - Climate and Spiritual Activism", "title": "Climate and Spiritual Activism", "speaker": "Reizan Bob Penny", "date": "2021-12-09", "series": "", "summary": "The talk explores how Soto Zen teachings, particularly those of Roshi John Dogen, offer a way to understand our interconnectedness with the world and ourselves. By embracing the concept of \"combustion\" or slipping out of our individual skins, we can transcend our habitual frames of reference and see the world as undivided. This understanding can lead to a deeper sense of connection and care for all things, which in turn can inform our actions and advocacy, ultimately leading to positive change when infused with spiritual authority and intimacy.", "themes": ["Interconnection", "Social engagement"], "texts": ["Shōbōgenzō"], "minutes": 38}, {"id": "2021-12-04 - Nomon Tim Burnett - The Devotional and the Practical", "title": "The Devotional and the Practical", "speaker": "Nomon Tim Burnett", "date": "2021-12-04", "series": "", "summary": "The speaker discusses the need for a more adaptable and individualized approach to Zen practice in the modern world, acknowledging that traditional monastic training may be losing its relevance due to issues such as ableism, gender binary assumptions, and stress related to food and body image. They argue that this requires a shift towards creating schedules and practices that prioritize flexibility, personal space, and individual needs, rather than adhering strictly to traditional models. By embracing this adaptability, practitioners can cultivate greater understanding, compassion, and wisdom in their own unique paths to enlightenment.", "themes": ["Acceptance", "Sangha"], "texts": [], "minutes": 66}, {"id": "2021-11-28 - Chiko Amie Diller - The Bodhisattvas Practice of Gratitude", "title": "The Bodhisattva's Practice of Gratitude", "speaker": "Chiko Amie Diller", "date": "2021-11-28", "series": "", "summary": "The speaker's main teaching emphasizes that true gratitude goes beyond a self-help practice focused on getting something out of it, instead embracing our interconnectedness with all things and recognizing the preciousness of life as a fleeting gift. By letting go of ego and individuality, we can tap into a sense of belonging and appreciate the beauty in ourselves, others, and the world around us. This gratitude allows us to be fully present and aware, even in difficult times, and find joy and peace in every moment.", "themes": ["Gratitude", "Interconnection", "No-self"], "texts": [], "minutes": 25}, {"id": "2021-11-21 - Kanho Chris Burkhart - The Peace of Wild Things", "title": "The Peace of Wild Things", "speaker": "Kanho Chris Burkhart", "date": "2021-11-21", "series": "", "summary": "The speaker's talk emphasizes the importance of cultivating stillness and presence in our daily lives, drawing inspiration from their own experiences with vertigo and nature. They encourage us to come into contact with wild things and find peace in the natural world, which can bring freedom from our thoughts and worries. Through practices like Zazen and meditation, we can develop mindfulness and clarity, allowing us to navigate life's challenges with greater ease and inner peace.", "themes": ["Acceptance"], "texts": ["Shōbōgenzō"], "minutes": 19}, {"id": "2021-11-14 - Nomon Tim Burnett - Stages of Monastic Life", "title": "Stages of Monastic Life", "speaker": "Nomon Tim Burnett", "date": "2021-11-14", "series": "", "summary": "The speaker reflects on their relationship with their teacher, Zoketsu Norman Fischer, highlighting the importance of humility and non-attachment in the teacher-student dynamic. They note that Norman's visits to Bellingham, Washington, were pivotal in their community's growth, and that this mutual support is essential for effective practice. The speaker suggests that as we progress on the path, we must learn to receive others with kindness and respect, even when they are struggling, and cultivate a deeper level of awareness, humility, and patience to navigate our own minds and relationships.", "themes": ["Impermanence", "Sangha"], "texts": ["Lotus Sutra"], "minutes": 54}, {"id": "2021-11-07 - Kanho Chris Burkhart - We Are Always Walking Each Other Home", "title": "We Are Always Walking Each Other Home", "speaker": "Kanho Chris Burkhart", "date": "2021-11-07", "series": "", "summary": "The speaker's main teaching emphasizes the importance of embracing our interconnectedness and letting go of control in order to find true fulfillment. They encourage us to appreciate the intricate web of relationships that shape our lives, from the simplest things like a candle or breakfast to the world around us, and to cultivate compassion and understanding for all beings and the natural world. By recognizing our dependence on others and the environment, we can shift our focus from the destination to the journey itself and find meaning in the unknown. This approach allows us to walk alongside one another, supporting each other home, and finding a sense of home within ourselves and with others.", "themes": ["Gratitude", "Interconnection"], "texts": [], "minutes": 24}, {"id": "2021-10-31 - Kanho Chris Burkhart - Dukkha Rollercoasters and Nonduality", "title": "Dukkha, Rollercoasters and Nonduality", "speaker": "Kanho Chris Burkhart", "date": "2021-10-31", "series": "", "summary": "The speaker encourages listeners to approach life's challenges with patience, humility, and a non-dualistic mindset, recognizing that our experiences are part of a larger reality that transcends individual perspectives. By acknowledging the complexity and interconnectedness of all things, we can cultivate compassion and understanding for ourselves and others, and work towards ending suffering. This involves embracing both joy and pain as an integral part of life, rather than trying to separate or resist them.", "themes": ["Compassion", "Interconnection"], "texts": [], "minutes": 24}, {"id": "2021-10-24 - Chikyo Ewan Magie - Our Zen Ancestors and Koans", "title": "Our Zen Ancestors and Koans", "speaker": "Chikyo Ewan Magie", "date": "2021-10-24", "series": "", "summary": "The talk's main teaching emphasizes the importance of embracing the complexity and imperfection of the human experience in Zen practice. By recognizing that even awakened beings like Buddha and Bodhidharma struggled with dissatisfaction and imperfection, practitioners can deepen their understanding of the path to awakening. This approach encourages a sense of determination and effort towards enlightenment, rather than trying to achieve a fixed state or ideal.", "themes": ["Buddha-nature", "No-self"], "texts": ["Diamond Sutra", "Gateless Barrier"], "minutes": 41}, {"id": "2021-10-21 - Nomon Tim Burnett - Zen Mind Beginners Mind Control", "title": "Zen Mind, Beginners Mind - Control", "speaker": "Nomon Tim Burnett", "date": "2021-10-21", "series": "", "summary": "The speaker's talk highlights the importance of letting go of control and embracing uncertainty and imperfection in order to find true freedom and well-being. By recognizing that we can't completely control our lives and that perfection is an illusion, we can begin to appreciate the beauty in the world as it is, rather than trying to change it. This perspective shift allows us to experience moments of lightness and happiness when we let go of our need for control, and to find fulfillment by embracing the natural unfolding of life.", "themes": ["Acceptance"], "texts": [], "minutes": 46}, {"id": "2021-10-17 - Karen DeCotis - Karma", "title": "Karma", "speaker": "Karen DeCotis", "date": "2021-10-17", "series": "", "summary": "The talk explores how our intentions and actions shape our experiences, suggesting that karma is not just about punishment or reward, but also about understanding the interconnectedness of all things. While intention matters, the consequences of our actions can be unpredictable and influenced by factors beyond our control. By cultivating good character and taking action in the present moment, we can approach our lives with greater awareness and intention, rather than relying solely on external forces to shape our behavior.", "themes": ["Ethics", "Interconnection"], "texts": [], "minutes": 41}, {"id": "2021-10-14 - Kanho Chris Burkhart - Instant Dukkha Suzuki Roshi Walk Like an Elephant", "title": "Instant Dukkha, Suzuki Roshi Walk Like an Elephant", "speaker": "Kanho Chris Burkhart", "date": "2021-10-14", "series": "", "summary": "The speaker encourages listeners to cultivate a mindful and non-attached approach to life by slowing down and practicing zazen, which involves sitting without expectation or attachment to achieve something specific. By focusing on the present moment and letting go of distractions, we can develop a deeper understanding of our true nature and find peace in the midst of suffering. This practice is not about achieving a specific state but rather about embracing the journey, just as an elephant walks with its trunk held low, without attachment to where it's going.", "themes": ["Suffering", "Vulnerability"], "texts": [], "minutes": 23}, {"id": "2021-10-10 - Kanho Chris Burkhart - Trust Worries and Self Improvement", "title": "Trust, Worries and Self Improvement", "speaker": "Kanho Chris Burkhart", "date": "2021-10-10", "series": "", "summary": "The speaker's main teaching is that our worries can be overwhelming, but by learning to observe them without getting caught up in their demands, we can find freedom from mental clutter. Through the example of a \"worry box\" filled with concerns, the speaker illustrates how our minds can be easily distracted and prioritized, but also shows how Zen practice allows us to take out these worries one by one, allowing for greater awareness and freedom. By letting go of conditioning and expectations, we can discover that true happiness and fulfillment come from within, rather than from external sources or achievements.", "themes": ["Acceptance", "Suffering"], "texts": [], "minutes": 30}, {"id": "2021-10-03 - Nomon Tim Burnett - Moments of Realization", "title": "Moments of Realization", "speaker": "Nomon Tim Burnett", "date": "2021-10-03", "series": "", "summary": "The talk's main teaching emphasizes the importance of being present and accepting in the current moment, rather than getting caught up in worries about the past or future. By acknowledging and embracing reality as it is, we can shift our perspective and find ways to cope with challenges such as environmental issues. This approach encourages us to cultivate mindfulness and awareness in our daily lives, taking small actions that make a difference when done with intention and attention.", "themes": ["Buddha-nature", "Interconnection", "Social engagement"], "texts": [], "minutes": 44}, {"id": "2021-09-23 - Nomon Tim Burnett - Suzuki Roshi Something Else Zen Practice is Useless", "title": "Suzuki Roshi, Something Else, Zen Practice is Useless", "speaker": "Nomon Tim Burnett", "date": "2021-09-23", "series": "", "summary": "The speaker emphasizes that true freedom from suffering can only be found by letting go of our attachment to external validation, goals, and dualistic thinking. By embracing the impermanence and emptiness of all things, we can cultivate a sense of acceptance and peace that transcends concepts like birth, death, and enlightenment. This is achieved through embodied practice, including sitting meditation (zazen) and mindful attention to our physical posture, which reveals a deeper connection between body and mind.", "themes": ["Buddha-nature", "Impermanence"], "texts": ["Shōbōgenzō"], "minutes": 58}, {"id": "2021-09-16 - Nomon Tim Burnett - Suzuki Roshis Students Katherine Thanas", "title": "Suzuki Roshi's Students, Katherine Thanas", "speaker": "Nomon Tim Burnett", "date": "2021-09-16", "series": "", "summary": "The talk's main teaching emphasizes the importance of approaching challenges with a non-judgmental mind, allowing things to be as they are without trying to change or improve them. This involves recognizing that our minds often judge and try to fix problems, but sometimes we don't have to; instead, we can learn to simply be present with what is, including difficult emotions like fear. By doing so, we can cultivate a deeper understanding of ourselves and the world around us, and develop a more balanced approach to practice that incorporates both form (practical action) and emptiness (the recognition of impermanence).", "themes": ["Buddha-nature", "Suffering", "Vulnerability"], "texts": [], "minutes": 38}, {"id": "2021-09-09 - Nomon Tim Burnett - The Women at the Beginning of Zen Mind Beginners Mind", "title": "The Women at the Beginning of Zen Mind, Beginner's Mind", "speaker": "Nomon Tim Burnett", "date": "2021-09-09", "series": "", "summary": "The talk emphasizes the importance of embracing an ordinary, humble approach to spiritual growth, rather than trying to emulate a revered teacher or achieve a specific state of mind. This allows for a deeper connection with one's true nature, characterized by openness, receptivity, and compassion. By cultivating this mindset, we can transcend dualistic thinking and limitations, experiencing freedom and joy in the present moment.", "themes": ["Buddha-nature", "Compassion"], "texts": [], "minutes": 32}, {"id": "2021-08-19 - Nomon Tim Burnett - Suzuki Roshis Life and Teachings Creating a New Temple", "title": "Suzuki Roshi's Life and Teachings, Creating a New Temple", "speaker": "Nomon Tim Burnett", "date": "2021-08-19", "series": "", "summary": "The talk explores the life and teachings of Suzuki Roshi, a key figure in the Soto Zen tradition, highlighting his emphasis on cultivating a \"beginner's mind\" - a mindset free from ego and preconceptions - as a path to spiritual growth and understanding. This approach is rooted in Suzuki Roshi's humility and non-ego attitude, which he believed was essential for bringing Buddhism to America. By studying Suzuki Roshi's teachings and legacy, the speaker hopes to create a similar sense of community and depth at Red Cedar Zen's new center in Bellingham, Washington.", "themes": ["Impermanence", "No-self"], "texts": ["Lotus Sutra"], "minutes": 44}, {"id": "2021-08-12 - Nomon Tim Burnett - The Power of Stories", "title": "The Power of Stories", "speaker": "Nomon Tim Burnett", "date": "2021-08-12", "series": "", "summary": "The speaker reflects on how engaging with stories and narratives can shape our experiences and perceptions, and encourages us to be mindful of our own storytelling in order to cultivate freedom and compassion. By recognizing the power of stories to influence us, we can choose to tell more expansive and hopeful narratives that bring us closer to reality and each other. This involves approaching life with a sense of openness and awareness, cutting through layers of meaning and conditioning to reveal a more authentic and compassionate way of being.", "themes": ["Emptiness"], "texts": ["Lotus Sutra"], "minutes": 41}, {"id": "2021-07-29 - Seishu John Wiley - Continuous Practice", "title": "Continuous Practice", "speaker": "Seishu John Wiley", "date": "2021-07-29", "series": "", "summary": "The talk's main teaching emphasizes the importance of integrating Zen principles into daily life through continuous practice, which encompasses both formal meditation and mindfulness in everyday activities. This approach is rooted in the concept of a circular path that never ends, where spiritual development is present at every stage. By focusing on how to harmonize body, mind, and spirit with the universe, we can bring balance and harmony into our lives and ultimately contribute to saving all beings by starting with ourselves.", "themes": ["Gratitude", "Sangha"], "texts": [], "minutes": 19}, {"id": "2021-07-22 - Reizan Bob Penny - Ummons Medicine and Sickness Correspond to Each Other", "title": "Ummon's Medicine and Sickness Correspond to Each Other", "speaker": "Reizan Bob Penny", "date": "2021-07-22", "series": "", "summary": "The talk's main teaching is that our individual experiences and reactions are not separate from the larger world around us, but rather an integral part of it. By acknowledging this interconnectedness, we can transform our personal struggles into opportunities for healing and growth, not just for ourselves, but also for others. This understanding encourages us to approach challenges with a sense of responsibility and compassion, recognizing that even our own emotions and reactions have the power to nurture or harm ourselves and those around us.", "themes": ["Interconnection", "Social engagement"], "texts": ["Blue Cliff Record"], "minutes": 17}, {"id": "2021-07-15 - Heigaku Talus Latona - Oops", "title": "Oops", "speaker": "Heigaku Talus Latona", "date": "2021-07-15", "series": "", "summary": "The speaker's talk emphasizes the importance of taking responsibility for our actions and cultivating gratitude, particularly when we make mistakes. By acknowledging our flaws and using them as opportunities for growth, we can learn to recognize harm and take steps to prevent it in the future. This involves being honest with ourselves about our mistakes, rather than trying to hide or excuse them, and finding ways to grow and improve from them.", "themes": ["Ethics", "Gratitude"], "texts": [], "minutes": 22}, {"id": "2021-07-10 - Kanho Chris Burkhart - The Venerable Ananda", "title": "The Venerable Ananda", "speaker": "Kanho Chris Burkhart", "date": "2021-07-10", "series": "", "summary": "The main teaching of the dharma talk revolves around the importance of respecting and honoring the principles that guide our lives as Buddhist practitioners, particularly for women. The speaker shares stories and reflections from the life of Ananda, one of the Buddha's closest disciples, to illustrate the value of humility, compassion, and mindfulness in our daily lives. Through these examples, the talk encourages listeners to cultivate a deeper understanding of the Dharma and its relevance to their own spiritual journeys, ultimately leading to greater wisdom, peace, and freedom.", "themes": ["Social engagement"], "texts": [], "minutes": 32}, {"id": "2021-06-24 - Nomon Tim Burnett - Anathapindika", "title": "Anathapindika", "speaker": "Nomon Tim Burnett", "date": "2021-06-24", "series": "", "summary": "The talk highlights the importance of Anathapindika's story as a model for lay practitioners who want to deepen their understanding of Buddhism. Despite facing challenges, Anathapindika demonstrated remarkable faith and commitment to supporting the sangha, illustrating that true practice requires dedication and support from a community. The talk encourages listeners to cultivate mindfulness, compassion, and generosity in order to receive deeper understandings of reality and bring comfort and support to others.", "themes": ["Impermanence", "Sangha"], "texts": [], "minutes": 46}, {"id": "2021-06-19 - Zoketsu Norman Fischer - The Body", "title": "The Body", "speaker": "Zoketsu Norman Fischer", "date": "2021-06-19", "series": "", "summary": "The speaker reflects on the challenges and problems of life, acknowledging that even in peaceful settings, difficulties can arise, but also encourages the audience to look beyond their immediate experiences and consider the broader context of suffering and injustice, such as the threat of a wildfire or the legacy of slavery and oppression. He invites the audience to cultivate awareness and compassion for themselves and others, and to approach life with a sense of hope and resilience. By doing so, we can find a deeper understanding of ourselves and our place in the world, and develop a more nuanced and compassionate response to the complexities of life.", "themes": ["No-self", "Social engagement"], "texts": [], "minutes": 43}, {"id": "2021-06-18 - Zoketsu Norman Fischer - The Zen Mirror of Tokeiji", "title": "The Zen Mirror of Tokeiji", "speaker": "Zoketsu Norman Fischer", "date": "2021-06-18", "series": "", "summary": "The talk's main teaching is that by looking into mirrors - both literal and metaphorical - we can gain insight into our true nature and find freedom from attachment to our physical appearance and identity. This practice allows us to see beyond the surface level of our thoughts, feelings, and body, revealing our inner selves and the interconnectedness of all things. By embracing this awareness, we can transcend our limitations and discover a deeper sense of self that is not bound by ego or material possessions.", "themes": ["Emptiness", "No-self", "Vulnerability"], "texts": [], "minutes": 41}, {"id": "2021-06-17 - Zoketsu Norman Fischer - The Seven Wise Women in the Charnel Ground", "title": "The Seven Wise Women in the Charnel Ground", "speaker": "Zoketsu Norman Fischer", "date": "2021-06-17", "series": "", "summary": "The talk emphasizes the importance of embracing impermanence and transformation as a path to awakening and understanding. Rather than trying to avoid or escape from difficult experiences, we can find freedom by turning towards them with an open heart and mind. This approach is not about individual achievement, but rather about recognizing that awakening is a collective process that happens between us all, and that true presence and understanding are only possible when we let go of attachment and desire.", "themes": ["Buddha-nature", "Impermanence", "Suffering"], "texts": ["Heart Sutra"], "minutes": 44}, {"id": "2021-06-16 - Nomon Tim Burnett - Reunion Welcoming Trouble Privilege", "title": "Reunion, Welcoming Trouble, Privilege", "speaker": "Nomon Tim Burnett", "date": "2021-06-16", "series": "", "summary": "The main teaching of the Soto Zen dharma talk emphasizes the importance of embracing imperfection and uncertainty in mindfulness practice, particularly during difficult times. Rather than trying to achieve a specific state or overcome challenges through forceful effort, the practice involves acknowledging and working with one's own struggles and limitations. By doing so, we can cultivate awareness, balance, and compassion in our daily lives, even if it means taking small steps towards greater mindfulness and connection with ourselves and others.", "themes": ["No-self", "Social engagement"], "texts": [], "minutes": 50}, {"id": "2021-06-15 - Zoketsu Norman Fischer - More About the Breath Sutra on the Full Awareness of Breathing", "title": "More About the Breath, Sutra on the Full Awareness of Breathing", "speaker": "Zoketsu Norman Fischer", "date": "2021-06-15", "series": "", "summary": "The speaker's main teaching emphasizes the importance of cultivating awareness through mindfulness meditation, particularly focusing on the breath and body. By letting go of attachment and judgment, one can develop a state of calmness and balance between body, breath, and mind, allowing for a direct experience of reality that transcends thoughts and concepts. This understanding is not about achieving a specific state or feeling, but rather embracing the present moment with an open and trusting heart.", "themes": ["Impermanence", "No-self", "Wisdom"], "texts": [], "minutes": 55}, {"id": "2021-06-14 - Kanho Chris Burkhart - A Dharma Talk in Two Chapters", "title": "A Dharma Talk in Two Chapters", "speaker": "Kanho Chris Burkhart", "date": "2021-06-14", "series": "", "summary": "The teacher emphasizes the importance of acknowledging and honoring both the suffering that exists in the world, particularly among those who are struggling with access to healthcare and vaccines, and one's own privilege as a practitioner. This recognition is key to cultivating compassion and understanding, rather than ignoring or separating from the difficulties of others. By embracing this paradoxical reality, we can begin to develop a more nuanced and inclusive approach to spiritual practice, one that acknowledges our interconnectedness with all beings.", "themes": ["Gratitude", "Social engagement", "Suffering"], "texts": [], "minutes": 30}, {"id": "2021-06-13 - Nomon Tim Burnett - Memorial Sesshin Mel Weitsman on How to Sit Zazen", "title": "Memorial Sesshin, Mel Weitsman on How to Sit Zazen", "speaker": "Nomon Tim Burnett", "date": "2021-06-13", "series": "", "summary": "The talk's main teaching emphasizes the importance of living one's spiritual practice in the present moment, rather than looking back at past teachers or traditions. By cultivating mindfulness and clarity through meditation, we can overcome distractions and find support in our daily lives. This approach is rooted in the continuity and constancy of the Dharma tradition, as exemplified by Sojun Mel Weitsman's writing on Zazen, which encourages us to embody the unity of body, breath, and mind to transcend suffering and find freedom.", "themes": ["Acceptance", "Impermanence"], "texts": [], "minutes": 44}, {"id": "2021-06-12 - Zoketsu Norman Fischer - Sojun Mel Weitsman on Breathing", "title": "Sojun Mel Weitsman on Breathing", "speaker": "Zoketsu Norman Fischer", "date": "2021-06-12", "series": "", "summary": "The main teaching of the Soto Zen dharma talk emphasizes the importance of cultivating mindfulness through focused attention on one's breath, which can lead to liberation, selflessness, and a deeper connection with life. By paying attention to the breath, practitioners can let go of attachments, experience release, and develop faith in their true nature, ultimately leading to a sense of well-being and connection to the present moment. This practice can be applied to all aspects of daily life, helping individuals cultivate calmness, composure, and a deeper understanding of impermanence.", "themes": ["Acceptance", "Impermanence"], "texts": [], "minutes": 41}, {"id": "2021-06-10 - Nomon Tim Burnett - Zazen", "title": "Zazen", "speaker": "Nomon Tim Burnett", "date": "2021-06-10", "series": "", "summary": "The talk's main teaching emphasizes the importance of embracing both the ordinary and extraordinary aspects of reality in Zen practice. By cultivating a sense of acceptance, groundedness, and allowingness, we can develop a direct and accepting relationship with our lives, rather than trying to control or manipulate them. This ordinary quality of zazen allows us to approach difficult situations with a sense of fundamental okay-ness, freeing us from reactive patterns and enabling us to live more fully in the present moment.", "themes": ["Acceptance", "Emptiness", "Wisdom"], "texts": [], "minutes": 58}, {"id": "2021-06-06 - Nomon Tim Burnett - Another Dharma Talk on Dharma Position", "title": "Another Dharma Talk on Dharma Position", "speaker": "Nomon Tim Burnett", "date": "2021-06-06", "series": "", "summary": "Our experiences in life may not be as straightforward or separate as we think they are, but rather interconnected and influenced by our minds and past experiences. This understanding is at the heart of the concept of \"Dharma position\" in Zen Buddhism, which encourages us to see things as they are, with all their complexities and imperfections, while also recognizing their emptiness and interconnectedness. By embracing this nuanced perspective, we can cultivate a deeper understanding of ourselves and the world around us, and approach life with greater hopefulness and possibility.", "themes": ["Emptiness", "Interconnection", "Wisdom"], "texts": ["Heart Sutra", "Shōbōgenzō"], "minutes": 49}, {"id": "2021-05-30 - Kanho Chris Burkhart - Dharma Position", "title": "Dharma Position", "speaker": "Kanho Chris Burkhart", "date": "2021-05-30", "series": "", "summary": "The talk's main teaching emphasizes the importance of understanding \"Dharma position,\" which refers to the unique, non-dual nature of each moment in time. By recognizing that all moments are interconnected and empty of separate past, present, and future, we can respond more fully to reality without being limited by our thoughts about time. This perspective encourages us to accept reality as it is, without trying to grasp or manipulate it, allowing for a deeper understanding of the present moment.", "themes": ["Emptiness", "Interconnection", "Wisdom"], "texts": ["Heart Sutra"], "minutes": 29}, {"id": "2021-05-27 - Nomon Tim Burnett - Diversity and the Way We Collectively Create a Social Reality", "title": "Diversity and the Way We Collectively Create a Social Reality", "speaker": "Nomon Tim Burnett", "date": "2021-05-27", "series": "", "summary": "The speaker's talk highlights the importance of recognizing and embracing cultural differences in order to deepen our understanding of diversity and intercultural development within their community, Red Cedar Zen. By acknowledging that our perceptions and behaviors are shaped by culture from childhood, we can approach life with humility, curiosity, and openness to new perspectives, leading to greater compassion and understanding for ourselves and others. This realization is rooted in the idea that there is no single human nature, but rather diverse versions of humanness that respond differently to stress and fear, and that our brains are \"sculpted\" by culture from an early age.", "themes": ["Social engagement", "Wisdom"], "texts": [], "minutes": 44}, {"id": "2021-05-23 - Hoka Chris Fortin - What is it to Wake Up and Be Here Together", "title": "What is it to Wake Up and Be Here Together?", "speaker": "Hoka Chris Fortin", "date": "2021-05-23", "series": "", "summary": "The talk's main teaching is that true transformation happens when we embody awareness and compassion in our daily lives, rather than just trying to achieve a specific state or feeling. By cultivating mindfulness and embracing the full range of human experience, including pain and joy, we can find freedom from suffering and develop deep love and connection with ourselves and others. This involves recognizing our interconnectedness with the world and living in harmony with it, rather than trying to separate ourselves from it.", "themes": ["Interconnection", "Social engagement", "Suffering"], "texts": [], "minutes": 39}, {"id": "2021-05-16 - Anita Feng - What am I Awakening to the Question of Being", "title": "What am I? Awakening to the Question of Being", "speaker": "Anita Feng", "date": "2021-05-16", "series": "", "summary": "The speaker invites us to explore our fundamental question \"what am I?\" by letting go of conceptual thinking and instead cultivating a direct experience of being present in the moment. This involves developing broad awareness and riveting attention onto our experiences, emotions, and thoughts, rather than trying to identify with a fixed self or label. By doing so, we can discover a sense of freedom and integration, and access a state of non-self and nirvana where attachments to labels and concepts dissolve.", "themes": ["Buddha-nature", "Impermanence", "No-self"], "texts": [], "minutes": 36}, {"id": "2021-05-13 - Nomon Tim Burnett - How Our Brains Influence Each Other", "title": "How Our Brains Influence Each Other", "speaker": "Nomon Tim Burnett", "date": "2021-05-13", "series": "", "summary": "The talk emphasizes the importance of recognizing our interconnectedness with others and cultivating compassion in the face of social injustices. By acknowledging our own limitations and taking action to expand our connections, we can work towards creating a more just and equitable world. This involves letting go of materialistic views and embracing a sense of community and shared humanity, particularly through Buddhist practice and honoring the lives and deaths of those who have been targeted by racism and hatred.", "themes": ["Interconnection", "Sangha", "Social engagement"], "texts": [], "minutes": 53}, {"id": "2021-05-09 - Heather Shoren Larusso - Case 29 of the Gateless Gate", "title": "Case 29 of the Gateless Gate", "speaker": "Heather Shoren Larusso", "date": "2021-05-09", "series": "", "summary": "The talk's main teaching is about cultivating a detached awareness by stopping attachment to thoughts and perceptions. This means letting go of our fixed views and investigating what's truly perceiving them, rather than getting caught up in dualistic analysis or identifying with thinking. By doing so, we can tap into the wisdom that animates all things, including ourselves and others, and find a common ground beyond our individual perspectives.", "themes": ["Buddha-nature", "Interconnection", "No-self"], "texts": ["Diamond Sutra", "Gateless Barrier"], "minutes": 27}, {"id": "2021-05-02 - Nomon Tim Burnett - The Sallatha Sutta", "title": "The Sallatha Sutta", "speaker": "Nomon Tim Burnett", "date": "2021-05-02", "series": "", "summary": "The talk emphasizes the importance of accepting pain as it arises, rather than resisting or trying to escape it, in order to break free from patterns of suffering and ignorance. It highlights the difference between those who are untaught worldlings, who often respond with worry and resistance, and well-taught noble disciples, who can experience painful feelings without distraction and instead know how to transcend them through understanding and acceptance. By recognizing our tendency to be \"fettered\" by suffering, we can cultivate a deeper understanding and simply be present in the moment, without needing to change or achieve anything.", "themes": ["Acceptance", "No-self", "Suffering"], "texts": [], "minutes": 36}, {"id": "2021-04-29 - Nomon Tim Burnett - How the Mind Generates Reality", "title": "How the Mind Generates Reality", "speaker": "Nomon Tim Burnett", "date": "2021-04-29", "series": "", "summary": "Our brains create a mental framework that predicts what we'll experience based on past experiences and context, rather than directly perceiving reality. This means that our perception of the world is shaped by our brain's internal workings, including its history and assumptions, which can lead to misunderstandings and misinterpretations. By recognizing this, we can gain a deeper understanding of ourselves and others, leading to greater compassion, wisdom, and self-awareness.", "themes": ["Compassion", "Social engagement", "Suffering"], "texts": [], "minutes": 39}, {"id": "2021-04-25 - Seishu John Wiley - Awakening Mumonkan 19 and the Best Things Ive Found", "title": "Awakening, Mumonkan 19 and the Best Things I've Found", "speaker": "Seishu John Wiley", "date": "2021-04-25", "series": "", "summary": "The talk's main teaching emphasizes that awakening is not a single event, but rather a process of gradual transformation and embodiment of wisdom and compassion through ongoing practice. This understanding was born out of the speaker's personal journey, which initially sought enlightenment as a means to cope with life's challenges, but ultimately revealed itself to be a path of gradual growth and self-discovery.", "themes": ["Acceptance", "Compassion"], "texts": ["Gateless Barrier"], "minutes": 26}, {"id": "2021-04-22 - Nomon Tim Burnett - How the Mind Generates Reality a First Look", "title": "How the Mind Generates Reality, a First Look", "speaker": "Nomon Tim Burnett", "date": "2021-04-22", "series": "", "summary": "The speaker shares a personal anecdote about being interrupted by an unexpected phone call, which allowed them to slow down and appreciate the importance of being present in the moment. This experience serves as a reminder that our minds often operate on autopilot, anticipating and responding to life's events before we're consciously aware of them. By understanding this process, we can begin to break free from automatic patterns and cultivate greater awareness and control over our thoughts and actions.", "themes": ["Sangha", "Suffering"], "texts": [], "minutes": 24}, {"id": "2021-04-18 - Ryushin Andrea Thach - Zen Life Enlightened Life Sojun Mel Weitsman", "title": "Zen Life, Enlightened Life, Sojun Mel Weitsman", "speaker": "Ryushin Andrea Thach", "date": "2021-04-18", "series": "", "summary": "Andrea Thatch will share insights into the teachings of Sochun Mel Weizmann, a renowned Zen master who emphasized cultivating awareness and acceptance in everyday life. According to Mel's approach, enlightenment is not something separate from our daily experiences, but rather an authentic expression that arises when we let go of preconceptions and oppositions. By practicing Zazen and being present to the moment, one can develop stability and transcend their ideas about it, allowing for a more genuine experience of enlightenment in daily life.", "themes": ["Buddha-nature", "No-self"], "texts": ["Shōbōgenzō"], "minutes": 48}, {"id": "2021-04-15 - Nomon Tim Burnett - Baby Brains Nature vs Nurture Not So Simple", "title": "Baby Brains - Nature vs. Nurture, Not So Simple", "speaker": "Nomon Tim Burnett", "date": "2021-04-15", "series": "", "summary": "The talk highlights the importance of understanding how our environment and experiences shape our brains, particularly in early childhood. Just as our brains develop and adapt throughout life, they are also influenced by our caregivers and social interactions, which can have lasting effects on our development and well-being. By recognizing the interplay between nature and nurture, we can better address issues like poverty and inequality that affect brain development and create a more compassionate and equitable society.", "themes": ["Interconnection", "Social engagement"], "texts": [], "minutes": 45}, {"id": "2021-04-11 - Kanho Chris Burkhart - Finding Freedom Through Ethical Conduct Liberty", "title": "Finding Freedom Through Ethical Conduct - Liberty", "speaker": "Kanho Chris Burkhart", "date": "2021-04-11", "series": "", "summary": "The speaker emphasizes that true freedom is not about doing whatever one wants, but rather about respecting the rights and freedoms of others, and cultivating awareness and responsibility in daily life. This requires considering how our individual actions impact those around us, and letting go of attachments to things that may harm or burden others. By embracing this mindset, we can live more mindfully and authentically, finding value in our own existence and making a positive contribution to the world.", "themes": ["Ethics", "Social engagement"], "texts": [], "minutes": 31}, {"id": "2021-04-08 - Nomon Tim Burnett - The Brain as a Network", "title": "The Brain as a Network", "speaker": "Nomon Tim Burnett", "date": "2021-04-08", "series": "", "summary": "The speaker suggests that our understanding of reality should not be limited by simplistic models or metaphors about how the brain works, but rather we should acknowledge their limitations and use them as tools for understanding while also recognizing the complexity and adaptability of the human mind. This approach can help us avoid suffering caused by taking these models too literally and instead cultivate a more nuanced and compassionate understanding of ourselves and the world around us. By acknowledging the dynamic and interconnected nature of our minds, we can begin to see beyond the limitations of our current understanding and move towards greater wisdom and freedom.", "themes": ["Compassion", "Suffering"], "texts": [], "minutes": 53}, {"id": "2021-04-04 - Nomon Tim Burnett - Continuous Practice", "title": "Continuous Practice", "speaker": "Nomon Tim Burnett", "date": "2021-04-04", "series": "", "summary": "The speaker's main teaching emphasizes the importance of continuous practice, inspired by Dogen's essay \"Continuous Practice,\" which involves carrying on with a certain spirit without attachment or expectation. This approach can have a profound impact, creating unity and interconnectedness between the individual and the world around them. By embracing this mindset, one can find peace and inner calm in everyday life, even in the midst of chaos, by simply taking things one step at a time.", "themes": ["Interconnection"], "texts": ["Shōbōgenzō"], "minutes": 35}, {"id": "2021-04-01 - Nomon Tim Burnett - The Dharma of Neuroscience The Triune Brain", "title": "The Dharma of Neuroscience - The Triune Brain", "speaker": "Nomon Tim Burnett", "date": "2021-04-01", "series": "", "summary": "The teacher's talk highlights the importance of critically evaluating scientific information and challenging Western notions of human superiority, particularly in relation to brain function. Instead, they suggest that true liberation comes from embracing our wholeness and interconnectedness with the world around us, letting go of attachments to time, space, and distinctions between ourselves and others. By doing so, we can transcend dualistic thinking and experience a sense of unity and harmony with all things.", "themes": ["Interconnection", "No-self"], "texts": ["Shōbōgenzō"], "minutes": 48}, {"id": "2021-03-28 - Kanho Chris Burkhart - Awakening on the Way of the Bodhisattva", "title": "Awakening on the Way of the Bodhisattva", "speaker": "Kanho Chris Burkhart", "date": "2021-03-28", "series": "Way of the Bodhisattva", "summary": "The speaker invites listeners to appreciate the present moment as a rare opportunity, encouraging them to be mindful of how they spend their time and energy without attachment or grasping. They share personal experiences with imagination and attachment, highlighting the importance of allowing things to arise and pass away naturally. This mindset is rooted in the teachings of Shantideva's \"The Way of the Bodhisattva\", which emphasizes cultivating patience, wisdom, and compassion for all sentient beings. By embracing bodhicitta, or the mind of enlightenment, one can work towards ending suffering and illusions, ultimately embodying Buddha's way of life.", "themes": ["Compassion", "Wisdom"], "texts": [], "minutes": 32}, {"id": "2021-03-25 - Nomon Tim Burnett - Neuroscience and Buddhism Mind and Brain", "title": "Neuroscience and Buddhism, Mind and Brain", "speaker": "Nomon Tim Burnett", "date": "2021-03-25", "series": "", "summary": "The speaker suggests that our traditional views of the mind and brain as separate entities or as solely rational systems may be limiting, and instead proposes exploring alternative perspectives that recognize the intricate interdependence between consciousness and the physical body. By acknowledging the unique value and complexity of consciousness, we can move beyond simplistic notions of logic and emotion to understand how our brains actually work and how they relate to our overall well-being. This new understanding can help us live in greater harmony with ourselves and the world around us, and find fulfillment by aligning with our deeper inner selves.", "themes": ["No-self", "Suffering"], "texts": [], "minutes": 39}, {"id": "2021-03-21 - Ryushin Kate Korn McKenna - Awakening", "title": "Awakening", "speaker": "Ryushin Kate Korn McKenna", "date": "2021-03-21", "series": "", "summary": "Here's a summary paragraph summarizing the main teaching of the Soto Zen dharma talk:\n\nThe talk emphasizes the importance of turning one's attention inward to awaken to the true nature of reality, rather than trying to control or separate from it. This involves recognizing the cycle of suffering that arises from our conditioning and reactions, and learning to pause and choose a more mindful response. By cultivating awareness of our thoughts, emotions, and sensations through mindfulness practice, we can develop a greater understanding of ourselves and approach life with a more open and accepting mindset.", "themes": ["Acceptance", "Suffering"], "texts": ["Heart Sutra"], "minutes": 39}, {"id": "2021-03-18 - Nomon Tim Burnett - Jungian Psychology and Buddhism", "title": "Jungian Psychology and Buddhism", "speaker": "Nomon Tim Burnett", "date": "2021-03-18", "series": "", "summary": "The main teaching of the Soto Zen dharma talk is that true understanding and freedom from suffering are not easily attainable, but by embracing the present moment and letting go of our conditioned minds, we can cultivate a deeper awareness of ourselves and the world around us. This involves recognizing the impermanence and interconnectedness of all things, including our own thoughts and emotions, and finding ways to balance our desire for safety with our need for growth and change. By doing so, we can begin to transcend our limitations and find a more authentic and fulfilling way of living.", "themes": ["Emptiness"], "texts": ["Diamond Sutra", "Heart Sutra"], "minutes": 54}, {"id": "2021-03-14 - Nomon Tim Burnett - Living the Awakened Life Reflections on the Dhammapada", "title": "Living the Awakened Life : Reflections on the Dhammapada", "speaker": "Nomon Tim Burnett", "date": "2021-03-14", "series": "", "summary": "The main teaching of this Soto Zen dharma talk is that cultivating a peaceful mind is essential for achieving liberation from suffering, but it requires recognizing and working with our own biases and flaws in understanding. The practice involves being open-minded, curious, and non-reactive, especially in the face of difficult emotions or experiences, and embracing the importance of morality, ethics, and compassion. By adopting this approach, we can develop a deeper understanding of ourselves and others, and ultimately achieve awakening through mindfulness and virtue.", "themes": ["Compassion", "Ethics", "Suffering"], "texts": [], "minutes": 54}, {"id": "2021-03-06 - Joden Bob Rose - Building a Sanctuary Coming Home to Continuous Practice", "title": "Building a Sanctuary, Coming Home to Continuous Practice", "speaker": "Joden Bob Rose", "date": "2021-03-06", "series": "", "summary": "The speaker emphasizes that spiritual growth requires steady practice and embracing limitations as opportunities for creativity and freedom. By cultivating a regular zazen practice, individuals can develop a healthy habit for mind and body, even in challenging circumstances like the pandemic. This approach encourages finding joy and meaning in simple acts, such as sitting in space, and practicing respect for all things, including one's own life.", "themes": ["Interconnection", "Sangha"], "texts": ["Shōbōgenzō"], "minutes": 41}, {"id": "2021-03-05 - Nomon Tim Burnett - The Meaning of Sesshin", "title": "The Meaning of Sesshin", "speaker": "Nomon Tim Burnett", "date": "2021-03-05", "series": "", "summary": "The talk's main teaching is that home is not a fixed physical place, but rather a state of mind and sense of belonging that can be cultivated through practice and self-inquiry. It requires embracing both stability and uncertainty, being present with the unknown, and cultivating a deep awareness of our humanity and impermanence. By approaching reality with an open and receptive mindset, we can find ease and calm in the present moment, regardless of circumstances, and discover a sense of true home within ourselves.", "themes": ["Acceptance", "Impermanence", "Vulnerability"], "texts": [], "minutes": 40}, {"id": "2021-03-04 - Joden Bob Rose - Song of the GrassRoof Hermitage Conclusion", "title": "Song of the Grass-Roof Hermitage, Conclusion", "speaker": "Joden Bob Rose", "date": "2021-03-04", "series": "Song of the Grass-Roof Hermitage", "summary": "Here is a summary of the talk in 4-6 sentences:\n\nThe speaker invites the audience to cultivate mindfulness and inner peace through a simple yet profound practice: embracing simplicity and non-attachment by living in harmony with nature, as described in the \"Song of the Grass Root Hermitage\". This poem encourages us to let go of attachments and conditioning, and instead approach life with ease and vulnerability. By doing so, we can find freedom from worldly desires and delusions, and discover a sense of peace and stability that is always available, even in difficult times. The speaker hopes to inspire the audience to reflect on the value of simplicity and non-attachment, and to incorporate this practice into their daily lives. Through this practice, we can quiet our minds and find our true nature, free from distractions and conditioning.", "themes": ["Acceptance", "Interconnection", "Sangha"], "texts": [], "minutes": 68}, {"id": "2021-02-28 - Ninen Susan Elbe - Dropping Fear", "title": "Dropping Fear", "speaker": "Ninen Susan Elbe", "date": "2021-02-28", "series": "", "summary": "The speaker's talk explores how fear can be a habitual pattern that affects our relationships and well-being, but also offers a way out of it by cultivating confidence and faith in ourselves and others. By letting go of preconceived notions and embracing the present moment, we can experience life more fully and connect with others on a deeper level. This involves practicing generosity, compassion, and vulnerability, which allows us to find moments of repose and connection with the world around us.", "themes": ["Compassion", "Interconnection", "Vulnerability"], "texts": ["Shōbōgenzō"], "minutes": 36}, {"id": "2021-02-25 - Joden Bob Rose - Song of the GrassRoof Hermitage Lines 2732", "title": "Song of the Grass-Roof Hermitage, Lines 27-32", "speaker": "Joden Bob Rose", "date": "2021-02-25", "series": "Song of the Grass-Roof Hermitage", "summary": "The talk emphasizes the importance of letting go of mental attachments and embracing the present moment, aligning with teachings from various Buddhist traditions that value joy, ease, and calm as keys to achieving enlightenment. Through the practice of Zazen, or sitting meditation, we can cultivate awareness and understanding by releasing thoughts and distractions, finding freedom from attachment and ego. By tuning into our physical bodies and being open to the impermanence of all things, we can live a more authentic and compassionate life.", "themes": ["Buddha-nature", "Impermanence"], "texts": [], "minutes": 30}, {"id": "2021-02-21 - Jeff Bickner - Spiritual Intention", "title": "Spiritual Intention", "speaker": "Jeff Bickner", "date": "2021-02-21", "series": "", "summary": "The speaker's main teaching emphasizes the importance of cultivating spiritual intention, which is motivation without attachment or grasping. This intention is directed towards bodhicitta, or the awakening to awareness with real clarity, and is crucial for spiritual practice. By setting an intention to approach ultimate truth with a genuine altruistic attitude, one can awaken to awareness in all aspects of life, not just during formal sitting practice, and embody the natural state of a bodhisattva.", "themes": ["Acceptance", "Compassion"], "texts": [], "minutes": 31}, {"id": "2021-02-18 - Joden Bob Rose - Song of the GrassRoof Hermitage Lines 2326", "title": "Song of the Grass-Roof Hermitage, Lines 23-26", "speaker": "Joden Bob Rose", "date": "2021-02-18", "series": "Song of the Grass-Roof Hermitage", "summary": "The main teaching of this Soto Zen dharma talk emphasizes the importance of turning inward and returning to one's original nature, rather than seeking answers or liberation through external means. This is seen as the key to awakening, and is encouraged through the study of ancient teachings, practices such as zazen, and a sense of humility and openness. By cultivating awareness and clarity in the present moment, we can embody the qualities of a Bodhisattva and radiate love and light into the world, ultimately finding liberation from our true source.", "themes": ["Sangha", "Wisdom"], "texts": ["Lotus Sutra"], "minutes": 47}, {"id": "2021-02-14 - Chikyo Ewan Magie - Jijuyu Zanmai Isolation Vulnerability Suffering and Courage", "title": "Jijuyu Zanmai, Isolation, Vulnerability, Suffering and Courage", "speaker": "Chikyo Ewan Magie", "date": "2021-02-14", "series": "", "summary": "The talk's main teaching emphasizes the importance of embracing vulnerability and courage in spiritual practice, drawing from experiences of isolation, suffering, and profound loss. This is rooted in the understanding that true growth and transformation can only occur by confronting and working through our deepest wounds and traumas. By acknowledging and accepting this vulnerability, we can tap into a deeper sense of resilience and motivation to continue on the path of spiritual practice, even in the face of adversity.", "themes": ["Sangha", "Suffering", "Vulnerability"], "texts": ["Shōbōgenzō"], "minutes": 25}, {"id": "2021-02-11 - Joden Bob Rose - Song of the GrassRoof Hermitage Lines 1922", "title": "Song of the Grass-Roof Hermitage, Lines 19-22", "speaker": "Joden Bob Rose", "date": "2021-02-11", "series": "Song of the Grass-Roof Hermitage", "summary": "The talk highlights the importance of sitting meditation (zazen) as a fundamental aspect of Zen practice, where one cultivates mindfulness and attention to let go of thoughts and distractions, allowing for a state of \"not knowing\" to arise. This involves embodying complete understanding and realization, rather than just learning meditation techniques. By bringing awareness and beginner's mind to the present moment, we can align with the bodhisattva path and manifest wholesome karma in daily life, without needing external teachings or methods.", "themes": ["Wisdom"], "texts": [], "minutes": 33}, {"id": "2021-02-07 - Nomon Tim Burnett - Enlightenment", "title": "Enlightenment", "speaker": "Nomon Tim Burnett", "date": "2021-02-07", "series": "", "summary": "The speaker's talk explores two approaches to Buddhist practice: systematic methods that aim for a specific goal of awakening, and trust methods that focus on cultivating a sense of freedom and wholeness through non-attachment and openness. The speaker suggests that these two approaches can be complementary, with the systematic method offering insight into our brokenness and the trust method offering a path to healing and transformation. By embracing both perspectives, practitioners can deepen their understanding of themselves and cultivate greater compassion, trust, and freedom in their practice.", "themes": ["Acceptance", "Social engagement", "Suffering"], "texts": [], "minutes": 47}, {"id": "2021-02-04 - Joden Bob Rose - Song of the GrassRoof Hermitage Lines 1318", "title": "Song of the Grass-Roof Hermitage, Lines 13-18", "speaker": "Joden Bob Rose", "date": "2021-02-04", "series": "Song of the Grass-Roof Hermitage", "summary": "Here is a summary of the main teaching in 5 sentences:\n\nThe poem by Keizan asks \"Will this hut perish or not?\" and invites us to look beyond our attachment to specific outcomes and concepts, recognizing that true wisdom lies in understanding that Buddha nature is present regardless of impermanence. This understanding allows us to see through uncertainty and recognize the presence of the original master within ourselves. The speaker suggests that by letting go of attachments to external directions or phenomena, we can find steadiness and stability in our daily practice. By embracing this approach, we can cultivate a sense of freedom and joy, and deepen our connection with the world around us. Ultimately, the poem invites us to explore the nature of reality and our place within it, challenging traditional notions of good and bad and revealing an all-encompassing yet empty quality of consciousness.", "themes": ["Buddha-nature", "Emptiness", "Impermanence"], "texts": ["Diamond Sutra"], "minutes": 52}, {"id": "2021-01-31 - Zoketsu Norman Fischer - Jijuyu Zanmai Escape This Crazy Life of Tears", "title": "Jijuyu Zanmai, Escape This Crazy Life of Tears", "speaker": "Zoketsu Norman Fischer", "date": "2021-01-31", "series": "", "summary": "The talk's main teaching is that even in moments of confusion or uncertainty, one can discover profound truths through practice and engagement with Buddhist rituals and ceremonies. By truly embodying these practices, such as Zazen and Zuisei ceremonies, one can experience a magical transformation and come to appreciate the deeper meaning behind them. This involves not just following external forms, but also cultivating mindfulness, compassion, and respect for others, ultimately leading to personal growth and spiritual development.", "themes": ["Buddha-nature"], "texts": ["Lotus Sutra", "Shōbōgenzō"], "minutes": 57}, {"id": "2021-01-28 - Joden Bob Rose - Song of the GrassRoof Hermitage Lines 912", "title": "Song of the Grass-Roof Hermitage, Lines 9-12", "speaker": "Joden Bob Rose", "date": "2021-01-28", "series": "Song of the Grass-Roof Hermitage", "summary": "The main teaching of the Soto Zen dharma talk emphasizes the importance of cultivating trust and confidence in one's experience and perception, rather than relying on intellectual understanding or doubt. This \"trust without doubt\" is a key aspect of Mahayana Buddhism, which encourages individuals to embody their practice by carrying it with them in daily life. By recognizing that our minds are like vast spaces capable of encompassing all phenomena, we can let go of fear and anxiety and approach our practice with patience, openness, and authenticity.", "themes": ["Acceptance", "Emptiness"], "texts": ["Heart Sutra", "Shōbōgenzō"], "minutes": 57}, {"id": "2021-01-24 - Kukushin Kate McCandless - Reflections of Relentless Rain", "title": "Reflections of Relentless Rain", "speaker": "Kukushin Kate McCandless", "date": "2021-01-24", "series": "", "summary": "The talk's main teaching emphasizes the importance of letting go of our tendency to separate ourselves from the world around us, instead embracing our embodied experience and allowing reality to unfold freely. By doing so, we can observe life more accurately and respond with wisdom and compassion, rather than being controlled by our conditioned perceptions. This understanding can lead to freedom from fixed views and patterns, allowing for a seamless practice of mindfulness and awakening.", "themes": ["Interconnection", "Wisdom"], "texts": ["Blue Cliff Record", "Heart Sutra"], "minutes": 39}, {"id": "2021-01-23 - Joden Bob Rose - Wayseeking Mind", "title": "Wayseeking Mind", "speaker": "Joden Bob Rose", "date": "2021-01-23", "series": "", "summary": "The speaker shares their personal journey as a path to discovering the importance of meditation and continuous practice in Zen Buddhism. Through experiences such as poetry, work, environmental conservation, farming, and community involvement, they came to understand the value of being present, trusting one's instincts, and letting go of regrets. By sharing their own story and reflecting on their Soto Zen practice, the speaker invites listeners to recognize where they are in their own journey and cultivate a steady and continuous practice.", "themes": ["Social engagement", "Vulnerability"], "texts": ["Lotus Sutra", "Shōbōgenzō"], "minutes": 39}, {"id": "2021-01-21 - Joden Bob Rose - Song of the GrassRoof Hermitage Lines 38", "title": "Song of the Grass-Roof Hermitage, Lines 3-8", "speaker": "Joden Bob Rose", "date": "2021-01-21", "series": "Song of the Grass-Roof Hermitage", "summary": "The talk's main teaching emphasizes the importance of accepting and embracing all experiences, including difficult emotions and thoughts, as part of one's practice. Rather than trying to control or avoid them, one should learn to \"love\" or accept these phenomena, allowing for growth and understanding. By letting go of attachment and aversion, we can cultivate a deeper sense of awareness and acceptance, and find true comfort in the present moment.", "themes": ["Acceptance", "Impermanence"], "texts": ["Lotus Sutra"], "minutes": 56}, {"id": "2021-01-17 - Heigaku Talus Latona - SelfReceiving", "title": "Self-Receiving", "speaker": "Heigaku Talus Latona", "date": "2021-01-17", "series": "", "summary": "The talk's main teaching is that true understanding and enlightenment come not from trying to control or change our experiences, but rather from embracing and accepting them exactly as they are. This means letting go of our need for a fixed sense of self and instead allowing phenomena to manifest and reveal themselves in the present moment, without judgment or resistance. By doing so, we can tap into a deeper reality that is beyond words and concepts, and find freedom and peace in the midst of life's challenges.", "themes": ["Emptiness", "Ethics", "Vulnerability"], "texts": ["Shōbōgenzō"], "minutes": 29}, {"id": "2021-01-10 - Kanho Chris Burkhart - Dukkha and Waking Up", "title": "Dukkha and Waking Up", "speaker": "Kanho Chris Burkhart", "date": "2021-01-10", "series": "", "summary": "The talk's main teaching emphasizes the importance of embracing uncertainty and discomfort in life, rather than trying to control or avoid it. By facing our painful experiences head-on through mindfulness practice, we can gain insight into our patterns of suffering and ultimately break free from them. This approach encourages us to cultivate a mindset of openness and awareness, allowing us to respond to life's challenges with greater authenticity and freedom.", "themes": ["Acceptance", "Suffering"], "texts": [], "minutes": 30}, {"id": "2021-01-03 - Nomon Tim Burnett - In Gratitude to Keizan Jokin", "title": "In Gratitude to Keizan Jokin", "speaker": "Nomon Tim Burnett", "date": "2021-01-03", "series": "", "summary": "The teacher reflected on the importance of addressing social issues like homelessness through the practice of Zen, drawing inspiration from Dogen's grandson Keizan Jokin, who helped establish a living tradition of Soto Zen in Japan. Keizan's inclusive approach to teaching and his commitment to listening to others informed his writings on Zazen and his leadership of the Dharma Hall ceremony. Through his teachings, Keizan encouraged practitioners to cultivate a deep understanding and freedom that transcends distinctions between worldly and spiritual realms.", "themes": ["Gratitude", "Social engagement"], "texts": [], "minutes": 38}, {"id": "2020-12-31 - Nomon Tim Burnett - Layman Pang", "title": "Layman Pang", "speaker": "Nomon Tim Burnett", "date": "2020-12-31", "series": "", "summary": "The speaker emphasizes the importance of embracing simplicity and living in the present moment, drawing inspiration from Layman Pong's story and the wisdom of Chinese poet Laman Peng. This involves letting go of attachments to material possessions and desires, finding humor in practice, and cultivating a sense of spontaneity and harmony. By doing so, one can find profound action and ultimate achievement, regardless of external circumstances or the passage of time.", "themes": ["Emptiness", "Wisdom"], "texts": [], "minutes": 29}, {"id": "2020-12-24 - Nomon Tim Burnett - Levels of Consciousness", "title": "Levels of Consciousness", "speaker": "Nomon Tim Burnett", "date": "2020-12-24", "series": "", "summary": "The speaker suggests that our true selves are shaped by deep forces beyond our conscious awareness, and that we should approach life with compassion, forgiveness, and patience rather than trying to control or manipulate ourselves. This requires acknowledging the interconnectedness of body, mind, and emotions, and being aware of our thoughts, emotions, and physical sensations as they influence each other. By recognizing this complexity, we can move beyond simplistic models of human development and tap into a more primal, adaptive system that allows us to thrive and survive.", "themes": ["Compassion", "No-self"], "texts": [], "minutes": 42}, {"id": "2020-12-07 - Nomon Tim Burnett - Keizans Zazen Yojinki Part 3 Practice with Stephen Levine", "title": "Keizan's Zazen Yojinki, Part 3: Practice with Stephen Levine", "speaker": "Nomon Tim Burnett", "date": "2020-12-07", "series": "Keizan's Zazen Yojinki", "summary": "Here is a summary paragraph summarizing the talk's main teaching:\n\nThe speaker emphasizes the importance of embracing impermanence as a fundamental aspect of life, encouraging listeners to cultivate acceptance and appreciation for the present moment. By letting go of resistance and attachment, we can find beauty in change and uncertainty, and ultimately, experience liberation from suffering. This understanding is not just about personal growth, but also about creating a more compassionate and harmonious world.", "themes": ["Acceptance", "Impermanence"], "texts": ["Heart Sutra"], "minutes": 65}, {"id": "2020-12-06 - Kanho Chris Burkhart - Mara and the Buddha", "title": "Mara and the Buddha", "speaker": "Kanho Chris Burkhart", "date": "2020-12-06", "series": "", "summary": "The talk highlights the importance of recognizing Mara, or our own internal temptations and distractions, as the first step towards overcoming them. Rather than seeing Mara as an external force, we must acknowledge its presence within ourselves, allowing us to see through its power and influence. By doing so, we can cultivate a sense of clarity and stability, much like the Buddha's steadfastness under the Bodhi tree, and ultimately achieve our own path to enlightenment.", "themes": ["Acceptance", "Compassion"], "texts": [], "minutes": 29}, {"id": "2020-12-05 - Nomon Tim Burnett - Keizans Zazen Yojinki Part 2", "title": "Keizan's Zazen Yojinki, Part 2", "speaker": "Nomon Tim Burnett", "date": "2020-12-05", "series": "Keizan's Zazen Yojinki", "summary": "The talk emphasizes the importance of cultivating clarity and inner stillness as the path to liberation from desire and attachment. By letting go of our grasping for external circumstances and focusing on our own inner peace, we can experience a sense of freedom and acceptance that allows us to see through life's challenges with clarity. This requires embracing simplicity and mindfulness in our daily lives, aligning our actions with the principles of Zen practice, and approaching each moment with an open and present mindset.", "themes": ["Acceptance", "Suffering"], "texts": [], "minutes": 44}, {"id": "2020-12-04 - Nomon Tim Burnett - Keizans Zazen Yojinki Part 1", "title": "Keizan's Zazen Yojinki, Part 1", "speaker": "Nomon Tim Burnett", "date": "2020-12-04", "series": "Keizan's Zazen Yojinki", "summary": "The speaker's main teaching emphasizes the importance of cultivating awareness and presence in every moment, rather than getting caught up in thoughts or distractions about life, death, or external circumstances. By practicing Zazen (meditation), we can develop a mind and body that are free from thinking and acting, allowing for clarity and inner peace. This freedom is not just an individual experience, but also extends to all beings, including ourselves and others, when we sit still and accept our experiences with an open heart.", "themes": ["Impermanence"], "texts": ["Heart Sutra", "Shōbōgenzō"], "minutes": 38}, {"id": "2020-12-02 - Nomon Tim Burnett - Dogen on Enlightenment", "title": "Dogen on Enlightenment", "speaker": "Nomon Tim Burnett", "date": "2020-12-02", "series": "", "summary": "Here is a summary of the talk's main teaching in plain language:\n\nThe speaker emphasizes that enlightenment and practice are not separate entities, but rather interconnected aspects of the Buddhist path. Through zazen (seated meditation), we can directly experience our true nature, which is beyond words and concepts, and drop away all dualistic thinking and distinctions between subject and object. The goal of zazen is not to achieve a specific state or experience, but rather to reveal our true nature, allowing us to live more authentically and peacefully in the present moment.", "themes": ["Buddha-nature", "No-self"], "texts": [], "minutes": 50}, {"id": "2020-11-26 - Nomon Tim Burnett - Thoughts on zazen from Zoketsu Norman Fischer", "title": "Thoughts on zazen from Zoketsu Norman Fischer", "speaker": "Nomon Tim Burnett", "date": "2020-11-26", "series": "", "summary": "The speaker's main teaching emphasizes the importance of cultivating concentration through meditation, particularly in the context of zazen (sitting meditation). By recognizing and working with common obstacles such as attachment, aversion, and doubt, practitioners can develop greater stability and peace in their minds. Ultimately, the goal is not just to achieve a specific state of mind, but to integrate mindfulness into daily life, allowing it to become a natural part of one's being.", "themes": [], "texts": [], "minutes": 25}, {"id": "2020-11-19 - Nomon Tim Burnett - 101 Zen Stories Part 2 Japanese Zen Stories", "title": "101 Zen Stories, Part 2: Japanese Zen Stories", "speaker": "Nomon Tim Burnett", "date": "2020-11-19", "series": "101 Zen Stories", "summary": "The main teaching of the Soto Zen dharma talk emphasizes the importance of humility, patience, and directness in spiritual practice. Through stories from Zen history, such as Ryōnen's self-mutilation, Bankei's humble response to a priest's boastfulness, and others like \"Midnight Excursion\" and \"A Drop of Water,\" the teacher illustrates that true awakening comes not through punishment or harshness, but rather through kindness, understanding, and attention to detail. By embracing this approach, we can cultivate a deeper understanding of ourselves and the world around us, and find our own path towards spiritual growth and awakening.", "themes": ["Impermanence"], "texts": [], "minutes": 38}, {"id": "2020-11-12 - Nomon Tim Burnett - 101 Zen Stories Part 1 Japanese Zen Stories", "title": "101 Zen Stories, Part 1: Japanese Zen Stories", "speaker": "Nomon Tim Burnett", "date": "2020-11-12", "series": "101 Zen Stories", "summary": "The main teaching of this Soto Zen dharma talk emphasizes the importance of embracing imperfection, acceptance, and letting go of ego in spiritual practice. Through stories from Nyogen Senzaki's book \"101 Zen Stories\" and personal anecdotes, the speaker highlights the value of humility, patience, and understanding in achieving enlightenment. By sharing relatable tales that illustrate the human side of Zen, the speaker aims to make the dharma more accessible and relevant to everyday life.", "themes": ["Acceptance", "Sangha"], "texts": [], "minutes": 40}, {"id": "2020-11-01 - Nomon Tim Burnett - Shosai Myo Kichijyo Dharani", "title": "Shosai Myo Kichijyo Dharani", "speaker": "Nomon Tim Burnett", "date": "2020-11-01", "series": "", "summary": "The main teaching of this Soto Zen dharma talk revolves around the concept of compassion and its relationship to wisdom, as explored in the Simeo Kichijo Dorani sutra. The speaker encourages listeners to approach spiritual practice with discernment, acknowledging that they don't have to attend every session or feel obligated to do so. Instead, they invite listeners to cultivate patience, forbearance, and awareness through devotional chants like \"Om gyah gyah,\" which aims to invoke the goddess Lakshmi and promote healthy positive desire and liberation.", "themes": [], "texts": ["Heart Sutra"], "minutes": 49}, {"id": "2020-10-27 - Kanho Chris Burkhart - On Being Shuso in 2020", "title": "On Being Shuso in 2020", "speaker": "Kanho Chris Burkhart", "date": "2020-10-27", "series": "", "summary": "The speaker encourages the sangha to approach challenges with awareness and openness, rather than avoidance or resistance, by embracing the practice period as a time for growth and community building. This involves recognizing that difficulties are an inherent part of life, but also seeing them as opportunities for spiritual development. By doing so, we can cultivate a sense of freedom from self-centeredness and break open our inner prison, leading to greater awareness and compassion for ourselves and the world around us.", "themes": ["Sangha", "Social engagement"], "texts": [], "minutes": 21}, {"id": "2020-10-22 - Nomon Tim Burnett - Gateless Barrier Case 48 Kanfengs One Road", "title": "Gateless Barrier, Case 48: Kan-feng's One Road", "speaker": "Nomon Tim Burnett", "date": "2020-10-22", "series": "Gateless Barrier", "summary": "The teacher encourages listeners to examine their approach to spiritual practice, considering whether they are making conscious choices or simply following habits and conditioning. They suggest that even small moments, like daily routines, require intention and attention to stay on track with one's spiritual goals. By recognizing our own wholeness and inner wisdom, we can cultivate a sense of community and mutual support among peers, creating a space where individuals can support each other in their practice.", "themes": ["Sangha"], "texts": ["Gateless Barrier"], "minutes": 32}, {"id": "2020-10-15 - Kanho Chris Burkhart - Basic Human Goodness Buddha Nature", "title": "Basic Human Goodness - Buddha Nature", "speaker": "Kanho Chris Burkhart", "date": "2020-10-15", "series": "", "summary": "The talk's main teaching is that even in the midst of challenging times, we can cultivate compassion and recognize the inherent goodness in human nature by shifting our focus to the present moment and letting go of attachment to problems. By doing so, we can transform our response to difficulties from avoidance or resistance to one of understanding and support. This approach recognizes that all events are interconnected and part of a larger web of life, and encourages us to cultivate generosity and compassion for ourselves and others.", "themes": ["Buddha-nature", "Compassion", "Gratitude", "Impermanence", "Interconnection"], "texts": [], "minutes": 28}, {"id": "2020-10-04 - Kanho Chris Burkhart - The Jewel Mirror Samadhi", "title": "The Jewel Mirror Samadhi", "speaker": "Kanho Chris Burkhart", "date": "2020-10-04", "series": "Jewel Mirror Samadhi", "summary": "The talk explores the concept of true mirror samadhi, or the ultimate reality that lies beyond concepts and dualities, as described by Dongshan Liangzhe's poem on the five ranks of enlightenment. This idea emphasizes a progression from recognizing one's personal nature within the universal to achieving unity and freedom, but also highlights the importance of humility and connection with others. By letting go of fixed notions of spiritual stages or ranks, practitioners can instead cultivate mindfulness and turn towards difficult emotions and thoughts with gentleness, leading to greater compassion and non-judgmental awareness.", "themes": ["Buddha-nature", "Emptiness", "Vulnerability"], "texts": [], "minutes": 62}, {"id": "2020-10-01 - Nomon Tim Burnett - Gateless Barrier Case 47 Toushuais Three Barriers", "title": "Gateless Barrier, Case 47: Tou-shuai's Three Barriers", "speaker": "Nomon Tim Burnett", "date": "2020-10-01", "series": "Gateless Barrier", "summary": "The speaker encourages listeners to embark on an open-ended inquiry into their true nature, leaving no stone unturned in their exploration. This process involves questioning initial thoughts and ideas, trusting only in the journey of discovery, and cultivating a mindset of wonder, trust, and openness. By embracing this attitude, we can gradually uncover our true nature, rather than arriving at a fixed understanding, and find freedom from the constraints of life and death.", "themes": ["Buddha-nature", "Impermanence", "Vulnerability"], "texts": ["Gateless Barrier", "Shōbōgenzō"], "minutes": 33}, {"id": "2020-09-29 - Nomon Tim Burnett - What are koans", "title": "What are koans?", "speaker": "Nomon Tim Burnett", "date": "2020-09-29", "series": "", "summary": "The talk's main teaching is that koans are not about achieving a special state or cutting off the mind, but rather about appreciating the present moment and letting go of habitual views. Koans can be seen as a way to smooth out our understanding of reality, much like concrete smoothing, by pointing us towards the ordinary nature of things. By embracing this perspective, we can gain new insights into the world around us and find freedom from preconceptions, rather than trying to grasp or understand them intellectually.", "themes": [], "texts": ["Gateless Barrier"], "minutes": 36}, {"id": "2020-09-24 - Nomon Tim Burnett - Gateless Barrier Case 46 Proceed From the Top of the Pole", "title": "Gateless Barrier, Case 46: Proceed From the Top of the Pole", "speaker": "Nomon Tim Burnett", "date": "2020-09-24", "series": "Gateless Barrier", "summary": "The speaker encourages listeners to fully embody their practice by letting go of attachment to specific outcomes and expectations, and instead trust in the natural unfolding of life. This means embracing uncertainty and impermanence, just like the universe itself, rather than trying to control or achieve a specific state. By doing so, one can cultivate a deeper sense of faith and trust in something greater than themselves, finding freedom and peace even in challenging circumstances.", "themes": ["Acceptance", "Impermanence", "Sangha"], "texts": ["Gateless Barrier"], "minutes": 36}, {"id": "2020-09-17 - Nomon Tim Burnett - Gateless Barrier Case 45 Wutsu Who Is That Other", "title": "'Gateless Barrier, Case 45: Wu-tsu: \"Who Is That Other?\"'", "speaker": "Nomon Tim Burnett", "date": "2020-09-17", "series": "Gateless Barrier", "summary": "The teacher invites participants to let go of automatic reactions and respond mindfully to their surroundings, encouraging them to question their assumptions and look beyond conventional understanding of Buddhism and enlightenment. This koan invites exploration of the nature of reality and the self, suggesting that true understanding can be found by looking within rather than seeking external answers or guidance. By letting go of attachment to specific goals or identities, participants may discover a deeper sense of freedom and awareness.", "themes": ["Buddha-nature", "Suffering"], "texts": ["Gateless Barrier"], "minutes": 35}, {"id": "2020-09-10 - Nomon Tim Burnett - Modern Love A Glance and a Rooster That Changed Everything", "title": "Modern Love - A Glance and a Rooster That Changed Everything", "speaker": "Nomon Tim Burnett", "date": "2020-09-10", "series": "", "summary": "The talk's main teaching is that true understanding and appreciation of Buddhist teachings can only be achieved by embracing their deeper meaning and truth, rather than literal interpretations. The speaker encourages everyone to approach these teachings with an open and curious mind, letting go of preconceptions and cultural biases. By doing so, we can tap into the wisdom and guidance offered by Buddhism, just as a person in need may find healing and transformation through a magical encounter or a loving relationship.", "themes": ["Impermanence", "Sangha", "Suffering"], "texts": [], "minutes": 23}, {"id": "2020-09-06 - Nomon Tim Burnett - The Hymn to the Perfection of Wisdom", "title": "The Hymn to the Perfection of Wisdom", "speaker": "Nomon Tim Burnett", "date": "2020-09-06", "series": "", "summary": "The talk explores the concept of Prajnaparamita, or transcendental wisdom, which emphasizes the importance of direct experience and personal relationship with wisdom. This approach to practice shifts from individual liberation to serving others and helping them awaken to enlightenment, highlighting the interconnectedness of all beings. By embracing this wisdom, one can cultivate a deeper understanding of reality and transform their daily life through generosity, ethics, patience, energy, concentration, and wisdom.", "themes": ["Emptiness", "Wisdom"], "texts": ["Diamond Sutra", "Heart Sutra"], "minutes": 43}, {"id": "2020-09-03 - Shuko Edie Norton - Autumn Light", "title": "Autumn Light", "speaker": "Shuko Edie Norton", "date": "2020-09-03", "series": "", "summary": "The speaker shares their personal journey of discovering Zen Buddhism in their late 30s, which involved struggling with traditional sitting Zazen practices and eventually finding guidance through a community college class taught by a Japanese Zen priest. Through a three-month practice period at Tosahara's Mountain Monastery, they faced numerous challenges, including physical and emotional exhaustion, but ultimately gained valuable insights into their own karma body reactions and limitations. This experience has had a lasting impact on the speaker's life, teaching them to accept themselves and their abilities, rather than trying to push beyond what is possible.", "themes": ["Acceptance", "Suffering"], "texts": [], "minutes": 33}, {"id": "2020-08-27 - Nomon Tim Burnett - Gateless Barrier Cases 4344 Zen Sticks", "title": "Gateless Barrier, Cases 43–44: Zen Sticks", "speaker": "Nomon Tim Burnett", "date": "2020-08-27", "series": "Gateless Barrier", "summary": "The talk highlights the importance of letting go of conceptual thinking and labels in our perception of reality. Through stories and poems, the teacher encourages us to approach life with an open mind and attention, rather than getting caught up in expectations or attachments. By recognizing the limitations of language and concepts, we can cultivate a deeper understanding of impermanence and non-attachment, allowing us to navigate life's challenges with greater ease and clarity.", "themes": ["Emptiness", "No-self"], "texts": ["Gateless Barrier"], "minutes": 27}, {"id": "2020-08-20 - Nomon Tim Burnett - Gateless Barrier Case 42 Manjusri and the Young Woman in Samadhi", "title": "Gateless Barrier, Case 42: Manjusri and the Young Woman in Samadhi", "speaker": "Nomon Tim Burnett", "date": "2020-08-20", "series": "Gateless Barrier", "summary": "The talk highlights that true awakening in Buddhism is not about achieving a specific state or level of spiritual development, but rather about embracing our unique experience and imperfections. It emphasizes the importance of understanding different stages and levels of spiritual development, as well as the value of practice and the role of wise friends in guiding us towards awakening. By letting go of our attachments to dramatic experiences and instead focusing on gradual release from suffering, we can find freedom and liberation in our daily lives.", "themes": ["Sangha", "Wisdom"], "texts": ["Gateless Barrier"], "minutes": 42}, {"id": "2020-08-13 - Nomon Tim Burnett - Gateless Barrier Case 41 Bodhidharma Pacifies the Mind part 2", "title": "Gateless Barrier, Case 41: Bodhidharma Pacifies the Mind, Part 2", "speaker": "Nomon Tim Burnett", "date": "2020-08-13", "series": "Gateless Barrier", "summary": "The talk's main teaching emphasizes the importance of approaching spiritual growth with an open heart and mind, recognizing that profound teachings and experiences are available whenever one is ready, regardless of imperfect conditions. The teacher encourages listeners to be receptive to guidance, even if it comes from unexpected sources or in unconventional settings. By embracing this openness, individuals can begin to cultivate a deeper understanding of themselves and the world around them, ultimately leading to greater freedom and enlightenment.", "themes": ["No-self", "Social engagement"], "texts": ["Gateless Barrier"], "minutes": 34}, {"id": "2020-08-06 - Shuko Edie Norton - Prajna Paramita", "title": "Prajna Paramita", "speaker": "Shuko Edie Norton", "date": "2020-08-06", "series": "Paramitas", "summary": "The talk's main teaching is that wisdom (prajna) is a way of being that allows us to face life's challenges with integrity, composure, and skillful response. It develops from understanding the fundamental teachings of Buddhism, particularly emptiness and impermanence, which reveal the interconnectedness of all phenomena and our place within it. By embracing this understanding, we can cultivate wisdom and navigate life's uncertainties with greater ease, humility, and compassion, ultimately finding peace and freedom in the midst of chaos.", "themes": ["Emptiness", "Impermanence", "Interconnection", "No-self", "Wisdom"], "texts": [], "minutes": 30}, {"id": "2020-08-02 - Kanho Chris Burkhart - The Meal Chant The Three Wheels", "title": "The Meal Chant, The Three Wheels", "speaker": "Kanho Chris Burkhart", "date": "2020-08-02", "series": "", "summary": "The talk's main teaching emphasizes the importance of cultivating an attitude of emptiness and interconnectedness in our daily lives, where everything is seen as a gift and not something that can be owned or controlled. This perspective allows us to practice giving and receiving without boundaries, recognizing that all life is always giving and receiving at the same time. By embracing this spirit, we can develop compassion and wisdom in our interactions with others, leading to a deeper understanding of reality and our place within it.", "themes": ["Emptiness", "Interconnection"], "texts": [], "minutes": 23}, {"id": "2020-07-23 - Ryushin Kate Korn McKenna - Virya Paramita", "title": "Virya Paramita", "speaker": "Ryushin Kate Korn McKenna", "date": "2020-07-23", "series": "Paramitas", "summary": "The speaker encourages everyone to cultivate patient endurance in the face of challenges, recognizing that joy and enthusiastic energy are always available, even in difficult situations. They emphasize the importance of accepting emotions rather than getting caught up in negative thoughts and reactions, and invite the audience to explore practices such as virya (perfect energy) and Shantideva's teachings on cultivating desire and courage, which can lead to freedom and transformation when done without pretense.", "themes": ["Impermanence", "No-self", "Vulnerability"], "texts": [], "minutes": 27}, {"id": "2020-07-16 - Seishu John Wiley - Kshanti Paramita", "title": "Kshanti Paramita", "speaker": "Seishu John Wiley", "date": "2020-07-16", "series": "Paramitas", "summary": "The speaker's talk emphasizes that cultivating patience is not about avoiding problems, but rather about actively engaging with them in a mindful and compassionate way. Through regular meditation practice, one can develop the skill of patience, which allows for full attention, action, and a deeper understanding of oneself and the world. This involves accepting difficulties without becoming annoyed or anxious, while also acknowledging and embracing emotions like anger, and finding humility and connection to all things in the face of impermanence and change.", "themes": ["Impermanence", "Social engagement", "Suffering"], "texts": [], "minutes": 20}, {"id": "2020-07-09 - Reizan Bob Penny - Sila Paramita", "title": "Sila Paramita", "speaker": "Reizan Bob Penny", "date": "2020-07-09", "series": "Paramitas", "summary": "The talk's main teaching is that ethics and morality are not about following strict rules or dogma, but about cultivating a personal approach to right living. Rather than trying to impose one's own views or opinions, it's more effective to listen respectfully and stay present in the moment, allowing for a clearer mind and greater sense of responsibility. By focusing on the process rather than the end goal, we can develop wisdom, practice mindfulness, and navigate complex issues with clarity and compassion.", "themes": ["Ethics", "Social engagement"], "texts": [], "minutes": 40}, {"id": "2020-07-05 - Kanho Chris Burkhart - The Five Contemplations", "title": "The Five Contemplations", "speaker": "Kanho Chris Burkhart", "date": "2020-07-05", "series": "", "summary": "The speaker emphasizes the importance of recognizing our deep connection to all beings and the world around us, encouraging us to cultivate gratitude, generosity, and mindfulness in everyday actions like eating. This understanding allows us to see that our existence is not separate from others, but rather intertwined with their lives and deaths, fostering a sense of equality and compassion. By embracing this interconnectedness, we can transform our relationship with the world and strive to embody the principles of Buddhism, becoming vessels for helping others and realizing our own potential as expressions of the Buddha's way.", "themes": ["Gratitude", "Interconnection"], "texts": [], "minutes": 18}, {"id": "2020-07-02 - Kanho Chris Burkhart - Dana Paramita", "title": "Dana Paramita", "speaker": "Kanho Chris Burkhart", "date": "2020-07-02", "series": "Paramitas", "summary": "The speaker invites listeners to explore the concept of paramitas, or \"perfections,\" which are six qualities that a bodhisattva cultivates in daily life. Rather than striving for an unattainable ideal, these qualities are aspirations to be cultivated through practice, such as cultivating generosity by learning to appreciate small joys and developing compassion through meditation. By examining the paramitas in a nuanced way, listeners can explore how to embody these qualities in their own lives, leading to greater understanding, connection, and wisdom.", "themes": ["Gratitude", "Interconnection"], "texts": [], "minutes": 29}, {"id": "2020-06-25 - Nomon Tim Burnett - Gateless Barrier Case 41 Bodhidharma Pacifies the Mind", "title": "Gateless Barrier, Case 41: Bodhidharma Pacifies the Mind", "speaker": "Nomon Tim Burnett", "date": "2020-06-25", "series": "Gateless Barrier", "summary": "The main teaching of this Soto Zen dharma talk is that true understanding and awakening arise when we let go of our attempts to control or manipulate ourselves, rather than trying to achieve a specific state. This involves embracing the vast emptiness of reality, letting go of fixed ideas and clingings, and approaching life with an open and non-conceptual mind. By doing so, we can connect with something greater and find true understanding in the present moment.", "themes": ["Emptiness", "No-self"], "texts": ["Gateless Barrier"], "minutes": 46}, {"id": "2020-06-18 - Nomon Tim Burnett - Gateless Barrier Case 40 Kueishan Kicks Over the Water Bottle", "title": "Gateless Barrier, Case 40: Kuei-shan Kicks Over the Water Bottle", "speaker": "Nomon Tim Burnett", "date": "2020-06-18", "series": "Gateless Barrier", "summary": "The talk emphasizes the importance of stripping away ego and attachments to gain a deeper understanding of reality. Through stories like Kuishan's rejection of his own ego and Bodhidharma's students' superficial grasping, the teacher highlights how traditional Zen training uses humor and ridicule to help students let go of their preconceptions. By embracing complexity and nuance, we can approach issues like racism and social inequality with a more profound understanding that goes beyond simplistic categorizations.", "themes": ["Emptiness", "Social engagement"], "texts": ["Gateless Barrier"], "minutes": 37}, {"id": "2020-06-17 - Zoketsu Norman Fischer - Ecclesiastes", "title": "Ecclesiastes", "speaker": "Zoketsu Norman Fischer", "date": "2020-06-17", "series": "", "summary": "The speaker suggests that a seemingly pessimistic biblical text like Ecclesiastes can actually be a reminder to appreciate the present moment, particularly our breath, which is both physical and spiritual. This perspective allows us to find meaning in life's impermanence and cultivate wonder and appreciation for what truly matters. By embracing this understanding, we can let go of attachments and find freedom from suffering, living more fully and authentically in the present moment.", "themes": ["Acceptance", "Impermanence", "Suffering"], "texts": ["Shōbōgenzō"], "minutes": 48}, {"id": "2020-06-16 - Zoketsu Norman Fischer - Matsus Meaning of the Ancestors Coming From India", "title": "Matsu's Meaning of the Ancestor's Coming From India", "speaker": "Zoketsu Norman Fischer", "date": "2020-06-16", "series": "", "summary": "The speaker encourages listeners to approach meditation with an open and curious mind, allowing themselves to be aware of their thoughts and emotions without attachment or resistance. This involves acknowledging our flaws and imperfections, rather than trying to escape or idealize ourselves, in order to develop acceptance and compassion for ourselves and others. By letting go of our negative tendencies and cultivating a sense of loving-kindness, we can transform our inner \"war\" into a more peaceful and authentic way of being.", "themes": ["Acceptance", "No-self", "Vulnerability"], "texts": [], "minutes": 44}, {"id": "2020-06-15 - Zoketsu Norman Fischer - Shilous Shortcomings", "title": "Shilou's Shortcomings", "speaker": "Zoketsu Norman Fischer", "date": "2020-06-15", "series": "", "summary": "The speaker encourages listeners to let go of unrealistic expectations and blame, instead embracing the imperfections of themselves and the world around them. By acknowledging both their own flaws and the difficulties faced by others, we can cultivate hope for long-term change and trust in the inherent goodness of human nature. This approach allows us to see ourselves and others as they truly are, rather than trying to fit into narrow or idealized categories, and to find meaning and purpose in our ongoing efforts to grow and learn.", "themes": ["Buddha-nature", "Social engagement"], "texts": ["Diamond Sutra", "Shōbōgenzō"], "minutes": 43}, {"id": "2020-06-14 - Zoketsu Norman Fischer - Tianhuangs Essential Dharma Gate", "title": "Tianhuang's Essential Dharma Gate", "speaker": "Zoketsu Norman Fischer", "date": "2020-06-14", "series": "", "summary": "The talk emphasizes that true understanding and awakening are rare and often missed due to our distractions, but through regular practice like zazen and meditation, we can cultivate awareness and presence, allowing us to appreciate profound moments when they arise. This awareness is not about achieving a specific state or goal, but rather about simply being present and aware, which is the essence of the Buddha's teaching. By embracing this simplicity and radical nature of Zen practice, we can create a more inclusive and compassionate world by recognizing our interconnectedness with others and bowing to their individuality.", "themes": ["Interconnection", "Sangha"], "texts": [], "minutes": 44}, {"id": "2020-06-13 - Zoketsu Norman Fischer - Guishans Do Not Betray Others", "title": "Guishan's Do Not Betray Others", "speaker": "Zoketsu Norman Fischer", "date": "2020-06-13", "series": "", "summary": "The speaker invites listeners to confront the suffering in the world, particularly among marginalized communities, and find peace by acknowledging their own interconnectedness with all beings. This requires recognizing the harm caused by systemic racism, economic injustice, and other forms of oppression, and taking responsibility for creating a more just and compassionate society through our actions and awareness. By settling into ourselves rather than retreating from the world's problems, we can cultivate a sense of unity and care that guides us towards healing and transformation.", "themes": ["Compassion", "Interconnection", "Social engagement", "Suffering"], "texts": [], "minutes": 42}, {"id": "2020-06-11 - Nomon Tim Burnett - Black Lives Matter", "title": "Black Lives Matter", "speaker": "Nomon Tim Burnett", "date": "2020-06-11", "series": "", "summary": "The teacher shares stories about Clyde Ross, an African American man who faced numerous challenges, including poverty, racism, and financial exploitation, to highlight the systemic injustices faced by marginalized communities. These experiences demonstrate how historical inequity continues to affect people of color today, often through unfair housing practices and predatory lending. The goal of sharing these stories is not only to educate but also to inspire a deeper understanding of privilege and inequality in American society, encouraging individuals to take action as bodhisattvas to create positive change.", "themes": ["Social engagement"], "texts": [], "minutes": 36}, {"id": "2020-06-07 - Kanshin Allison Tate - SelfReceiving and Employing Samadhi", "title": "Self-Receiving and Employing Samadhi", "speaker": "Kanshin Allison Tate", "date": "2020-06-07", "series": "", "summary": "The main teaching of this Soto Zen dharma talk emphasizes the importance of embracing an attitude of evenness, or \"jiji u zanmai,\" where everything is encountered without judgment or attachment. Through regular practice of meditation (zazen), one can experience a direct transmission of the Buddha's teachings and realize their true nature, dropping away ego and body to manifest enlightenment. Ultimately, the goal of Zen practice is not to achieve a specific state, but to embody the wisdom and compassion of the Buddha in all aspects of life, making every moment an expression of enlightenment.", "themes": ["Buddha-nature", "Interconnection"], "texts": ["Shōbōgenzō"], "minutes": 43}, {"id": "2020-05-28 - Nomon Tim Burnett - Paramitas Tonglen", "title": "Paramitas, Tonglen", "speaker": "Nomon Tim Burnett", "date": "2020-05-28", "series": "Paramitas", "summary": "The talk highlights the transformative power of imagination and creativity in spiritual practice, drawing on the concept of \"tong len\" from Tibetan Buddhism. This practice involves imagining and breathing in suffering with the intention of transforming it into healing and compassion, ultimately cultivating a sense of light, warmth, and love. By embracing this imaginative approach, one can transcend preconceptions and simply notice how they imagine themselves in relation to others' suffering, radiating out healing energy while offering love back into the world.", "themes": ["Compassion", "Suffering"], "texts": [], "minutes": 39}, {"id": "2020-05-21 - Nomon Tim Burnett - Gateless Barrier Case 39 Yunmen You Have Misspoken", "title": "'Gateless Barrier, Case 39: Yun-men: \"You Have Misspoken\"'", "speaker": "Nomon Tim Burnett", "date": "2020-05-21", "series": "Gateless Barrier", "summary": "The teacher encourages the audience to consider how they can learn from and work with the obstacles and interruptions that inevitably arise in life, rather than getting stuck or frustrated by them. This requires a willingness to let go of our own ego and expectations, and instead cultivate humility and awareness. By embracing this complexity, we can find opportunities for growth and transformation, even when things don't go as planned.", "themes": ["No-self", "Vulnerability", "Wisdom"], "texts": ["Gateless Barrier"], "minutes": 30}, {"id": "2020-05-14 - Nomon Tim Burnett - Gateless Barrier Case 38 Wutsus Buffalo Passes Through the Window", "title": "Gateless Barrier, Case 38: Wu-tsu's Buffalo Passes Through the Window", "speaker": "Nomon Tim Burnett", "date": "2020-05-14", "series": "Gateless Barrier", "summary": "The teacher invites listeners to consider an alternate perspective on their lives by embracing the complexity and mystery of reality, much like the buffalo in Mumonkong case 38. This involves letting go of our usual ways of thinking and being, and being willing to get \"upside down\" with this realization, which can be uncomfortable but ultimately leads to a deeper understanding of ourselves and the world. By embracing this complexity, we can begin to embody the Dharma in our daily lives, rather than just practicing it in quiet contemplation or external rituals.", "themes": ["Acceptance", "Buddha-nature", "No-self"], "texts": ["Gateless Barrier"], "minutes": 31}, {"id": "2020-05-03 - Kakumyo Lowe-Charde - The Eko Dedication of Merit", "title": "The Eko, Dedication of Merit", "speaker": "Kakumyo Lowe-Charde", "date": "2020-05-03", "series": "", "summary": "The speaker's main teaching emphasizes the importance of embracing imperfection and uncertainty in meditation practice, encouraging individuals to let go of preconceptions and expectations in order to tap into a more expansive and receptive state. By cultivating mindfulness and attention to the subtle differences between imagination and experience, one can develop a more authentic and embodied practice that is guided by intuition rather than rational thinking. This approach allows for a deeper connection with the present moment, leading to greater ease, joy, and satisfaction in daily life.", "themes": ["Interconnection", "No-self", "Vulnerability"], "texts": [], "minutes": 23}, {"id": "2020-04-30 - Nomon Tim Burnett - Gateless Barrier Case 37 Chaochou The Oak Tree in the Courtyard", "title": "Gateless Barrier, Case 37: Chao-chou: The Oak Tree in the Courtyard", "speaker": "Nomon Tim Burnett", "date": "2020-04-30", "series": "Gateless Barrier", "summary": "The main teaching of the Soto Zen dharma talk is that true understanding and freedom from suffering can be found within ourselves, without needing external answers or solutions. The speaker suggests that our seeking mind often creates a sense of lack, but by cultivating mindfulness and presence, we can see that what we're looking for was right in front of us all along - much like the oak tree outside the monastery courtyard. By letting go of our need to find answers elsewhere, we can tap into a deeper sense of happiness and stability within ourselves.", "themes": ["Buddha-nature", "Suffering"], "texts": ["Gateless Barrier"], "minutes": 23}, {"id": "2020-04-23 - Nomon Tim Burnett - Gateless Barrier Case 36 Wutsu Meeting Someone Attained in the Way", "title": "Gateless Barrier, Case 36: Wu-tsu: Meeting Someone Attained in the Way", "speaker": "Nomon Tim Burnett", "date": "2020-04-23", "series": "Gateless Barrier", "summary": "The talk's main teaching emphasizes the importance of embracing uncertainty and taking action in the face of adversity, drawing inspiration from the stories of Nyogen Senzaki and Paramahansa Yogananda. The speaker encourages listeners to cultivate a sense of dedication, clarity, and commitment in their own spiritual practice, just as these teachers persevered despite facing significant challenges. By doing so, individuals can find guidance and support on their journey, even when faced with uncertainty or adversity.", "themes": ["Social engagement", "Vulnerability"], "texts": ["Gateless Barrier"], "minutes": 30}, {"id": "2020-04-16 - Nomon Tim Burnett - Gateless Barrier Case 35 Wutsu Which Is the True Chien", "title": "'Gateless Barrier, Case 35: Wu-tsu: \"Which Is the True Ch''ien?\"'", "speaker": "Nomon Tim Burnett", "date": "2020-04-16", "series": "Gateless Barrier", "summary": "The Soto Zen teacher uses a parable from Chinese folklore to encourage listeners to confront their difficult choices and consider the limitations of conventional wisdom. The story illustrates how our inner conflict can lead to division within us, but also suggests that by embracing both sides of ourselves, we can heal and return to wholeness. This teaching invites listeners to explore their own inner divisions and consider a more nuanced approach to decision-making, one that acknowledges the complexity of human experience rather than relying solely on external guidance or rigid rules.", "themes": ["Acceptance", "No-self"], "texts": ["Gateless Barrier"], "minutes": 21}, {"id": "2020-04-05 - Seishu John Wiley - The Merging of Difference and Unity", "title": "The Merging of Difference and Unity", "speaker": "Seishu John Wiley", "date": "2020-04-05", "series": "", "summary": "Here is a summary of the main teaching in plain language:\n\nThe speaker emphasizes the interconnectedness of all things, suggesting that everything in life is part of a larger whole. This idea is reflected in various Buddhist teachings, including the concept of emptiness and form being two sides of the same coin. To truly understand this reality, one must cultivate a clear and open mind through mindfulness and meditation, allowing them to see beyond conceptual labels and biases, and simply be present and aware in daily life.", "themes": ["Emptiness", "Interconnection"], "texts": ["Heart Sutra", "Shōbōgenzō"], "minutes": 23}, {"id": "2020-03-26 - Nomon Tim Burnett - Gateless Barrier Case 32 The Buddha Responds to an Outsider", "title": "Gateless Barrier, Case 32: The Buddha Responds to an Outsider", "speaker": "Nomon Tim Burnett", "date": "2020-03-26", "series": "Gateless Barrier", "summary": "The talk emphasizes the importance of embracing uncertainty and silence in order to cultivate courage and wisdom. In a world filled with constant talking and distraction, it's essential to practice \"emptiness\" by letting go of all views and acknowledging the unknown nature of reality. By doing so, we can develop the strength and clarity needed to navigate life's challenges, including those presented by uncertainty and fear.", "themes": ["Emptiness", "Impermanence", "Social engagement"], "texts": ["Gateless Barrier"], "minutes": 28}, {"id": "2020-03-19 - Nomon Tim Burnett - Gateless Barrier Case 31 Chaochou Investigates the Old Woman", "title": "Gateless Barrier, Case 31: Chao-chou Investigates the Old Woman", "speaker": "Nomon Tim Burnett", "date": "2020-03-19", "series": "Gateless Barrier", "summary": "The talk emphasizes the importance of letting go of preconceptions and assumptions in order to find one's own path forward, especially in uncertain times. By taking a step back from external expectations and distractions, we can cultivate kindness, compassion, and connection with ourselves and others, ultimately tapping into a deeper sense of freedom and rest in the present moment. This approach encourages us to trust our intuition and guidance, rather than relying on external sources or predictability.", "themes": ["Compassion", "Wisdom"], "texts": ["Gateless Barrier"], "minutes": 21}, {"id": "2020-03-07 - Nomon Tim Burnett - Gateless Barrier Case 30 Matsu This Very Mind is Buddha", "title": "'Gateless Barrier, Case 30: Ma-tsu: \"This Very Mind is Buddha\"'", "speaker": "Nomon Tim Burnett", "date": "2020-03-07", "series": "Gateless Barrier", "summary": "The main teaching of this Soto Zen dharma talk emphasizes the importance of embracing our true nature through meditation practice, rather than grasping onto concepts or ideas about Buddhism. By sitting still and allowing ourselves to be present in the moment, we can let go of distractions and find clarity and acceptance. This approach encourages us to sit with our lives as they are, without judgment or attachment, and to cultivate a sense of courage, gratitude, and interdependence with others.", "themes": ["Acceptance", "Buddha-nature"], "texts": ["Gateless Barrier"], "minutes": 38}, {"id": "2020-03-06 - Kanho Chris Burkhart - Why we chant", "title": "Why we chant", "speaker": "Kanho Chris Burkhart", "date": "2020-03-06", "series": "", "summary": "The speaker's talk emphasizes the importance of embracing joy and uncertainty in our lives, rather than getting caught up in negative thoughts and news. By cultivating a sense of openness and connection to something deeper, we can find meaning and guidance in times of challenge. Through practices like chanting, we can connect with our community, honor our ancestors, and tap into the wisdom of the path, ultimately orienting ourselves towards a more compassionate and awakened way of living.", "themes": ["Compassion", "Interconnection", "Sangha"], "texts": ["Heart Sutra"], "minutes": 28}, {"id": "2020-03-05 - Nomon Tim Burnett - Gateless Barrier Case 29 Not the Wind Not the Flag", "title": "'Gateless Barrier, Case 29: \"Not the Wind; Not the Flag\"'", "speaker": "Nomon Tim Burnett", "date": "2020-03-05", "series": "Gateless Barrier", "summary": "The speaker's main teaching emphasizes the importance of cultivating mindfulness and awareness in daily life, particularly during times of uncertainty or crisis like the coronavirus pandemic. By recognizing that our minds are constantly moving and often caught up in fear and doubt, we can learn to observe these thoughts and emotions without judgment, allowing us to respond more skillfully to challenging situations. This practice, rooted in Buddhist teachings, encourages us to focus on the present moment, letting go of control and instead inviting the breath to guide us towards greater understanding and freedom.", "themes": ["Acceptance", "Impermanence", "Vulnerability"], "texts": ["Gateless Barrier"], "minutes": 45}, {"id": "2020-03-01 - Shinmon Michael Newton - The Enmei Jukku Kannon Gyo", "title": "The Enmei Jukku Kannon Gyo", "speaker": "Shinmon Michael Newton", "date": "2020-03-01", "series": "", "summary": "The talk explores the significance of cultivating compassion in Soto Zen practice, highlighting its connection to recognizing our intimate relationship with everything. The speaker emphasizes the importance of embracing our true nature as interconnected beings, rather than separate entities, and invites listeners to reflect on their understanding of this concept through personal exploration and discussion. By doing so, we can deepen our sense of compassion and intimacy, leading to a more authentic and meaningful connection with ourselves and the world around us.", "themes": ["Buddha-nature", "Compassion", "Interconnection"], "texts": ["Heart Sutra"], "minutes": 35}, {"id": "2020-02-27 - Nomon Tim Burnett - Practice Period 5 Sandokai", "title": "Practice Period 5 - Sandokai", "speaker": "Nomon Tim Burnett", "date": "2020-02-27", "series": "Sandokai", "summary": "The speaker's main teaching emphasizes the importance of embracing reality as it is, without getting caught up in concepts or language that can create delusion. This means allowing things to be clear and murky at the same time, rather than trying to separate ourselves from our interconnectedness with all things. By letting go of preconceived notions and embracing uncertainty, we can cultivate a sense of wonder and appreciation for the world around us, and ultimately find true understanding through mindfulness and openness.", "themes": ["Emptiness", "No-self"], "texts": ["Shōbōgenzō"], "minutes": 43}, {"id": "2020-02-20 - Nomon Tim Burnett - Practice Period 4 Sandokai", "title": "Practice Period 4 - Sandokai", "speaker": "Nomon Tim Burnett", "date": "2020-02-20", "series": "Sandokai", "summary": "The main teaching of the Soto Zen dharma talk is that true understanding of Zen cannot be found in words or concepts, but rather through direct experience and intuition. Instead of trying to define or grasp it intellectually, one must be willing to embrace uncertainty and trust in their own goodness and the goodness of others. This involves finding balance within the dynamic tension between opposing forces, such as light and darkness, and learning to navigate relationships with a sense of harmony and mutual understanding.", "themes": ["Acceptance", "Interconnection"], "texts": ["Heart Sutra"], "minutes": 38}, {"id": "2020-02-13 - Nomon Tim Burnett - Practice Period 3 Sandokai", "title": "Practice Period 3 - Sandokai", "speaker": "Nomon Tim Burnett", "date": "2020-02-13", "series": "Sandokai", "summary": "The speaker invites listeners to explore how their minds categorize and divide experiences into pleasant, unpleasant, and neutral, leading to division and suffering. By studying this process, they suggest we can develop greater flexibility and fluidity in our perception of reality. The goal is not to change or achieve a specific state, but rather to cultivate awareness of the process itself, allowing us to appreciate the \"good emptiness\" that arises from recognizing the interconnectedness of all things.", "themes": ["Emptiness", "Interconnection", "Suffering"], "texts": ["Heart Sutra"], "minutes": 29}, {"id": "2020-02-06 - Nomon Tim Burnett - Practice Period 2 Sandokai", "title": "Practice Period 2 - Sandokai", "speaker": "Nomon Tim Burnett", "date": "2020-02-06", "series": "Sandokai", "summary": "The talk's main teaching emphasizes the importance of direct experience over conceptual understanding, suggesting that grasping at abstract concepts like emptiness or unity can lead to delusion rather than enlightenment. Instead, the speaker invites the audience to sit in silence and meditation, allowing them to experience the world without the filter of conceptual thinking, and to develop a deeper understanding of reality through direct engagement with their senses. By doing so, we can transcend dualistic thinking and appreciate the interconnectedness of all things.", "themes": ["Emptiness", "Interconnection", "Suffering"], "texts": [], "minutes": 46}, {"id": "2020-02-02 - Kanho Chris Burkhart - Fukanzazengi Why Sit", "title": "Fukanzazengi - Why Sit?", "speaker": "Kanho Chris Burkhart", "date": "2020-02-02", "series": "", "summary": "The speaker's talk highlights how Dogen's teachings on Fukanzazengi offer a practical approach to embracing uncertainty and impermanence in daily life, encouraging a practice that goes beyond traditional meditation to cultivate awareness and acceptance of the present moment. This involves letting go of thoughts and projections to appreciate reality as it is, rather than trying to control or manipulate it. By doing so, we can find support and authenticity in our lives, even in times of tension and upheaval.", "themes": ["Buddha-nature", "Impermanence", "Vulnerability"], "texts": ["Shōbōgenzō"], "minutes": 22}, {"id": "2020-02-01 - Nomon Tim Burnett - Ritual Just Do It Ji and Ri", "title": "'Ritual, \"Just\" Do It, Ji and Ri'", "speaker": "Nomon Tim Burnett", "date": "2020-02-01", "series": "", "summary": "The talk emphasizes the importance of approaching spiritual practice with a mindset of ritualized awareness, letting go of expectations and attachments. By doing so, we can connect with ourselves and others more deeply and find balance between distinctions and appreciation for impermanence. This approach encourages us to look within and trust our own intuition, rather than relying on external authorities or intellectual understanding, allowing us to access wisdom in everyday moments and relationships.", "themes": ["Buddha-nature", "Suffering"], "texts": ["Diamond Sutra"], "minutes": 39}, {"id": "2020-01-05 - Nomon Tim Burnett - Suffering Humans Practice Here The Heart Sutra", "title": "Suffering Humans Practice Here, The Heart Sutra", "speaker": "Nomon Tim Burnett", "date": "2020-01-05", "series": "Heart Sutra", "summary": "The speaker emphasizes the importance of finding balance between taking life seriously and holding it lightly with humility, suggesting that this paradoxical approach can help us cultivate wisdom, compassion, and liberation from our attachments and ego. By embracing the concept of \"emptiness,\" we can release our assumptions and projections onto the world, leading to a softer boundary between ourselves and others and a greater sense of freedom and openness. This balance allows us to approach life with a sense of hope and prayer for freedom, rather than just intellectual understanding, in order to live with wisdom and kindness.", "themes": ["Emptiness"], "texts": ["Heart Sutra"], "minutes": 39}, {"id": "2019-12-19 - Seishu John Wiley - Teachings Ive Appreciated", "title": "Teachings I've Appreciated", "speaker": "Seishu John Wiley", "date": "2019-12-19", "series": "", "summary": "The speaker shares that a key teaching from their Soto Zen dharma talk is the importance of acceptance and mindfulness in navigating life's challenges. By embracing difficult situations without resistance, individuals can cultivate a deeper sense of peace and meaning, and develop skills to respond more effectively to limitations and challenges. This practice is not about passivity, but rather an active process of fully experiencing and responding to situations with greater equanimity, which can lead to greater liberation and fulfillment in life.", "themes": ["Acceptance", "Sangha", "Social engagement"], "texts": [], "minutes": 24}, {"id": "2019-12-12 - Nomon Tim Burnett - Gateless Barrier Case 26 Fayen Two Monks Roll Up the Blinds", "title": "Gateless Barrier, Case 26: Fa-yen: Two Monks Roll Up the Blinds", "speaker": "Nomon Tim Burnett", "date": "2019-12-12", "series": "Gateless Barrier", "summary": "The talk highlights how our minds often get caught up in seeking happiness through external means, such as others' approval or possessions, rather than finding it within ourselves. This pattern is rooted in a lack of understanding and can lead to attachment and craving, causing us to lose sight of the present moment. By embracing the unknown and letting go of these patterns, we can cultivate a clear mind, calm heart, and sense of satisfaction that comes from within, rather than relying on external sources of happiness.", "themes": ["Compassion", "Emptiness", "Suffering"], "texts": ["Gateless Barrier"], "minutes": 30}, {"id": "2019-12-07 - Nomon Tim Burnett - Gateless Barrier Case 24 Fenghsueh Equality and Differentiation", "title": "Gateless Barrier, Case 24: Feng-hsueh: Equality and Differentiation", "speaker": "Nomon Tim Burnett", "date": "2019-12-07", "series": "Gateless Barrier", "summary": "The teacher's talk emphasizes the importance of embracing the present moment, letting go of notions of before and after, and finding balance between silence and speech. This involves acknowledging both the beauty and imperfection of each, rather than trying to transcend or escape one or the other. By doing so, we can cultivate mindfulness and presence, find our place in life without conceptual thinking, and approach our practice with humility and openness, ultimately showing up for our life as it is, with all its suffering and joy.", "themes": ["Acceptance", "Emptiness", "Vulnerability"], "texts": ["Gateless Barrier"], "minutes": 38}, {"id": "2019-12-06 - Kanshin Allison Tate - Gateless Barrier Case 27 Nansens Not Mind Not Buddha Not Things", "title": "'Gateless Barrier, Case 27: Nansen''s \"Not Mind, Not Buddha, Not Things\"'", "speaker": "Kanshin Allison Tate", "date": "2019-12-06", "series": "Gateless Barrier", "summary": "In this dharma talk, Alison explores the concept of reality as constantly changing and impermanent, encouraging us to let go of attachments to fixed ideas about ourselves or the world around us. We often cling to concepts like a permanent \"everyday mind\" or a safe \"Buddha,\" but true understanding reveals that these are just illusions. By embracing this ever-changing nature of reality, we can begin to see beyond our conceptual frameworks and rest in the present moment, unencumbered by attachments to identity or permanence.", "themes": ["Emptiness", "No-self"], "texts": ["Gateless Barrier"], "minutes": 28}, {"id": "2019-12-05 - Nomon Tim Burnett - Gateless Barrier Case 46 Shihshuang Step from the Top of the Pole", "title": "'Gateless Barrier, Case 46: Shih-shuang: \"Step from the Top of the Pole\"'", "speaker": "Nomon Tim Burnett", "date": "2019-12-05", "series": "Gateless Barrier", "summary": "The speaker's main teaching emphasizes the importance of embracing uncertainty and stability simultaneously, rather than idealizing one over the other. This is achieved by letting go of our need for certainty and control, and instead cultivating a sense of balance and harmony in the midst of chaos. By doing so, we can find freedom and refreshment in the present moment, and trust that true stability comes from embracing the fluidity of life rather than trying to grasp it.", "themes": ["Gratitude", "Impermanence", "Sangha"], "texts": ["Gateless Barrier"], "minutes": 38}, {"id": "2019-11-21 - Reizan Bob Penny - Meditation in the Trees Metta Practice", "title": "Meditation in the Trees, Metta Practice", "speaker": "Reizan Bob Penny", "date": "2019-11-21", "series": "", "summary": "The talk's main teaching emphasizes the importance of approaching all beings, including nature, with kindness and compassion, recognizing our interconnectedness and shared humanity. This means cultivating a sense of empathy and understanding that transcends individual boundaries, allowing us to connect with others on a deeper level. By doing so, we can heal the \"Wound of the Heart\" that often leads to feelings of disconnection and isolation, and instead experience love, compassion, and unity with ourselves and others.", "themes": ["Compassion", "Interconnection", "Vulnerability"], "texts": [], "minutes": 25}, {"id": "2019-11-14 - Nomon Tim Burnett - Gateless Barrier Case 25 Yangshans Sermon from the Third Seat", "title": "Gateless Barrier, Case 25: Yang-shan's Sermon from the Third Seat", "speaker": "Nomon Tim Burnett", "date": "2019-11-14", "series": "Gateless Barrier", "summary": "The talk's main teaching is that our perceptions of reality are shaped by our minds, which can be just as active and imaginative when we're dreaming as they are when we're awake. This idea challenges us to consider whether the boundaries between dreams and waking life are as clear-cut as we think, and encourages us to approach all experiences with a sense of openness and curiosity. By letting go of fixed views and embracing uncertainty, we can cultivate a deeper understanding of ourselves and the world around us.", "themes": ["Wisdom"], "texts": ["Gateless Barrier"], "minutes": 31}, {"id": "2019-10-26 - Nomon Tim Burnett - Gateless Barrier Case 23 Huineng Neither Good Nor Evil", "title": "'Gateless Barrier, Case 23: Hui-neng: \"Neither Good Nor Evil\"'", "speaker": "Nomon Tim Burnett", "date": "2019-10-26", "series": "Gateless Barrier", "summary": "The talk emphasizes the importance of recognizing one's true nature, or original face, through direct experience and letting go of attachment to form and essence. This realization is not just a personal achievement but also a transmission from teacher to student, highlighting the interconnectedness of the sangha and the need for humility and growth together. By embracing this understanding, individuals can deepen their practice and find greater peace and clarity in their daily lives.", "themes": ["Emptiness", "Sangha"], "texts": ["Diamond Sutra", "Gateless Barrier"], "minutes": 43}, {"id": "2019-10-24 - Nomon Tim Burnett - Gateless Barrier Case 22 Mahakasyapas Flagpole", "title": "Gateless Barrier, Case 22: Mahakasyapa's Flagpole", "speaker": "Nomon Tim Burnett", "date": "2019-10-24", "series": "Gateless Barrier", "summary": "The talk highlights the importance of diligent practice and devotion in spiritual growth, as exemplified by Ananda's story about receiving a transmission from his teacher Mahakasyapa. The speaker encourages listeners to cultivate a sense of openness and receptivity, allowing them to settle into their true nature and connection with the world. By embracing life's twists and turns and learning to listen deeply, we can tap into the wisdom and guidance that lies within our experiences.", "themes": ["Acceptance"], "texts": ["Gateless Barrier"], "minutes": 27}, {"id": "2019-10-17 - Nomon Tim Burnett - Gateless Barrier Case 21 Yunmens Dried Shitstick", "title": "Gateless Barrier, Case 21: Yun-men's Dried Shitstick", "speaker": "Nomon Tim Burnett", "date": "2019-10-17", "series": "Gateless Barrier", "summary": "The talk's main teaching centers on finding virtue and enlightenment in everyday life, rather than seeking external validation or special powers. This idea is illustrated by a story where Master Yun Min responds to a monk's question about Buddha with a simple answer: a dried shit stick, which encourages letting go of aversion and appreciating the ordinary nature of reality. By embracing the mundane, we can cultivate a deeper sense of awareness and understanding that is not dependent on external circumstances or achievements.", "themes": ["Acceptance", "Buddha-nature"], "texts": ["Gateless Barrier", "Lotus Sutra"], "minutes": 25}, {"id": "2019-10-10 - Nomon Tim Burnett - Gateless Barrier Case 20 SungYuans Person of Great Strength", "title": "Gateless Barrier, Case 20: Sung-Yuan's Person of Great Strength", "speaker": "Nomon Tim Burnett", "date": "2019-10-10", "series": "Gateless Barrier", "summary": "The talk highlights the importance of recognizing that our minds and actions are often beyond our conscious control, and that relying solely on self-effort can lead to frustration and disappointment. Instead, the teacher suggests embracing a more humble approach, acknowledging that true transformation and spiritual growth may come from external sources or \"other power\" - a concept that transcends individual effort and recognizes the interconnectedness of all things.", "themes": ["No-self"], "texts": ["Gateless Barrier"], "minutes": 20}, {"id": "2019-09-26 - Nomon Tim Burnett - Gateless Barrier Case 19 Nanchuan Everyday Mind is the Way", "title": "'Gateless Barrier, Case 19: Nan-ch''uan: \"Everyday Mind is the Way\"'", "speaker": "Nomon Tim Burnett", "date": "2019-09-26", "series": "Gateless Barrier", "summary": "The teacher's main teaching is that true understanding and freedom come not from trying to achieve a specific state or goal, but rather by cultivating curiosity and interest in the present moment. Rather than focusing on what we want to know or experience, we should focus on simply being with our breath, body, and surroundings without attachment or expectation. By letting go of our need for control and perfection, we can find freedom from mental constructs and simply practice with an open and compassionate mind.", "themes": ["Acceptance"], "texts": ["Gateless Barrier"], "minutes": 33}, {"id": "2019-09-19 - Kanho Chris Burkhart - Gateless Barrier Case 38 Wutsus Buffalo Passes Through the Window", "title": "Gateless Barrier, Case 38: Wu-tsu's Buffalo Passes Through the Window", "speaker": "Kanho Chris Burkhart", "date": "2019-09-19", "series": "Gateless Barrier", "summary": "In this Soto Zen dharma talk, the speaker uses a classic koan to explore the nature of enlightenment and the importance of practice. They suggest that true understanding lies in embracing our imperfections and limitations, rather than trying to force or suppress them. The talk encourages listeners to approach their spiritual journey with gratitude, humility, and awareness, recognizing that true freedom and realization may be just beyond our grasp, and that taking care of the world is an essential part of this process.", "themes": ["Gratitude", "Vulnerability"], "texts": ["Gateless Barrier"], "minutes": 17}, {"id": "2019-09-12 - Nomon Tim Burnett - Gateless Barrier Case 18 Tungshans Three Pounds of Flax", "title": "Gateless Barrier, Case 18: Tung-shan's Three Pounds of Flax", "speaker": "Nomon Tim Burnett", "date": "2019-09-12", "series": "Gateless Barrier", "summary": "The talk emphasizes the importance of embracing uncertainty and mystery in life, encouraging listeners to let go of the need for explanations and understanding. By pausing from our usual tendency to organize and analyze everything, we can find freedom in simply being present with what is, without needing to analyze or understand it further. This approach allows us to cultivate awareness and compassion in daily life, rather than trying to grasp complex concepts or definitive answers.", "themes": ["Buddha-nature"], "texts": ["Gateless Barrier"], "minutes": 32}, {"id": "2019-09-07 - Nomon Tim Burnett - Gateless Barrier Case 17 Kuoshihs Three Calls", "title": "Gateless Barrier, Case 17: Kuo-shih's Three Calls", "speaker": "Nomon Tim Burnett", "date": "2019-09-07", "series": "Gateless Barrier", "summary": "The talk emphasizes that true growth and transformation come from embracing our imperfections and being open to the interactions with others, rather than trying to achieve individual perfection on our own. This requires patience, trust, and a willingness to be vulnerable, allowing us to heal and grow together with others. By surrendering our need for external validation and recognition, we can transcend our limitations and embody compassion, wisdom, and freedom in our daily lives.", "themes": ["Compassion", "Gratitude", "Vulnerability"], "texts": ["Gateless Barrier", "Heart Sutra"], "minutes": 35}, {"id": "2019-08-29 - Kanho Chris Burkhart - The Four Noble Truths Part 4", "title": "The Four Noble Truths, Part 4", "speaker": "Kanho Chris Burkhart", "date": "2019-08-29", "series": "The Four Noble Truths", "summary": "The talk emphasizes the importance of living an ethical life, which is closely tied to the Buddhist path of the Eightfold Path. To cultivate this path, one must develop qualities like honesty, courage, and self-awareness through mindfulness, effort, and concentration. Ultimately, this leads to the practice of Right Concentration, where a clear and focused mind is cultivated through meditation, allowing for a deeper understanding of emptiness and the cultivation of kindness and compassion in daily life.", "themes": ["Compassion", "Emptiness", "Ethics"], "texts": [], "minutes": 20}, {"id": "2019-08-22 - Kanho Chris Burkhart - The Four Noble Truths Part 3", "title": "The Four Noble Truths, Part 3", "speaker": "Kanho Chris Burkhart", "date": "2019-08-22", "series": "The Four Noble Truths", "summary": "In this Soto Zen dharma talk, the main teaching emphasizes the importance of cultivating wise and compassionate communication by abandoning unskillful and ego-driven speech. The speaker encourages participants to develop a practice of right speech that is truthful, kind, and non-harming, and invites them to reflect on their own experiences with discernment in order to deepen their understanding of this essential aspect of the Buddhist path. By doing so, individuals can create a more harmonious and supportive environment for themselves and others.", "themes": ["Ethics", "Wisdom"], "texts": [], "minutes": 21}, {"id": "2019-08-15 - Kanho Chris Burkhart - The Four Noble Truths Part 2", "title": "The Four Noble Truths, Part 2", "speaker": "Kanho Chris Burkhart", "date": "2019-08-15", "series": "The Four Noble Truths", "summary": "The main teaching of this Soto Zen dharma talk emphasizes the importance of recognizing and releasing our attachments to suffering, which arises from our mistaken perception of a separate self. By letting go of these attachments and cultivating mindfulness and wisdom, we can break free from the cycle of suffering and find ease in life. This involves understanding that our thoughts and perceptions are not reality, but rather a way of experiencing it, and learning to respond to life's complexities with greater freedom and liberation.", "themes": ["No-self", "Suffering"], "texts": [], "minutes": 22}, {"id": "2019-08-08 - Kanho Chris Burkhart - The Four Noble Truths Part 1", "title": "The Four Noble Truths, Part 1", "speaker": "Kanho Chris Burkhart", "date": "2019-08-08", "series": "The Four Noble Truths", "summary": "The talk's main teaching emphasizes the importance of understanding our own patterns and attachments in order to end suffering. By examining our lives through meditation and self-reflection, we can gain insight into our habits and behaviors that contribute to our suffering, and ultimately find freedom from it. This process involves recognizing dukkha, or the impermanent and ungraspable nature of life, and taking responsibility for our own well-being, allowing us to live more authentically and freely.", "themes": ["Impermanence", "Suffering"], "texts": [], "minutes": 32}, {"id": "2019-08-01 - Ryushin Kate Korn McKenna and Reizan Bob Penny - What is Zen Part 4", "title": "What is Zen, Part 4", "speaker": "Ryushin Kate Korn McKenna and Reizan Bob Penny", "date": "2019-08-01", "series": "What is Zen", "summary": "The speaker emphasizes the importance of approaching conflicts and imperfections with sincerity and openness, rather than seeking a state of constant peace and happiness. They share their personal experience of finding a more honest community in Zen Buddhism, where mistakes are acknowledged and grown from, and encourage the audience to use available resources to work through their own differences and make good use of their \"messy stories\" in history. By practicing conflict resolution tools like nonviolent communication and anchoring, individuals can cultivate cooperative energy and soften their approach to resolve conflicts in a way that is honest and non-blaming.", "themes": ["Ethics", "Sangha"], "texts": [], "minutes": 48}, {"id": "2019-07-27 - Heigaku Talus Latona and Nyogen Connie Martin - What is Zen Part 3", "title": "What is Zen, Part 3", "speaker": "Heigaku Talus Latona and Nyogen Connie Martin", "date": "2019-07-27", "series": "What is Zen", "summary": "The talk highlights the significance of Sangha, or community, in Zen Buddhism, emphasizing that it encompasses not only monastic communities but also all living beings and nonliving entities. The speaker encourages listeners to cultivate admirable friends, colleagues, and virtues in their own Sangha, recognizing its essential role in spiritual growth and maturity. By doing so, individuals can develop the qualities necessary for a fulfilling and meaningful life, including discernment, persistence, and virtuous behavior.", "themes": ["Sangha"], "texts": [], "minutes": 24}, {"id": "2019-07-18 - Shuko Edie Norton and Shin-yu Scott Allen - What is Zen Part 2", "title": "What is Zen, Part 2", "speaker": "Shuko Edie Norton and Shin-yu Scott Allen", "date": "2019-07-18", "series": "What is Zen", "summary": "The main teaching of this Soto Zen dharma talk emphasizes the importance of having guidance in one's spiritual practice, particularly when it comes to navigating complex questions and doubts. The speaker shares their personal experiences with multiple teachers who have helped them deepen their understanding of Buddhist teachings such as emptiness and perception. By working with a teacher or exploring different perspectives, individuals can cultivate mindfulness, wisdom, and compassion, ultimately leading to a more authentic and fulfilling Zen practice.", "themes": ["Compassion", "Sangha"], "texts": [], "minutes": 46}, {"id": "2019-07-11 - Kanho Chris Burkhart and Seishu John Wiley - What is Zen Part 1", "title": "What is Zen, Part 1", "speaker": "Kanho Chris Burkhart and Seishu John Wiley", "date": "2019-07-11", "series": "What is Zen", "summary": "The speaker's main teaching is that while Zen practice may seem restrictive or formulaic at times, these forms are actually meant to facilitate spiritual growth and transformation by cultivating awareness, mindfulness, and connection with oneself and others. By embracing the forms and rituals of Zen practice, we can develop a greater sense of presence and clarity in our daily lives, even as we navigate imperfection and uncertainty. Ultimately, the goal is not to follow external rules, but to use these tools to train ourselves to be fully present and engaged in each moment.", "themes": ["Buddha-nature", "Sangha"], "texts": ["Heart Sutra"], "minutes": 35}, {"id": "2019-07-03 - Nomon Tim Burnett - Gateless Barrier Case 16 Yunmen The Sound of the Bell", "title": "Gateless Barrier, Case 16: Yun-men: The Sound of the Bell", "speaker": "Nomon Tim Burnett", "date": "2019-07-03", "series": "Gateless Barrier", "summary": "Here is a summary paragraph summarizing the main teaching of the dharma talk:\n\nThe teacher emphasized that true understanding and growth come not from intellectual comprehension or external validation, but from embracing the present moment without attachment or expectation. This involves letting go of questioning and reasoning, and instead cultivating stability and awareness through practices like Zazen meditation. By doing so, we can develop faith, energy, mindfulness, and wisdom, and deepen our connection to ourselves and the world around us.", "themes": ["Emptiness", "Wisdom"], "texts": ["Gateless Barrier", "Heart Sutra"], "minutes": 52}, {"id": "2019-07-02 - Nomon Tim Burnett - Gateless Barrier Case 15 Tungshans Sixty Blows", "title": "Gateless Barrier, Case 15: Tung-shan's Sixty Blows", "speaker": "Nomon Tim Burnett", "date": "2019-07-02", "series": "Gateless Barrier", "summary": "The talk's main teaching emphasizes the importance of embracing uncertainty and impermanence in Zen practice, rather than seeking clear answers or enlightenment as a separate entity. It suggests that powerful experiences in meditation are often conditioned by personal factors and may not necessarily lead to understanding or clarity. Instead, the speaker encourages listeners to approach challenges with humility and self-awareness, recognizing their own inner critic as a potential teacher and learning to sit with the present moment without resistance.", "themes": ["Buddha-nature", "Vulnerability"], "texts": ["Gateless Barrier"], "minutes": 36}, {"id": "2019-07-01 - Nomon Tim Burnett - Gateless Barrier Case 14 Nanchuan Kills the Cat", "title": "Gateless Barrier, Case 14: Nan-ch'uan Kills the Cat", "speaker": "Nomon Tim Burnett", "date": "2019-07-01", "series": "Gateless Barrier", "summary": "The talk's main teaching is that true understanding and peace come from embracing life as it is, without trying to control or predict its twists and turns. By letting go of our attachments to plans and expectations, we can tap into the present moment and find genuine connection and compassion with ourselves and others. This approach encourages us to be open, humble, and aware, allowing us to navigate life's challenges with greater ease and wisdom.", "themes": ["Compassion", "Interconnection", "Social engagement"], "texts": ["Gateless Barrier"], "minutes": 48}, {"id": "2019-06-21 - Zoketsu Norman Fischer - Save the World by Saving Your Own Mind", "title": "Save the World by Saving Your Own Mind", "speaker": "Zoketsu Norman Fischer", "date": "2019-06-21", "series": "", "summary": "Here's a summary paragraph summarizing the main teaching of the Soto Zen dharma talk:\n\nThe true essence of Zen lies not in meditation alone, but in embracing a holistic approach that integrates wisdom, conduct, community, intellectual exploration, and personal reflection into daily life. By doing so, one can cultivate a deeper sense of wonder, awe, and connection with others, leading to a more balanced and compassionate self. Ultimately, this approach allows us to live with greater ease, love, and peace, even in the midst of suffering, by embracing the present moment and letting go of attachments to specific outcomes.", "themes": ["Social engagement", "Suffering", "Wisdom"], "texts": ["Blue Cliff Record"], "minutes": 54}, {"id": "2019-06-20 - Zoketsu Norman Fischer - The Reappearance by Aspiration Sutta", "title": "The Reappearance by Aspiration Sutta", "speaker": "Zoketsu Norman Fischer", "date": "2019-06-20", "series": "", "summary": "The Buddha teaches that even if we have good intentions or aspirations for a better life, they still create a sense of separation from the present moment, which can prevent us from experiencing true freedom and liberation. Instead, he encourages us to focus on being fully alive and present in this moment, without attachment to any idea of purity or impurity, allowing us to cultivate kindness, trust, and self-awareness that goes beyond future goals or desires.", "themes": ["Impermanence", "Wisdom"], "texts": [], "minutes": 44}, {"id": "2019-06-19 - Zoketsu Norman Fischer - Practicing at Samish The Six Subtle Gates to the Sublime", "title": "Practicing at Samish, The Six Subtle Gates to the Sublime", "speaker": "Zoketsu Norman Fischer", "date": "2019-06-19", "series": "", "summary": "The speaker invites listeners to explore the practice of listening to silence, which involves quieting the mind and tuning into the body's connection with the earth, allowing awareness to open up and revealing profound beauty and truth about oneself and the world. This practice can lead to a deeper understanding of one's nature and the ultimate reality of existence, beyond words and concepts. By embracing stillness and silence, we can access a state of stability, calmness, and questioning that reveals the true nature of existence.", "themes": ["Impermanence"], "texts": ["Blue Cliff Record"], "minutes": 61}, {"id": "2019-06-18 - Nomon Tim Burnett - Gateless Barrier Case 13 TeShan Bowls in Hand", "title": "Gateless Barrier, Case 13: Te-Shan : Bowls in Hand", "speaker": "Nomon Tim Burnett", "date": "2019-06-18", "series": "Gateless Barrier", "summary": "The talk's main teaching is about embracing the impermanence and uncertainty of life, letting go of our need for control and explanations, and approaching spiritual practice with a sense of curiosity and openness. By accepting what is happening in the present moment, without judgment or attachment to fixed views, we can cultivate a deeper sense of humility, emptiness, and compassion. This allows us to approach life's challenges with greater ease and wisdom, trusting in the natural flow of time and the unfolding of our own spiritual journey.", "themes": ["Acceptance", "Emptiness"], "texts": ["Gateless Barrier"], "minutes": 53}, {"id": "2019-06-17 - Zoketsu Norman Fischer - The Meal Chant", "title": "The Meal Chant", "speaker": "Zoketsu Norman Fischer", "date": "2019-06-17", "series": "", "summary": "The speaker's talk emphasizes the importance of cultivating generosity, love, and wisdom through simple yet profound acts like eating oriochi meals together as a community. By honoring Buddha and the Bodhisattvas with intention and mindfulness, participants can transform their daily activities into sources of spiritual growth and compassion. This practice is meant to inspire individuals to embody the ideal human life, where they are born into the world with suffering, awaken, teach, and enter nirvana, recognizing the interconnectedness and emptiness of all things.", "themes": ["Emptiness", "Gratitude"], "texts": ["Lotus Sutra", "Shōbōgenzō"], "minutes": 62}, {"id": "2019-06-16 - Kanho Chris Burkhart - Working With Upset", "title": "Working With Upset", "speaker": "Kanho Chris Burkhart", "date": "2019-06-16", "series": "", "summary": "The speaker shares practical advice from the Buddhist text Shantideva on how to tame the mind and overcome obstacles such as anger and distraction, emphasizing the importance of mindfulness and patience in dealing with challenging emotions. They suggest two key practices: focusing on physical sensations in the body and cultivating a sense of \"dis-identification\" where one observes their thoughts and habits without getting caught up in them. By letting go of identification with our thoughts and actions, we can approach life with a fresh and non-judgmental mindset, allowing us to be more open to new perspectives and make more intentional choices.", "themes": ["Acceptance", "Compassion"], "texts": [], "minutes": 31}, {"id": "2019-06-15 - Nomon Tim Burnett - Master Yes Stability and Clarity", "title": "Master! Yes! Stability and Clarity", "speaker": "Nomon Tim Burnett", "date": "2019-06-15", "series": "", "summary": "The speaker invites participants to approach their retreat with an open heart and mind, focusing on cultivating love, confidence, and mindfulness rather than trying to achieve a specific outcome or expectation. This practice is seen as a way to repay their parents for all that they've given them, not through external actions but through the development of virtue and discernment from within. By embracing the ordinary moments of life as opportunities for practice and connection with others, we can cultivate generosity, love, and kindness in our minds and hearts.", "themes": ["Ethics", "Gratitude", "Interconnection"], "texts": ["Gateless Barrier"], "minutes": 42}, {"id": "2019-06-13 - Nomon Tim Burnett - Gateless Barrier Case 12 Juiyen Calls Master", "title": "'Gateless Barrier, Case 12: Jui-yen Calls \"Master\"'", "speaker": "Nomon Tim Burnett", "date": "2019-06-13", "series": "Gateless Barrier", "summary": "The speaker's main teaching emphasizes the importance of approaching life with awareness, curiosity, and an open mind. By acknowledging our presence in each moment, we can cultivate stability and clarity that allows us to stay present and aware, even in the midst of uncertainty or distraction. This practice involves holding attention on a specific object, such as the breath, while also being aware of subtle feelings and sensations in the body, allowing for a supportive and non-judgmental mindset to emerge.", "themes": ["Emptiness", "Wisdom"], "texts": ["Gateless Barrier", "Heart Sutra"], "minutes": 34}, {"id": "2019-05-23 - Heigaku Talus Latona - Faxiangs Created World", "title": "Faxiang's Created World", "speaker": "Heigaku Talus Latona", "date": "2019-05-23", "series": "", "summary": "The talk's main teaching emphasizes the importance of letting go of our ego and self-concept, which can lead to suffering and conditioning. By embracing humility and a sense of service, we can cultivate a more authentic and compassionate way of being. This involves recognizing that our true nature is not defined by our thoughts or actions, but rather by our ability to respond without attachment or expectation, allowing us to tap into our inner strength and wisdom.", "themes": ["Buddha-nature", "No-self"], "texts": [], "minutes": 24}, {"id": "2019-05-16 - Nomon Tim Burnett - Gateless Barrier Case 11 Chaochou and the Hermits", "title": "Gateless Barrier, Case 11: Chao-chou and the Hermits", "speaker": "Nomon Tim Burnett", "date": "2019-05-16", "series": "Gateless Barrier", "summary": "The talk highlights the importance of embracing paradox and humility in Zen practice, drawing on stories from Chinese Buddhist masters such as Zhao Zhou and Master Jiaojiao. These teachings encourage us to look beyond grand or impressive things and instead cultivate a deeper understanding of the ordinary aspects of life, where love, connection, and compassion can be found. By letting go of our attachments and expectations, we can respond authentically to others and find freedom in our actions.", "themes": ["Compassion", "No-self"], "texts": ["Blue Cliff Record", "Gateless Barrier"], "minutes": 34}, {"id": "2019-05-09 - Nomon Tim Burnett - Gateless Barrier Case 10 Chingshui Solitary and Destitute", "title": "Gateless Barrier, Case 10: Ch'ing-shui: Solitary and Destitute", "speaker": "Nomon Tim Burnett", "date": "2019-05-09", "series": "Gateless Barrier", "summary": "The teacher shares a story from the Mumonkan project about a monk named Xingzhui who asks his teacher for help, but is instead pointed towards recognizing his own state of independence and freedom from attachment. This teaching suggests that \"alone\" and \"poor\" may not mean what we typically think they do, but rather refer to a state of possessionlessness and inner richness. The story encourages us to trust in our own practice and recognize the treasure within ourselves, rather than feeling desperate or lacking.", "themes": ["Acceptance", "Buddha-nature"], "texts": ["Gateless Barrier", "Lotus Sutra"], "minutes": 35}, {"id": "2019-04-25 - Ryushin Andrea Thach - The Center of All Existence", "title": "The Center of All Existence", "speaker": "Ryushin Andrea Thach", "date": "2019-04-25", "series": "", "summary": "The talk's main teaching is that our true purpose and passion can be found by listening to an inner call or essence that guides us, but this requires letting go of ego and control. By trusting this inner voice and embracing the present moment with all its uncertainties, we can find comfort and growth in not knowing what's next. This involves cultivating a sense of curiosity, openness, and willingness to risk, allowing life to unfold without obstruction or control.", "themes": ["Acceptance", "Interconnection", "Vulnerability"], "texts": [], "minutes": 35}, {"id": "2019-04-18 - Nomon Tim Burnett - Gateless Barrier Case 9 Chingjangs Nonattained Buddha", "title": "Gateless Barrier, Case 9: Ch'ing-jang's Nonattained Buddha", "speaker": "Nomon Tim Burnett", "date": "2019-04-18", "series": "Gateless Barrier", "summary": "The main teaching of this Soto Zen dharma talk is that true enlightenment or awakening is not something we need to strive for through meditation or self-improvement, but rather it's our natural state of being. This understanding challenges the idea that we must practice and work towards a specific goal in order to attain enlightenment, instead embracing the inherent perfection of reality itself. By letting go of attachments and expectations, we can find true freedom and awakening, without trying to control or achieve it through effort.", "themes": ["Acceptance", "Buddha-nature", "Emptiness"], "texts": ["Gateless Barrier", "Heart Sutra", "Lotus Sutra"], "minutes": 29}, {"id": "2019-03-28 - Nomon Tim Burnett - Gateless Barrier Case 8 Hsichang Builds Carts", "title": "Gateless Barrier, Case 8: Hsi-chang Builds Carts", "speaker": "Nomon Tim Burnett", "date": "2019-03-28", "series": "Gateless Barrier", "summary": "The talk highlights how our conceptual thinking can create rigid views that blind us to reality, but by letting go of these fixed perspectives, we can develop an appreciation for the flow of all phenomena, including thoughts and experiences. This allows us to see things as they truly are, without a sense of self or separate existence, and creates space for us to function and be fully alive. By embracing this fluid and dynamic reality, we can experience liberation from suffering and find freedom in the present moment.", "themes": ["Emptiness", "Impermanence", "Sangha"], "texts": ["Gateless Barrier"], "minutes": 26}, {"id": "2019-03-21 - Nomon Tim Burnett - Gateless Barrier Case 7 Chaochou Wash Your Bowl", "title": "'Gateless Barrier, Case 7: Chao-chou: \"Wash Your Bowl\"'", "speaker": "Nomon Tim Burnett", "date": "2019-03-21", "series": "Gateless Barrier", "summary": "The talk's main teaching is that true understanding and wisdom come from being present and mindful in everyday moments, rather than seeking external guidance. By embracing this approach, we can cultivate a more grounded and compassionate life, where we meet the world with wisdom and strength. This involves letting go of our need for explanations or answers and simply being with what is happening, just as we would when engaging in daily activities.", "themes": ["Impermanence", "Vulnerability"], "texts": ["Gateless Barrier", "Shōbōgenzō"], "minutes": 31}, {"id": "2019-03-02 - Shin-yu Scott Allen - Sharing Our Maturity", "title": "Sharing Our Maturity", "speaker": "Shin-yu Scott Allen", "date": "2019-03-02", "series": "", "summary": "Maturity is not just about acquiring skills and responsibilities, but also cultivating a deeper sense of spirituality that provides meaning and direction in life. This spiritual aspect is essential for leaving a positive impact on the world and making a difference in society. By acknowledging and working with our ego and its tendency to block personal growth, we can mature and develop a deeper understanding of ourselves and others, ultimately creating positive change through intergenerational connections and mentorship.", "themes": ["Compassion", "No-self"], "texts": [], "minutes": 38}, {"id": "2019-03-01 - Ryushin Andrea Thach - Gateless Barrier Case 12 Juiyen Calls Master", "title": "Gateless Barrier, Case 12: Juiyen Calls Master", "speaker": "Ryushin Andrea Thach", "date": "2019-03-01", "series": "Gateless Barrier", "summary": "The talk explores the idea of coming into maturity through embracing life's natural cycles, just like nature responds to changing seasons. This is illustrated through a Zen case about Suigan Calls Master, who remains true to his nature despite 30 years of practice and the influence of external thoughts and emotions. The speaker suggests that true mastery comes from taking responsibility for oneself and trusting one's inner guidance, rather than relying on external authority or codes of ethics.", "themes": ["Interconnection", "Wisdom"], "texts": ["Gateless Barrier", "Shōbōgenzō"], "minutes": 35}, {"id": "2019-02-28 - Nomon Tim Burnett - Gateless Barrier Case 5 Hsiangyen Up a Tree", "title": "Gateless Barrier, Case 5: Hsiang-yen: Up a Tree", "speaker": "Nomon Tim Burnett", "date": "2019-02-28", "series": "Gateless Barrier", "summary": "Maturity is not a fixed state, but rather a process that requires effort and courage to develop. It involves embracing challenges and uncertainty, letting go of our need for certainty and control, and responding with openness and humility in the face of impossibility. By doing so, we can tap into our true nature, find freedom from confusion and judgment, and cultivate a sense of compassion, trust, and authenticity that allows us to live more fully and authentically.", "themes": ["Vulnerability"], "texts": ["Gateless Barrier"], "minutes": 37}, {"id": "2019-02-27 - Shin-yu Scott Allen - Winter Practice Period Shusos Class Continuing Our Maturity Part 5", "title": "Winter Practice Period Shuso's Class - Continuing Our Maturity Part 5", "speaker": "Shin-yu Scott Allen", "date": "2019-02-27", "series": "Winter Practice Period Shuso's Class", "summary": "The talk emphasizes the importance of living an ethical life by cultivating remorse, correcting mistakes, and forgiving oneself, which is key to resolving issues and moving forward with integrity. This involves facing our fears and ego, and acting with compassion towards all beings, including ourselves and others. By practicing generosity, honesty, and self-awareness, we can overcome challenges and cultivate loving kindness, allowing us to find our place in the world and connect with others on a deeper level.", "themes": ["Compassion", "Ethics", "Interconnection"], "texts": [], "minutes": 47}, {"id": "2019-02-20 - Shin-yu Scott Allen - Winter Practice Period Shusos Class Continuing Our Maturity Part 4", "title": "Winter Practice Period Shuso's Class - Continuing Our Maturity Part 4", "speaker": "Shin-yu Scott Allen", "date": "2019-02-20", "series": "Winter Practice Period Shuso's Class", "summary": "Through mindfulness and meditation, we can develop greater awareness of our patterns of pain and suffering, and by letting go of them, we can cultivate a sense of ease, freedom, and acceptance in life. This process allows us to regain control over our lives and live with respect and forgiveness, rather than being controlled by our thoughts and emotions. By embracing this path, we can find direction and meaning in life through making long-term commitments or vows, which bring joy and purpose, even if the goal is not fully attained.", "themes": ["Acceptance", "Impermanence"], "texts": [], "minutes": 42}, {"id": "2019-02-13 - Shin-yu Scott Allen - Winter Practice Period Shusos Class Continuing Our Maturity Part 3", "title": "Winter Practice Period Shuso's Class - Continuing Our Maturity Part 3", "speaker": "Shin-yu Scott Allen", "date": "2019-02-13", "series": "Winter Practice Period Shuso's Class", "summary": "The speaker emphasizes that true growth and maturity come from persisting in our efforts with faith and determination, even when faced with frustration or obstacles. This persistence requires taking a long-range view, recognizing that not every action will have the desired outcome, and continuing to act with wisdom and kindness nonetheless. By cultivating this mindset, we can break free from patterns of anger and negativity passed down from our parents and develop a more compassionate sense of self.", "themes": ["Acceptance", "Compassion", "Interconnection"], "texts": [], "minutes": 44}, {"id": "2019-01-30 - Shin-yu Scott Allen - Winter Practice Period Shusos Class Continuing Our Maturity Part 2", "title": "Winter Practice Period Shuso's Class - Continuing Our Maturity Part 2", "speaker": "Shin-yu Scott Allen", "date": "2019-01-30", "series": "Winter Practice Period Shuso's Class", "summary": "In this Soto Zen dharma talk, the speaker emphasizes the importance of cultivating mature listening skills as a key aspect of personal growth and effective communication. This involves not only actively hearing others but also being present with our own thoughts and emotions without judgment, allowing us to understand ourselves and others more deeply. By recognizing the pitfalls of ego-influenced listening and practicing self-listening, we can develop a more open and empathetic mind, leading to greater understanding and connection with others.", "themes": ["No-self", "Vulnerability"], "texts": [], "minutes": 54}, {"id": "2019-01-23 - Shin-yu Scott Allen - Winter Practice Period Shusos Class Continuing Our Maturity Part 1", "title": "Winter Practice Period Shuso's Class - Continuing Our Maturity Part 1", "speaker": "Shin-yu Scott Allen", "date": "2019-01-23", "series": "Winter Practice Period Shuso's Class", "summary": "Maturity is not solely defined by age or societal expectations of adulthood, but rather by a willingness to confront our own limitations and vulnerabilities. This involves embracing our imperfections and being open to growth and change, especially when faced with uncertainty or discomfort. By letting go of ego and cultivating self-awareness, we can develop the maturity needed to truly fulfill spiritual practice and live a fulfilling life, one that is rooted in wisdom, flexibility, and relational depth.", "themes": ["Acceptance", "No-self", "Wisdom"], "texts": [], "minutes": 49}, {"id": "2019-01-10 - Nomon Tim Burnett - Gateless Barrier Case 4 Bodhidharma Has No Beard", "title": "Gateless Barrier, Case 4: Bodhidharma Has No Beard", "speaker": "Nomon Tim Burnett", "date": "2019-01-10", "series": "Gateless Barrier", "summary": "In this Soto Zen dharma talk, the main teaching is that death can be seen as an opportunity for awakening, using the metaphor of a cradle falling away. This idea encourages us to let go of our attachment to conventional notions and explore what lies beneath by being with questions rather than seeking answers. By embracing the mystery and uncertainty of koans, we can discover new ways of being and experience a sense of ease and clarity that transcends our ordinary perceptions.", "themes": ["Impermanence", "No-self"], "texts": ["Gateless Barrier"], "minutes": 40}, {"id": "2019-01-02 - Nomon Tim Burnett - Gateless Barrier Case 3 Juzhi Raises a Finger", "title": "Gateless Barrier, Case 3: Juzhi Raises a Finger", "speaker": "Nomon Tim Burnett", "date": "2019-01-02", "series": "Gateless Barrier", "summary": "The talk emphasizes the importance of embracing difficult lessons in one's spiritual practice, encouraging listeners to approach challenging experiences with an open heart and mind. This is rooted in the concept of \"one finger Zen,\" which values commitment, steadiness, and remembering what truly matters. By cherishing painful or uncomfortable aspects of our journey, we can deepen our understanding and freedom, ultimately leading us closer to enlightenment.", "themes": ["Acceptance", "Gratitude"], "texts": ["Gateless Barrier"], "minutes": 29}, {"id": "2018-12-27 - Nomon Tim Burnett - Gateless Barrier Case 2 Baizhangs Fox", "title": "Gateless Barrier, Case 2: Baizhang's Fox", "speaker": "Nomon Tim Burnett", "date": "2018-12-27", "series": "Gateless Barrier", "summary": "The talk highlights the importance of understanding karma and its complexities in Buddhist teachings, particularly when it comes to enlightened beings. It emphasizes that even those who have achieved enlightenment are not completely free from cause and effect, but rather navigate it with clarity. The speaker encourages listeners to consider the power of their words, thoughts, and actions, acknowledging that they can create harm or benefit, and to cultivate greater awareness and wisdom through this understanding.", "themes": ["Ethics", "Social engagement"], "texts": ["Gateless Barrier"], "minutes": 32}, {"id": "2018-12-20 - Nomon Tim Burnett - Gateless Barrier Case 1 Zhaozhous Mu", "title": "Gateless Barrier, Case 1: Zhaozhou's Mu", "speaker": "Nomon Tim Burnett", "date": "2018-12-20", "series": "Gateless Barrier", "summary": "The speaker's main teaching is that true understanding and connection can only be achieved by letting go of fixed views and embracing a spirit of openness and curiosity. Rather than seeking answers or outcomes, we should focus on asking questions like \"What is it?\" to cultivate a sense of wonder and freshness in our experience of reality. By doing so, we can develop a deeper connection with the world and ourselves, and find a more authentic and compassionate way of being.", "themes": ["Buddha-nature", "Interconnection"], "texts": ["Gateless Barrier"], "minutes": 22}, {"id": "2018-12-08 - Eko Jeff Kelley - Great Faith Great Doubt Great Determination Part 4 River Obstacles", "title": "Great Faith, Great Doubt, Great Determination, Part 4: River Obstacles", "speaker": "Eko Jeff Kelley", "date": "2018-12-08", "series": "Great Faith, Great Doubt, Great Determination", "summary": "The talk's main teaching emphasizes the importance of embracing both spaciousness and intimacy in one's practice, finding a balance between relaxation into form and personal expression. This is likened to navigating life's challenges, where faith and trust are strengthened through practice but also face obstacles that require patience, skillfulness, and determination to overcome. By acknowledging and surrendering to our doubts and desires, we can transform them into opportunities for growth and deepen our connection with ourselves and the world around us.", "themes": ["Acceptance", "Impermanence", "Vulnerability"], "texts": [], "minutes": 30}, {"id": "2018-12-08 - Nomon Tim Burnett - Great Faith Great Doubt Great Determination Part 3 Without Your Knowledge", "title": "Great Faith, Great Doubt, Great Determination, Part 3: Without Your Knowledge", "speaker": "Nomon Tim Burnett", "date": "2018-12-08", "series": "Great Faith, Great Doubt, Great Determination", "summary": "The talk's main teaching emphasizes the importance of living faith, which is cultivated through experience, determination, and embracing doubt rather than seeking certainty. This approach allows for a deeper connection to Buddhist teachings and tradition, as well as personal growth and liberation. By letting go of attachment to one's own understanding and embracing uncertainty, we can develop a more open and curious mind that ultimately leads to freedom.", "themes": ["Suffering"], "texts": ["Shōbōgenzō"], "minutes": 50}, {"id": "2018-12-07 - Eko Jeff Kelley - Great Faith Great Doubt Great Determination Part 2 Coming Together", "title": "Great Faith, Great Doubt, Great Determination, Part 2: Coming Together", "speaker": "Eko Jeff Kelley", "date": "2018-12-07", "series": "Great Faith, Great Doubt, Great Determination", "summary": "The speaker's talk highlights the importance of balancing two seemingly opposing perspectives in Zen practice: the relational, interconnected model that recognizes our inherent interdependence with others and the world around us, and the individualistic, heroic vision of overcoming obstacles through determination and faith. This balance is crucial for a healthy practice, as it allows us to cultivate both compassion and courage. By embracing this paradox, we can let go of our attachment to a fixed sense of self and instead surrender to the present moment, finding freedom and peace in the process.", "themes": ["Acceptance", "Buddha-nature", "No-self", "Vulnerability"], "texts": [], "minutes": 35}, {"id": "2018-12-06 - Nomon Tim Burnett - Great Faith Great Doubt Great Determination Part 1 Stepping Forward Quietly", "title": "Great Faith, Great Doubt, Great Determination, Part 1: Stepping Forward Quietly", "speaker": "Nomon Tim Burnett", "date": "2018-12-06", "series": "Great Faith, Great Doubt, Great Determination", "summary": "The talk's main teaching is that true spiritual growth and stability come from embracing a simple yet profound practice of trusting in the present moment, rather than trying to control or achieve something specific. By letting go of reactivity and embracing silence, participants can develop greater trust and inner peace, even in the face of difficult emotions or memories. This approach encourages individuals to cultivate a sense of grounding and awareness that can be applied to everyday life, leading to greater stability and freedom.", "themes": ["Suffering"], "texts": [], "minutes": 52}, {"id": "2018-11-30 - Reizan Bob Penny - Integrating Thankfulness", "title": "Integrating Thankfulness", "speaker": "Reizan Bob Penny", "date": "2018-11-30", "series": "", "summary": "The speaker suggests that cultivating thankfulness can be integrated into daily life by practicing mindfulness, particularly through focusing on the breath, allowing us to notice the flow of thoughts, feelings, and elements without attachment or judgment. By embracing this understanding, we can approach life with a sense of contentment, kindness, and generosity, letting go of possessiveness and grasping, and instead finding joy in the present moment. This mindset is cultivated through an accepting attitude of kindness, which involves giving and receiving with generosity and mindfulness, helping us to appreciate even small things, like a breath of air, and express gratitude through letting go of attachments.", "themes": ["Acceptance", "Gratitude", "Interconnection"], "texts": [], "minutes": 20}, {"id": "2018-09-27 - Nomon Tim Burnett - Moving from Form to Formlessness", "title": "Moving from Form to Formlessness", "speaker": "Nomon Tim Burnett", "date": "2018-09-27", "series": "", "summary": "The speaker emphasizes the importance of developing stability and insight through meditation practice, allowing us to see beyond our assumptions and theories about reality. This involves cultivating a sense of grounding and equanimity, as well as taking a fresh look at our understanding of the world. By exploring concepts such as formlessness and awareness, we can begin to see that everything is ephemeral and fabricated, leading to freedom from suffering and a more open way of living.", "themes": ["Emptiness", "Suffering"], "texts": [], "minutes": 27}, {"id": "2018-09-20 - Nomon Tim Burnett - Fundamentals of Zen Practice", "title": "Fundamentals of Zen Practice", "speaker": "Nomon Tim Burnett", "date": "2018-09-20", "series": "", "summary": "The talk's main teaching emphasizes the importance of cultivating stability and insight through meditation practice, recognizing that these two qualities are interconnected and inseparable. By focusing on the breath and letting go of attachment to thoughts or outcomes, we can touch into our true nature and experience reality more clearly. This practice allows us to see things with fresh eyes, free from judgment and reactivity, and respond to challenges in a more open and liberated way.", "themes": ["Acceptance"], "texts": [], "minutes": 35}, {"id": "2018-09-13 - Edward Espe Brown - The Stranger Who Loves You", "title": "The Stranger Who Loves You", "speaker": "Edward Espe Brown", "date": "2018-09-13", "series": "", "summary": "The talk's main teaching is that true fulfillment in Zen practice comes from cultivating a warm-hearted companion to oneself, rather than striving for external validation or perfection. This involves embracing all aspects of one's self, including difficult emotions and experiences, with kindness and acceptance. By doing so, we can find inner peace and connection with others, and let go of the need to change or fix ourselves in order to be worthy.", "themes": ["Acceptance", "Compassion", "Vulnerability"], "texts": [], "minutes": 40}, {"id": "2018-09-06 - Ryushin Andrea Thach - Suzuki Roshis Compassion", "title": "Suzuki Roshi's Compassion", "speaker": "Ryushin Andrea Thach", "date": "2018-09-06", "series": "", "summary": "The speaker reflects on their experience at Tassajara Monastery, where they studied calligraphy and communed with nature, drawing inspiration for exploring the concept of compassion in relation to emptiness. They note that true freedom comes from letting go of attachments and desires, as exemplified by Suzuki Roshi's journey towards compassion after recognizing his own suffering. This understanding is rooted in the idea that compassion arises from embracing emptiness and interconnectedness, allowing us to be present and supportive in the face of difficulties, both within ourselves and for others.", "themes": ["Compassion", "Emptiness", "Suffering"], "texts": [], "minutes": 36}, {"id": "2018-08-23 - Nomon Tim Burnett - Lojong Smoke in the Air", "title": "Lojong - Smoke in the Air", "speaker": "Nomon Tim Burnett", "date": "2018-08-23", "series": "", "summary": "The speaker's talk highlights the importance of accepting reality as it is, rather than trying to change or avoid it. This involves taking responsibility for one's actions, being grateful for everyone and everything, and embracing confusion and imperfection. By doing so, we can cultivate a deeper understanding of reality and awaken to new possibilities, allowing our lives to evolve and transform in response to the challenges we face.", "themes": ["Compassion", "Emptiness", "Gratitude", "Social engagement"], "texts": ["Shōbōgenzō"], "minutes": 38}, {"id": "2018-08-19 - Kanho Chris Burkhart - The Compassion of Noself and Emptiness", "title": "The Compassion of No-self and Emptiness", "speaker": "Kanho Chris Burkhart", "date": "2018-08-19", "series": "", "summary": "The talk explores the concept of compassion and impermanence, suggesting that true understanding can only be grasped by letting go of our preconceptions and expectations. By embracing the present moment and acknowledging the interconnectedness of all things, we can transcend our limited perspectives and find freedom in the midst of change. This involves recognizing that our sense of self is an illusion and that everything is ultimately empty and boundless, free from definition or completion. By dropping our conditioning and biases, we can open ourselves to the experience of life and love, and cultivate a profound recognition of the interconnectedness of all beings, leading to a deeper understanding of compassion and wisdom.", "themes": ["Compassion", "Emptiness", "No-self"], "texts": ["Heart Sutra"], "minutes": 17}, {"id": "2018-08-16 - Nomon Tim Burnett - The Compassionate One Whos Not Busy", "title": "The Compassionate One Who's Not Busy", "speaker": "Nomon Tim Burnett", "date": "2018-08-16", "series": "The One Who's Not Busy", "summary": "The main teaching of this Soto Zen dharma talk emphasizes the importance of embracing impermanence and uncertainty as a path for growth and learning. By letting go of our need to control or fix suffering, we can cultivate compassion and connection with ourselves and others. This approach encourages us to take a bigger perspective, recognizing that even in the midst of activity, there is always someone who is not busy, and to find peace and understanding by breathing in light, love, and compassion.", "themes": ["Compassion", "Social engagement", "Suffering"], "texts": [], "minutes": 39}, {"id": "2018-08-01 - Nomon Tim Burnett - The One Whos Not Busy Part 3", "title": "The One Who's Not Busy, Part 3", "speaker": "Nomon Tim Burnett", "date": "2018-08-01", "series": "The One Who's Not Busy", "summary": "The talk's main teaching emphasizes the importance of letting go of preconceptions and simply being present in the moment, rather than striving for mental clarity or understanding. This is illustrated through the concept of \"non-thinking,\" which refers to a state of engagement with reality without judgment or evaluation. By embracing this approach, practitioners can cultivate compassion and wisdom, and deepen their understanding of themselves and the world around them.", "themes": ["Compassion", "Sangha"], "texts": [], "minutes": 47}, {"id": "2018-07-31 - Nomon Tim Burnett - The One Whos Not Busy Part 2", "title": "The One Who's Not Busy, Part 2", "speaker": "Nomon Tim Burnett", "date": "2018-07-31", "series": "The One Who's Not Busy", "summary": "The main teaching of the Soto Zen dharma talk emphasizes the importance of approaching practice with openness, awareness, and gratitude, rather than trying to control or avoid distractions. This involves recognizing the impermanence of thoughts and emotions, allowing them to arise and pass without judgment, and cultivating a sense of \"not busy\" or effortless awareness. By letting go of our preconceptions and habitual perceptions, we can begin to see reality with fresh eyes, leading to liberation from suffering and a deeper understanding of ourselves and the world around us.", "themes": ["Acceptance", "No-self", "Vulnerability"], "texts": [], "minutes": 57}, {"id": "2018-07-30 - Nomon Tim Burnett - The One Whos Not Busy Part 1", "title": "The One Who's Not Busy, Part 1", "speaker": "Nomon Tim Burnett", "date": "2018-07-30", "series": "The One Who's Not Busy", "summary": "The speaker's main teaching emphasizes that our individual experiences are interconnected with everything around us, allowing us to see ourselves as part of a larger system rather than separate individuals. This understanding can help cultivate compassion and cooperation by recognizing the complexity of our experiences. Through practices like sesshin meditation, we can explore this interconnectedness and develop greater awareness and presence in our daily lives, leading to a more nuanced and open approach to reality.", "themes": ["Interconnection"], "texts": [], "minutes": 29}, {"id": "2018-06-28 - Nomon Tim Burnett - Bodhisattva Vows of Compassion", "title": "Bodhisattva Vows of Compassion", "speaker": "Nomon Tim Burnett", "date": "2018-06-28", "series": "", "summary": "The talk's main teaching is that cultivating compassion and renunciation is key to practicing the Bodhisattva vow, which aims to save all beings. This requires finding a middle way between extremes of selflessness and paralysis, and instead embracing a genuine and practical approach to helping others. By doing so, we can remember our true nature and cultivate peace and continuity, even in the face of impossible vows and contradictions.", "themes": ["Acceptance", "Compassion"], "texts": [], "minutes": 34}, {"id": "2018-06-22 - Zoketsu Norman Fischer - Mahaparinirvana Sutra Part 3", "title": "Mahaparinirvana Sutra, Part 3", "speaker": "Zoketsu Norman Fischer", "date": "2018-06-22", "series": "Mahaparinirvana Sutra", "summary": "The talk emphasizes the importance of embracing the present moment and finding peace in the midst of change and impermanence. It suggests that our usual expectations around concentration and spiritual transformation may not be necessary or even helpful, and instead encourages us to cultivate compassion and mindfulness as we navigate the natural process of life and death. By doing so, we can find a sense of continuity with those who have passed on and carry forward their legacy in our own lives.", "themes": ["Compassion", "Impermanence"], "texts": [], "minutes": 51}, {"id": "2018-06-21 - Zoketsu Norman Fischer - Mahaparinirvana Sutra Part 2", "title": "Mahaparinirvana Sutra, Part 2", "speaker": "Zoketsu Norman Fischer", "date": "2018-06-21", "series": "Mahaparinirvana Sutra", "summary": "Here's a summary of the talk in one paragraph:\n\nThe dharma talk explores the impermanence of all things, using stories from the Buddha's life to illustrate this principle. The story of Ananda's awakening highlights the importance of interdependence and humility in spiritual growth, while the Buddha's own passing away is seen as a natural progression towards Nirvana. Ultimately, the talk encourages listeners to cultivate mindfulness and awareness by appreciating all encounters, including those that may seem challenging or unhelpful, and to remember a quiet and peaceful presence at the heart of life and death.", "themes": ["Buddha-nature", "Impermanence", "Interconnection"], "texts": [], "minutes": 53}, {"id": "2018-06-20 - Zoketsu Norman Fischer - Mahaparinirvana Sutra Part 1", "title": "Mahaparinirvana Sutra, Part 1", "speaker": "Zoketsu Norman Fischer", "date": "2018-06-20", "series": "Mahaparinirvana Sutra", "summary": "The teacher emphasizes the importance of cultivating moral conduct as a foundation for spiritual growth, encouraging listeners to approach their own pain and confusion with courage and kindness. By practicing morality, we can develop wisdom that is free from false views and ignorance, allowing us to appreciate life as it is and be fully content and appreciative. This approach is rooted in the Buddha's teachings on the interconnectedness of morality, concentration, and wisdom, which together bring about great fruit and profit when cultivated together.", "themes": ["Ethics", "Suffering", "Wisdom"], "texts": [], "minutes": 50}, {"id": "2018-06-19 - Zoketsu Norman Fischer - Dogens Refrain From Evil part 2", "title": "Dogen's Refrain From Evil Part 2", "speaker": "Zoketsu Norman Fischer", "date": "2018-06-19", "series": "Dogen's Refrain From Evil", "summary": "The talk's main teaching emphasizes that everything we do can be considered spiritual practice if we approach it with mindfulness and intention. By recognizing this, we can transform even mundane activities into opportunities for growth and self-realization, letting go of ego and attachment to achieve a state of awakening where life unfolds naturally. This understanding allows us to cultivate wholesome action and purify our minds, revealing the inherent goodness in reality that can bring about positive change and personal transformation.", "themes": ["Buddha-nature", "Ethics"], "texts": ["Shōbōgenzō"], "minutes": 57}, {"id": "2018-06-18 - Zoketsu Norman Fischer - Dogens Refrain From Evil part 1", "title": "Dogen's Refrain From Evil Part 1", "speaker": "Zoketsu Norman Fischer", "date": "2018-06-18", "series": "Dogen's Refrain From Evil", "summary": "The speaker's talk emphasizes the importance of living a life guided by goodness and creating a world where good action prevails. They encourage listeners to thoroughly investigate the teachings of the three pure precepts, which are not just individual choices, but a mutual activity of transmitting and receiving that allows us to see reality as it is, without judgment or attachment. By embracing this understanding, we can let go of our attachments and judgments, and instead focus on making wholesome actions the center of our lives, trusting that everything will be okay even in difficult times.", "themes": ["Ethics", "Social engagement"], "texts": ["Shōbōgenzō"], "minutes": 49}, {"id": "2018-06-16 - Nomon Tim Burnett - Taking In The Whole Landscape Treatment of Immigrants to the US", "title": "Taking In The Whole Landscape - Treatment of Immigrants to the US", "speaker": "Nomon Tim Burnett", "date": "2018-06-16", "series": "", "summary": "The talk's main teaching emphasizes the importance of embracing complexity and uncertainty in life, rather than retreating from challenges or difficulties. The speaker encourages listeners to cultivate compassion and awareness, particularly when faced with issues like immigration policy and social injustice, and to find freedom and unity by letting go of habitual ways of thinking and believing in separation. By doing so, we can transcend our fears and obstacles, including the fear of time itself, and co-create a world of strong love and freedom for all beings.", "themes": ["Compassion", "Sangha", "Social engagement", "Suffering"], "texts": ["Shōbōgenzō"], "minutes": 53}, {"id": "2018-05-31 - Seishu John Wiley - Compassion Stories", "title": "Compassion Stories", "speaker": "Seishu John Wiley", "date": "2018-05-31", "series": "", "summary": "The talk's main teaching is about cultivating compassion in difficult situations by acknowledging and accepting our own emotions, rather than trying to suppress or numb them. By doing so, we can develop a deeper understanding of ourselves and others, allowing us to connect with their suffering and respond with kindness and love. This approach is reflected in the Bodhisattva vow, which encourages us to act with compassion regardless of our circumstances, even when it feels impossible.", "themes": ["Compassion", "Vulnerability"], "texts": [], "minutes": 24}, {"id": "2018-05-24 - Marc Anderson - Because Something Has to be Said", "title": "Because Something Has to be Said", "speaker": "Marc Anderson", "date": "2018-05-24", "series": "", "summary": "The speaker encourages the audience to cultivate gratitude and compassion by recognizing the interconnectedness of all life, drawing parallels between the natural world and human relationships. They share stories that illustrate the value of kindness and generosity, suggesting that it is only through embracing both sorrow and kindness that we can truly understand ourselves and the world around us. By doing so, we can transcend our attachments to things that bring us pain and find a deeper sense of connection and love.", "themes": ["Compassion", "Gratitude", "Interconnection"], "texts": [], "minutes": 56}, {"id": "2018-05-20 - Nomon Tim Burnett - Everything Is Hidden", "title": "Everything Is Hidden", "speaker": "Nomon Tim Burnett", "date": "2018-05-20", "series": "", "summary": "The speaker's main teaching is that reality is already present and accessible, and can be experienced directly through a sense of openness and curiosity. This \"suchness\" or \"thusness\" involves letting go of our conceptual understanding and dualistic thinking, and instead embracing the interconnectedness and impermanence of all things. By cultivating this awareness, we can find healing and guidance in the present moment, and approach spiritual growth with patience, humility, and inner practice.", "themes": ["Emptiness", "Impermanence", "Interconnection"], "texts": [], "minutes": 35}, {"id": "2018-05-17 - Shuko Edie Norton - Buddhist Practice on Western Ground", "title": "Buddhist Practice on Western Ground", "speaker": "Shuko Edie Norton", "date": "2018-05-17", "series": "", "summary": "The talk highlights the importance of considering cultural differences when approaching Buddhist teachings, particularly in how individualism versus collectivism shape our understanding of concepts like self and ego. This is crucial for Westerners who may be accustomed to a more individualistic approach to personal growth, as opposed to the interdependent nature of Eastern cultures. By acknowledging these cultural nuances, practitioners can gain a deeper understanding of Buddhist teachings on emptiness, attachment, and the practice of selflessness, ultimately allowing them to apply these principles in a more meaningful way.", "themes": ["Emptiness", "No-self", "Suffering"], "texts": [], "minutes": 35}, {"id": "2018-05-10 - Reizan Bob Penny - Blossoming of Spiritual Path", "title": "Blossoming of Spiritual Path", "speaker": "Reizan Bob Penny", "date": "2018-05-10", "series": "", "summary": "The talk's main teaching is that true growth and development in spiritual communities often arise organically from within, without deliberate planning or imposition of one's own viewpoint. This is illustrated by the example of the Miao Feng Shan pilgrimage site, which grew naturally over time through the contributions of various groups and associations. The speaker suggests that their approach to leading the Wilderness Dharma program this year is centered on participating with nature rather than trying to control it, reflecting a similar organic and natural process in their own community's development.", "themes": ["Sangha"], "texts": [], "minutes": 26}, {"id": "2018-04-19 - Nomon Tim Burnett - The Making of Me Caring for self without elevating self", "title": "The Making of Me - Caring for self without elevating self", "speaker": "Nomon Tim Burnett", "date": "2018-04-19", "series": "", "summary": "The speaker's main teaching is that true freedom from suffering comes not from trying to eliminate our negative tendencies, but by acknowledging and embracing them as a natural part of the human experience. By cultivating mindfulness, self-awareness, and compassion, we can learn to see through our own self-cherishing and aversions, and instead cultivate a sense of wisdom and care for ourselves and others. This allows us to approach life with greater honesty, patience, and understanding, leading to a more fulfilling and compassionate existence.", "themes": ["Compassion", "No-self", "Suffering", "Wisdom"], "texts": [], "minutes": 39}, {"id": "2018-04-12 - Ryushin Andrea Thach - The Heart of Zen", "title": "The Heart of Zen", "speaker": "Ryushin Andrea Thach", "date": "2018-04-12", "series": "", "summary": "The speaker's talk encourages embracing a mindset of equal reception and acceptance of all experiences, rather than judgment or attachment. This involves letting go of our emotional attachments and seeing ourselves as part of a larger whole, supported by the universe itself. By doing so, we can cultivate a state of equanimity and kindness in the face of challenges, responding with compassion rather than reacting out of aversion or grasping.", "themes": ["Acceptance", "Interconnection", "No-self", "Suffering"], "texts": [], "minutes": 31}, {"id": "2018-03-29 - Kanho Chris Burkhart - Compsassion Bodhisattvas", "title": "Compsassion Bodhisattvas", "speaker": "Kanho Chris Burkhart", "date": "2018-03-29", "series": "", "summary": "The talk's main teaching is that compassion is not just a virtue, but a fundamental necessity for human survival and peace. It is not limited to Buddhist or religious contexts, but can be found in various forms and expressions throughout history and culture. The Bodhisattva Avalokiteshvara, often depicted with multiple arms and faces, embodies the qualities of fierce compassion, humility, and wisdom. Through stories and examples from different traditions, the talk highlights the importance of cultivating compassion in our daily lives, including through practices like GRACE (Gathering Attention, Recalling Intention, Attuning to Self and Other, Considering what will serve, and Engaging ethically) and nonviolent communication, which can transform our relationships and society. Ultimately, the talk encourages listeners to embody compassion as a radical act of love that can set both ourselves and others free from suffering and violence.", "themes": ["Compassion", "Social engagement"], "texts": [], "minutes": 16}, {"id": "2018-03-22 - Nomon Tim Burnett - Compassion for Self", "title": "Compassion for Self", "speaker": "Nomon Tim Burnett", "date": "2018-03-22", "series": "", "summary": "The talk emphasizes the importance of receiving compassion and self-compassion as a foundation for personal growth and well-being. It suggests that by practicing kindness towards ourselves, we can develop greater resilience, improve our relationships, and cultivate a more positive relationship with ourselves. This approach encourages us to look inward and explore our own patterns of self-criticism and defensiveness, rather than just focusing on helping others, in order to find freedom from suffering and connect with others on a deeper level.", "themes": ["Compassion", "Vulnerability"], "texts": [], "minutes": 33}, {"id": "2018-03-15 - Nomon Tim Burnett - Compassion Kickoff", "title": "Compassion Kickoff", "speaker": "Nomon Tim Burnett", "date": "2018-03-15", "series": "", "summary": "The main teaching of the Soto Zen dharma talk emphasizes the importance of cultivating compassion as a natural response to anger and suffering. The teacher invites the audience to reflect on their understanding of compassion, acknowledging its complexity and multifaceted nature, which includes awareness, sympathetic concern, intention to help, and responsiveness to relieve suffering. By exploring these components and overcoming common obstacles such as pity, the speaker encourages listeners to integrate compassion into their daily lives, both in their personal relationships and in broader social contexts.", "themes": ["Compassion"], "texts": [], "minutes": 37}, {"id": "2018-03-03 - Nomon Tim Burnett - Quietism and Activism Difficult and Easy", "title": "Quietism and Activism - Difficult and Easy", "speaker": "Nomon Tim Burnett", "date": "2018-03-03", "series": "", "summary": "The talk highlights the importance of embracing paradox and ambiguity, rather than trying to categorize experiences as \"easy\" or \"difficult.\" This is reflected in the story of Leman Pong, who sat with his family studying sutras but ultimately realized that neither perspective was fully accurate - we simply need to show up and be present. By letting go of our need for labels and judgments, we can cultivate a sense of openness, kindness, and curiosity that supports both quietism and activism, and inspires us to live more mindfully and authentically.", "themes": ["Social engagement", "Suffering", "Wisdom"], "texts": [], "minutes": 51}, {"id": "2018-03-03 - Zoketsu Norman Fischer - Moral Suffering", "title": "Moral Suffering", "speaker": "Zoketsu Norman Fischer", "date": "2018-03-03", "series": "", "summary": "The speaker's main teaching emphasizes the importance of embracing reality as it is, rather than trying to change or solve problems. By accepting our circumstances without judgment, we can find liberation and cultivate a deeper appreciation for life's complexities. This involves letting go of moral outrage, injury, apathy, and other forms of suffering that arise from trying to uphold rigid values or principles, and instead embracing integrity, which means living with courage, optimism, and hopefulness, even in difficult situations.", "themes": ["Acceptance", "Social engagement", "Suffering"], "texts": [], "minutes": 55}, {"id": "2018-03-02 - Nyogen Connie Martin - Shusos Insights on Anger", "title": "Shuso's Insights on Anger", "speaker": "Nyogen Connie Martin", "date": "2018-03-02", "series": "", "summary": "The speaker shares their personal journey of learning to transform anger into a catalyst for growth and healing, rather than being controlled by it. Through practice and meditation, they've come to understand that anger is not something to be eliminated, but rather transformed into love and compassion when directed towards injustices and suffering. By cultivating a sense of understanding, forgiveness, and responsibility, we can develop a more mindful and compassionate relationship with our emotions, leading to greater peace and connection in the present moment.", "themes": ["Compassion", "Impermanence", "Interconnection"], "texts": [], "minutes": 40}, {"id": "2018-03-02 - Zoketsu Norman Fischer - Layman Pang and the Obvious Case", "title": "Layman Pang and the Obvious Case", "speaker": "Zoketsu Norman Fischer", "date": "2018-03-02", "series": "", "summary": "The speaker suggests that true understanding and happiness come from approaching challenges with a sense of wonder and appreciation for the present moment, rather than trying to analyze or intellectualize them. They draw on the concept of \"Genjokoan,\" which means an obvious case or self-evident phenomenon, to encourage listeners to trust their own experience and intuition. By embracing life fully in every moment, we can find freedom from suffering and cultivate a sense of community and shared understanding with others.", "themes": ["Buddha-nature", "Suffering", "Wisdom"], "texts": ["Shōbōgenzō"], "minutes": 45}, {"id": "2018-02-03 - Nyogen Connie Martin - Way Seeking Mind", "title": "Way Seeking Mind", "speaker": "Nyogen Connie Martin", "date": "2018-02-03", "series": "", "summary": "The speaker shares their personal journey of discovering meaning and healing through Soto Zen Buddhism, which began with a turning point when they adopted a child with special needs. Through this challenging experience, they found solace and peace through Buddhist practice, learning to accept and cope with their emotions. As they continue on their path, the speaker emphasizes the transformative power of ritual, such as zazen, in creating sacred space for self-reflection and healing, ultimately revealing the divine significance in all aspects of life.", "themes": ["Acceptance", "Suffering", "Vulnerability"], "texts": [], "minutes": 31}, {"id": "2018-01-11 - Shuko Edie Norton - Working With Defilements and Hinderances", "title": "Working With Defilements and Hinderances", "speaker": "Shuko Edie Norton", "date": "2018-01-11", "series": "", "summary": "The speaker shares a personal journey of applying Buddhist teachings to navigate the challenges of politics and activism, finding balance and clarity through a three-step process: observing one's mind, acknowledging emotions, and rationalizing actions. By cultivating mindfulness and awareness, they've learned to recognize their own limitations, work with negative emotions, and focus on personal growth rather than trying to change others. This practice has allowed them to stay focused, avoid burnout, and make more informed decisions, ultimately leading to a greater sense of calmness and clarity in their efforts to create positive change.", "themes": ["Interconnection", "Social engagement", "Wisdom"], "texts": [], "minutes": 37}, {"id": "2017-12-28 - Ryushin Andrea Thach - The Appearance of Light Encouragement for the New Year", "title": "The Appearance of Light - Encouragement for the New Year", "speaker": "Ryushin Andrea Thach", "date": "2017-12-28", "series": "", "summary": "The speaker's main teaching is about cultivating a calm and accepting mind by embracing all experiences in the present moment, without resistance or struggle. This allows us to find our authentic self and function in harmony with the world around us, leading to a sense of peace and connection that dissolves distinctions between ourselves and others. By letting go of control and judgment, we can tap into a deeper sense of understanding and kindness towards others, and receive new experiences that bring us closer to our true nature.", "themes": ["Acceptance", "Compassion", "Interconnection"], "texts": [], "minutes": 33}, {"id": "2017-12-21 - Nomon Tim Burnett - Gratitude and Desire", "title": "Gratitude and Desire", "speaker": "Nomon Tim Burnett", "date": "2017-12-21", "series": "", "summary": "The talk's main teaching is that true gratitude arises from embracing life as it is, rather than focusing on specific objects or reasons for gratitude. By cultivating this deeper understanding, we can develop a sense of appreciation and connection to the world around us, even in challenging times. This approach involves letting go of desires that can lead to suffering and instead finding peace and acceptance through mindfulness and awareness of the present moment.", "themes": ["Acceptance", "Gratitude", "Suffering"], "texts": [], "minutes": 32}, {"id": "2017-12-09 - Eko Jeff Kelley - Hongzhi Part 4 Wonder", "title": "Hongzhi, Part 4: Wonder", "speaker": "Eko Jeff Kelley", "date": "2017-12-09", "series": "Hongzhi", "summary": "The speaker invites listeners to revisit Hongzhu's teaching on \"wonder\" as a key aspect of his practice of silent illumination, encouraging them to cultivate an open and receptive mindset that allows them to see beyond their own agendas and preoccupations. By letting go of our self-concept and allowing ourselves to be curious, we can tap into a field of wonder that includes everything, revealing the interconnectedness and complexity of life. This state of wonder is not just about appreciating beauty, but also about embracing the challenges and complexities of existence, leading to a more authentic and expansive way of living.", "themes": ["Emptiness", "No-self"], "texts": [], "minutes": 28}, {"id": "2017-12-09 - Nomon Tim Burnett - Hongzhi Part 3 Guidepost For The Hall Of Pure Bliss", "title": "Hongzhi, Part 3: Guidepost For The Hall Of Pure Bliss", "speaker": "Nomon Tim Burnett", "date": "2017-12-09", "series": "Hongzhi", "summary": "The speaker reflects on the importance of balance between serenity and illumination, encouraging listeners to cultivate inner clarity and wonder through practices like meditation and non-verbal communication. They emphasize that responding without falling into achievement is key to achieving serenity, but also acknowledge the need for balance with insight. By embracing both opposites - what's good and what's bad - we can develop a more nuanced and compassionate understanding of the world.", "themes": ["Compassion", "No-self", "Social engagement"], "texts": ["Shōbōgenzō"], "minutes": 59}, {"id": "2017-12-08 - Eko Jeff Kelley - Hongzhi Part 2 Guidepost For The House Of Silent Illumination", "title": "Hongzhi, Part 2: Guidepost For The House Of Silent Illumination", "speaker": "Eko Jeff Kelley", "date": "2017-12-08", "series": "Hongzhi", "summary": "The speaker's talk emphasizes the importance of letting go of ego and distractions to access a deeper state of awareness, where the distinctions between self and other, silence and wisdom, dissolve. This \"undivided mind\" is seen as a vast and supportive field that holds everything together, allowing us to respond with kindness and clarity in everyday life. By embracing this concept, we can cultivate a more elegant and gracious way of living, even in challenging situations, by recognizing that beings do not obstruct each other.", "themes": ["Emptiness", "Interconnection", "Wisdom"], "texts": [], "minutes": 35}, {"id": "2017-12-07 - Nomon Tim Burnett - Hongzhi Part 1 Introduction", "title": "Hongzhi, Part 1: Introduction", "speaker": "Nomon Tim Burnett", "date": "2017-12-07", "series": "Hongzhi", "summary": "The talk's main teaching emphasizes the importance of embracing simplicity and letting go of self-improvement efforts, instead encouraging practitioners to simply \"be\" and embody the practice without trying to figure out how to do it. This approach is rooted in the idea that true understanding and insight arise from a trusting and faith-based approach, rather than individual effort or analysis. By cultivating a sense of non-doing and being like water, practitioners can let go of attachments and ego, finding harmony with others and embracing uncertainty and imperfection.", "themes": ["Acceptance", "Emptiness"], "texts": [], "minutes": 47}, {"id": "2017-11-30 - Koshin Chris Cain - Hakuins Song of Zazen", "title": "Hakuin's Song of Zazen", "speaker": "Koshin Chris Cain", "date": "2017-11-30", "series": "", "summary": "Hakuin Ekaku, a renowned Soto Zen master, emphasized the importance of integrating spiritual realization into daily life, rather than simply resting on past experiences. He believed that everyone has a Buddha nature present in them, and that true freedom comes from embracing both life and death, rather than just individual choices. Through his teachings, Hakuin encouraged listeners to approach their lives with an open heart and mind, using meditation as a tool to cultivate awareness and find balance amidst challenges.", "themes": ["Buddha-nature", "No-self"], "texts": ["Lotus Sutra"], "minutes": 45}, {"id": "2017-11-09 - Nomon Tim Burnett - Inclusive Thinking", "title": "Inclusive Thinking", "speaker": "Nomon Tim Burnett", "date": "2017-11-09", "series": "", "summary": "The talk's main teaching is that embracing complexity and holding opposites can lead to a more inclusive and flexible mind. By accepting both sides of an issue, rather than trying to simplify or categorize it, we can cultivate a mindset that can navigate challenges with kindness and hope. This approach encourages us to look beyond black-and-white thinking and instead find a middle ground where both good and bad coexist, allowing us to respond to reality as it is, without judgment or simplification.", "themes": ["Acceptance", "Compassion", "Wisdom"], "texts": [], "minutes": 40}, {"id": "2017-11-04 - Nomon Tim Burnett - Trying On Zen", "title": "Trying On Zen", "speaker": "Nomon Tim Burnett", "date": "2017-11-04", "series": "", "summary": "The speaker's talk emphasizes the importance of embracing simplicity and letting go of expectations in Zen practice. They share their personal journey from struggling with the responsibilities of being part of a Zen community to finding comfort and belonging through connection with Norman Fischer, who taught them that true depth and seriousness come from embracing simplicity and inclusivity. By doing so, they encourage listeners to approach Zen practice with an open heart and mind, rather than trying to grasp or understand it intellectually.", "themes": ["Gratitude", "Sangha"], "texts": ["Shōbōgenzō"], "minutes": 38}, {"id": "2017-11-02 - Nomon Tim Burnett - Caring for Hungry Ghosts", "title": "Caring for Hungry Ghosts", "speaker": "Nomon Tim Burnett", "date": "2017-11-02", "series": "", "summary": "The talk's main teaching is that all beings are interconnected and suffering, including those who have passed away or are struggling with internal difficulties. The ceremony aims to acknowledge this suffering by offering peace, forgiveness, and teachings to \"hungry ghosts\" - beings consumed by desire and desperation - particularly through the power of sound. By participating in the ceremony, individuals can cultivate a sense of compassion and connection with all beings, including those who have passed away, and experience spiritual renewal and healing.", "themes": ["Acceptance", "Compassion", "Suffering"], "texts": [], "minutes": 16}, {"id": "2017-10-26 - Heigaku Talus Latona - Ash", "title": "Ash", "speaker": "Heigaku Talus Latona", "date": "2017-10-26", "series": "", "summary": "The speaker shares a personal experience of attending the wrong memorial service, highlighting how our own evaluation can lead us astray, but ultimately leading to a deeper understanding of the importance of embracing paradox and contradictions in spiritual practice. They draw on this experience to discuss the need to balance spaciousness with suspicion of conventional understanding, encouraging us to let go of attachments and expectations while remaining aware and confident. This approach is rooted in the Buddhist concept of \"abiding,\" which involves embracing our current condition without attachment or expectation of change, allowing us to find freedom and clarity in the midst of life's challenges.", "themes": ["Emptiness", "Impermanence", "No-self"], "texts": [], "minutes": 24}, {"id": "2017-10-19 - Kanho Chris Burkhart - Genjokoan", "title": "Genjokoan", "speaker": "Kanho Chris Burkhart", "date": "2017-10-19", "series": "", "summary": "In this Soto Zen dharma talk, the speaker invites listeners to re-examine their relationship with the teachings of Dogen Zenji, shifting from viewing him as a philosopher to seeing his words as directly applicable to one's own practice. The speaker shares a passage that highlights how our current understanding is always incomplete and limited, and encourages the audience to explore what they're truly seeking in their practice through small group discussion. By letting go of attachments and embracing the present moment without judgment, we can begin to recognize the limits of our understanding and perpetually explore the nature of reality.", "themes": ["Wisdom"], "texts": ["Shōbōgenzō"], "minutes": 31}, {"id": "2017-09-21 - Nomon Tim Burnett - Sesshin", "title": "Sesshin", "speaker": "Nomon Tim Burnett", "date": "2017-09-21", "series": "", "summary": "The talk's main teaching emphasizes the importance of cultivating mindfulness and presence in everyday life to counteract feelings of frustration, anxiety, or attachment to specific outcomes. By stopping and being present with whatever arises, we can develop greater freedom, compassion, and understanding of ourselves and the world around us. This approach, often referred to as \"non-way\" or \"non-method,\" allows for a kind of liberation from our tendency to control and optimize life, revealing its complexity and unpredictability in all its beauty and wonder.", "themes": ["Acceptance", "Interconnection", "Sangha"], "texts": [], "minutes": 39}, {"id": "2017-09-14 - Nomon Tim Burnett - Towards a Participatory Buddhism part 1", "title": "Towards a Participatory Buddhism, Part 1", "speaker": "Nomon Tim Burnett", "date": "2017-09-14", "series": "", "summary": "The talk focuses on how American Buddhism has developed unique trends that set it apart from traditional forms in Asia, including an emphasis on individualism, egalitarianism, and activism, which can lead to a focus on personal results rather than spiritual practice. The speaker contrasts these trends with the more hierarchical and traditional approach of Dogen's Japan, where students were immersed in the sacred and saw their actions as expressions of Buddha. This talk aims to explore how Dogen's teachings can bridge traditional Asian understanding with American values, offering a new way to approach spiritual growth through \"participatory Buddhism\".", "themes": ["Sangha", "Social engagement"], "texts": [], "minutes": 34}, {"id": "2017-08-31 - Ryushin Andrea Thach - Jizos Vow", "title": "Jizo's Vow", "speaker": "Ryushin Andrea Thach", "date": "2017-08-31", "series": "", "summary": "The talk's main teaching is about finding balance and steadiness in life by invoking the support and protection of Jiso Bodhisattva, a Japanese figure associated with grief and protection, particularly for women and children. By embracing Jiso's fearlessness and flexibility, individuals can cultivate faith and trust that allows them to navigate uncertainty and chaos, even in the face of insurmountable problems. This teaching encourages listeners to find creative ways to honor and process their own experiences of pain and struggle, such as visiting a Jiso garden or making offerings, in order to find balance and steadiness in their lives.", "themes": ["Compassion", "Suffering", "Vulnerability"], "texts": [], "minutes": 35}, {"id": "2017-08-17 - Nomon Tim Burnett - Three Poisons and Seventy Farmworkers", "title": "Three Poisons and Seventy Farmworkers", "speaker": "Nomon Tim Burnett", "date": "2017-08-17", "series": "", "summary": "The talk's main teaching emphasizes the importance of facing reality, acknowledging our conditioning, and taking responsibility for our actions as a means to cultivate compassion and wisdom. This is not about escaping or avoiding difficulties, but rather about finding space and openness even in challenging situations, such as social injustices like the exploitation of farm workers. By recognizing and letting go of greed, hatred, and delusion, we can act with kindness and wisdom towards ourselves and others, ultimately contributing to a more compassionate and sustainable world.", "themes": ["Social engagement", "Suffering", "Wisdom"], "texts": [], "minutes": 33}, {"id": "2017-08-10 - Nomon Tim Burnett - Franma and the Mustard Seed", "title": "Franma and the Mustard Seed", "speaker": "Nomon Tim Burnett", "date": "2017-08-10", "series": "", "summary": "The talk's main teaching is about finding comfort and solace in Buddhism despite facing rejection and hardship throughout one's life. The speaker shares personal stories of their family's history, including their grandmother Fran's journey from being scorned by her husband's family to finding peace through Buddhism, as well as a story about Kisa Gotani, an Indian woman who found refuge in Buddhism after being shunned by her community. Through these stories, the speaker highlights the importance of compassion and community in healing and coping with loss, emphasizing that even in difficult times, there is always the possibility for transformation and connection.", "themes": ["Acceptance", "Impermanence", "Suffering"], "texts": [], "minutes": 36}, {"id": "2017-07-27 - Heigaku Talus Latona and Ryushin Kate Korn McKenna - Uji Time Being", "title": "Uji - Time Being", "speaker": "Heigaku Talus Latona and Ryushin Kate Korn McKenna", "date": "2017-07-27", "series": "", "summary": "The speaker's main teaching is that time is not separate from the present moment, but rather an integral part of it. This means that every moment is connected to and encompasses all of existence, past, present, and future, and that there is no distinction between these concepts. By letting go of our worries and judgments about time, we can appreciate the present moment as it truly is, unencumbered by our perceptions of past or future.", "themes": ["Interconnection"], "texts": ["Shōbōgenzō"], "minutes": 36}, {"id": "2017-07-20 - Kanho Chris Burkhart and Seishu John Wiley - Bodhisattvas Four Methods of Guidance", "title": "Bodhisattva's Four Methods of Guidance", "speaker": "Kanho Chris Burkhart and Seishu John Wiley", "date": "2017-07-20", "series": "", "summary": "The talk emphasizes the importance of cultivating a mindset of generosity, kindness, and compassion in our daily lives. This involves letting go of attachment to personal gain and instead embracing everyday activities as acts of giving, whether it's work or simply being present for others. By doing so, we can transform our minds and the world around us, leading to a state of non-duality where our actions are spontaneous and guided by wisdom, rather than ego or premeditation.", "themes": ["Compassion", "Interconnection"], "texts": ["Lotus Sutra", "Shōbōgenzō"], "minutes": 37}, {"id": "2017-07-13 - Reizan Bob Penny - Mountains and Waters Sutra", "title": "Mountains and Waters Sutra", "speaker": "Reizan Bob Penny", "date": "2017-07-13", "series": "", "summary": "The speaker emphasizes the importance of directly experiencing reality beyond conditioned views and logical thought, encouraging listeners to look beyond their preconceptions and instead embody the paradoxical teachings of the Mountain and Water Sutra, such as \"green mountains are always walking\" and \"eastern mountains travel on water.\" By embracing these seemingly illogical statements, one can gain a deeper understanding of the Buddha's path and cultivate a sense of freedom from attachment and conditioning. This direct experience allows for a profound connection with nature and the realization of the true dharma wheel of the Tathagata.", "themes": ["Interconnection"], "texts": ["Shōbōgenzō"], "minutes": 70}, {"id": "2017-07-06 - Ryushin Andrea Thach - Shishobo A Bodhisattvas Embracing Method of Guidance", "title": "Shishobo - A Bodhisattva's Embracing Method of Guidance", "speaker": "Ryushin Andrea Thach", "date": "2017-07-06", "series": "", "summary": "The speaker shares insights from Dogen's teachings, specifically the concept of generosity (dana), which is one of the four methods of guidance in Buddhism. Generosity is not just about giving material objects, but also about cultivating a mindset of openness and acceptance, allowing oneself to receive and appreciate what is given without expectation or attachment. By practicing generosity, individuals can release themselves from the three poisons of greed, hate, and delusion, and cultivate a deeper sense of compassion and wisdom.", "themes": ["Compassion", "Ethics"], "texts": ["Heart Sutra", "Shōbōgenzō"], "minutes": 52}, {"id": "2017-06-29 - Nomon Tim Burnett - Shikantaza", "title": "Shikantaza", "speaker": "Nomon Tim Burnett", "date": "2017-06-29", "series": "", "summary": "The talk emphasizes the importance of balancing insight (understanding) with serenity (openness), as neglecting one can lead to imbalance. When these two aspects come together, a state of silent illumination is fulfilled, allowing for awakening and union with reality. This balance can be cultivated through the practice of zazen, which combines physical postures with mindfulness and awareness, ultimately leading to a more open and compassionate way of being.", "themes": ["Buddha-nature", "Gratitude"], "texts": [], "minutes": 33}, {"id": "2017-06-23 - Zoketsu Norman Fischer - Paramitas", "title": "Paramitas", "speaker": "Zoketsu Norman Fischer", "date": "2017-06-23", "series": "Paramitas", "summary": "The speaker's main teaching emphasizes that bodhisattvas cultivate a state of mind characterized by generosity, compassion, and wisdom, which is not tied to specific roles or outcomes. This involves practicing \"upaya\" or skillful means, embracing various circumstances as opportunities to benefit others, and letting go of attachment to personal identities and desires. By doing so, individuals can develop a carefree and generous attitude towards life, approach challenges with patience and compassion, and ultimately bring light and inspiration to the world.", "themes": ["Compassion", "Emptiness", "Ethics", "Wisdom"], "texts": [], "minutes": 59}, {"id": "2017-06-22 - Zoketsu Norman Fischer - Desire", "title": "Desire", "speaker": "Zoketsu Norman Fischer", "date": "2017-06-22", "series": "", "summary": "The speaker suggests that true fulfillment and joy come from embracing our deepest desires and longings, rather than trying to suppress or satisfy them. This can involve confronting the pain and suffering that often accompanies these feelings, but ultimately leads to spiritual growth and awakening. By letting go of expectations and complacency, we can tap into a sense of inner peace and awareness that is not dependent on external objects or experiences, but rather on the present moment itself.", "themes": ["Suffering"], "texts": [], "minutes": 46}, {"id": "2017-06-21 - Zoketsu Norman Fischer - Vasubandhus Yogacara Text", "title": "Vasubandhu's Yogacara Text", "speaker": "Zoketsu Norman Fischer", "date": "2017-06-21", "series": "", "summary": "The talk's main teaching emphasizes the importance of understanding consciousness as the foundation for awakening and living a peaceful life. By grasping the nature of consciousness, we can learn to process emotions wisely, cultivate harmony with the world, and recognize our interconnectedness with all things. This awareness allows us to approach life with clarity, skillfulness, and compassion, ultimately leading to a more awakened and expansive experience of reality.", "themes": ["Compassion", "Emptiness", "Interconnection"], "texts": ["Heart Sutra"], "minutes": 43}, {"id": "2017-06-20 - Zoketsu Norman Fischer - What Do You Preserve", "title": "What Do You Preserve?", "speaker": "Zoketsu Norman Fischer", "date": "2017-06-20", "series": "", "summary": "The talk highlights how our language and thinking can be limited by our tendency to rely on comparisons and opposites, which were necessary for early human development but have since become outdated. This \"Tower of Babel effect\" leads us to overemphasize critique and clarity, causing us to forget the ancient sense of wholeness and unity that underlies our language and thinking. By embracing both clarity and confusion as intertwined aspects of reality, we can move beyond the need for definitive answers and instead cultivate a deeper understanding of the present moment.", "themes": ["Emptiness", "Wisdom"], "texts": [], "minutes": 40}, {"id": "2017-06-19 - Zoketsu Norman Fischer - Waiting for What", "title": "Waiting for What?", "speaker": "Zoketsu Norman Fischer", "date": "2017-06-19", "series": "", "summary": "The speaker shares a personal experience of finding inspiration in sparrows, which embody qualities like persistence and resilience, and sees this as an opportunity to explore the concept of bodhisattvas in Soto Zen. They suggest that embracing our own emptiness and lack can lead to true freedom and fulfillment, rather than trying to find meaning in life despite feeling despair or fear of death. By recognizing that our lives are not our own but expressions of something greater, we can cultivate mindfulness, compassion, and wisdom to bring blessings to others and wake them up to their true nature.", "themes": ["Buddha-nature", "Emptiness", "Wisdom"], "texts": [], "minutes": 54}, {"id": "2017-06-18 - Zoketsu Norman Fischer - Prajna Paramita in Eight Thousand Lines", "title": "Prajna Paramita in Eight Thousand Lines", "speaker": "Zoketsu Norman Fischer", "date": "2017-06-18", "series": "Paramitas", "summary": "The speaker invites listeners to cultivate awareness and compassion by letting go of attachments and ego, embracing the present moment without preconceptions or expectations. By doing so, we can live in the world with full enjoyment and appreciation, free from entanglements and misunderstandings about reality. This approach is likened to the practice of a bodhisattva, who goes forth into the world with love and awareness, cultivating compassion and kindness in each moment.", "themes": ["Compassion", "Emptiness", "No-self"], "texts": [], "minutes": 46}, {"id": "2017-05-25 - Shuko Edie Norton - Befriend Everyone", "title": "Befriend Everyone", "speaker": "Shuko Edie Norton", "date": "2017-05-25", "series": "", "summary": "The talk emphasizes the importance of cultivating compassion and respect in our interactions with others, particularly when we disagree or have differing perspectives. By recognizing our interconnectedness and accepting others as they are in the present moment, we can begin to bridge the divides that often lead to polarization and conflict. This requires a shift from judgmental and reactive communication to a more mindful and non-judgmental approach, allowing us to connect with others on a deeper level and create positive change.", "themes": ["Compassion", "Interconnection", "Social engagement", "Suffering"], "texts": [], "minutes": 25}, {"id": "2017-05-20 - Nomon Tim Burnett - Tenzo Kyokun Dogens Instructions to the Cook", "title": "Tenzo Kyokun - Dogen's Instructions to the Cook", "speaker": "Nomon Tim Burnett", "date": "2017-05-20", "series": "", "summary": "In this Soto Zen dharma talk, the teacher encourages participants to let go of needing all the answers and instead embark on a journey of exploration and discussion, just as their founding teacher Norman did. They will be exploring Dogen's work \"Moon in a Dewdrop,\" which offers a unique approach to translating ancient texts into modern English. By embracing this process, we can cultivate mindfulness and awareness in our daily lives, including even the most mundane tasks like cooking, by paying attention to detail and intention.", "themes": ["Acceptance"], "texts": [], "minutes": 47}, {"id": "2017-05-18 - Nomon Tim Burnett - Bendowa 4 Zen Practice as Expressing Enlightenment", "title": "Bendōwa 4 - Zen Practice as Expressing Enlightenment", "speaker": "Nomon Tim Burnett", "date": "2017-05-18", "series": "", "summary": "The main teaching of the Soto Zen dharma talk is that enlightenment is not something separate from practice, but rather it's the natural state of being that can be accessed through zazen (meditation). Rather than striving to achieve enlightenment, we should simply sit in the present moment and allow ourselves to be, as Uchiyama Roshi emphasizes. This understanding offers a profound yet unassuming perspective on enlightenment, one that values harmony, quietness, and effortless realization over forced effort or struggle.", "themes": ["Buddha-nature"], "texts": ["Shōbōgenzō"], "minutes": 13}, {"id": "2017-05-11 - Ryushin Andrea Thach - Its All Over", "title": "It's All Over", "speaker": "Ryushin Andrea Thach", "date": "2017-05-11", "series": "", "summary": "The speaker's main teaching emphasizes that death and dying are not something to be feared, but rather a natural part of life, and that living in the present moment is what truly matters. From a Soto Zen perspective, life only exists because of death, and true appreciation for life comes from embracing its impermanence. This understanding allows us to see that everything is interconnected and that separation is an illusion, enabling us to experience a deeper sense of oneness and acceptance in the present moment.", "themes": ["Impermanence", "Interconnection", "Suffering"], "texts": [], "minutes": 29}, {"id": "2017-05-04 - Nomon Tim Burnett - Bendowa 3 Transmission of the Dharma", "title": "Bendōwa 3 - Transmission of the Dharma", "speaker": "Nomon Tim Burnett", "date": "2017-05-04", "series": "", "summary": "In a Soto Zen dharma talk, the speaker reflects on the importance of lineage in understanding Buddhism's true teachings, acknowledging that while patriarchal language may be present, it is still valuable and worthy of appreciation. They emphasize that true understanding comes from direct experience and practice, rather than just intellectual knowledge or reading about it. The speaker encourages listeners to let go of conceptual thinking and instead directly experience reality, allowing awakening to happen naturally through curiosity and attention.", "themes": ["Emptiness"], "texts": ["Shōbōgenzō"], "minutes": 33}, {"id": "2017-04-27 - Nomon Tim Burnett - Bendowa 2 For Authentic Seekers", "title": "Bendōwa 2 - For Authentic Seekers", "speaker": "Nomon Tim Burnett", "date": "2017-04-27", "series": "", "summary": "The main teaching of this Soto Zen dharma talk is that true freedom and peace can be found by letting go of our ego's need for external validation and instead embracing our natural state of being. Dogen's experiences as a monk, including his time in China and his focus on transmitting the true teachings of Zen, emphasize the importance of establishing practice without expectation or attachment to enlightenment. By doing so, we can cultivate acceptance of who we are and find peace beyond conscious experience, allowing us to live more freely and authentically.", "themes": ["Acceptance", "Buddha-nature", "No-self"], "texts": ["Shōbōgenzō"], "minutes": 34}, {"id": "2017-04-20 - Nomon Tim Burnett - Bendowa 1 Holding to Fixed Views", "title": "Bendōwa 1 - Holding to Fixed Views", "speaker": "Nomon Tim Burnett", "date": "2017-04-20", "series": "", "summary": "The speaker shares an experience with a cold that led them to re-evaluate their fixed views about what works for them, ultimately discovering the importance of letting go of rigid thinking in Buddhism. This realization is echoed in Dogen's teachings on practical truth, which emphasizes the need to evaluate and allow new ideas to \"inhabit\" one's being over time. By cultivating a flexible and open approach to life, we can tap into the Buddha life that lies beyond human agency, finding freedom and fulfillment through practice and letting go of preconceptions.", "themes": ["Buddha-nature"], "texts": ["Shōbōgenzō"], "minutes": 34}, {"id": "2017-03-23 - Ryushin Andrea Thach - Possibility", "title": "Possibility", "speaker": "Ryushin Andrea Thach", "date": "2017-03-23", "series": "", "summary": "The talk's main teaching emphasizes trusting one's inner power and inherent wholeness, rather than relying on external sources or specific outcomes. By letting go of conceptual thinking and embracing silence, we can tap into our true nature and live authentically, without attachment to particular hopes or expectations. This approach encourages us to cultivate openness and receptivity, allowing life to unfold naturally and manifesting hope in small yet meaningful ways, such as kindness towards ourselves and others.", "themes": ["Buddha-nature", "Social engagement"], "texts": [], "minutes": 35}, {"id": "2017-03-16 - Reizan Bob Penny - Awareness of Diversity", "title": "Awareness of Diversity", "speaker": "Reizan Bob Penny", "date": "2017-03-16", "series": "", "summary": "As we deepen our connection with nature, our perception of the world shifts, allowing us to see its subtleties and complexity with greater clarity. This process involves cultivating awareness and recognition, rather than just accumulating knowledge, and it's made possible through a practice that allows us to approach life with an open and receptive attitude - like \"still hunting\" in meditation, where we let go of preconceptions and allow ourselves to be present with our surroundings. Through direct experience and observation, we can gain true understanding of the world around us, just as we might recognize a rare bird species through clear perception. This kind of insight is essential for living a more compassionate life, one that values connection and recognition over preconceived notions or intellectual knowledge.", "themes": ["Wisdom"], "texts": [], "minutes": 31}, {"id": "2017-03-05 - Zoketsu Norman Fischer - Three Aspects of Consciousness", "title": "Three Aspects of Consciousness", "speaker": "Zoketsu Norman Fischer", "date": "2017-03-05", "series": "", "summary": "The talk's main teaching emphasizes the importance of cultivating awareness and presence in our daily lives through meditation practice. By letting go of preconceptions and simply paying attention to our surroundings, we can experience moments of contentment and joy even in chaotic situations. This practice allows us to deepen our emotional lives, become more open and appreciative of others, and ultimately transcend the limitations of our individual selves, revealing a deeper connection to ourselves and the world around us.", "themes": ["No-self", "Suffering"], "texts": [], "minutes": 56}, {"id": "2017-03-04 - Nomon Tim Burnett - Appreciating Tathata", "title": "Appreciating Tathata", "speaker": "Nomon Tim Burnett", "date": "2017-03-04", "series": "", "summary": "The speaker invites listeners to cultivate an appreciation for reality as it is, without judgment or attachment, by embracing the present moment with openness and softness. This approach allows us to experience life's beauty and majesty without striving for specific outcomes, and instead, trusts in the unfolding of life itself. By doing so, we can connect more deeply with ourselves and others, and find a sense of freedom and peace that arises from being fully present.", "themes": ["Acceptance", "Sangha"], "texts": [], "minutes": 44}, {"id": "2017-03-03 - Ryushin Kate Korn McKenna - Reflections on Intimacy in the Heart of Conflict", "title": "Reflections on Intimacy in the Heart of Conflict", "speaker": "Ryushin Kate Korn McKenna", "date": "2017-03-03", "series": "", "summary": "The speaker's talk emphasizes the importance of approaching life with vulnerability and openness, particularly when it comes to conflict and communication. They acknowledge that conflict is an inherent part of human experience, but also offer a transformative approach by embracing our fears, hopes, and desires, and taking risks to connect with others in a compassionate and honest way. By letting go of narrow perspectives and biases, we can cultivate a sense of unity and cooperation, recognizing our shared humanity and interconnectedness.", "themes": ["Compassion", "Social engagement", "Vulnerability"], "texts": [], "minutes": 31}, {"id": "2017-03-03 - Zoketsu Norman Fischer - Caring for the Heart of the Human Family", "title": "Caring for the Heart of the Human Family", "speaker": "Zoketsu Norman Fischer", "date": "2017-03-03", "series": "", "summary": "The speaker's main teaching emphasizes the importance of acknowledging and addressing our collective shortcomings as human beings, just like Nakagawa Soen Roshi did with his prostrations to prisoners. This requires cultivating compassion, love, and wisdom to overcome greed, hate, and confusion, ultimately creating a more harmonious and loving world. By embracing our imperfections and letting go of illusions, we can develop true happiness and understanding, transforming ourselves and the world around us through mindfulness and simplicity.", "themes": ["Compassion", "Wisdom"], "texts": [], "minutes": 52}, {"id": "2016-12-29 - Seishu John Wiley - Ritual and Home Practice", "title": "Ritual and Home Practice", "speaker": "Seishu John Wiley", "date": "2016-12-29", "series": "", "summary": "The speaker shares how reading Paula Arai's book \"Bringing Zen Home\" has inspired them to incorporate body rituals into their daily life, such as cleaning and flower arranging, which they believe help cultivate compassion and well-being. These practices are rooted in Buddhist teachings and have become an integral part of their meditation practice at home. By embracing these simple yet profound rituals, the speaker has found a deeper sense of connection with themselves, others, and even those who have passed away, bringing peace and unity to their relationships. This newfound awareness has also helped them cultivate gratitude and become more mindful of their actions' impact on others.", "themes": ["Gratitude"], "texts": [], "minutes": 24}, {"id": "2016-12-22 - Shuko Edie Norton - Buddhist Practice for Climate Change", "title": "Buddhist Practice for Climate Change", "speaker": "Shuko Edie Norton", "date": "2016-12-22", "series": "", "summary": "The talk's main teaching is that Buddhist principles can guide us in responding to climate change by cultivating individual actions of compassion and wisdom, while also acknowledging the importance of collective action and systemic change. The speaker encourages listeners to reflect on their own role in addressing climate change and to find ways to integrate their Buddhist practice with taking action in the world. By starting small and being mindful of our intentions, we can make a positive impact, even if it feels overwhelming or uncertain, and by supporting efforts like lawsuits against oil companies, we can work towards a common goal of protecting the environment.", "themes": ["Ethics", "Sangha", "Social engagement"], "texts": [], "minutes": 29}, {"id": "2016-12-15 - Heigaku Talus Latona - When Truth Moves", "title": "When Truth Moves", "speaker": "Heigaku Talus Latona", "date": "2016-12-15", "series": "", "summary": "The speaker's talk highlights the importance of letting go of our conditioned perceptions in order to access a deeper understanding of reality. Through the koan case 75, we are invited to consider what lies beyond our limited understanding, and to recognize when our thinking or perception is clouded by unhelpful patterns. By embracing this unknown, we can begin to see through our own mental habits and find freedom in the ordinary moments of life, where the truth of Buddha Dharma is always present.", "themes": ["Impermanence"], "texts": ["Shōbōgenzō"], "minutes": 18}, {"id": "2016-12-03 - Nomon Tim Burnett - Four Foundations of Mindfulness Part 1 Observation of Body 3", "title": "Four Foundations of Mindfulness, Part 1: Observation of Body (3)", "speaker": "Nomon Tim Burnett", "date": "2016-12-03", "series": "Four Foundations of Mindfulness", "summary": "The speaker emphasizes that true freedom and understanding come not from trying to change or transcend our physical bodies, but rather from embracing and accepting them as they are. By cultivating awareness and acceptance in the present moment, we can let go of resistance and judgment, allowing us to connect with our own imperfections and limitations. This embodied practice of Zazen allows us to tap into a deeper sense of compassion, faith, and wisdom that goes beyond intellectual understanding or dualistic thinking.", "themes": ["Buddha-nature", "Impermanence"], "texts": [], "minutes": 49}, {"id": "2016-12-02 - Eko Jeff Kelley - Avowal and Repentance", "title": "Avowal and Repentance", "speaker": "Eko Jeff Kelley", "date": "2016-12-02", "series": "", "summary": "The speaker's main teaching emphasizes the importance of acknowledging and taking responsibility for our individual actions as part of a larger web of interconnected suffering. They encourage us to let go of guilt or shame by confessing and repenting, rather than dwelling on past mistakes, in order to work towards healing and awakening both individually and collectively. By recognizing our interconnectedness and releasing attachments to outcomes, we can experience freedom and connection to the world around us, ultimately leading to liberation from karmic conditioning.", "themes": ["Ethics", "Interconnection", "Suffering"], "texts": [], "minutes": 39}, {"id": "2016-12-01 - Nomon Tim Burnett - David Loys Response", "title": "David Loy's Response", "speaker": "Nomon Tim Burnett", "date": "2016-12-01", "series": "", "summary": "The speaker suggests that Buddhist practice is not just about personal awakening, but also about responding to the challenges of the world in an authentic way. This requires finding a balance between cultivating one's own inner peace through meditation and engaging with social and ecological issues, while also embracing uncertainty and taking action without attachment to specific outcomes. By doing so, we can develop a sense of courage, humility, and openness that allows us to respond to the world's challenges in a meaningful way.", "themes": ["Compassion", "Interconnection", "Social engagement"], "texts": [], "minutes": 39}, {"id": "2016-11-24 - Nomon Tim Burnett - Four Foundations of Mindfulness Part 2 Observation of Actions", "title": "Four Foundations of Mindfulness, Part 2: Observation of Actions", "speaker": "Nomon Tim Burnett", "date": "2016-11-24", "series": "Four Foundations of Mindfulness", "summary": "The talk emphasizes the importance of cultivating mindfulness and presence in daily life, encouraging listeners to pay attention to their bodies and be fully engaged with the world around them. By doing so, we can develop a sense of connection and intimacy with others and with ourselves, and find ways to contribute positively to the world. This practice is not about achieving some grand state of enlightenment, but rather about being present and helpful in our daily activities, using techniques such as zazen and ritual language to stay grounded and aware.", "themes": ["Sangha", "Social engagement"], "texts": [], "minutes": 32}, {"id": "2016-11-17 - Nomon Tim Burnett - Loving My Country", "title": "Loving My Country", "speaker": "Nomon Tim Burnett", "date": "2016-11-17", "series": "", "summary": "The speaker's talk highlights the importance of cultivating mindfulness and presence in navigating complex issues, particularly in times of uncertainty and division. They encourage listeners to let go of expectations and desires, instead embracing what is as it arises, and to approach life with a sense of loving-kindness towards themselves and others. By sharing their personal experiences and connecting with others, the speaker aims to inspire a community of individuals who can support each other in finding freedom from suffering and contributing to a more compassionate and peaceful world.", "themes": ["Compassion", "Social engagement", "Suffering"], "texts": [], "minutes": 34}, {"id": "2016-11-03 - Nomon Tim Burnett - Four Foundations of Mindfulness Part 1 Observation of Body 2", "title": "Four Foundations of Mindfulness, Part 1: Observation of Body (2)", "speaker": "Nomon Tim Burnett", "date": "2016-11-03", "series": "Four Foundations of Mindfulness", "summary": "The main teaching of the Soto Zen dharma talk emphasizes the importance of cultivating mindfulness and presence in everyday life by focusing on the body and breath. By letting go of distractions and conceptual thinking, we can return to the present moment and connect with our true nature, leading to a sense of peace, joy, and unity with reality. This practice encourages us to be aware of our bodies and minds without relying on external techniques or practices, instead embracing simplicity and presence in all aspects of life.", "themes": ["Impermanence", "No-self"], "texts": [], "minutes": 31}, {"id": "2016-10-29 - Nomon Tim Burnett - Four Foundations of Mindfulness Part 1 Observation of Body 1", "title": "Four Foundations of Mindfulness, Part 1: Observation of Body (1)", "speaker": "Nomon Tim Burnett", "date": "2016-10-29", "series": "Four Foundations of Mindfulness", "summary": "The talk's main teaching emphasizes the importance of understanding mindfulness as a complex and nuanced concept that cannot be reduced to simple definitions or practices. Rather than trying to cultivate a specific mental state, mindfulness is about recognizing and accepting the present moment just as it is, without judgment or attachment. This approach encourages individuals to focus on the qualities of their experience, such as the breath, rather than trying to control or manipulate them, in order to cultivate a sense of calm and stability in daily life.", "themes": ["Acceptance", "Interconnection"], "texts": [], "minutes": 48}, {"id": "2016-10-27 - Nomon Tim Burnett - Four Foundations of Mindfulness Part 0 Introduction", "title": "Four Foundations of Mindfulness, Part 0: Introduction", "speaker": "Nomon Tim Burnett", "date": "2016-10-27", "series": "Four Foundations of Mindfulness", "summary": "The talk's main teaching emphasizes the importance of cultivating loving-kindness towards others by recognizing that our minds are capable of both love and hatred, but also that we can learn to manage these impulses through awareness and practice. By becoming more aware of our thoughts and emotions, we can avoid getting caught up in negative patterns and instead cultivate a more compassionate and inclusive world. This requires a willingness to let go of preconceptions and be open-minded, allowing us to see others as complex individuals with their own unique qualities.", "themes": ["Compassion"], "texts": [], "minutes": 35}, {"id": "2016-10-20 - Ryushin Andrea Thach - To Forgive and Forget", "title": "To Forgive and Forget", "speaker": "Ryushin Andrea Thach", "date": "2016-10-20", "series": "", "summary": "The talk's main teaching is that true forgiveness involves not just letting go of resentment towards others, but also releasing attachment to past hurts and expectations for a better future. This means giving up hope for change or reparation and instead accepting what has happened as it was, without judgment or expectation. By doing so, we can cultivate humility, gratitude, and compassion, which allows us to see ourselves and others in a new light and meet each other with kindness and understanding.", "themes": ["Compassion", "Ethics", "Gratitude", "Interconnection"], "texts": [], "minutes": 34}, {"id": "2016-10-13 - Nomon Tim Burnett - Yogachara Love Seeds", "title": "Yogachara Love Seeds", "speaker": "Nomon Tim Burnett", "date": "2016-10-13", "series": "", "summary": "The speaker encourages listeners to explore how patterns of mind block their ability to give and receive love, using the Yogachara model as a tool for self-inquiry. By understanding how our minds generate reality and store experiences, tendencies, and impulses in a subconscious \"storehouse consciousness,\" we can recognize when anxiety or negative thoughts arise and take a step back to observe them without identification. This recognition allows us to approach ourselves and others with compassion and understanding, rather than judgment or reaction, ultimately cultivating love and compassion in all aspects of life.", "themes": ["Compassion", "Interconnection", "No-self"], "texts": [], "minutes": 37}, {"id": "2016-10-02 - Nomon Tim Burnett - Understanding Consciousness", "title": "Understanding Consciousness", "speaker": "Nomon Tim Burnett", "date": "2016-10-02", "series": "", "summary": "The talk explores the Yogachara school's model of consciousness, which emphasizes understanding the inner process behind our experiences to gain insight into reality. This model reveals that our experience is characterized by impermanence, dissatisfaction, and lack of a permanent self, challenging us to let go of attachment and find freedom from suffering. By recognizing this nature of reality, we can begin to understand how our thoughts, emotions, and circumstances shape our minds and influence our experiences, allowing for personal growth and healing through mindfulness and intentional response.", "themes": ["Impermanence", "No-self", "Suffering"], "texts": ["Heart Sutra"], "minutes": 78}, {"id": "2016-09-29 - Manja Deb Wibe - Debs Wayfinding Talk", "title": "Deb's Wayfinding Talk", "speaker": "Manja Deb Wibe", "date": "2016-09-29", "series": "", "summary": "The speaker shares that their life journey has been shaped by various influences, but ultimately came to understand that true meaning and liberation lie not in trying to control or perfect their experiences, but rather in embracing the present moment as it is. This realization has brought a sense of freedom from ego and perfectionism, allowing them to find peace and fulfillment in being fully engaged with life. Through regular meditation practice, they've discovered a deeper connection to themselves and others, finding a sense of home and transformation that transcends external circumstances.", "themes": ["Gratitude", "No-self", "Sangha"], "texts": [], "minutes": 17}, {"id": "2016-09-22 - Ryushin Andrea Thach - Everything We Do Is About Love", "title": "Everything We Do Is About Love", "speaker": "Ryushin Andrea Thach", "date": "2016-09-22", "series": "", "summary": "The speaker's talk emphasizes that true peace and understanding come from embracing love and compassion as fundamental aspects of Zen practice. This involves letting go of ego and seeing ourselves and others as part of a larger, interconnected universe, rather than separate entities. By cultivating this sense of unity and acceptance, we can respond to difficult times with kindness and understanding, rather than hatred or division, and live our lives with greater awareness and connection to the world around us.", "themes": ["Buddha-nature", "Compassion", "Interconnection"], "texts": ["Lotus Sutra"], "minutes": 30}, {"id": "2016-08-25 - Nyogen Connie Martin - Revival", "title": "Revival", "speaker": "Nyogen Connie Martin", "date": "2016-08-25", "series": "", "summary": "The speaker shares their personal journey from finding solace in Buddhism and Zen practices after growing up in a conservative Christian household, where they initially turned away from pain and difficulty but eventually learned to approach them with compassion and understanding. Through their experiences, they explore themes of identity, faith, and resilience, highlighting the importance of courage, humility, and embracing mistakes as essential for growth. Ultimately, the speaker finds peace and understanding in the present moment, even if it's just brief moments, and acknowledges their ongoing journey of discovery and exploration.", "themes": ["Suffering", "Vulnerability"], "texts": ["Shōbōgenzō"], "minutes": 29}, {"id": "2016-08-18 - Nomon Tim Burnett - Breathing and Healing in Africa Part 2", "title": "Breathing and Healing in Africa, Part 2", "speaker": "Nomon Tim Burnett", "date": "2016-08-18", "series": "Breathing and Healing in Africa", "summary": "The speaker shares an experience from visiting Kenya where they spent time with Marcy Okumu, a young woman they were sponsoring through a charity project, which shifted their perspective on reality and highlighted the importance of humility and awareness as they witnessed stark contrasts between wealth and poverty. This experience allowed them to gain a deeper understanding of life in Kenya and the complexities that come with it. Through this encounter, the speaker was reminded of the need for awareness and compassion in our daily lives.", "themes": ["Social engagement", "Suffering"], "texts": [], "minutes": 50}, {"id": "2016-08-11 - Nomon Tim Burnett - Breathing and Healing in Africa Part 1", "title": "Breathing and Healing in Africa, Part 1", "speaker": "Nomon Tim Burnett", "date": "2016-08-11", "series": "Breathing and Healing in Africa", "summary": "The speaker shares their 25-year journey as a Zen practitioner, highlighting the importance of community, simplicity, and being open to new experiences. They reflect on how meditation practice can help cultivate awareness, presence, and curiosity about oneself and the world, allowing us to respond to suffering in a more compassionate way. By embracing simplicity and letting go of complex thoughts and judgments, we can deepen our understanding of ourselves and others, and find greater connection and meaning in life.", "themes": ["Compassion", "Social engagement", "Suffering"], "texts": [], "minutes": 50}, {"id": "2016-08-04 - Seiu Hannah Sullivan, Joden Bob Rose and Seishu John Wiley - Japan Pilgrimage", "title": "Japan Pilgrimage", "speaker": "Seiu Hannah Sullivan, Joden Bob Rose and Seishu John Wiley", "date": "2016-08-04", "series": "", "summary": "The speaker reflects on their experiences visiting various temples and shrines in Japan, including traditional Zen monasteries and cultural sites, which deepened their understanding of Soto Zen principles. They share stories about the warmth and hospitality they encountered at each site, as well as the unique architecture, art, and culture they observed. Through these experiences, the speaker came to appreciate the importance of mindfulness, community, and connection with nature in Zen practice, and how these values can be found in everyday life.", "themes": [], "texts": [], "minutes": 47}, {"id": "2016-07-28 - Ryushin Andrea Thach - Our Embodied Life Part 4 Resiliancy and Chiyonos No Moon No Water", "title": "Our Embodied Life, Part 4: Resiliancy and Chiyono's No Moon, No Water", "speaker": "Ryushin Andrea Thach", "date": "2016-07-28", "series": "Our Embodied Life", "summary": "The main teaching of the dharma talk is that true strength and resilience come from embracing our imperfections and letting go of attachment to control or perfection. By cultivating a sense of buoyancy, or pliancy, we can learn to be present with uncertainty and allow things to unfold naturally, rather than trying to force them into a specific shape or outcome. This approach allows us to find confidence and trust in the present moment, rather than striving for an idealized version of ourselves or our lives.", "themes": ["Acceptance", "No-self", "Suffering"], "texts": [], "minutes": 40}, {"id": "2016-07-21 - Ryushin Andrea Thach - Our Embodied Life Part 3 Who is Senjo", "title": "Our Embodied Life, Part 3: Who is Senjo?", "speaker": "Ryushin Andrea Thach", "date": "2016-07-21", "series": "Our Embodied Life", "summary": "The talk explores how our experiences shape us into who we are, and how we can come to understand our true essence beyond these roles and personas. It's not about losing ourselves, but recognizing and inhabiting our fundamental nature, which is often hidden beneath layers of conditioning and circumstance. By letting go of attachments and acknowledging the influence of external causes, we can discover a deeper sense of self that is more authentic and whole.", "themes": ["Emptiness", "No-self"], "texts": ["Shōbōgenzō"], "minutes": 51}, {"id": "2016-07-14 - Ryushin Andrea Thach - Our Embodied Life Part 2 Kisagotami and the Tender Heart", "title": "Our Embodied Life, Part 2: Kisagotami and the Tender Heart", "speaker": "Ryushin Andrea Thach", "date": "2016-07-14", "series": "Our Embodied Life", "summary": "The Soto Zen dharma talk teaches that true freedom and understanding come from embracing the reality of impermanence and loss in our lives. By acknowledging that we are not safe from suffering or loss, and that our identity is not tied to external circumstances, we can cultivate radical compassion and acceptance. This allows us to move forward with a sense of peace and understanding, rather than trying to escape or deny our pain, and ultimately leads to transcendent wisdom and a deeper connection with ourselves and others.", "themes": ["Compassion", "Impermanence", "Suffering", "Vulnerability"], "texts": [], "minutes": 53}, {"id": "2016-06-28 - Ryushin Andrea Thach - Knock Down the Banner", "title": "Knock Down the Banner", "speaker": "Ryushin Andrea Thach", "date": "2016-06-28", "series": "", "summary": "The teacher emphasizes the importance of putting teachings into practice rather than just holding onto them as abstract concepts. In a world where polarization and fear are on the rise, it's easy to get caught up in trying to impose our own moral frameworks on others, leading to division and striving. Instead, the speaker suggests embracing uncertainty and provisionality, allowing for multiple perspectives and ways of solving problems, and cultivating connection with others through active listening and understanding.", "themes": ["Interconnection", "Social engagement", "Wisdom"], "texts": [], "minutes": 33}, {"id": "2016-06-24 - Zoketsu Norman Fischer - Evaluating Doctrines", "title": "Evaluating Doctrines", "speaker": "Zoketsu Norman Fischer", "date": "2016-06-24", "series": "", "summary": "The talk's main teaching emphasizes the importance of critically evaluating teachings and considering their impact on one's life, rather than relying solely on external factors like lineage or reputation. It encourages individuals to verify wisdom through personal experience and confirmation from others, acknowledging both individual responsibility and social accountability. This approach recognizes that we may be prone to biases and errors, and seeks to cultivate a deeper understanding of teachings by considering their effects in our own lives.", "themes": ["Compassion", "Ethics"], "texts": [], "minutes": 23}, {"id": "2016-06-23 - Zoketsu Norman Fischer - When Mountains are Mountains", "title": "When Mountains are Mountains", "speaker": "Zoketsu Norman Fischer", "date": "2016-06-23", "series": "", "summary": "The speaker shares that true understanding in Zen practice comes from letting go of our tendency to grasp for fixed truths or judgments, and instead embracing the present moment without attachment or expectation. This means recognizing that truth is not something we can control or understand, but rather it emerges when we stop trying to grasp it. By doing so, we can awaken to the reality of life itself, which is inherently complex, beautiful, and imperfect.", "themes": ["Emptiness", "Wisdom"], "texts": ["Shōbōgenzō"], "minutes": 50}, {"id": "2016-06-22 - Zoketsu Norman Fischer - Self", "title": "Self", "speaker": "Zoketsu Norman Fischer", "date": "2016-06-22", "series": "", "summary": "The Buddha teaches that our experience is not defined by a permanent, unchanging self, but rather by interconnected aspects of reality such as form, feeling, perception, impulse, and consciousness. By recognizing this, we can unify body and mind, ground ourselves in the present moment, and find liberation from suffering. This understanding allows us to see things as they truly are, without attachment or identification, leading to a sense of freedom and enlightenment.", "themes": ["No-self", "Suffering"], "texts": [], "minutes": 48}, {"id": "2016-06-21 - Zoketsu Norman Fischer - About Nothing", "title": "About Nothing", "speaker": "Zoketsu Norman Fischer", "date": "2016-06-21", "series": "", "summary": "The talk's main teaching emphasizes the importance of embracing emptiness, or \"suchness,\" which means letting go of attachments to concepts like God, self, and external realities. This understanding allows us to connect with the present moment and find meaning in our lives without seeking something more. By embracing imperfection and finding comfort in our current circumstances, we can discover a sense of peace and home that is already within us, regardless of where we are or what we have.", "themes": ["Buddha-nature", "Emptiness"], "texts": [], "minutes": 49}, {"id": "2016-06-16 - Shuko Edie Norton - Mumonkan 7 Clean Your Bowl", "title": "Mumonkan 7 - Clean Your Bowl", "speaker": "Shuko Edie Norton", "date": "2016-06-16", "series": "", "summary": "The main teaching of the Soto Zen dharma talk emphasizes the importance of taking care of oneself, others, and the world around us. By practicing mindfulness through zazen and becoming more aware of our thoughts, emotions, and surroundings, we can develop compassion for all beings and embody the Bodhisattva practice. This awareness can be cultivated through both instruction and personal responsibility, leading to a deeper understanding of ourselves and others, and ultimately transforming our relationships with the world around us.", "themes": ["Compassion", "Social engagement"], "texts": ["Gateless Barrier"], "minutes": 38}, {"id": "2016-06-09 - Nomon Tim Burnett - Perception", "title": "Perception", "speaker": "Nomon Tim Burnett", "date": "2016-06-09", "series": "", "summary": "The talk's main teaching emphasizes the importance of cultivating compassion and understanding in our interactions with others by being aware of our own perceptions and reactions. The speaker invites the audience to explore perception as a process that involves noticing suffering, feeling empathy, and staying with it, rather than just offering abstract support. By recognizing how our individual perspectives can lead to misunderstandings and frustration, we can work towards greater compassion and understanding for ourselves and others.", "themes": ["Compassion", "Wisdom"], "texts": [], "minutes": 35}, {"id": "2016-05-26 - Nomon Tim Burnett - Zenkei Blanche Hartman", "title": "Zenkei Blanche Hartman", "speaker": "Nomon Tim Burnett", "date": "2016-05-26", "series": "", "summary": "Blanche Hartman shares her personal experience of meeting Suzuki Roshi, who taught her that true understanding comes from embracing one's imperfections and limitations. Through private interviews with Roshi, she learned to cultivate self-awareness and humility, recognizing that spiritual growth requires a willingness to let go of ego and misconceptions about oneself. This lesson has stayed with Hartman, offering valuable insights into the importance of acknowledging others' worth and value with respect and gratitude, particularly as we age.", "themes": ["Vulnerability"], "texts": [], "minutes": 15}, {"id": "2016-05-19 - Heigaku Talus Latona - Mumonkan 5 Up a Tree", "title": "Mumonkan 5 - Up a Tree", "speaker": "Heigaku Talus Latona", "date": "2016-05-19", "series": "", "summary": "The talk emphasizes the importance of embracing life's challenges with a sense of curiosity and openness, rather than trying to intellectually solve them. By recognizing our current moment and dilemma, we can tap into our own power to make choices and take action, freeing us from suffering. This requires a willingness to let go of attachments and find freedom in the present moment, which is often facilitated by guidance from teachers and community members.", "themes": ["Impermanence", "Suffering"], "texts": ["Gateless Barrier"], "minutes": 30}, {"id": "2016-05-12 - Nomon Tim Burnett - Compassion Part 3 To Hell and Back Again", "title": "Compassion, Part 3: To Hell and Back Again", "speaker": "Nomon Tim Burnett", "date": "2016-05-12", "series": "Compassion (series)", "summary": "The talk emphasizes the importance of cultivating compassion by acknowledging and embracing our own suffering as well as that of others. This involves being willing to feel and understand the pain and imperfections of ourselves and others, rather than trying to limit or compartmentalize them. By doing so, we can find a happiness that includes the full human experience of suffering, which requires patience, practice, and a willingness to connect with others' struggles.", "themes": ["Compassion", "Suffering"], "texts": [], "minutes": 29}, {"id": "2016-04-28 - Charlie-Anne Mikkelsen - Taking Up the Way of Letting Go of Anger", "title": "Taking Up the Way of Letting Go of Anger", "speaker": "Charlie-Anne Mikkelsen", "date": "2016-04-28", "series": "", "summary": "The talk's main teaching emphasizes the importance of embracing difficult emotions like anger, rather than trying to eliminate or suppress them. By taking a curious and present approach, we can transform our responses to challenging situations, finding meaning and purpose in the midst of suffering. This approach was illustrated through the speaker's personal experience with her husband's passing from Parkinson's disease, where she came to understand that love and connection can persist even after impermanence and letting go.", "themes": ["Acceptance", "Compassion", "Impermanence"], "texts": [], "minutes": 26}, {"id": "2016-04-21 - Ryushin Andrea Thach - Nothing is ever out of place", "title": "Nothing is ever out of place.", "speaker": "Ryushin Andrea Thach", "date": "2016-04-21", "series": "", "summary": "The speaker's main teaching emphasizes the importance of embracing the paradoxical nature of life, where darkness and light are intertwined aspects of our experiences. By letting go of binary thinking and moral judgment, we can find freedom from trying to change or judge ourselves based on past events, and instead discover our true nature by being present with the world as it is. This includes accepting that karma is simply an unfolding of causes and conditions, rather than good or bad, allowing us to tap into the universal energy that points towards our own light, even in its darkest moments.", "themes": ["Acceptance", "Buddha-nature"], "texts": ["Heart Sutra", "Shōbōgenzō"], "minutes": 29}, {"id": "2016-04-14 - Nomon Tim Burnett - Compassion Part 2 Contemplation of Death", "title": "Compassion, Part 2: Contemplation of Death", "speaker": "Nomon Tim Burnett", "date": "2016-04-14", "series": "Compassion (series)", "summary": "The speaker invites the community to explore their fear of abandonment as a practice, acknowledging its prevalence and potential for growth. They then shift focus to Joan Casey's passing, using her presence as an opportunity to come together with the Shambhala Center and cultivate compassion through contemplation of death and impermanence. By exploring these themes, the speaker hopes to inspire listeners to develop greater emotional awareness, acceptance, and connection to their own lives and the lives of those around them.", "themes": ["Compassion", "Impermanence"], "texts": [], "minutes": 33}, {"id": "2016-03-31 - Nomon Tim Burnett - Compassion Part 1 All Beings Want Happiness", "title": "Compassion, Part 1: All Beings Want Happiness", "speaker": "Nomon Tim Burnett", "date": "2016-03-31", "series": "Compassion (series)", "summary": "The talk's main teaching emphasizes the importance of recognizing our interconnectedness with all beings, which can help us cultivate compassion and understanding for ourselves and others. By acknowledging that we are all connected through shared experiences like breathing and life, we can respond with kindness and love, even in difficult situations. This recognition requires a shift from our individual perspectives to a more expansive awareness, allowing us to see the world and its inhabitants as part of a larger whole.", "themes": ["Compassion", "Interconnection", "Suffering"], "texts": [], "minutes": 29}, {"id": "2016-03-13 - Nomon Tim Burnett - Inner Gold Part 2 Handling Inner Gold", "title": "Inner Gold, Part 2: Handling Inner Gold", "speaker": "Nomon Tim Burnett", "date": "2016-03-13", "series": "Inner Gold", "summary": "The talk's main teaching emphasizes the importance of balancing mental clarity with physical relaxation in meditation practice, suggesting that a more open and receptive posture can allow for greater awareness and spaciousness. This is contrasted with the tendency to focus too much on the mind and neglect the body's needs, which can lead to tension and suffering. By cultivating a sense of openness and relaxation through gentle movements like lifting the sternum, practitioners can create a more conducive environment for meditation and spiritual growth.", "themes": ["Compassion", "Sangha", "Vulnerability"], "texts": [], "minutes": 48}, {"id": "2016-03-12 - Nomon Tim Burnett - Inner Gold Part 1 Why did Zen take root in the West", "title": "Inner Gold, Part 1: Why did Zen take root in the West?", "speaker": "Nomon Tim Burnett", "date": "2016-03-12", "series": "Inner Gold", "summary": "The talk's main teaching emphasizes the importance of looking within oneself for spiritual fulfillment, rather than relying on others or projecting one's inner essence onto them. This can involve recognizing patterns of hero worship and unhealthy reliance on others for validation and purpose, and instead cultivating self-awareness and introspection to discover one's own true nature. By doing so, we can break free from the need for external sources of meaning and connection and find our own path to growth and understanding.", "themes": ["Buddha-nature", "Sangha"], "texts": [], "minutes": 43}, {"id": "2016-03-12 - Zoketsu Norman Fischer - Devadatta Trouble in the First Sangha", "title": "Devadatta - Trouble in the First Sangha", "speaker": "Zoketsu Norman Fischer", "date": "2016-03-12", "series": "", "summary": "The talk's main teaching revolves around the importance of responding to difficulty with love and respect, rather than letting it lead to pain and suffering for everyone involved. The Buddha's story about Devadatta serves as a reminder that even in the face of adversity, we can choose to approach challenges with compassion and kindness, rather than resorting to aggression or harm. This teaching encourages listeners to cultivate a sense of loving-kindness towards themselves and others, particularly those who may be struggling with aging, illness, or other challenges.", "themes": ["Compassion", "No-self", "Sangha"], "texts": [], "minutes": 59}, {"id": "2016-03-11 - Zoketsu Norman Fischer - Anapanasati Sutra On Breath Mindfulness", "title": "Anapanasati Sutra On Breath Mindfulness", "speaker": "Zoketsu Norman Fischer", "date": "2016-03-11", "series": "", "summary": "The speaker's main teaching emphasizes the importance of cultivating mindfulness and awareness in daily life, particularly through the practice of breathing with full attention. By doing so, one can develop a greater sense of gratitude, appreciation, and connection to their body and surroundings, leading to a more peaceful and liberated state of being. This practice allows us to let go of attachment to happiness and instead find calmness and peace in the present moment, embracing impermanence and interconnectedness with an open and aware heart.", "themes": ["Impermanence", "Interconnection"], "texts": [], "minutes": 57}, {"id": "2016-01-30 - Nomon Tim Burnett - Essence", "title": "Essence", "speaker": "Nomon Tim Burnett", "date": "2016-01-30", "series": "", "summary": "The main teaching of this Soto Zen dharma talk emphasizes the importance of cultivating kindness and warmth towards oneself and one's body as the essence of true practice. This involves recognizing that our nature is already tranquil and imperturbable, and that we can develop a deeper understanding of ourselves and the world by embracing silence and letting go of external expectations or desires. By doing so, we can transform our lives and share this tranquility with others, living in harmony with the world rather than isolating ourselves from it.", "themes": ["Buddha-nature"], "texts": ["Shōbōgenzō"], "minutes": 44}, {"id": "2016-01-14 - Reizan Bob Penny - Western Ancestors Part 5 Henry David Thoreau", "title": "Western Ancestors, Part 5: Henry David Thoreau", "speaker": "Reizan Bob Penny", "date": "2016-01-14", "series": "Western Ancestors", "summary": "The talk's main teaching is that simplicity and non-action can be a powerful path to living fully in the present moment, unencumbered by societal expectations or distractions. Drawing inspiration from Henry David Thoreau's carefree spirit and embodiment of nonviolence, the speaker encourages listeners to cultivate a similar attitude of mindfulness and connection with nature, letting go of external values and dogma to experience reality directly. By embracing this approach, we can find joy and freedom in our daily lives, just as Thoreau did at Walden Pond.", "themes": ["Social engagement"], "texts": [], "minutes": 36}, {"id": "2016-01-07 - Ryushin Kate Korn McKenna and Seishu John Wiley - Understanding Conflict", "title": "Understanding Conflict", "speaker": "Ryushin Kate Korn McKenna and Seishu John Wiley", "date": "2016-01-07", "series": "", "summary": "Here's a summary of the Soto Zen dharma talk in one paragraph:\n\nThe speaker offers an interest and needs-based model for conflict resolution, which focuses on understanding the underlying needs and interests of all parties involved rather than just asserting one's own needs. This approach aims to create a more relational and compassionate way of managing conflicts, leading to greater intimacy and connection. By recognizing and addressing these underlying issues, individuals can potentially change the course of the conflict and achieve a better outcome, fostering empathy, transparency, and vulnerability in their interactions with others.", "themes": ["Sangha", "Vulnerability"], "texts": [], "minutes": 54}, {"id": "2015-12-24 - Nomon Tim Burnett - Western Ancestors Part 4 Suzuki Roshi", "title": "Western Ancestors, Part 4: Suzuki Roshi", "speaker": "Nomon Tim Burnett", "date": "2015-12-24", "series": "Western Ancestors", "summary": "The talk's main teaching is that true fulfillment and peace can be found not by achieving some specific state or goal, but by embracing the present moment and finding courage in the midst of challenges. This sense of \"okay-ness\" or feeling enough can be a powerful antidote to feelings of inadequacy, and it can be cultivated through the practice of zazen and other spiritual disciplines. By letting go of ego and attachment, we can find freedom and peace, even in the face of difficulties, and discover that true understanding comes from embracing the endless nature of practice.", "themes": ["Acceptance"], "texts": ["Heart Sutra"], "minutes": 30}, {"id": "2015-12-17 - Nomon Tim Burnett - The Self and the Listener", "title": "The Self and the Listener", "speaker": "Nomon Tim Burnett", "date": "2015-12-17", "series": "", "summary": "The talk emphasizes the importance of embracing a simple yet profound practice, such as sitting with awareness of one's breath or simply being present, without trying to change or improve oneself. This approach requires trust and renunciation, allowing the practitioner to let go of desire for understanding and perfection. By focusing on a single practice, we can cultivate stability and insight over time, and find peace and clarity in the midst of our thoughts and emotions.", "themes": ["Acceptance", "No-self"], "texts": ["Shōbōgenzō"], "minutes": 32}, {"id": "2015-12-05 - Eko Jeff Kelley - Dongshans Companion", "title": "Dongshan's Companion", "speaker": "Eko Jeff Kelley", "date": "2015-12-05", "series": "", "summary": "The talk's main teaching emphasizes the importance of cultivating a \"companion\" within oneself, rather than trying to grasp external concepts or ideas. This companion is not something that can be constructed or grasped, but rather an energy of loyalty and openness that allows us to show up in each moment with sincerity and humility. By developing this inner companion, we can invite our true nature into being and meet it with compassion and kindness, allowing us to embody the qualities of mindfulness, determination, and openness in our daily lives.", "themes": ["Buddha-nature", "Compassion"], "texts": [], "minutes": 32}, {"id": "2015-12-04 - Nomon Tim Burnett - Western Ancestors Part 3 Nyogen Senzaki", "title": "Western Ancestors, Part 3: Nyogen Senzaki", "speaker": "Nomon Tim Burnett", "date": "2015-12-04", "series": "Western Ancestors", "summary": "Here is a summary of the main teaching in plain language:\n\nThe talk encourages us to look beyond our immediate perceptions and consider the broader reality of poverty rates, which have actually decreased significantly since 1993, despite what many people may think. This shift in perspective can help us recognize that our individual efforts can make a positive impact on creating change. By understanding this reality and cultivating mindfulness, humility, and patience, we can transform our own \"effort\" into an easeful practice that brings greater ease and fulfillment to ourselves and others.", "themes": ["Sangha", "Suffering"], "texts": [], "minutes": 55}, {"id": "2015-11-26 - Nomon Tim Burnett - Western Ancestors Part 2 Katagiri Roshi", "title": "Western Ancestors, Part 2: Katagiri Roshi", "speaker": "Nomon Tim Burnett", "date": "2015-11-26", "series": "Western Ancestors", "summary": "The speaker emphasizes the importance of simplicity and presence in Zen practice, encouraging listeners to focus on being a mature and grounded person rather than seeking brilliant insights or great meditative attainment. This approach is rooted in the history of Soto Zen in America, where women like G.U. Kennet Roshi brought this sensibility to North America despite not intending to do so. By embracing simplicity and presence, practitioners can embody Buddha's teachings in the here and now, rather than trying to preserve a precious jewel or attain great spiritual status.", "themes": ["Sangha"], "texts": [], "minutes": 44}, {"id": "2015-11-19 - Eko Jeff Kelley - Compassionate Communication", "title": "Compassionate Communication", "speaker": "Eko Jeff Kelley", "date": "2015-11-19", "series": "", "summary": "The talk's main teaching is that true compassion and connection involve meeting each other's basic human needs, such as respect, love, and empathy, while also acknowledging our own limitations and flaws. This approach recognizes that we don't have to transcend our humanity in order to cultivate compassion, but rather work to create conditions where both ourselves and others can flourish. By doing so, we can tap into a deeper sense of connection and understanding that is rooted in our shared humanity.", "themes": ["Compassion", "No-self", "Suffering"], "texts": [], "minutes": 31}, {"id": "2015-11-12 - Heigaku Talus Latona - Western Ancestors Part 1 Jiyu Kennet", "title": "Western Ancestors, Part 1: Jiyu Kennet", "speaker": "Heigaku Talus Latona", "date": "2015-11-12", "series": "Western Ancestors", "summary": "The speaker will explore the teachings of Gyoku Carlson, an American Soto Zen abbot who emphasizes mindfulness and compassion, drawing on her lineage rooted in Eihei Dogen and his teachers. This lineage has evolved over centuries, from its origins in Japan to its spread throughout the West, influenced by key figures such as Roshi Juyukenet and D.T. Suzuki. The speaker will delve into the history of Soto Zen, tracing its roots and evolution through texts like Keizan's Record of the Transmission of Light, which emphasizes the importance of koans in achieving enlightenment.", "themes": ["Sangha"], "texts": ["Gateless Barrier"], "minutes": 29}, {"id": "2015-10-31 - Nomon Tim Burnett - Compassion Seminar", "title": "Compassion Seminar", "speaker": "Nomon Tim Burnett", "date": "2015-10-31", "series": "", "summary": "The speaker's talk encourages us to explore compassion by looking at what it is not, rather than defining it directly. This involves recognizing our tendency to project our own flaws onto others, but also acknowledging the value of self-criticism while learning to distinguish between constructive criticism and self-judgment. By examining how we respond to suffering in ourselves and others, we can cultivate compassion as a process that requires us to engage with our own vulnerabilities and those of others, while being mindful of our own limitations and the autonomy of others.", "themes": ["Compassion", "Suffering", "Vulnerability"], "texts": [], "minutes": 45}, {"id": "2015-10-22 - Kanho Chris Burkhart - Mara Part 2", "title": "Mara, Part 2", "speaker": "Kanho Chris Burkhart", "date": "2015-10-22", "series": "Mara", "summary": "The talk explores the concept of Mara, a personification of obstacles and hindrances on the Buddhist path, who tempts individuals to flee from reality by distracting themselves with sensual pleasures or seeking security in phenomena. Through stories from the Pali Canon, it's shown that even the Buddha and nuns were not immune to Mara's temptations, but they recognized him and firmly put him in his place. The talk suggests that recognizing Mara involves developing mindfulness of one's own mind, befriending thoughts rather than aversion, and cultivating bravery to be present with experience, allowing one to see through Mara's tricks and find peace.", "themes": ["Suffering"], "texts": [], "minutes": 15}, {"id": "2015-09-24 - Kanho Chris Burkhart - Mara Part 1", "title": "Mara, Part 1", "speaker": "Kanho Chris Burkhart", "date": "2015-09-24", "series": "Mara", "summary": "The speaker suggests that Mara, often seen as an obstacle on the Buddhist path, can actually be viewed as a shadowy representation of humanity's own attachments and ego. By recognizing this dualistic relationship, practitioners can transform their negative tendencies into positive ones, much like gardeners turning garbage into compost. This understanding encourages us to look beyond our usual tendency to see things as separate from ourselves, instead embracing the interconnectedness and interdependence of all phenomena.", "themes": ["No-self"], "texts": [], "minutes": 16}, {"id": "2015-09-10 - Nomon Tim Burnett - Paramitas Patience Beyond Patience Kshanti", "title": "Paramitas - Patience Beyond Patience (Kshanti)", "speaker": "Nomon Tim Burnett", "date": "2015-09-10", "series": "Paramitas", "summary": "The talk's main teaching is about cultivating patience as a way to connect with life rather than resisting it. It involves letting go of our individual perspectives and instead embracing the world around us, even when things don't go as planned. By studying non-patience and holding it in a helpful way, we can transform impatience into an opportunity for growth and connection, allowing us to approach life with greater openness and trust.", "themes": ["Acceptance"], "texts": [], "minutes": 25}, {"id": "2015-08-27 - Heigaku Talus Latona - Paramitas Perfection of Conduct Sila", "title": "Paramitas - Perfection of Conduct (Sīla)", "speaker": "Heigaku Talus Latona", "date": "2015-08-27", "series": "Paramitas", "summary": "The speaker's talk emphasizes the importance of cultivating gratitude and letting go of attachment to things we already possess. This is rooted in the concept of sila, or perfection of conduct, which is a key aspect of the Buddhist path. By practicing right speech, action, and livelihood according to the eightfold path, we can recognize and release our attachment to material possessions and cultivate a more mindful and compassionate way of living.", "themes": ["Ethics", "Gratitude"], "texts": ["Diamond Sutra"], "minutes": 25}, {"id": "2015-08-20 - Nomon Tim Burnett - Gratitude", "title": "Gratitude", "speaker": "Nomon Tim Burnett", "date": "2015-08-20", "series": "", "summary": "The speaker shares two contrasting experiences that highlight the importance of approaching life's challenges with greater mindfulness and acceptance. They reflect on how their mind quickly spins out of control when faced with unwanted news or difficulties, such as being stuck in traffic, and how this experience is a reminder to cultivate gratitude and appreciation for the present moment. This talk encourages listeners to pause and acknowledge their thoughts, emotions, and experiences, including difficulties and challenges, rather than resisting or getting caught up in them.", "themes": ["Acceptance", "Gratitude"], "texts": [], "minutes": 29}, {"id": "2015-08-13 - Ryushin Kate Korn McKenna - Doubt", "title": "Doubt", "speaker": "Ryushin Kate Korn McKenna", "date": "2015-08-13", "series": "", "summary": "The speaker's main teaching is that doubt can be both beneficial and harmful in the context of meditation practice, but ultimately serves as a catalyst for growth and awakening. By embracing great doubt and questioning our current understanding, we can tear down old certainties and find new insights, allowing us to approach challenges with a fresh perspective and deepen our practice over time. This process requires courage, humility, and openness, and is essential for manifesting Buddha nature and realizing our true potential.", "themes": ["Buddha-nature", "Vulnerability"], "texts": [], "minutes": 26}, {"id": "2015-07-23 - Shuko Edie Norton - Paramitas 4 Effort", "title": "Paramitas – #4 Effort", "speaker": "Shuko Edie Norton", "date": "2015-07-23", "series": "Paramitas", "summary": "The main teaching of this Soto Zen dharma talk emphasizes the importance of effort or zeal in Zen practice, which involves developing spiritual strength and stamina to persist in one's practice despite challenges and discomforts. This requires discipline, self-awareness, and adaptability, particularly as we age or face physical limitations. By cultivating mindfulness and compassion, we can find a balance between our body's needs and our spiritual aspirations, leading to greater clarity and focus in all aspects of life.", "themes": ["Acceptance", "Impermanence", "Sangha"], "texts": [], "minutes": 23}, {"id": "2015-07-16 - Kanho Chris Burkhart - Two Ways of Knowing", "title": "Two Ways of Knowing", "speaker": "Kanho Chris Burkhart", "date": "2015-07-16", "series": "", "summary": "The talk's main teaching centers on the importance of transcending our attachment to a fixed identity and instead embracing our experiences and emotions as the true source of our being. Through a personal experience of falling and recovering from a severe head injury, the speaker shares how they came to realize that their sense of self was not defined by their physical body, but rather by their capacity for awareness and connection with others. This realization allows us to approach life with greater openness, vulnerability, and compassion, and to live more fully in the present moment. By letting go of our ego's need for control and instead embracing our shared humanity, we can cultivate a sense of unity and interconnectedness that is at the heart of Buddhist teachings.", "themes": ["Impermanence", "Vulnerability"], "texts": [], "minutes": 22}, {"id": "2015-07-12 - Nomon Tim Burnett - The Bodhisattvas Four Methods", "title": "The Bodhisattvas Four Methods", "speaker": "Nomon Tim Burnett", "date": "2015-07-12", "series": "", "summary": "The main teaching of this Soto Zen dharma talk is that true freedom and peace come from embracing our imperfections and limitations as human beings, rather than trying to suppress or overcome them. By cultivating a sense of balance and community in our practice, we can develop stability, compassion, and wholeness. This involves being present with ourselves and others, practicing kindness and generosity, and being willing to adapt and change in response to life's challenges.", "themes": ["Compassion", "No-self"], "texts": ["Shōbōgenzō"], "minutes": 50}, {"id": "2015-07-09 - Nomon Tim Burnett - Bodhisattva Methods Part 4 Identity Action", "title": "Bodhisattva Methods, Part 4: Identity Action", "speaker": "Nomon Tim Burnett", "date": "2015-07-09", "series": "Bodhisattva Methods", "summary": "The main teaching of the Soto Zen dharma talk is that meditation practice can help us cultivate mindfulness, awareness, and balance in our lives, allowing us to navigate both challenging and joyful experiences with greater ease and connection to ourselves and others. By embracing this paradoxical nature of life, we can learn to be more adaptable, humble, and kind, even in difficult situations, and find a sense of completion and wholeness through our spiritual practice. Ultimately, the goal is not to achieve a fixed state, but to cultivate a fluid and dynamic awareness that allows us to move with greater harmony and compassion in the world.", "themes": ["No-self", "Sangha"], "texts": ["Shōbōgenzō"], "minutes": 41}, {"id": "2015-06-20 - Nomon Tim Burnett - Compassion For Charleston", "title": "Compassion For Charleston", "speaker": "Nomon Tim Burnett", "date": "2015-06-20", "series": "", "summary": "The talk's main teaching is that true freedom and peace can be found by embracing the present moment, even in the midst of suffering and uncertainty. This requires cultivating patience, compassion, and understanding, not just for ourselves, but also for others who may be struggling with pain and hatred. By acknowledging our own limitations and vulnerabilities, we can begin to see the interconnectedness of all beings and find ways to heal and transform suffering, rather than simply trying to transcend or escape it.", "themes": ["Compassion", "Social engagement"], "texts": [], "minutes": 46}, {"id": "2015-06-09 - Nomon Tim Burnett - Bodhisattva Methods Part 1 Giving continued", "title": "Bodhisattva Methods, Part 1: Giving continued", "speaker": "Nomon Tim Burnett", "date": "2015-06-09", "series": "Bodhisattva Methods", "summary": "The talk emphasizes the transformative power of giving, which is not just about external actions but also about cultivating self-giving and compassion towards oneself and others. Giving can take many forms, from small acts like kindness to larger ones like letting go of attachment or embracing life's challenges as opportunities for growth. By inclining our minds towards generosity and giving, we can experience positive outcomes and find peace in the present moment, even when things don't turn out as expected.", "themes": ["Gratitude"], "texts": [], "minutes": 34}, {"id": "2015-05-28 - Nomon Tim Burnett - Bodhisattva Methods Part 1 Giving", "title": "Bodhisattva Methods, Part 1: Giving", "speaker": "Nomon Tim Burnett", "date": "2015-05-28", "series": "Bodhisattva Methods", "summary": "The talk emphasizes the importance of letting go of attachment and expectation when it comes to giving, and instead cultivating a genuine and generous mindset. By recognizing our own limitations and the impermanence of all things, we can transform our stinginess into willing generosity and connect with others on a deeper level. This practice of giving is not just about external actions, but also about offering ourselves to others and to ourselves, allowing us to practice non-greed and find greater value in life.", "themes": ["Gratitude"], "texts": ["Shōbōgenzō"], "minutes": 37}, {"id": "2015-05-21 - Seishu John Wiley - Gratitude", "title": "Gratitude", "speaker": "Seishu John Wiley", "date": "2015-05-21", "series": "", "summary": "The talk's main teaching is that cultivating gratitude can profoundly impact one's day-to-day experience and well-being by shifting focus away from negative thoughts and appreciating the beauty of life, including its complexities and challenges. By practicing gratitude, individuals can develop qualities like joy, patience, generosity, and connection to others, leading to a more balanced and fulfilling life. This practice is not about accumulating material possessions or external validation, but rather about recognizing and honoring the many freely given aspects of life that make existence worthwhile.", "themes": ["Gratitude", "Sangha"], "texts": [], "minutes": 23}, {"id": "2015-04-14 - Heigaku Talus Latona - Paramitas 1 Dana Generosity", "title": "Paramitas – #1 Dana – Generosity", "speaker": "Heigaku Talus Latona", "date": "2015-04-14", "series": "Paramitas", "summary": "The talk's main teaching emphasizes the importance of cultivating generosity in our daily lives, not just through material acts, but also through emotional and spiritual ones. It encourages us to recognize that we are both the giver and receiver of life, and to approach intimacy with vulnerability and compassion. By letting go of attachment and fear, we can tap into a sense of energy and wisdom that surrounds us, and use it to benefit all living beings, just as water evaporates and rises into the atmosphere, releasing its potential for good.", "themes": ["Compassion", "Emptiness"], "texts": [], "minutes": 27}, {"id": "2015-03-19 - Nomon Tim Burnett - Bodhisattva at the Gas Station Studying the Ways of the Bodhisattva", "title": "Bodhisattva at the Gas Station: Studying the Ways of the Bodhisattva", "speaker": "Nomon Tim Burnett", "date": "2015-03-19", "series": "", "summary": "The speaker's talk emphasizes the importance of cultivating compassion, understanding, and interconnectedness in daily life as a way to embody the bodhisattva ideal. This involves letting go of distractions, focusing one's attention, and recognizing that all beings are part of a larger whole. By doing so, we can develop a sense of connection and service to others, rather than striving for unattainable goals or achievements.", "themes": ["Compassion", "Interconnection"], "texts": [], "minutes": 28}, {"id": "2015-01-25 - Nomon Tim Burnett - Dharma Talk 1 Way of the Bodhisattva", "title": "Dharma Talk 1 – Way of the Bodhisattva", "speaker": "Nomon Tim Burnett", "date": "2015-01-25", "series": "Way of the Bodhisattva", "summary": "The speaker emphasizes the importance of cultivating compassion in all its forms, including receiving it from others and practicing it towards ourselves. They encourage individuals to consider their own emotional needs and boundaries when offering or receiving compassion, and to approach this practice with self-awareness, honesty, and kindness. By embracing vulnerability and openness, we can develop a more authentic connection with ourselves and others, leading to a deeper understanding of what it means to truly care for and support one another.", "themes": ["Compassion", "Vulnerability"], "texts": [], "minutes": 55}, {"id": "2015-01-21 - Nomon Tim Burnett - Study Group 1 Way of the Bodhisattva", "title": "Study Group 1 - Way of the Bodhisattva", "speaker": "Nomon Tim Burnett", "date": "2015-01-21", "series": "Way of the Bodhisattva", "summary": "The main teaching of the Soto Zen dharma talk emphasizes the importance of cultivating bodhicitta, or the thought of awakening, as a means of recognizing and taking responsibility for one's actions and motivations. By acknowledging our own imperfections and limitations, we can begin to let go of self-centeredness and cultivate greater humility and self-awareness. This process involves setting intentions and making offerings, such as giving something away, in order to deepen our understanding of ourselves and the world around us.", "themes": ["Compassion", "Ethics"], "texts": [], "minutes": 46}, {"id": "2014-12-17 - Nomon Tim Burnett - Entangled", "title": "Entangled", "speaker": "Nomon Tim Burnett", "date": "2014-12-17", "series": "", "summary": "In Soto Zen practice, the goal isn't just to find inner peace or reduce stress, but to cultivate a deeper understanding of oneself and the present moment. This requires letting go of control and embracing uncertainty, allowing us to sit with our experiences without trying to change them. By doing so, we can develop a sense of fundamental okayness and connection to the world around us.", "themes": ["Sangha"], "texts": [], "minutes": 55}, {"id": "2014-12-10 - Shuko Edie Norton - Bodhisattva Path", "title": "Bodhisattva Path", "speaker": "Shuko Edie Norton", "date": "2014-12-10", "series": "", "summary": "The talk emphasizes the importance of being present and fully engaged with one's experience, rather than relying on external rituals or practices to bring about spiritual growth. The speaker suggests that by letting go of attachments to specific traditions or formulas, one can tap into a deeper sense of awareness and understanding. This approach encourages individuals to cultivate a sense of \"being\" in the moment, unencumbered by expectations or distractions. By doing so, they may discover a more authentic and profound connection with themselves and the world around them.", "themes": ["Compassion"], "texts": [], "minutes": 0}, {"id": "2014-12-06 - Eko Jeff Kelley - Temple Pillars", "title": "Temple Pillars", "speaker": "Eko Jeff Kelley", "date": "2014-12-06", "series": "", "summary": "In this Soto Zen dharma talk, the speaker emphasizes the importance of surrendering individual preferences and expectations to allow for transformation and liberation through meditation practice. By imitating the teacher's actions and letting go of control, we can open ourselves to a more expansive reality and receive guidance from all things, including our physical environment. This approach encourages us to relate to others as bodhisattvas and trust in the universe's support, allowing us to awaken to its transformative energy.", "themes": ["Acceptance", "Sangha"], "texts": [], "minutes": 33}, {"id": "2014-12-05 - Nomon Tim Burnett - Precious Practice", "title": "Precious Practice", "speaker": "Nomon Tim Burnett", "date": "2014-12-05", "series": "", "summary": "The speaker encourages listeners to cultivate gratitude for their ability to practice mindfulness and meditation, even when faced with challenges such as physical discomfort or mental clarity. They invite listeners to release attachment to the idea of \"doing it right\" and instead appreciate the present moment and their own body's capacity to sit and breathe. By embracing this approach, listeners can deepen their understanding of the Dharma and find a more authentic path to spiritual growth.", "themes": ["Gratitude", "Sangha"], "texts": [], "minutes": 53}, {"id": "2014-11-26 - Nomon Tim Burnett - Every Day is a Good Day", "title": "Every Day is a Good Day", "speaker": "Nomon Tim Burnett", "date": "2014-11-26", "series": "", "summary": "The talk's main teaching emphasizes the importance of cultivating gratitude as a way to transcend external circumstances and find peace in daily life. By letting go of resistance and embracing each day with an attitude of appreciation, we can shift from conflict to openness and create a sense of community. This practice is seen as a key aspect of Buddhist teachings, requiring us to confront and include difficult emotions like bitterness and despair, rather than trying to suppress them.", "themes": ["Gratitude"], "texts": ["Blue Cliff Record"], "minutes": 32}, {"id": "2014-09-24 - Kanho Chris Burkhart - Song of the Jewel Mirror Samadhi part 2", "title": "Song of the Jewel Mirror Samadhi, Part 2", "speaker": "Kanho Chris Burkhart", "date": "2014-09-24", "series": "Jewel Mirror Samadhi", "summary": "The talk's main teaching emphasizes the importance of transforming not just our negative emotions and attachments, but their root causes as well. This requires a holistic approach that combines study, meditation, and guidance from a teacher, as well as letting go of ego-driven attitudes. Ultimately, true transformation leads to an experience of enlightenment that arises from our practice, embracing both the relative and absolute aspects of reality.", "themes": ["Buddha-nature", "Wisdom"], "texts": [], "minutes": 30}, {"id": "2014-09-05 - Kanho Chris Burkhart - Song of the Jewel Mirror Samadhi part 1", "title": "Song of the Jewel Mirror Samadhi, Part 1", "speaker": "Kanho Chris Burkhart", "date": "2014-09-05", "series": "Jewel Mirror Samadhi", "summary": "The talk centered on the concept of suchness, which refers to reality beyond concepts and phenomena, and how it relates to everyday experience. The poem \"Chul Mir Samadhi\" describes this state, where enlightenment is not something separate from our daily life but rather a natural awareness that reveals interconnectedness and interdependence. This understanding encourages us to let go of preconceptions and see ourselves as part of the world around us, allowing our true nature to shine through without attachment or obstruction.", "themes": ["Buddha-nature", "Interconnection"], "texts": [], "minutes": 31}, {"id": "2014-08-27 - Nomon Tim Burnett - Metta Sutta Part 4 The Teachings on Loving Kindness", "title": "Metta Sutta, Part 4: The Teachings on Loving Kindness", "speaker": "Nomon Tim Burnett", "date": "2014-08-27", "series": "Metta Sutta", "summary": "The speaker reflects on their experience practicing loving-kindness meditation through the Heart Sutra, highlighting the importance of recognizing and releasing conditional thinking that can lead to unconditioned positive emotions towards ourselves and others. They emphasize the interconnectedness of four paramita practices - metta, mudita, compassion, and equanimity - and the need to cultivate balance and resilience in our emotional responses. By letting go of our own conditioning and limitations, we can awaken to a more authentic and compassionate practice of loving-kindness that sees all beings as whole and worthy of love and support.", "themes": ["Compassion", "Ethics"], "texts": ["Heart Sutra", "Metta Sutta"], "minutes": 40}, {"id": "2014-08-23 - Nomon Tim Burnett - Heart Sutra 7 San Miguel de Allende", "title": "Heart Sutra 7 San Miguel de Allende", "speaker": "Nomon Tim Burnett", "date": "2014-08-23", "series": "", "summary": "The talk's main teaching encourages mindfulness and awareness to avoid creating unnecessary separations and divisions in ourselves and others by recognizing how language and categorization can distort our view of reality. Our minds often make assumptions about others and ourselves, leading to miscommunications and misunderstandings, but this understanding is not meant to be rigid or dogmatic, rather a flexible approach to wisdom that allows us to cultivate curiosity, openness, and non-attachment. By embracing simplicity and mystery, we can soften our attachment to concepts and perceptions and investigate our true experience moment by moment.", "themes": ["Emptiness", "Wisdom"], "texts": ["Heart Sutra"], "minutes": 60}, {"id": "2014-08-21 - Nomon Tim Burnett - Heart Sutra 5 San Miguel de Allende", "title": "Heart Sutra 5 San Miguel de Allende", "speaker": "Nomon Tim Burnett", "date": "2014-08-21", "series": "", "summary": "The teacher's main teaching emphasizes the importance of embracing all aspects of life, including joy and pain, in order to cultivate compassion and wisdom. He encourages looking beyond ordinary knowledge and attainment by exploring emptiness and understanding that our understanding is always changing. By letting go of attachments and misconceptions about a permanent self or lasting satisfaction, we can tap into a deeper state of mind that allows us to see through mistaken views and find true freedom.", "themes": ["Compassion", "Emptiness"], "texts": ["Heart Sutra"], "minutes": 76}, {"id": "2014-08-21 - Nomon Tim Burnett - Heart Sutra 6 San Miguel de Allende", "title": "Heart Sutra 6 San Miguel de Allende", "speaker": "Nomon Tim Burnett", "date": "2014-08-21", "series": "", "summary": "The main teaching of the Soto Zen dharma talk emphasizes the importance of cultivating awareness and connection through mindfulness and meditation practices. The teacher invites listeners to explore the concept of \"going beyond\" and establishing themselves in enlightenment, using the Prajnaparamita mantra as a tool for this process. By reciting the mantra with intention and attention, individuals can deepen their understanding of themselves and others, and ultimately find a more profound sense of freedom and awakening.", "themes": ["Emptiness", "Impermanence"], "texts": ["Heart Sutra"], "minutes": 59}, {"id": "2014-08-20 - Nomon Tim Burnett - Heart Sutra 3 San Miguel de Allende", "title": "Heart Sutra 3 San Miguel de Allende", "speaker": "Nomon Tim Burnett", "date": "2014-08-20", "series": "", "summary": "The speaker's main teaching is that our preconceptions and assumptions can create suffering by limiting our understanding of reality, but by letting go of these mental constructs, we can develop a more nuanced awareness of the world around us. This involves observing experiences without judgment or labeling, allowing us to see things as they truly are, rather than through the lens of our own thoughts and emotions. By doing so, we can find freedom from pain and suffering, and cultivate a deeper understanding of the interconnectedness of all things.", "themes": ["Emptiness", "Suffering"], "texts": ["Heart Sutra"], "minutes": 92}, {"id": "2014-08-20 - Nomon Tim Burnett - Heart Sutra 4 San Miguel de Allende", "title": "Heart Sutra 4 San Miguel de Allende", "speaker": "Nomon Tim Burnett", "date": "2014-08-20", "series": "", "summary": "Here is a summary of the Soto Zen dharma talk in 4-6 sentences:\n\nOur bodies are not isolated entities, but complex ecosystems that rely on trillions of microorganisms to function properly. This realization challenges our traditional notions of self and encourages us to reevaluate our place within the world. By acknowledging the interconnectedness of all living beings, we can begin to let go of our attachment to external sources of happiness and fulfillment. This shift in perspective allows us to cultivate a deeper understanding of ourselves and others, and to approach life with greater compassion and awareness.", "themes": ["Emptiness", "Impermanence", "Interconnection"], "texts": ["Heart Sutra"], "minutes": 85}, {"id": "2014-08-19 - Nomon Tim Burnett - Heart Sutra 1 San Miguel de Allende", "title": "Heart Sutra 1 San Miguel de Allende", "speaker": "Nomon Tim Burnett", "date": "2014-08-19", "series": "", "summary": "The main teaching of this Soto Zen dharma talk is that true understanding and wisdom come from looking beyond superficial assumptions about reality. The Heart Sutra, a key Buddhist text, encourages us to question our conventional views and seek deeper insight by exploring the nature of emptiness and non-duality. By embracing this approach, we can cultivate a more profound and nuanced understanding of the world and ourselves.", "themes": ["Wisdom"], "texts": ["Heart Sutra"], "minutes": 51}, {"id": "2014-08-19 - Nomon Tim Burnett - Heart Sutra 2 San Miguel de Allende", "title": "Heart Sutra 2 San Miguel de Allende", "speaker": "Nomon Tim Burnett", "date": "2014-08-19", "series": "", "summary": "The talk's main teaching is that our capacity for giving and making a positive impact in the world is often limited by our own self-doubt and lack of faith in ourselves. By cultivating awareness of our thoughts and feelings, we can discover a sense of responsibility and compassion that allows us to be present and offer love and support to others. This realization is not about grand actions or gestures, but rather about being fully engaged with the people around us, listening deeply, and offering wisdom and kindness from a place of inner peace.", "themes": ["Compassion", "Emptiness"], "texts": ["Heart Sutra"], "minutes": 26}, {"id": "2014-07-30 - Nomon Tim Burnett - Metta Sutta Part 3 The Teachings on Loving Kindness", "title": "Metta Sutta, Part 3: The Teachings on Loving Kindness", "speaker": "Nomon Tim Burnett", "date": "2014-07-30", "series": "Metta Sutta", "summary": "The talk's main teaching emphasizes the importance of recognizing and challenging our own conditioning, particularly when it comes to cultivating loving-kindness meditation. The speaker suggests that we often create conditions for ourselves to feel a certain way, only to find fault with others who fail to meet those expectations. By acknowledging and letting go of our own conditioning, we can develop a more authentic and compassionate practice of metta, or unconditional loving-kindness.", "themes": ["Compassion"], "texts": ["Metta Sutta"], "minutes": 37}, {"id": "2014-07-15 - Nomon Tim Burnett - Metta Sutta Part 2 The Teachings on Loving Kindness", "title": "Metta Sutta, Part 2: The Teachings on Loving Kindness", "speaker": "Nomon Tim Burnett", "date": "2014-07-15", "series": "Metta Sutta", "summary": "The teacher will explore the Metta-sutta, a Buddhist text on loving kindness, by comparing two translations that emphasize different qualities: moral virtues in one translation and wisdom, sincerity, and strength in another. The goal is to understand how these approaches shape our understanding of loving kindness and its practice. By examining the differences between the two translations, the teacher aims to deepen listeners' comprehension of this important Buddhist teaching.", "themes": ["Compassion", "Ethics"], "texts": ["Metta Sutta"], "minutes": 41}, {"id": "2014-07-09 - Nomon Tim Burnett - Metta Sutta Part 1 The Teachings on Loving Kindness", "title": "Metta Sutta, Part 1: The Teachings on Loving Kindness", "speaker": "Nomon Tim Burnett", "date": "2014-07-09", "series": "Metta Sutta", "summary": "The speaker's talk emphasizes the importance of cultivating unconditional love and compassion in our relationships with others, which can be developed through a meditation practice known as Metta Sutta. This practice involves imagining and offering good wishes to individuals we have positive feelings towards, those we are neutral about, and even those we struggle with, without condition or attachment. By doing so, we can develop a deeper understanding of the interconnectedness and interdependence that underlies all relationships, and cultivate a sense of kindness and compassion for ourselves as well.", "themes": ["Compassion"], "texts": ["Metta Sutta"], "minutes": 38}, {"id": "2014-06-15 - Shinmon Michael Newton - On Hongshi", "title": "On Hongshi", "speaker": "Shinmon Michael Newton", "date": "2014-06-15", "series": "", "summary": "The speaker encourages listeners to approach their experiences with a sense of care and attention, rather than judgment or resistance, by looking at afflictive states like anger and sadness not as obstacles to be overcome, but as opportunities for transformation and growth. This involves cultivating a sense of openness and awareness that allows us to penetrate through conditioning and simply be present with whatever arises, without attachment or aversion. By doing so, we can come to see life and death in their true nature and respond to the world with compassion and clarity.", "themes": ["Acceptance", "Gratitude"], "texts": [], "minutes": 41}, {"id": "2014-06-14 - Nomon Tim Burnett - No Distractions", "title": "No Distractions", "speaker": "Nomon Tim Burnett", "date": "2014-06-14", "series": "", "summary": "The talk's main teaching is that true awakening comes from letting go of our preconceptions and expectations, allowing us to simply be present in each moment. By doing so, we can find peace and simplicity, and experience a sense of gratitude and humility. This requires acknowledging and accepting all states of mind, including those that may feel uncomfortable or difficult, rather than trying to escape or avoid them.", "themes": ["Acceptance"], "texts": [], "minutes": 48}, {"id": "2014-06-11 - Nomon Tim Burnett - No Aims", "title": "No Aims", "speaker": "Nomon Tim Burnett", "date": "2014-06-11", "series": "", "summary": "The speaker invites us to consider a broader path of practice that encompasses all aspects of life, rather than just focusing on specific techniques or goals. They suggest exploring the \"three doors of liberation\" - emptiness, signlessness, and aimlessness - which involve letting go of attachments to thoughts, labels, and outcomes. By embracing these doors, we can cultivate a deeper understanding of reality and find comfort in the present moment, rather than striving for a specific destination or goal.", "themes": ["Acceptance", "Emptiness"], "texts": [], "minutes": 32}, {"id": "2014-05-28 - Heigaku Talus Latona - Sandokai Part 4", "title": "Sandokai Part 4", "speaker": "Heigaku Talus Latona", "date": "2014-05-28", "series": "Sandokai", "summary": "The talk explores the concept of two incompatible truths, often referred to as phenomenal and numinal perspectives, which are both accurate but cannot be simultaneously true. The phenomenal perspective views the world through our individual experiences and perceptions, while the numinal perspective sees reality as a unified whole that includes all distinctions. The talk suggests that understanding and embracing this paradox is crucial for liberation from suffering, but it also requires letting go of attachment to understanding and instead practicing mindfulness and awareness in every moment, allowing us to see the world with clarity and freedom.", "themes": ["Emptiness", "Interconnection"], "texts": ["Shōbōgenzō"], "minutes": 15}, {"id": "2014-05-21 - Shuko Edie Norton - Sandokai Part 3", "title": "Sandokai Part 3", "speaker": "Shuko Edie Norton", "date": "2014-05-21", "series": "Sandokai", "summary": "The talk's main teaching emphasizes the importance of embracing both our individual uniqueness and our interconnectedness with others. It suggests that we should find a sense of harmony by recognizing how each person has their own unique role or \"show\" in life, while also acknowledging our connection to the larger community. By reconciling these two aspects, we can cultivate a deeper understanding of ourselves and our place in the world, ultimately finding unity and balance in our daily lives.", "themes": ["Emptiness", "Interconnection", "Sangha"], "texts": [], "minutes": 21}, {"id": "2014-05-07 - Seishu John Wiley - Sandokai Part 2", "title": "Sandokai Part 2", "speaker": "Seishu John Wiley", "date": "2014-05-07", "series": "Sandokai", "summary": "The talk's main teaching is that everything in life is interconnected and interdependent, and that our individual experiences and perceptions are not separate from the world around us. This idea, known as \"merging of difference and unity,\" suggests that distinctions between things like light and dark, self and other, are ultimately illusory and that we are all part of a larger web of relationships. By recognizing this interconnectedness, we can cultivate greater gratitude and appreciation for the many sources of joy and enrichment in our lives, rather than getting caught up in negative thoughts or complaints.", "themes": ["Gratitude", "Interconnection"], "texts": ["Heart Sutra"], "minutes": 15}, {"id": "2014-04-30 - Nomon Tim Burnett - Joan Memorial", "title": "Joan Memorial", "speaker": "Nomon Tim Burnett", "date": "2014-04-30", "series": "", "summary": "In this Soto Zen dharma talk, the speaker shares personal stories about their family members' experiences with illness and loss, highlighting the importance of being present with loved ones in the end stages of life. They reflect on how these experiences have taught them that life is precious and fleeting, and that relationships with others are essential to our well-being. The speaker encourages listeners to cultivate forgiveness, understanding, and appreciation for those who help us, while also finding hope and positivity in the midst of grief and loss.", "themes": ["Compassion", "Gratitude", "Impermanence"], "texts": [], "minutes": 25}, {"id": "2014-04-30 - Nomon Tim Burnett - Sandokai Part 1", "title": "Sandokai Part 1", "speaker": "Nomon Tim Burnett", "date": "2014-04-30", "series": "Sandokai", "summary": "The speaker's main teaching emphasizes that separation and unity are not opposing forces, but complementary aspects of reality. Rather than trying to choose one over the other, we can learn to hold both perspectives simultaneously, allowing us to approach life with a sense of wonder and curiosity. By embracing this paradoxical nature of existence, we can cultivate greater awareness, acceptance, and compassion in our daily lives, ultimately leading to a deeper understanding of ourselves and the world around us.", "themes": ["Interconnection", "Suffering"], "texts": [], "minutes": 29}, {"id": "2014-04-23 - Heigaku Talus Latona - Dai Hi Shin Dharani", "title": "Dai Hi Shin Dharani", "speaker": "Heigaku Talus Latona", "date": "2014-04-23", "series": "Chant Book", "summary": "The speaker's main teaching emphasizes that true understanding and liberation come not from intellectual comprehension of spiritual concepts, but rather from direct experience and awareness. Through meditation and practice, we can cultivate a deeper connection to the present moment, allowing us to transcend our individual boundaries and limitations. This is where \"Buddhas\" or enlightened beings appear in life, guiding us towards a more profound sense of unity and understanding.", "themes": ["Compassion"], "texts": [], "minutes": 26}, {"id": "2014-04-19 - Nomon Tim Burnett - Heart Sutra Part 2", "title": "Heart Sutra Part 2", "speaker": "Nomon Tim Burnett", "date": "2014-04-19", "series": "Heart Sutra", "summary": "The speaker shares a personal experience of feeling uncertain about attending a ritual, but ultimately realizes it was because they are a Dharma teacher, highlighting the importance of self-awareness in our spiritual practice. They discuss the Heart Sutra's teachings on emptiness and dependent origination, which reveal that nothing is fixed and everything is interconnected, leading to freedom from suffering by understanding the nature of reality. This understanding encourages us to see beyond our perceptions and judgments, recognizing that they are often based on incomplete information, and instead cultivates flexibility, resilience, and liberation.", "themes": ["Emptiness", "Interconnection"], "texts": ["Heart Sutra"], "minutes": 35}, {"id": "2014-04-16 - Nomon Tim Burnett - Heart Sutra Part 1", "title": "Heart Sutra Part 1", "speaker": "Nomon Tim Burnett", "date": "2014-04-16", "series": "Heart Sutra", "summary": "The speaker's talk highlights the importance of understanding the concept of \"emptiness\" in Soto Zen Buddhism, which refers to the idea that our expectations and ideas about reality are often unrealistic and lack inherent existence. This understanding can lead to a sense of liberation from attachments and expectations, allowing us to approach life with a more open and accepting mindset. By embracing the way things are exactly as they are, we can find freedom from suffering and cultivate a deeper appreciation for the present moment.", "themes": ["Emptiness"], "texts": ["Heart Sutra"], "minutes": 34}, {"id": "2014-04-02 - Shuko Edie Norton - Communication", "title": "Communication", "speaker": "Shuko Edie Norton", "date": "2014-04-02", "series": "", "summary": "Shuko Edie Norton emphasizes the importance of letting go of preconceptions and expectations when interacting with others in relationships, particularly in a community setting like the monastery. This \"not knowing\" allows us to approach others without judgment or attachment, creating space for authentic connection and intimacy. By embracing generosity, radical respect, and self-awareness, we can overcome our negative judgments and cultivate deeper connections with those around us, ultimately promoting well-being for all involved.", "themes": ["Compassion", "Ethics", "Sangha"], "texts": [], "minutes": 25}, {"id": "2014-03-08 - Kanho Chris Burkhart - Zen Marketplace", "title": "Zen Marketplace", "speaker": "Kanho Chris Burkhart", "date": "2014-03-08", "series": "", "summary": "The talk highlights the importance of cultivating virtues such as generosity, moral discipline, and loving-kindness, which are central to the Buddha's teaching, rather than chasing after fleeting happiness through consumerism and material possessions. The speaker suggests that true freedom and meaning can be found in radical presence and tending to suffering, rather than seeking external sources of fulfillment. By embracing this path, one can discover an implicit sense of enlightenment that is present in everyday activities, rather than waiting for some future state of being.", "themes": ["Interconnection", "Suffering"], "texts": [], "minutes": 28}, {"id": "2014-03-08 - Zoketsu Norman Fischer - No Teachers of Zen", "title": "No Teachers of Zen", "speaker": "Zoketsu Norman Fischer", "date": "2014-03-08", "series": "", "summary": "The main teaching of the Soto Zen dharma talk emphasizes the importance of self-compassion and embracing uncertainty in spiritual practice. It encourages individuals to take responsibility for their own growth and development, while also recognizing the value of guidance from a qualified teacher who embodies the principles of the tradition through their daily life and example. By letting go of ego and judgment, one can cultivate patience, forgiveness, and compassion, ultimately awakening the inherent goodness in themselves and others.", "themes": ["Buddha-nature", "Sangha", "Vulnerability"], "texts": [], "minutes": 51}, {"id": "2014-03-07 - Nomon Tim Burnett - Two Sides of Zen", "title": "Two Sides of Zen", "speaker": "Nomon Tim Burnett", "date": "2014-03-07", "series": "", "summary": "The speaker invites everyone to cultivate a radical acceptance of themselves, including difficult emotions and thoughts, by meeting each aspect with kindness and compassion rather than judgment. This requires embracing both our \"doing\" and \"non-doing\" aspects, recognizing the paradoxical nature of practice where effort and surrender are intertwined. By doing so, we can develop greater awareness and understanding of ourselves, leading to a more authentic and compassionate approach to meditation and spiritual growth.", "themes": ["Compassion", "Emptiness"], "texts": ["Heart Sutra"], "minutes": 39}, {"id": "2014-03-07 - Zoketsu Norman Fischer - On Zazen", "title": "On Zazen", "speaker": "Zoketsu Norman Fischer", "date": "2014-03-07", "series": "", "summary": "The talk's main teaching is that true freedom and fulfillment come from embracing the present moment, rather than getting caught up in past regrets or future anxieties. By letting go of our attachment to ego and self-clinging, we can cultivate a deeper sense of awareness and connection to ourselves and others, allowing us to live more authentically and find peace in the midst of life's challenges. This is made possible through the practice of zazen, which helps us quiet the mind and approach life with curiosity and openness.", "themes": ["Compassion", "Suffering"], "texts": [], "minutes": 40}, {"id": "2014-02-01 - Kanho Chris Burkhart - Wayseeking Mind", "title": "Wayseeking Mind", "speaker": "Kanho Chris Burkhart", "date": "2014-02-01", "series": "", "summary": "The speaker shares their personal journey from struggling with trauma and identity to finding peace and understanding through Zen practice. They reflect on how regular zazen practice helped them let go of goal-driven thinking and embrace a more present and spontaneous approach to life, allowing them to appreciate the beauty of uncertainty and interconnectedness. This shift in mindset has led to significant changes in their life and work, including applying Zen principles to their job as a code enforcement officer. The speaker invites the audience to consider this talk as a heartfelt but tentative expression, acknowledging that it is not a linear record of their practice or life.", "themes": ["Sangha", "Vulnerability"], "texts": ["Shōbōgenzō"], "minutes": 36}, {"id": "2014-01-25 - Kanho Chris Burkhart - Enlightening Activity Class 1", "title": "Enlightening Activity Class 1", "speaker": "Kanho Chris Burkhart", "date": "2014-01-25", "series": "", "summary": "The teacher invites students to explore the concept of \"enlightening activity\" or the Bodhisattva, which involves cultivating dynamic balance between action and stillness, encouraging mindful engagement in daily life while maintaining quietness and presence. This practice is seen as a way to transform one's perspective, letting go of attachment to outcomes and embracing compassion and intentional action. By aligning their actions with universal virtue and inter-connectedness, students can cultivate wisdom, kindness, and awareness, leading to greater fulfillment and well-being.", "themes": ["Compassion", "Social engagement"], "texts": ["Lotus Sutra"], "minutes": 90}, {"id": "2014-01-08 - Heigaku Talus Latona - Enmei Jukku Kannon Gyo", "title": "Enmei Jukku Kannon Gyo", "speaker": "Heigaku Talus Latona", "date": "2014-01-08", "series": "Chant Book", "summary": "The talk emphasizes the importance of cultivating self-compassion, particularly in Buddhism, by recognizing our own inherent suffering and imperfection. Through the story of the speaker's personal experience with Kanzeon, the Bodhisattva of Compassion, we see that embracing our vulnerabilities is a key aspect of developing compassion for ourselves. This understanding is rooted in the 10 Verses for Protecting Life Bodhisattva Sutra, which encourages us to recognize the interconnectedness of Buddha, Dharma, and Sangha as our transcending cause, leading to freedom from suffering through acceptance and purity.", "themes": ["Compassion", "Vulnerability"], "texts": ["Blue Cliff Record"], "minutes": 24}, {"id": "2013-12-18 - Yuzan Nancy Welch - Bodhisattva Vows 2", "title": "Bodhisattva Vows 2", "speaker": "Yuzan Nancy Welch", "date": "2013-12-18", "series": "Bodhisattva Vows", "summary": "The speaker shares that taking Bodhisattva vows literally can lead to feelings of inadequacy, but instead suggests cultivating awareness and intention by embracing a mindful and compassionate approach. This means recognizing the Buddha nature already present within themselves and others, rather than striving for perfection. By doing so, they encourage listeners to focus on serving others and using their energy to help them find their own path to happiness, rather than indulging in personal gain or comfort.", "themes": ["Buddha-nature", "Compassion", "Vulnerability"], "texts": [], "minutes": 15}, {"id": "2013-12-11 - Seishu John Wiley - Bodhisattva Vows 1", "title": "Bodhisattva Vows 1", "speaker": "Seishu John Wiley", "date": "2013-12-11", "series": "Bodhisattva Vows", "summary": "The speaker emphasizes that true practice involves living on the basis of reality, rather than just sitting meditation (zazen). They suggest that everyday activities like smiling at strangers, listening to others without judgment, and letting go of opinions can be examples of working with the vows of saving all beings and ending delusion. By paying attention to these practices in daily life, one can cultivate a more authentic expression of Buddha's way. This approach encourages us to embody the bodhisattva vow by extending our intentions equally to every being and place, rather than just focusing on formal meditation practice.", "themes": ["Compassion", "Ethics", "Interconnection"], "texts": ["Shōbōgenzō"], "minutes": 16}, {"id": "2013-12-07 - Eko Jeff Kelley - Rohatsu 2013", "title": "Rohatsu 2013", "speaker": "Eko Jeff Kelley", "date": "2013-12-07", "series": "", "summary": "Our sense of identity and ego can create suffering by making us feel like we need to constantly assert ourselves and compare with others. In Zazen practice, letting go of this assertion allows us to see beyond our limited selves and connect with a more fluid and multifaceted true nature. By embracing this freedom, we can become more fully present and alive, without being held back by our attachments to specific roles or personas. This means we don't have to be bound by our usual identity or role, but can instead embody different aspects of ourselves as the circumstances call for it.", "themes": ["No-self"], "texts": ["Diamond Sutra"], "minutes": 36}, {"id": "2013-12-06 - Nomon Tim Burnett - Rohatsu 2013", "title": "Rohatsu 2013", "speaker": "Nomon Tim Burnett", "date": "2013-12-06", "series": "", "summary": "The speaker shares a story about Chiyono, an illiterate servant who learned the importance of cultivating compassion from an elderly nun, illustrating that we can already embody the qualities of a Buddha in our daily lives by acting with kindness and awareness, rather than waiting for some big realization or insight. This teaching encourages us to let go of distinctions between people and simply be present with others, just as it is, finding beauty and interconnectedness in everyday activities. By embracing this approach, we can create an environment where everyone's unique contributions are valued and nurtured, ultimately leading to the unfolding of a shared enlightenment.", "themes": ["Buddha-nature", "Compassion", "Impermanence"], "texts": [], "minutes": 27}, {"id": "2013-12-04 - Nomon Tim Burnett - Three Treasures 2", "title": "Three Treasures 2", "speaker": "Nomon Tim Burnett", "date": "2013-12-04", "series": "Three Treasures", "summary": "The talk's main teaching emphasizes the importance of finding refuge in one's own embodied experience, rather than relying on external sources or concepts. This involves cultivating awareness of the present moment in the body, which can help develop a sense of connection with others and the world around us. By embracing impermanence and uncertainty, we can find true refuge not in external sources, but in our ability to be present and aware in the midst of life's challenges.", "themes": ["Sangha", "Suffering", "Vulnerability"], "texts": [], "minutes": 30}, {"id": "2013-11-27 - Reizan Bob Penny - Three Treasures 1", "title": "Three Treasures 1", "speaker": "Reizan Bob Penny", "date": "2013-11-27", "series": "Three Treasures", "summary": "The talk's main teaching emphasizes the importance of cultivating a sense of unity and interconnectedness with the world, rather than perpetuating divisions and fragmentation. By recognizing our place within the larger web of life, we can begin to let go of our individualistic concerns and find a deeper sense of belonging and refuge. This is reflected in the three refuges of Pauley, which serve as a universal ethic that underlies many other values, including environmentalism and social responsibility.", "themes": ["Ethics", "Interconnection", "Sangha"], "texts": [], "minutes": 30}, {"id": "2013-11-21 - Nomon Tim Burnett - Repentance Verse", "title": "Repentance Verse", "speaker": "Nomon Tim Burnett", "date": "2013-11-21", "series": "Chant Book", "summary": "The talk's main teaching is that true freedom and healing come from embracing our emotions, including difficult ones like guilt or anger, rather than trying to suppress or avoid them. Through a guided meditation on forgiveness, participants are encouraged to cultivate a sense of responsibility, compassion, and understanding for themselves and others, letting go of past harm and karmic conditioning without judgment. This practice aims to reveal the interconnectedness and emptiness that underlies all suffering, ultimately leading to a deeper understanding of reality and a more authentic way of being.", "themes": ["Compassion", "Emptiness", "Interconnection"], "texts": [], "minutes": 40}, {"id": "2013-11-16 - Nomon Tim Burnett - Jukai Retreat", "title": "Jukai Retreat", "speaker": "Nomon Tim Burnett", "date": "2013-11-16", "series": "", "summary": "The speaker emphasizes that true progress in Zen practice involves embracing imperfection, being willing to confront challenges, and cultivating kindness, wisdom, and gentleness. This is reflected in the ordination ceremony, which is not about achieving perfection but rather about receiving Buddhist training and empowerment as a lifelong commitment to the spiritual path. By embracing this approach, individuals can deepen their understanding of themselves and the world around them, finding comfort and guidance in the present moment despite life's challenges.", "themes": ["Ethics", "Sangha"], "texts": [], "minutes": 38}, {"id": "2013-11-13 - Heigaku Talus Latona - Dedication of Merit", "title": "Dedication of Merit", "speaker": "Heigaku Talus Latona", "date": "2013-11-13", "series": "Chant Book", "summary": "The speaker suggests that traditional notions of \"merit\" in Buddhism can be overly simplistic and may lead to a focus on accumulating good karma, rather than cultivating genuine compassion and wisdom. Instead, they propose practicing generosity and giving without expectation of reward, as taught by the Indian master Shantideva, with the intention of benefiting all sentient beings and bringing them out of suffering. This approach is rooted in the prajnaparamita teaching, which emphasizes recognizing the impermanence and interconnectedness of all phenomena, and loving the present moment as it arises.", "themes": ["Compassion", "Interconnection"], "texts": ["Lotus Sutra", "Shōbōgenzō"], "minutes": 38}, {"id": "2013-10-23 - Nomon Tim Burnett - Robe Chant", "title": "Robe Chant", "speaker": "Nomon Tim Burnett", "date": "2013-10-23", "series": "Chant Book", "summary": "The teacher emphasizes the significance of rituals in daily life, encouraging participants to pay attention to the actions they take with intention and awareness. This includes recognizing that even ordinary tasks can hold deep meaning and significance. By doing so, we can cultivate a deeper connection to ourselves, others, and the world around us, ultimately unfolding our true nature and engaging with reality in a more profound way.", "themes": ["Emptiness"], "texts": ["Heart Sutra"], "minutes": 37}, {"id": "2013-10-09 - Nomon Tim Burnett - Zen Work", "title": "Zen Work", "speaker": "Nomon Tim Burnett", "date": "2013-10-09", "series": "", "summary": "In Soto Zen Buddhism, work is seen as an essential part of spiritual practice that can bring fulfillment and dignity when approached with mindfulness and effort. By focusing on the process of work itself, rather than its outcome, individuals can cultivate a deeper appreciation for their labor and find greater joy and meaning in their daily activities. This approach involves working with awareness and attention to the present moment, letting go of extra conditions that lead to striving and dissatisfaction, and finding energy and stability in the task at hand.", "themes": ["Acceptance", "Sangha"], "texts": [], "minutes": 27}, {"id": "2013-10-06 - Nomon Tim Burnett - Prajna Paramita Retreat 3", "title": "Prajna Paramita Retreat 3", "speaker": "Nomon Tim Burnett", "date": "2013-10-06", "series": "Prajna Paramita Retreat", "summary": "Here is a summary paragraph in plain language:\n\nThe speaker emphasizes the importance of letting go of our expectations for happiness and instead cultivating an open-hearted and compassionate approach to life. This involves being vulnerable, allowing ourselves to receive love and support from others, rather than trying to control or manipulate external circumstances. By embracing this dynamic tension between conventional happiness and liberation, we can develop a deeper sense of self-love and acceptance, which in turn allows us to extend love and kindness to others.", "themes": ["Acceptance", "Compassion", "Vulnerability"], "texts": ["Diamond Sutra", "Heart Sutra"], "minutes": 44}, {"id": "2013-10-06 - Nomon Tim Burnett - Prajna Paramita Retreat 4", "title": "Prajna Paramita Retreat 4", "speaker": "Nomon Tim Burnett", "date": "2013-10-06", "series": "Prajna Paramita Retreat", "summary": "The speaker discusses how understanding Mara, or ignorance and confusion, can be a powerful tool for spiritual growth, rather than trying to eliminate it. By recognizing its actions and motivations, we can see that Mara is driven by a desire to disrupt our study and practice of wisdom, but ultimately, the power of wisdom and compassion can overcome these obstacles. This understanding allows us to approach challenges with greater clarity and compassion, leading to a deeper path to enlightenment.", "themes": ["Ethics", "Wisdom"], "texts": ["Lotus Sutra"], "minutes": 79}, {"id": "2013-10-05 - Nomon Tim Burnett - Prajna Paramita Retreat 1", "title": "Prajna Paramita Retreat 1", "speaker": "Nomon Tim Burnett", "date": "2013-10-05", "series": "Prajna Paramita Retreat", "summary": "The teacher invites participants to explore the concept of emptiness as a fundamental aspect of reality that can lead to liberation and happiness. Emptiness is not about escaping the world, but rather about developing a relationship with it and finding freedom from suffering. By studying texts like the Prajnaparamita Sutra and practicing mindfulness, participants can cultivate an understanding of emptiness that allows them to appreciate its presence in every moment.", "themes": ["Emptiness", "Suffering", "Wisdom"], "texts": ["Heart Sutra"], "minutes": 67}, {"id": "2013-10-05 - Nomon Tim Burnett - Prajna Paramita Retreat 2", "title": "Prajna Paramita Retreat 2", "speaker": "Nomon Tim Burnett", "date": "2013-10-05", "series": "Prajna Paramita Retreat", "summary": "The teacher emphasizes the importance of cultivating the six paramitas (perfections) in order to bring about awakening and benefit all beings, but notes that these are not states or destinations, but rather processes to be cultivated. This approach encourages a mindset of openness, acceptance, and letting go, allowing for a kind of \"immersion\" in the present moment where one can release attachment to thoughts and ideas and simply be. By embracing this process, one can develop perfect wisdom and find freedom from attachments and limitations.", "themes": ["Emptiness", "Wisdom"], "texts": [], "minutes": 51}, {"id": "2013-10-05 - Nomon Tim Burnett - Prajna Paramita Retreat Mantra", "title": "Prajna Paramita Retreat Mantra", "speaker": "Nomon Tim Burnett", "date": "2013-10-05", "series": "", "summary": "I couldn't find any information on a Soto Zen dharma talk that matches the provided notes. The text appears to be a repetition of a Buddhist mantra or invocation, rather than a summary of a teaching. If you could provide more context or information about the talk, I may be able to help you summarize its main teaching in plain language.", "themes": ["Wisdom"], "texts": [], "minutes": 0}, {"id": "2013-10-02 - Nomon Tim Burnett and Satya - Touching Earth Sangha", "title": "Touching Earth Sangha", "speaker": "Nomon Tim Burnett and Satya", "date": "2013-10-02", "series": "", "summary": "The talk's main teaching is that true wisdom can be cultivated by embracing uncertainty and discomfort, rather than relying on expertise or rightness. This approach involves taking on roles without a basis in personal expertise, allowing for comfort with the unknown, and finding wisdom through experiential learning and simple living. By practicing this type of wisdom, individuals can develop a deeper understanding of themselves and the world around them, leading to a more authentic and compassionate way of life.", "themes": ["Ethics", "Social engagement", "Wisdom"], "texts": [], "minutes": 37}, {"id": "2013-09-25 - Nomon Tim Burnett - Prajna Paramita 5 Friendship", "title": "Prajna Paramita 5 Friendship", "speaker": "Nomon Tim Burnett", "date": "2013-09-25", "series": "", "summary": "The speaker emphasizes the importance of cultivating good friends in our spiritual journey, particularly through the Prajna Paramita teachings. These good friends include teachers, guides, and fellow practitioners who support us on our path to wisdom and enlightenment. By embracing these supportive relationships, we can develop the qualities of generosity, patience, energy, stability, and ethical conduct that are essential for achieving liberation from suffering.", "themes": ["Acceptance", "Sangha", "Wisdom"], "texts": [], "minutes": 31}, {"id": "2013-09-18 - Nomon Tim Burnett - Prajna Paramita 4 Hymn to Prajna Paramita", "title": "Prajna Paramita 4 Hymn to Prajna Paramita", "speaker": "Nomon Tim Burnett", "date": "2013-09-18", "series": "", "summary": "The teacher's main teaching emphasizes the importance of approaching Buddhist texts with an open mind, allowing oneself to feel and experience their power without needing to fully understand every detail. This approach can help tap into the healing and transformative qualities of these texts, which often use magical and mysterious language to convey profound insights about reality. By embracing this mindset, one can begin to explore the nature of emptiness and stillness in a more direct and intuitive way.", "themes": ["Emptiness", "Wisdom"], "texts": [], "minutes": 37}, {"id": "2013-09-11 - Nomon Tim Burnett - Prajna Paramita 3 Emptiness", "title": "Prajna Paramita 3 Emptiness", "speaker": "Nomon Tim Burnett", "date": "2013-09-11", "series": "", "summary": "The teacher emphasizes the importance of embracing our unique roles and responsibilities within the community, acknowledging that even seemingly minor actions contribute to the overall well-being of the group. This understanding is rooted in the concept of \"no self\" or \"emptiness,\" which challenges our conventional notions of a stable and abiding identity. By recognizing reality as inherently interconnected and impermanent, we can approach life with greater clarity and freedom from conceptual frameworks.", "themes": ["Emptiness", "No-self", "Wisdom"], "texts": [], "minutes": 43}, {"id": "2013-09-03 - Nomon Tim Burnett - Prajna Paramita 2 Vedana", "title": "Prajna Paramita 2 Vedana", "speaker": "Nomon Tim Burnett", "date": "2013-09-03", "series": "", "summary": "The talk's main teaching emphasizes that our habitual tendency to label experiences as good or bad can be a powerful tool for self-awareness and liberation. By recognizing this pattern, we can begin to see reality in a more nuanced way, beyond our usual notions of right and wrong. This understanding is rooted in the concept of Prajnaparamita, which suggests that there may be more to existence than our ordinary perceptions, and invites us to explore this idea further.", "themes": ["Suffering", "Wisdom"], "texts": ["Diamond Sutra"], "minutes": 31}, {"id": "2013-08-28 - Nomon Tim Burnett - Prajna Paramita 1 Three Marks", "title": "Prajna Paramita 1 Three Marks", "speaker": "Nomon Tim Burnett", "date": "2013-08-28", "series": "", "summary": "The speaker's main teaching from the Soto Zen dharma talk emphasizes the importance of transcending limited thinking and dualism in order to achieve a deeper understanding of reality. By studying the three marks of reality - impermanence, dissatisfaction, and no-self - we can become more accepting and comfortable with the interconnectedness of experience, leading to a wisdom that supports practices like selflessness and acceptance of change. This approach encourages us to look beyond surface-level explanations and explore the underlying complexities of our thoughts and emotions, ultimately cultivating true wisdom and self-awareness.", "themes": ["Impermanence", "No-self", "Suffering", "Wisdom"], "texts": ["Heart Sutra"], "minutes": 33}, {"id": "2013-06-25 - Nomon Tim Burnett - Dongshan Suchness", "title": "Dongshan Suchness", "speaker": "Nomon Tim Burnett", "date": "2013-06-25", "series": "", "summary": "The talk explores the idea that true understanding and freedom from suffering can't be found through words or explanations, but rather by looking within ourselves and embracing uncertainty. A story about Dongshan suggests that true freedom lies not in avoiding difficulties, but in understanding their nature, which is not separate from our own fundamental self. By examining our thoughts and perceptions, we can find contentment in the present moment and directly encounter reality, rather than trying to escape or avoid it.", "themes": ["Acceptance"], "texts": [], "minutes": 36}, {"id": "2013-06-12 - Nomon Tim Burnett - Precepts as Inner Work", "title": "Precepts as Inner Work", "speaker": "Nomon Tim Burnett", "date": "2013-06-12", "series": "", "summary": "The speaker's main teaching is that ordination as a priest is not about achieving spiritual accomplishment, but rather a commitment to practice humility, help others, and see everyone as Buddha. By embracing this mindset, we take responsibility for our own minds and efforts, letting go of the need to control or change everything. This approach allows us to cultivate mindfulness, curiosity, and playfulness in our daily lives, softening our patterns of mind and recognizing the interconnectedness of all things.", "themes": ["Ethics", "No-self", "Wisdom"], "texts": ["Heart Sutra"], "minutes": 33}, {"id": "2013-05-29 - Reizan Bob Penny - Three Treasures", "title": "Three Treasures", "speaker": "Reizan Bob Penny", "date": "2013-05-29", "series": "", "summary": "The speaker's talk highlights the importance of not defaming or diminishing the Buddha, Dharma, and Sangha in our lives, a precept often misunderstood as simply avoiding criticism of these concepts. Instead, it's about cultivating a genuine understanding of what it means to take refuge in them and developing an authentic practice that allows us to see their true nature within ourselves. By letting go of cynicism and doubt, we can deepen our connection with the Buddhist teachings and open ourselves up to the present moment, embracing the world as it is without trying to fit everything into a set of teachings.", "themes": ["Buddha-nature", "Ethics", "Sangha"], "texts": [], "minutes": 20}, {"id": "2013-05-23 - Seishu John Wiley - Intoxicants", "title": "Intoxicants", "speaker": "Seishu John Wiley", "date": "2013-05-23", "series": "", "summary": "The speaker emphasizes the importance of cultivating patience, kindness, and awareness in the face of discomfort, rather than reacting to it with substances or distractions. By practicing being upright through generosity, precept, meditation, and other spiritual practices, we can develop the wisdom to navigate difficult emotions and situations without resorting to escape mechanisms. This approach allows us to find relief from anxiety and discomfort through mindfulness and compassion, rather than relying on external solutions.", "themes": ["Acceptance", "Ethics"], "texts": [], "minutes": 17}, {"id": "2013-05-08 - Shuko Edie Norton - Not Anger", "title": "Not Anger", "speaker": "Shuko Edie Norton", "date": "2013-05-08", "series": "", "summary": "The main teaching of the Soto Zen dharma talk is that anger is a natural human emotion that can be transformed through self-investigation and awareness, rather than suppressed or acted upon impulsively. By studying our own body and thoughts when anger arises, we can uncover the underlying emotions driving it, such as fear or shame, and learn to express it in healthier ways. This process allows us to develop greater control over our reactions and find peace even when we make mistakes with anger.", "themes": ["Ethics", "No-self", "Vulnerability"], "texts": [], "minutes": 23}, {"id": "2013-05-01 - Nomon Tim Burnett - Not Misusing Sex", "title": "Not Misusing Sex", "speaker": "Nomon Tim Burnett", "date": "2013-05-01", "series": "", "summary": "The talk's main teaching emphasizes the importance of embracing one's full humanity, including all emotions and experiences, as a path to spiritual growth and understanding. This involves letting go of resistance and expectation, and instead cultivating a sense of community and mutual support that allows us to connect with others on a deeper level. By exploring traditional Buddhist teachings in a way that is authentic and inclusive, we can gain a more nuanced understanding of ourselves and the world around us, and find alignment with our own unique energies and perspectives.", "themes": ["Ethics", "Suffering", "Vulnerability"], "texts": [], "minutes": 34}, {"id": "2013-04-24 - Yuzan Nancy Welch - Right Speech Precepts", "title": "Right Speech Precepts", "speaker": "Yuzan Nancy Welch", "date": "2013-04-24", "series": "", "summary": "The talk emphasizes the importance of honest speech as a key aspect of Buddhist practice, encouraging listeners to cultivate truthful communication that promotes connection and intimacy with others. By avoiding lies, gossip, and slander, we can break free from harm and create a more harmonious community. This involves cultivating mindfulness in our speech, being willing to listen without defensiveness, and considering the impact of our words on ourselves and others before speaking.", "themes": ["Ethics", "Interconnection"], "texts": [], "minutes": 29}, {"id": "2013-04-17 - Nomon Tim Burnett - Precepts Generosity", "title": "Precepts Generosity", "speaker": "Nomon Tim Burnett", "date": "2013-04-17", "series": "", "summary": "The speaker shares a powerful experience at a green funeral, highlighting the importance of practices like environmental burial as expressions of love and generosity. This experience sets the stage for exploring the eighth precept, \"not stingy\" or generous, which originally referred to generosity with temple assets but has been expanded to encompass broader aspects of life, including financial giving and protecting others from harm. The talk encourages embracing fluidity and openness in one's practice, recognizing both relative and absolute aspects of the precepts, and seeking liberation through greater understanding and awareness.", "themes": ["Emptiness", "Ethics"], "texts": [], "minutes": 34}, {"id": "2013-04-10 - Heigaku Talus Latona - The Practice of Generosity", "title": "The Practice of Generosity", "speaker": "Heigaku Talus Latona", "date": "2013-04-10", "series": "", "summary": "The talk explores the concept of \"not killing\" as one of the five hindrances in Buddhism, highlighting how our actions and thoughts can be forms of harm, even if they seem minor or unintentional. It emphasizes the importance of acknowledging and addressing harmful tendencies through mindfulness and compassion, rather than just avoiding overt violence. By cultivating a deeper understanding of interconnectedness and acting with kindness and wisdom, we can transform our daily choices into expressions of compassion and non-harm, ultimately leading to spiritual growth and enlightenment.", "themes": ["Compassion", "Ethics", "Social engagement"], "texts": ["Heart Sutra"], "minutes": 32}, {"id": "2013-04-03 - Nomon Tim Burnett - Precepts Intro", "title": "Precepts Intro", "speaker": "Nomon Tim Burnett", "date": "2013-04-03", "series": "", "summary": "The precepts in Soto Zen are not meant to be a rigid set of rules, but rather a guiding framework for living a compassionate and mindful life that supports spiritual growth. Developed from the Tendai school's adoption of Chinese Bodhisattva precepts, these 16 guidelines emphasize connection, humility, and generosity, encouraging practitioners to honor their ancestors and cultivate a sense of community and social responsibility. By embracing this approach, Soto Zen practitioners aim to embody the principles of compassion and wisdom in all aspects of life.", "themes": ["Ethics"], "texts": [], "minutes": 35}, {"id": "2013-03-20 - Nomon Tim Burnett - Equanimity", "title": "Equanimity", "speaker": "Nomon Tim Burnett", "date": "2013-03-20", "series": "", "summary": "The main teaching of the Soto Zen dharma talk emphasizes the importance of integrating different aspects of practice to cultivate true awakening. This involves exploring various qualities of mind, such as mindfulness, discernment, energy, joy, calm, concentration, and wisdom, which are not something that can be forced or achieved, but rather involve a dynamic process of inclining the mind towards awareness, acceptance, and accuracy. By working with attention and cultivating these qualities, individuals can develop a more accurate understanding of themselves and the world around them, leading to greater stability, calmness, and presence in life.", "themes": ["Acceptance"], "texts": ["Shōbōgenzō"], "minutes": 37}, {"id": "2013-03-13 - Nomon Tim Burnett - 7 Factors 6 Samadhi", "title": "7 Factors 6 Samadhi", "speaker": "Nomon Tim Burnett", "date": "2013-03-13", "series": "Seven Factors of Awakening", "summary": "The talk's main teaching emphasizes the importance of stability and adaptability in Zen practice, highlighting mindfulness as a pivot point that allows for flexibility and openness. Rather than focusing on concentration or achieving a specific state, the goal is to cultivate a stable and aware mind that can accommodate various experiences and emotions. This approach encourages practitioners to look inward and understand their own minds, rather than seeking answers outside themselves, in order to develop wisdom and compassion.", "themes": ["Wisdom"], "texts": ["Gateless Barrier", "Platform Sutra"], "minutes": 28}, {"id": "2013-03-02 - Nomon Tim Burnett - Calm and Permission", "title": "Calm and Permission", "speaker": "Nomon Tim Burnett", "date": "2013-03-02", "series": "", "summary": "The speaker's main teaching is that our perception of reality is often limited by our habitual patterns of attention and blind spots, which can lead to missed opportunities for understanding and connection. By becoming aware of these limitations and cultivating mindfulness, we can develop a more open and non-judgmental awareness, allowing us to find ease and liberation from suffering. This involves embracing both the aspects of our nature that may seem contradictory, such as karmic beings and bodhisattvas, rather than trying to reject or accept one over the other.", "themes": ["Acceptance", "Ethics"], "texts": [], "minutes": 47}, {"id": "2013-03-02 - Zoketsu Norman Fischer - Living in Vow 2", "title": "Living in Vow 2", "speaker": "Zoketsu Norman Fischer", "date": "2013-03-02", "series": "Living in Vow", "summary": "The speaker shares their experience working on a course at Google that aimed to bring mindfulness meditation to engineers, highlighting the enthusiasm and dedication of individuals like Meng who are passionate about promoting meditation in the workplace. This experience has led them to reflect on the significance of Buddhist teachings, particularly the concept of liberation and emptiness, which they see as a powerful reminder of our interconnectedness with others and the world around us. Through their own practice and experiences, they have come to understand that true fulfillment and happiness can only be found by embracing our limitations and humbly surrendering ourselves to spiritual growth.", "themes": ["Emptiness", "Interconnection"], "texts": [], "minutes": 53}, {"id": "2013-03-01 - Heigaku Talus Latona - Courage and Blind Spots", "title": "Courage and Blind Spots", "speaker": "Heigaku Talus Latona", "date": "2013-03-01", "series": "", "summary": "The talk explores how recognizing and understanding our own \"blind spots\" - both physical and conceptual - can lead to greater compassion and wisdom in our lives. By embracing the idea that all phenomena are empty of inherent existence, we can develop a more open and non-judgmental mind, allowing us to see things as they truly are rather than through our preconceptions. This understanding is closely tied to cultivating bodhicitta, or awakened heart, which involves a selfless desire for all beings to be happy and free from suffering.", "themes": ["Emptiness", "Vulnerability", "Wisdom"], "texts": ["Heart Sutra"], "minutes": 34}, {"id": "2013-03-01 - Zoketsu Norman Fischer - Living in Vow 1", "title": "Living in Vow 1", "speaker": "Zoketsu Norman Fischer", "date": "2013-03-01", "series": "Living in Vow", "summary": "The talk's main teaching emphasizes the importance of clarity, compassion, and accountability in Buddhist communities, particularly when it comes to addressing issues of abuse and harm. The speaker encourages the community to examine their own practices and teachings, acknowledging both the positive and negative aspects of Buddhism, and to work towards reformulation and reform. Ultimately, the talk highlights the value of dedication, devotion, and humility in spiritual practice, particularly through the practice of Zazen (meditation), which is rooted in the Bodhisattva's vow to help all beings.", "themes": ["Ethics", "Sangha", "Suffering"], "texts": [], "minutes": 52}, {"id": "2013-02-18 - Heigaku Talus Latona - Courage 4 Zongchi", "title": "Courage 4 Zongchi", "speaker": "Heigaku Talus Latona", "date": "2013-02-18", "series": "Courage", "summary": "The talk highlights the importance of direct experience and personal understanding in achieving true insight into reality. Rather than relying on external authority or intellectual understanding, Bodhidharma's approach encourages students to explore their own nature and see the Buddha within themselves. This involves embracing the present moment with courage and openness, allowing for a direct and unmediated experience of reality that transcends conceptual thinking.", "themes": ["Impermanence"], "texts": [], "minutes": 21}, {"id": "2013-02-16 - Heigaku Talus Latona - Blindspots 3 Vimalakirti", "title": "Blindspots 3 Vimalakirti", "speaker": "Heigaku Talus Latona", "date": "2013-02-16", "series": "Blindspots", "summary": "The main teaching of the Vimalakirti Sutra emphasizes recognizing non-duality, where everything is interconnected and not separate from each other, challenging traditional notions of distinctions between self and others, subject and object. This understanding encourages embracing imperfection and impermanence, rather than striving for a fixed or purified state. By letting go of dualities, we can cultivate greater awareness and acceptance of our experiences, including the complexities of emotions like pain and joy that arise within us.", "themes": ["Acceptance", "Interconnection"], "texts": [], "minutes": 16}, {"id": "2013-02-11 - Heigaku Talus Latona - Courage 3 Heart Sutra", "title": "Courage 3 Heart Sutra", "speaker": "Heigaku Talus Latona", "date": "2013-02-11", "series": "Courage", "summary": "The talk's main teaching emphasizes the importance of embracing emptiness and impermanence in all aspects of life, including our perceptions, thoughts, and emotions. It suggests that even when we think we've achieved a clear understanding of reality, there is still room for uncertainty and sand in the eye, reminding us to approach life with compassion, openness, and curiosity. By studying the concept of emptiness through koans like the Heart Sutra, we can develop courage, wisdom, and a deeper understanding of our interconnectedness with all beings, ultimately leading to a more authentic and liberated way of living.", "themes": ["Emptiness", "Wisdom"], "texts": ["Heart Sutra"], "minutes": 16}, {"id": "2013-02-09 - Heigaku Talus Latona - Blindspots 2 Bodhicitta", "title": "Blindspots 2 Bodhicitta", "speaker": "Heigaku Talus Latona", "date": "2013-02-09", "series": "Blindspots", "summary": "The speaker's main teaching emphasizes the importance of cultivating bodhicitta, or an awakened heart that desires the happiness of all beings, as a foundation for spiritual practice and liberation from suffering. By developing this desire through practices such as loving kindness and meditation, individuals can begin to see beyond their own blind spots and recognize the interconnectedness of all things. This shift in perspective allows us to approach life with a more open and compassionate heart, recognizing that our actions have consequences not just for ourselves, but for others and the world around us.", "themes": ["Buddha-nature", "Compassion", "Interconnection"], "texts": [], "minutes": 24}, {"id": "2013-02-04 - Heigaku Talus Latona - Courage Week 2 Equanimity", "title": "Courage Week 2 Equanimity", "speaker": "Heigaku Talus Latona", "date": "2013-02-04", "series": "Courage", "summary": "The talk explores the concept of equanimity, a key Buddhist teaching that refers to balance and composure in the face of challenges. It's not about ignoring or suppressing emotions, but rather about being fully present and attentive to what's happening, even when we're experiencing difficult feelings like grief. Equanimity is not something we achieve overnight, but rather it arises through consistent practice and mindfulness. By cultivating equanimity, we can develop the courage to ride the waves of life without getting overwhelmed or losing our sense of self, and we can respond with compassion and loving-kindness towards ourselves and others.", "themes": ["Acceptance", "Compassion", "Suffering"], "texts": [], "minutes": 10}, {"id": "2013-01-28 - Heigaku Talus Latona - Courage Week 1 Part 1", "title": "Courage Week 1 Part 1", "speaker": "Heigaku Talus Latona", "date": "2013-01-28", "series": "Courage", "summary": "The speaker's talk highlights the importance of recognizing and embracing differences between men and women, rather than assuming absolute distinctions based on cultural norms or power structures. By acknowledging that these differences are shaped by environment and social conditioning, we can move beyond simplistic categorizations and cultivate a more nuanced understanding of individual strengths and weaknesses. This approach allows us to appreciate the unique qualities of each person, rather than trying to fit them into predetermined roles or expectations.", "themes": ["Social engagement"], "texts": [], "minutes": 17}, {"id": "2013-01-28 - Heigaku Talus Latona - Courage Week 1 Part 2", "title": "Courage Week 1 Part 2", "speaker": "Heigaku Talus Latona", "date": "2013-01-28", "series": "Courage", "summary": "In this exercise, participants are invited to sit in meditation with eyes closed and write down their fears as they arise, without judgment or expectation of sharing. The goal is not to confront or overcome fear, but to acknowledge it gently and explore its underlying causes, seeking a deeper understanding of the relationship between courage and fear. By doing so, participants aim to discover an antidote to fear, such as kindness or gentle friendship, which can transform their fears and themselves. This exercise is meant to be a starting point for exploring courage in class, with the hope that it will lead to a deeper understanding of what courage means and how to cultivate it.", "themes": ["Compassion", "Vulnerability"], "texts": [], "minutes": 11}, {"id": "2013-01-19 - Heigaku Talus Latona - Blindspots Week 1 Wisdom", "title": "Blindspots Week 1 Wisdom", "speaker": "Heigaku Talus Latona", "date": "2013-01-19", "series": "Blindspots", "summary": "The talk explores the concept of wisdom in Buddhism, which involves recognizing the causal relationship between actions and their consequences, rather than judging things as good or bad. This means observing how certain behaviors lead to suffering and understanding the impermanence of all things. Wisdom is not about imposing a fixed standard, but rather about cultivating discernment through inquiry and attention, allowing us to see patterns and connections that may have been previously overlooked. By developing wisdom, we can gain clarity and insight into our lives, cutting through deception and ego, and ultimately experiencing a deeper understanding of reality.", "themes": ["Emptiness", "Wisdom"], "texts": [], "minutes": 11}, {"id": "2013-01-19 - Heigaku Talus Latona - Way Seeking Mind", "title": "Way Seeking Mind", "speaker": "Heigaku Talus Latona", "date": "2013-01-19", "series": "", "summary": "The talk's main teaching emphasizes the importance of being present in the moment, free from distractions and preconceptions. By cultivating mindfulness and trust in the process, we can find gratitude and purpose in our daily lives, even in the face of challenges and setbacks. This approach is rooted in the speaker's personal journey, which was shaped by their experiences as a caregiver, martial artist, and explorer of Eastern spiritual traditions, ultimately leading them to prioritize relationships, well-being, and personal growth.", "themes": ["Compassion", "Gratitude", "Sangha"], "texts": [], "minutes": 40}, {"id": "2013-01-09 - Nomon Tim Burnett - On Practice Period", "title": "On Practice Period", "speaker": "Nomon Tim Burnett", "date": "2013-01-09", "series": "", "summary": "The main teaching of this Soto Zen dharma talk emphasizes the importance of participating in a 90-day practice period as a way to cultivate spiritual growth and fulfillment, regardless of one's background or identity. The speaker encourages everyone, even those who may not feel like they can embody the ideal of a Buddha, to participate and be supported by others. By doing so, individuals can experience personal growth, community, and a deeper connection with their practice, ultimately becoming a Buddha in the process.", "themes": ["Buddha-nature", "Sangha"], "texts": [], "minutes": 28}, {"id": "2013-01-02 - Nomon Tim Burnett - 7 Factors 5 Joy", "title": "7 Factors 5 Joy", "speaker": "Nomon Tim Burnett", "date": "2013-01-02", "series": "Seven Factors of Awakening", "summary": "The talk emphasizes the importance of cultivating joy (P-T) in Buddhism, rather than just happiness, as a key factor in awakening. Joy is not just a pleasant feeling, but also has a relationship with the object that brings it about, making it more profound and meaningful. To cultivate joy, one must let go of thinking mind's tendency to evaluate and control emotions, instead paying attention to the present moment and working directly with experience, allowing thoughts and emotions to arise without judgment or resistance.", "themes": ["Impermanence", "Suffering"], "texts": [], "minutes": 44}, {"id": "2012-12-08 - Eko Jeff Kelley - Steer the Ship", "title": "Steer the Ship", "speaker": "Eko Jeff Kelley", "date": "2012-12-08", "series": "", "summary": "The speaker invites listeners to explore their mental habits and patterns that perpetuate suffering by cultivating awareness and intention to interrupt them, viewing these patterns as workable and observable like other habits. By doing so, they aim to develop a more spacious relationship with their mind and reality, embodying the principles of Bodhisattva practice through subtle efforts to transform patterns such as anger or fear without judgment. This approach involves stepping forward into new life with compassion and gentleness, finding support in one's true nature and experiencing freedom and open-heartedness in the present moment.", "themes": ["Buddha-nature", "Compassion"], "texts": ["Shōbōgenzō"], "minutes": 42}, {"id": "2012-12-07 - Nomon Tim Burnett - Great Effort", "title": "Great Effort", "speaker": "Nomon Tim Burnett", "date": "2012-12-07", "series": "", "summary": "The talk's main teaching emphasizes the importance of cultivating mindfulness and awareness through rigorous training and discipline, but not in a way that seeks to suppress or overcome one's natural tendencies. Instead, it encourages embracing and sitting with difficult emotions and thoughts, such as hazing and self-concern, directly and without resistance, allowing for greater ease and clarity in daily life. By approaching practice with kindness, self-awareness, and mindfulness, individuals can develop a strong foundation for spiritual growth and awakening.", "themes": ["Suffering"], "texts": [], "minutes": 46}, {"id": "2012-12-04 - Nomon Tim Burnett - Drumming Interdependence", "title": "Drumming Interdependence", "speaker": "Nomon Tim Burnett", "date": "2012-12-04", "series": "", "summary": "The talk's main teaching is about the importance of embracing uncertainty and letting go of ego in spiritual practice. The speaker shares an experience with drumming classes as a metaphor for how we can learn to trust ourselves and let our natural abilities emerge when we release our need to control or figure things out. This approach is contrasted with the tendency to doubt and seek external validation, highlighting the value of cultivating mindfulness, joy, and wisdom by acknowledging and working with our own limitations rather than trying to overcome them.", "themes": ["Interconnection", "Sangha"], "texts": [], "minutes": 25}, {"id": "2012-11-28 - Nomon Tim Burnett - 7 Factors 4 Energy Cont", "title": "7 Factors 4 Energy Cont", "speaker": "Nomon Tim Burnett", "date": "2012-11-28", "series": "Seven Factors of Awakening", "summary": "The teacher invites the group to reflect on what supports or hinders their intention to sit daily, using energy as a starting point for this inquiry. They encourage mindfulness and self-awareness, drawing from the Buddha's teachings that cultivating energy requires acknowledging the states of misery caused by laziness and surrounding oneself with positive influences. The practice involves deliberately cultivating inner energy through noble examples, appreciating support, and inclining one's mind towards mindfulness. This approach aims to help individuals overcome obstacles and find serenity in their daily sitting practice.", "themes": ["Gratitude", "Sangha"], "texts": [], "minutes": 22}, {"id": "2012-11-21 - Nomon Tim Burnett - 7 Factors 3 Energy", "title": "7 Factors 3 Energy", "speaker": "Nomon Tim Burnett", "date": "2012-11-21", "series": "Seven Factors of Awakening", "summary": "The speaker shares their personal experience of meeting strong aversion and doubt with mindfulness and discernment, allowing them to pass through without becoming stuck. They also explore how \"sloth\" or dullness can be met with energy, suggesting a shift in understanding of what it means to cultivate persistence and effort in Zen practice. Ultimately, the speaker emphasizes the importance of being present, letting go of effort and striving, and cultivating mindfulness through daily practice as an object of investigation into its nature and conditions.", "themes": ["Acceptance"], "texts": ["Gateless Barrier"], "minutes": 32}, {"id": "2012-11-14 - Nomon Tim Burnett - 7 Factors 2 Discernment", "title": "7 Factors 2 Discernment", "speaker": "Nomon Tim Burnett", "date": "2012-11-14", "series": "Seven Factors of Awakening", "summary": "The talk teaches that cultivating awareness through mindfulness is essential for developing discernment, which involves understanding the causes and effects of our actions and experiences. This awareness allows us to make subtle choices about where to put our energy in order to cultivate wholesome actions, rather than getting stuck in analysis or judgment. By combining mindfulness with discernment, we can develop a deeper understanding of the present moment and its causes, leading to greater awakening and liberation from suffering.", "themes": ["Suffering", "Wisdom"], "texts": [], "minutes": 43}, {"id": "2012-11-07 - Nomon Tim Burnett - 7 Factors 1 Intro", "title": "7 Factors 1 Intro", "speaker": "Nomon Tim Burnett", "date": "2012-11-07", "series": "Seven Factors of Awakening", "summary": "The talk focuses on cultivating awareness and understanding of the mind through recognizing and working with its tendencies, habits, and patterns, rather than trying to change specific thoughts or content. The Seven Factors of Awakening offer a framework for developing an open, flexible, and joyful approach to life by balancing and integrating these factors, which include mindfulness, concentration, wisdom, and others. By understanding and working with the mind's natural patterns, one can reduce suffering, confusion, and delusion and cultivate a more awakened and fulfilling way of being.", "themes": ["Wisdom"], "texts": [], "minutes": 27}, {"id": "2012-10-31 - Nomon Tim Burnett - Dale Wright Challenges of Zen", "title": "Dale Wright Challenges of Zen", "speaker": "Nomon Tim Burnett", "date": "2012-10-31", "series": "", "summary": "The talk highlights the importance of cultivating lovingness and connection in Soto Zen practice, challenging the common perception of the tradition as austere or detached. The speaker reflects on how this can be achieved by directly attending to suffering without becoming isolated, and how this allows for a more nuanced view of wisdom and compassion that includes the environment and all beings. By practicing with others who share similar experiences, individuals can foster a sense of solidarity and shared humanity, ultimately helping themselves and others while being present with suffering.", "themes": ["Compassion", "Ethics", "Social engagement"], "texts": [], "minutes": 33}, {"id": "2012-10-17 - Nomon Tim Burnett - Three Noble Truths", "title": "Three Noble Truths", "speaker": "Nomon Tim Burnett", "date": "2012-10-17", "series": "", "summary": "The talk's main teaching is that traditional Buddhist teachings on suffering can be limiting if they're presented as a list of truths to be memorized or understood intellectually. Instead, the speaker suggests reframing these teachings as practical verbs or actions that help us engage with our lives more honestly and realistically, such as deep knowing and examination. This approach emphasizes the importance of direct experience and inner wisdom in understanding and transforming suffering, rather than just relying on external knowledge or formulas.", "themes": ["Suffering", "Wisdom"], "texts": ["Heart Sutra"], "minutes": 25}, {"id": "2012-10-14 - Nomon Tim Burnett - Bodhi Pakshika Dharma Retreat 4", "title": "Bodhi Pakshika Dharma Retreat 4", "speaker": "Nomon Tim Burnett", "date": "2012-10-14", "series": "Bodhi Pakshika Dharma Retreat", "summary": "The talk emphasizes the importance of cultivating faith, confidence, and diligence as roots of spiritual practice, which can lead to peace of mind and security in daily life. By recognizing the impermanent nature of reality and letting go of a fixed self, we can find freedom and appreciation in the present moment. This awareness allows us to approach life with greater openness and trust, leading to a more authentic and liberated experience.", "themes": ["Impermanence", "No-self", "Suffering"], "texts": [], "minutes": 101}, {"id": "2012-10-13 - Nomon Tim Burnett - Bodhi Pakshika Dharma Retreat 2", "title": "Bodhi Pakshika Dharma Retreat 2", "speaker": "Nomon Tim Burnett", "date": "2012-10-13", "series": "Bodhi Pakshika Dharma Retreat", "summary": "The talk emphasizes the importance of cultivating awareness and presence in daily life, rather than trying to escape or manipulate external circumstances. By practicing mindfulness and concentration, one can develop a steady and open awareness that allows them to navigate life with greater ease and freedom. This approach is not about achieving a specific state, but rather about embracing qualities such as joy, lightness, and ease, which are essential for experiencing happiness and fulfillment in daily life.", "themes": ["Interconnection"], "texts": [], "minutes": 54}, {"id": "2012-10-13 - Nomon Tim Burnett - Bodhi Pakshika Dharma Retreat 3", "title": "Bodhi Pakshika Dharma Retreat 3", "speaker": "Nomon Tim Burnett", "date": "2012-10-13", "series": "Bodhi Pakshika Dharma Retreat", "summary": "The main teaching of the Soto Zen dharma talk emphasizes the importance of cultivating awareness and balance in the body through mindfulness practices, such as paying attention to the physical position of the head during zazen. By doing so, one can develop a deeper understanding of oneself and the world, leading to greater freedom and acceptance. This approach is also linked to the concept of \"four proper exertions,\" which involves cultivating wholesome mental powers and making intentional choices that shape one's future, all while maintaining a soft and open mindset that allows for clarity and discernment.", "themes": ["Wisdom"], "texts": [], "minutes": 63}, {"id": "2012-10-12 - Nomon Tim Burnett - Bodhi Pakshika Dharma Retreat 1", "title": "Bodhi Pakshika Dharma Retreat 1", "speaker": "Nomon Tim Burnett", "date": "2012-10-12", "series": "Bodhi Pakshika Dharma Retreat", "summary": "The speaker suggests that true value and meaning come from the relationships and circumstances we encounter, rather than external events or rituals themselves. They encourage us to acknowledge and work with our limitations and uncertainties, rather than trying to control or force them, as an example of how this can lead to greater freedom and understanding. By recognizing and letting go of patterns of desire, aversion, and ignorance, we can cultivate a more straightforward and free approach to life, one that is not about escaping suffering but about being present and clear in the midst of it.", "themes": ["Suffering"], "texts": [], "minutes": 27}, {"id": "2012-10-10 - Nomon Tim Burnett - The Strengths of Zen", "title": "The Strengths of Zen", "speaker": "Nomon Tim Burnett", "date": "2012-10-10", "series": "", "summary": "The main teaching of the Soto Zen dharma talk centered around the importance of taking Zen practice seriously and recognizing its value in cultivating positive human qualities such as mindfulness, concentration, and compassion. The tradition emphasizes freedom from suffering and desire, playfulness, and creativity, and values an approach that is flexible and inclusive, allowing for a more personal and individualized spiritual path. This approach recognizes that Zen is not bound by traditional notions of belief or doctrine, but rather seeks to embody the principles of mindfulness and compassion in everyday life.", "themes": ["Sangha"], "texts": [], "minutes": 22}, {"id": "2012-09-26 - Nomon Tim Burnett - Bodhi Pakshika Dharma 2 Foundations of Mindfulness", "title": "Bodhi Pakshika Dharma 2 Foundations of Mindfulness", "speaker": "Nomon Tim Burnett", "date": "2012-09-26", "series": "", "summary": "The main teaching of this Soto Zen dharma talk emphasizes the importance of mindfulness as a practice that allows us to direct our attention and influence what we're aware of, much like a spotlight shining on different aspects of experience. By cultivating mindfulness, we can develop a greater understanding and appreciation for reality, including our own bodies and attitudes towards them, in order to guide wholesome states in body and mind. This practice is meant to be repeated and refined over time, rather than just memorized or studied once, in order to establish a life of purity and bring happiness to oneself and others.", "themes": [], "texts": [], "minutes": 39}, {"id": "2012-09-05 - Nomon Tim Burnett - Bodhi Pakshika Dharma Practice 1", "title": "Bodhi Pakshika Dharma Practice 1", "speaker": "Nomon Tim Burnett", "date": "2012-09-05", "series": "", "summary": "The talk emphasizes the importance of cultivating mindfulness and awareness as a means to achieve awakening and liberation from suffering. The speaker invites listeners to dedicate themselves to practicing the 37 Aids to Awakening, which are organized into four foundations of mindfulness and seven factors of enlightenment. By doing so, they aim to develop wholesome states, overcome unwholesome ones, and ultimately enter the fullness of Buddha's way, bringing joy, wisdom, and understanding not only for themselves but also for all beings. The practice is seen as a continuous and ongoing process that requires patience, diligence, and mindfulness, with the ultimate goal of realizing awakening and achieving liberation from suffering.", "themes": ["Ethics", "Wisdom"], "texts": [], "minutes": 8}, {"id": "2012-09-05 - Nomon Tim Burnett - On Duality", "title": "On Duality", "speaker": "Nomon Tim Burnett", "date": "2012-09-05", "series": "", "summary": "The speaker emphasizes that true freedom from stress and suffering comes not from achieving some external state of enlightenment, but rather from cultivating an awakened heart and mind that is our true nature. This involves finding a balance between letting go of preconceptions and actively practicing meditation and self-awareness, which can be guided by practical teachings such as the Bodhi Pakshika Dharma. By embracing these principles and committing to them, we can break down the walls we build around ourselves and respond freely in each moment, allowing us to live more fully and authentically.", "themes": ["Buddha-nature", "Suffering"], "texts": ["Shōbōgenzō"], "minutes": 41}, {"id": "2012-06-27 - Nomon Tim Burnett - Letting in the Darkness", "title": "Letting in the Darkness", "speaker": "Nomon Tim Burnett", "date": "2012-06-27", "series": "", "summary": "The talk emphasizes the importance of cultivating an authentic and honest relationship with oneself through the guidance of a trusted teacher or \"friend.\" This process involves acknowledging and working with one's own darkness, imperfections, and fears in order to grow and transform. By embracing this inner work, we can develop a deeper understanding of ourselves and connect more deeply with others, ultimately finding greater freedom from suffering and cultivating a more authentic spiritual practice.", "themes": ["Interconnection", "Sangha", "Vulnerability"], "texts": [], "minutes": 42}, {"id": "2012-06-02 - Yuzan Nancy Welch - Buddhas Zen Brain", "title": "Buddhas Zen Brain", "speaker": "Yuzan Nancy Welch", "date": "2012-06-02", "series": "", "summary": "The talk's main teaching is that by understanding how our brains process emotions and thoughts, we can learn to integrate and accept suffering as part of our experience, rather than trying to separate or eliminate it. By calming the \"fight or flight\" response that triggers suffering, we can access a more thoughtful state and respond more mindfully to life's challenges. This practice allows us to rewire our brain chemistry to favor calmness, clarity, and compassion, ultimately leading to greater happiness and well-being.", "themes": ["Acceptance", "Impermanence", "Suffering"], "texts": [], "minutes": 49}, {"id": "2012-05-24 - Nomon Tim Burnett - Nothing Holy", "title": "Nothing Holy", "speaker": "Nomon Tim Burnett", "date": "2012-05-24", "series": "", "summary": "Here is a summary paragraph summarizing the main teaching of the Soto Zen dharma talk:\n\nThe talk emphasizes the importance of embracing openness and humility in spiritual practice, particularly through seated meditation (zazen). By letting go of attachments and expectations, practitioners can cultivate awareness and presence, even when faced with challenges or difficulties. This approach is rooted in the teachings of Bodhidharma, who embodied a sense of curiosity and devotion, and encourages practitioners to explore their own path while embracing the unknown, rather than trying to pin down or define truth.", "themes": ["Emptiness", "Wisdom"], "texts": ["Blue Cliff Record"], "minutes": 62}, {"id": "2012-05-09 - Nomon Tim Burnett - Zhaozhous Bridge", "title": "Zhaozhou's Bridge", "speaker": "Nomon Tim Burnett", "date": "2012-05-09", "series": "", "summary": "The speaker shared an experience where they gave a Dharma talk on the koan \"Zhaozhou's donkey's cross,\" highlighting how our perceptions can change over time and how we can learn to let go of preconceptions. The story invites us to reflect on our own experiences and emotions, considering whether we're holding onto idealized expectations for others or ourselves, which can lead to feelings of inadequacy or frustration. By embracing our imperfections and limitations, we can find liberation from these expectations and cultivate a more authentic understanding of reality.", "themes": ["Acceptance", "Vulnerability"], "texts": [], "minutes": 27}, {"id": "2012-05-05 - Nomon Tim Burnett - Buddhas Birthday", "title": "Buddhas Birthday", "speaker": "Nomon Tim Burnett", "date": "2012-05-05", "series": "", "summary": "The talk's main teaching is that every moment of life has the quality of birth, where we're fully alive and present, and this realization can help us approach our lives with equanimity and kindness. By embracing this perspective, we can find freedom in our relationships and experiences, recognizing that each person is constantly being reborn into new moments of life. This understanding encourages us to accept the impermanence of all things, including our own mortality, and to cultivate mindfulness and presence in our daily lives.", "themes": ["Acceptance", "Impermanence"], "texts": [], "minutes": 35}, {"id": "2012-04-11 - Nomon Tim Burnett - Women in Buddhism", "title": "Women in Buddhism", "speaker": "Nomon Tim Burnett", "date": "2012-04-11", "series": "", "summary": "The main teaching of this Soto Zen dharma talk highlights the importance of women's participation and leadership in spiritual communities, drawing inspiration from the story of Maha Pajapati Gautami, a Buddhist woman who achieved enlightenment and played a significant role in establishing the order of nuns in early Buddhism. Her legacy serves as a powerful example of the value of women's contributions to spiritual growth and the transmission of the Buddha's teachings. This teaching emphasizes the need for humility, openness, and adaptability in approaching spiritual practice, recognizing that our understanding is always incomplete and subject to change.", "themes": ["Social engagement"], "texts": ["Lotus Sutra", "Shōbōgenzō"], "minutes": 54}, {"id": "2012-04-11 - Shuko Edie Norton - Lotus Sutra Intro", "title": "Lotus Sutra Intro", "speaker": "Shuko Edie Norton", "date": "2012-04-11", "series": "", "summary": "The talk emphasizes the importance of skillful means in Buddhist teachings, highlighting how the Buddha adapts his message to suit different levels of understanding and achieve enlightenment for all beings. This approach is exemplified by the Lotus Sutra, which presents a nuanced and evolving understanding of reality, challenging traditional notions of beauty and human form. By embracing this concept of emptiness, we can move beyond limited perspectives and cultivate a deeper understanding of the interconnectedness of all phenomena.", "themes": [], "texts": ["Lotus Sutra"], "minutes": 42}, {"id": "2012-03-24 - Nomon Tim Burnett - Practical Work with the Mind", "title": "Practical Work with the Mind", "speaker": "Nomon Tim Burnett", "date": "2012-03-24", "series": "", "summary": "The talk's main teaching emphasizes the importance of cultivating mindfulness in daily life by being aware of one's body and posture, observing thoughts without judgment, and trusting in a larger source that sustains us. By slowing down and paying attention to physical sensations, we can shift our baseline and make even small moments more effective, finding comfort and ease in letting go of self-doubt and anxiety. Regular practice can help us develop a greater sense of trust and confidence, allowing us to navigate life's challenges with greater ease and clarity.", "themes": ["Impermanence", "Vulnerability"], "texts": [], "minutes": 47}, {"id": "2012-03-03 - Zoketsu Norman Fischer - Impermanence", "title": "Impermanence", "speaker": "Zoketsu Norman Fischer", "date": "2012-03-03", "series": "", "summary": "The speaker shares a personal reflection on the importance of impermanence, highlighting its central role in Buddhism as an \"inescapable and essentially painful fact of life.\" They suggest that instead of trying to avoid or overcome loss, we can find freedom and happiness by embracing change and letting go of our attachment to a permanent self. By understanding that everything is interconnected and impermanent, we can learn to live fully in the present moment and find joy in the beauty of impermanence.", "themes": ["Buddha-nature", "Impermanence", "No-self"], "texts": ["Heart Sutra"], "minutes": 56}, {"id": "2012-03-02 - Nomon Tim Burnett - Heart of the Matter 5", "title": "Heart of the Matter 5", "speaker": "Nomon Tim Burnett", "date": "2012-03-02", "series": "Heart of the Matter", "summary": "The speaker invites listeners to explore how they create their own world through their experiences and perceptions, embracing the chaos and uncertainty of life rather than trying to control it. They encourage approaching this process with love, care, and curiosity, rather than seeking a specific goal or outcome, and instead cultivate awareness and acceptance of life as it is. By letting go of attachments to thoughts and understanding, we can tap into a sense of wonder, compassion, and connection that allows us to live more fully in the present moment.", "themes": ["No-self", "Wisdom"], "texts": ["Heart Sutra"], "minutes": 41}, {"id": "2012-02-23 - Nomon Tim Burnett - Heart of the Matter 4", "title": "Heart of the Matter 4", "speaker": "Nomon Tim Burnett", "date": "2012-02-23", "series": "Heart of the Matter", "summary": "The speaker's main teaching emphasizes the importance of embracing emptiness or boundlessness in reality, rather than trying to grasp or control it through thought or understanding. This concept, rooted in Prajnaparamita literature, suggests that all experiences are interconnected and interdependent, and that true wisdom lies in letting go of attachments and desires. By recognizing this emptiness, we can experience a sense of freedom and liberation from the limitations of our perceptions and understanding.", "themes": ["Emptiness", "Impermanence", "No-self"], "texts": ["Heart Sutra"], "minutes": 58}, {"id": "2012-02-15 - Nomon Tim Burnett - Heart of the Matter 3", "title": "Heart of the Matter 3", "speaker": "Nomon Tim Burnett", "date": "2012-02-15", "series": "Heart of the Matter", "summary": "The main teaching of this Soto Zen dharma talk is that by understanding and embracing the impermanence and interconnectedness of all things, we can break free from suffering caused by our own mental afflictions such as attachment, anger, and delusion. This involves letting go of a fixed sense of self and grasping for things that are ultimately empty of inherent existence. By doing so, we can find freedom and liberation in the present moment, rather than trying to escape or transcend it through meditation or other means.", "themes": ["Emptiness", "No-self", "Suffering"], "texts": ["Heart Sutra"], "minutes": 44}, {"id": "2012-02-04 - Nomon Tim Burnett - Extraordinary in the Ordinary", "title": "Extraordinary in the Ordinary", "speaker": "Nomon Tim Burnett", "date": "2012-02-04", "series": "", "summary": "The speaker encourages listeners to appreciate the beauty and significance of everyday moments, rather than constantly seeking something more extraordinary or complex. By being present and open, we can find love and awareness in even ordinary experiences, such as a rain-soaked barrow or a simple task like washing a bowl. This approach to life is one of humility and service, where we cultivate connection and community through practices like gratitude, curiosity, and full engagement.", "themes": ["Gratitude"], "texts": [], "minutes": 41}, {"id": "2012-02-01 - Nomon Tim Burnett - Heart of the Matter 2", "title": "Heart of the Matter 2", "speaker": "Nomon Tim Burnett", "date": "2012-02-01", "series": "Heart of the Matter", "summary": "The teacher invites participants to explore the concept of the heart of the matter by examining their own experiences with inquiry and self-inquiry, encouraging them to share their insights as an offering to benefit everyone in the group. This process can lead to a deeper understanding of one's true nature and the interconnectedness of all things. By sharing and listening to each other's perspectives, participants can cultivate greater awareness, compassion, and wisdom.", "themes": ["Emptiness", "No-self"], "texts": ["Heart Sutra", "Lotus Sutra"], "minutes": 69}, {"id": "2012-01-25 - Nomon Tim Burnett - Heart of the Matter 1", "title": "Heart of the Matter 1", "speaker": "Nomon Tim Burnett", "date": "2012-01-25", "series": "Heart of the Matter", "summary": "The teacher invites participants to explore their own understanding of wisdom and knowledge by reflecting on how these concepts are distorted or oversimplified by our human minds and culture. To facilitate this exploration, the group will engage in a mindfulness conversation where each person shares their thoughts and feelings without worrying about saying the \"right\" thing. This process is likened to the translation and interpretation of Buddhist texts like the Heart Sutra, which have undergone many changes over time, reflecting our own journey of growth and understanding as we navigate the complexities of reality.", "themes": ["Wisdom"], "texts": ["Heart Sutra"], "minutes": 58}, {"id": "2012-01-21 - Nomon Tim Burnett - The Sun Wont Come Out", "title": "The Sun Wont Come Out", "speaker": "Nomon Tim Burnett", "date": "2012-01-21", "series": "", "summary": "The teacher's main teaching is that true awakening and understanding can be cultivated through devotion, love, and practice, rather than solely through rational or scientific processes. This is reflected in the Heart Sutra's concept of emptiness, which suggests that all phenomena are empty of inherent existence and characteristic, allowing us to transcend our limited views and perceptions. By bringing awareness to the present moment and letting go of distractions, we can access a deeper level of wisdom and freedom from suffering, revealing a more authentic and joyful experience of life.", "themes": ["Emptiness", "Wisdom"], "texts": ["Heart Sutra"], "minutes": 43}, {"id": "2011-12-28 - Nomon Tim Burnett - Being Seen", "title": "Being Seen", "speaker": "Nomon Tim Burnett", "date": "2011-12-28", "series": "", "summary": "The speaker's main teaching is that true freedom and connection come from embracing our imperfections and vulnerabilities, rather than hiding behind a mask of perfection or self-protection. By acknowledging and working with our tendency to isolate ourselves through physical sensations and self-perception, we can cultivate greater intimacy and healing in our lives. This involves reframing difficulties as opportunities for growth and transformation, rather than evidence of personal flaws, and using awareness and attention to understand and heal ourselves and our relationships.", "themes": ["No-self", "Suffering", "Vulnerability"], "texts": [], "minutes": 13}, {"id": "2011-12-03 - Eko Jeff Kelley - Rohatsu Two Stories", "title": "Rohatsu Two Stories", "speaker": "Eko Jeff Kelley", "date": "2011-12-03", "series": "", "summary": "The teacher suggests that traditional stories about spiritual awakening can be limiting, as they often rely on heroic narratives that don't accurately represent the complexity of spiritual practice. Instead, they offer an alternative approach exemplified by Wutsu, who responds to situations with humility and openness, letting go of preconceptions and simply being present in the moment. This approach is seen as a model for teachers and practitioners alike, encouraging us to stay present and loyal to our immediate experience, rather than getting caught up in analysis or conceptualization.", "themes": ["Vulnerability", "Wisdom"], "texts": [], "minutes": 32}, {"id": "2011-12-02 - Nomon Tim Burnett - Rohatsu Praise and Blame", "title": "Rohatsu Praise and Blame", "speaker": "Nomon Tim Burnett", "date": "2011-12-02", "series": "", "summary": "The speaker encourages listeners to approach life's challenges and imperfections with a sense of curiosity and openness, rather than trying to avoid or escape them. They suggest that by cultivating mindfulness through meditation and practice, we can develop a greater understanding of ourselves and the world around us, and find peace and freedom in the present moment. By embracing our limitations and imperfections, we can let go of ego and perfectionism and simply be, finding joy and contentment in the simplicity of everyday life.", "themes": ["Emptiness"], "texts": [], "minutes": 37}, {"id": "2011-10-26 - Shuko Edie Norton - Buddhism and the Brain", "title": "Buddhism and the Brain", "speaker": "Shuko Edie Norton", "date": "2011-10-26", "series": "", "summary": "The talk's main teaching is that our suffering arises from our mistaken assumption of a permanent, unchanging self, which is actually an illusion created by our brains. By understanding how the brain constructs reality through perception and attachment, we can learn to loosen up and let go of attachments, and instead cultivate a more open and accepting approach to life. This involves recognizing that our sense of identity is constantly changing and has biological origins, and training our minds to respond with patience, intuition, and openness to external events, rather than trying to control or grasp onto things.", "themes": ["Impermanence", "No-self", "Suffering"], "texts": [], "minutes": 49}, {"id": "2011-10-15 - Nomon Tim Burnett - Genjokoan 1", "title": "Genjokoan 1", "speaker": "Nomon Tim Burnett", "date": "2011-10-15", "series": "", "summary": "The speaker explores Dogen's Genjokoans as a way to live fully present in life, acknowledging that our individual perspectives are inherently incomplete and limited. By embracing this realization, we can approach reality with openness and awareness, rather than trying to change or improve it through thinking. This approach encourages us to focus on the immediate present moment, letting go of assumptions and striving for enlightenment, and instead cultivating a sense of wonder and appreciation for life's complexities.", "themes": ["Suffering"], "texts": ["Shōbōgenzō"], "minutes": 82}, {"id": "2011-08-24 - Nomon Tim Burnett - Fukanzazengi Part 6", "title": "Fukanzazengi Part 6", "speaker": "Nomon Tim Burnett", "date": "2011-08-24", "series": "Fukanzazengi", "summary": "The talk emphasizes the importance of being present and aware in meditation practice, suggesting that simply showing up with an open mind is enough, rather than trying to achieve a specific state or skill. This approach is rooted in Dogen's text Phukan Zazengi, which challenges traditional notions of meditation as a skill to be learned and mastered. By embracing this mindset, individuals can cultivate a deeper understanding of their own nature and the true value of Zen practice lies not in its historical accuracy, but in its ability to convey a wordless, transcendent reality.", "themes": ["Buddha-nature", "Impermanence"], "texts": [], "minutes": 62}, {"id": "2011-08-06 - Nomon Tim Burnett - Practice Beyond Preferences", "title": "Practice Beyond Preferences", "speaker": "Nomon Tim Burnett", "date": "2011-08-06", "series": "", "summary": "The Soto Zen dharma talk emphasizes the importance of living in the present moment, free from attachment to thoughts, emotions, or expectations. By cultivating awareness through meditation and embracing life's imperfections, one can find happiness and stability, rather than trying to control or achieve a specific state. This approach requires faith and trust in the practice itself, letting go of need for control and planning, and instead discovering freedom and presence in everyday life.", "themes": ["Acceptance", "Suffering"], "texts": [], "minutes": 45}, {"id": "2011-07-27 - Nomon Tim Burnett - Fukanzazengi Part 5", "title": "Fukanzazengi Part 5", "speaker": "Nomon Tim Burnett", "date": "2011-07-27", "series": "Fukanzazengi", "summary": "In this Soto Zen dharma talk, the main teaching emphasizes the importance of embracing the present moment without attachment or expectation, allowing thoughts and emotions to arise and pass through without getting caught in them. The speaker encourages listeners to cultivate a sense of being present and aware, rather than seeking answers or trying to be wise, and invites them to explore their own nature by simply sitting quietly with breath awareness. This approach is rooted in the idea that problems are not things to be solved, but opportunities for awakening and growth, and that true understanding requires a deeper level of awareness and attitudinal change.", "themes": ["Buddha-nature", "Emptiness"], "texts": [], "minutes": 52}, {"id": "2011-07-13 - Nomon Tim Burnett - Taking A Step", "title": "Taking A Step", "speaker": "Nomon Tim Burnett", "date": "2011-07-13", "series": "", "summary": "The speaker shares a personal story about their experience with Dharma transmission, which they received from their teacher in a private ceremony at the temple. This process helped them deepen their understanding of the interconnectedness of all things and cultivate trust and letting go of expectation. Ultimately, the speaker emphasizes that true spiritual realization is not about achieving something new, but rather recognizing one's true nature as already complete and being able to inhabit powerful symbols without being overwhelmed by them.", "themes": ["Interconnection", "Sangha"], "texts": [], "minutes": 43}, {"id": "2011-06-08 - Nomon Tim Burnett - Fukanzazengi Part 4", "title": "Fukanzazengi Part 4", "speaker": "Nomon Tim Burnett", "date": "2011-06-08", "series": "Fukanzazengi", "summary": "The speaker emphasizes that true spiritual growth comes from letting go of our dualistic thinking and expectations, and instead cultivating a sense of awareness and presence in the present moment. By sitting meditation (zazen) without preparation or expectation, we can drop our tendency to judge ourselves and others, and simply be with what is. This approach allows us to tap into a deeper sense of freedom and wholeness, even in the midst of uncertainty and imperfection.", "themes": ["Acceptance"], "texts": [], "minutes": 56}, {"id": "2011-05-25 - Seishu John Wiley - Your Best Season", "title": "Your Best Season", "speaker": "Seishu John Wiley", "date": "2011-05-25", "series": "", "summary": "The talk's main teaching emphasizes the importance of approaching life with an open and non-judgmental mind, letting go of preconceived notions and perspectives. By cultivating awareness and appreciation for the present moment, we can transform even challenging experiences into opportunities for growth and gratitude. This involves embracing impermanence and finding magic in the midst of difficulties, rather than resisting or judging them.", "themes": ["Acceptance", "Gratitude", "Impermanence"], "texts": [], "minutes": 20}, {"id": "2011-05-11 - Nomon Tim Burnett - Fukanzazengi Part 3", "title": "Fukanzazengi Part 3", "speaker": "Nomon Tim Burnett", "date": "2011-05-11", "series": "Fukanzazengi", "summary": "Here is a summary of the talk's main teaching in plain language:\n\nThe talk emphasizes the importance of transformation through Zen practice, which involves letting go of attachments and conditioning to tap into one's true nature. This requires courage to be different, take chances, and give up habits and moods, rather than trying to control or intellectualize it. By doing so, practitioners can cultivate a deeper sense of wisdom and enlightenment that is always present, regardless of external circumstances.", "themes": ["Acceptance"], "texts": [], "minutes": 48}, {"id": "2011-05-07 - Nomon Tim Burnett - Fukanzazengi Part 2", "title": "Fukanzazengi Part 2", "speaker": "Nomon Tim Burnett", "date": "2011-05-07", "series": "Fukanzazengi", "summary": "The speaker shares a personal story about learning to observe and settle their angry thoughts through a simple yet powerful analogy involving a jar of water and sparkles, illustrating how this practice can help address complex problems by cultivating awareness and clarity in daily life. This approach encourages us to look beyond our conceptual understanding and instead cultivate awareness of our body and emotions, allowing us to deepen our practice and avoid getting caught up in dualistic thinking. By embracing the imperfections and uncertainties of life, we can find a sense of calm and clarity that is not dependent on external validation or intellectual understanding.", "themes": ["Buddha-nature"], "texts": [], "minutes": 51}, {"id": "2011-04-27 - Nomon Tim Burnett - Fukanzazengi Part 1", "title": "Fukanzazengi Part 1", "speaker": "Nomon Tim Burnett", "date": "2011-04-27", "series": "Fukanzazengi", "summary": "The talk explores the concept of reality and understanding, drawing on the teachings of Dogen, a Japanese priest who wrote \"Fukanzazengi\", a text on Zen practice that challenges traditional notions of enlightenment as something to be achieved through meditation or effort. Instead, Dogen's text suggests that reality is already perfect and all-pervading, and that true understanding comes from recognizing what is already present, rather than trying to fix or change it. This approach encourages a sense of immediacy and non-separation, inviting readers to explore the depths of their own experience without attachment to concepts like separation and lack.", "themes": ["Buddha-nature"], "texts": [], "minutes": 38}, {"id": "2011-04-13 - Nomon Tim Burnett - Dogens Intimate Practice", "title": "Dogens Intimate Practice", "speaker": "Nomon Tim Burnett", "date": "2011-04-13", "series": "", "summary": "The speaker reflects on the importance of letting go of our sense of separation from the world and ourselves, a central teaching of Dogen's Zen philosophy. By embracing this idea, we can cultivate intimacy and connection with ourselves and others, and tap into a deeper reality that transcends individual experience. This process involves recognizing that our sense of self is constantly changing and releasing attachment to fixed notions of good or bad, leading to a greater presence and awareness in the present moment.", "themes": ["Interconnection", "No-self"], "texts": ["Shōbōgenzō"], "minutes": 61}, {"id": "2011-03-27 - Nomon Tim Burnett - Dogens Intimate Practice", "title": "Dogens Intimate Practice", "speaker": "Nomon Tim Burnett", "date": "2011-03-27", "series": "", "summary": "The speaker invites listeners to explore the idea that true awakening comes not from seeking inner peace or calmness, but from letting go of our sense of separation and individuality. This is a central teaching of Dogen, who suggests that enlightenment arises from understanding and releasing our attachment to the self, allowing us to connect more deeply with the world around us. By embracing this idea, we can experience a profound shift in our perception of reality, one that reveals the interconnectedness of all things and allows us to move forward with greater courage and joy.", "themes": ["Interconnection", "No-self"], "texts": ["Shōbōgenzō"], "minutes": 42}, {"id": "2011-03-06 - Shuko Edie Norton - Hossenshiki Ceremony", "title": "Hossenshiki Ceremony", "speaker": "Shuko Edie Norton", "date": "2011-03-06", "series": "", "summary": "Edie shares that true freedom and direction can be found in embracing our imperfections and letting go of attachments, rather than trying to achieve some idealized state. By cultivating discernment and living with openness and humility, we can tap into our true nature and find peace in the midst of uncertainty and chaos. This approach requires us to practice non-thinking and acceptance, rather than trying to control or manipulate our experiences.", "themes": ["Acceptance", "Sangha", "Suffering"], "texts": [], "minutes": 55}, {"id": "2011-03-05 - Shuko Edie Norton - Renunciation", "title": "Renunciation", "speaker": "Shuko Edie Norton", "date": "2011-03-05", "series": "", "summary": "The speaker discusses the challenges of renunciation, initially finding it appealing but struggling to hold onto it as they grapple with the concept of letting go of their individual identity. They explore how traditional notions of renunciation can be difficult to grasp, but suggest that there may be a deeper aspect to it - releasing the idea of a permanent, separate self. Through practices like zazen and cultivating awareness in daily life, one can learn to let go of egoic defenses and experience renunciation as a natural part of their spiritual practice, revealing a more authentic and harmonious reality.", "themes": ["Acceptance", "No-self", "Sangha"], "texts": [], "minutes": 27}, {"id": "2011-03-05 - Zoketsu Norman Fischer - On Gender", "title": "On Gender", "speaker": "Zoketsu Norman Fischer", "date": "2011-03-05", "series": "", "summary": "The talk highlights the importance of addressing gender dynamics in Zen practice to prevent similar situations from arising, particularly when charismatic leaders become seduced by power and engage in addictive behavior. This issue is not new, but rather a manifestation of societal conditioning that can lead to prejudice against women, emphasizing the need for embracing our differences rather than trying to suppress them. By recognizing and respecting the complexity and nuance of human experience, including gender and consent, we can cultivate true loving-kindness and enlightenment.", "themes": ["Buddha-nature", "Ethics", "Vulnerability"], "texts": [], "minutes": 53}, {"id": "2011-03-04 - Nomon Tim Burnett - Opening and Closing", "title": "Opening and Closing", "speaker": "Nomon Tim Burnett", "date": "2011-03-04", "series": "", "summary": "The talk's main teaching emphasizes the importance of embracing imperfection and uncertainty in Zen practice, encouraging listeners to let go of judgment and perfectionism by resting in the present moment. By cultivating a sense of wonderment and openness through inquiry and exploration, we can develop vulnerability and connection with ourselves and others, ultimately leading to deeper spiritual growth and understanding. This approach is illustrated through classic Zen myths, such as the story of Nanyu, which highlights the value of questioning and investigation in uncovering the truth.", "themes": ["Gratitude", "Vulnerability"], "texts": [], "minutes": 56}, {"id": "2011-03-04 - Zoketsu Norman Fischer - Resting in the Six Senses", "title": "Resting in the Six Senses", "speaker": "Zoketsu Norman Fischer", "date": "2011-03-04", "series": "", "summary": "The teacher reflects on the recent losses of four Zen Center priests who embodied the principles of Zen practice, such as perseverance and humility, and sees these losses as an opportunity for new life to emerge. He encourages the community to continue growing and evolving through their practice, embracing impermanence and preciousness in all relationships. By letting go of attachment to expectations and judgments, we can cultivate a deeper connection with others and find happiness and joy in the present moment.", "themes": ["Impermanence", "Sangha"], "texts": [], "minutes": 52}, {"id": "2011-02-07 - Shuko Edie Norton - Zen and Creativity Class 2 Part 1", "title": "Zen and Creativity Class 2 Part 1", "speaker": "Shuko Edie Norton", "date": "2011-02-07", "series": "Zen and Creativity", "summary": "In this Soto Zen dharma talk, the teacher invites participants to write short descriptive poems in a haiku-like style, exploring images and emotions through words without adhering to traditional syllable counts or rhymes. The goal is not perfection but rather to observe and express experience as it arises, much like Japanese painting, which values simplicity, elegance, and attention to detail. The teacher shares examples of classic haiku poems and Japanese paintings, highlighting the importance of capturing a moment in time, evoking emotions, and appreciating the beauty in everyday things. By embracing this process, participants aim to cultivate mindfulness, creativity, and a deeper connection with their surroundings.", "themes": ["Impermanence", "Interconnection"], "texts": [], "minutes": 13}, {"id": "2011-02-07 - Shuko Edie Norton - Zen and Creativity Class 2 Part 2", "title": "Zen and Creativity Class 2 Part 2", "speaker": "Shuko Edie Norton", "date": "2011-02-07", "series": "Zen and Creativity", "summary": "The talk's main teaching is about the importance of observing and experiencing reality in a direct and unfiltered way, without trying to impose preconceived notions or expectations on it. The speaker suggests using ordinary objects, such as a chair or pillow, as a starting point for observation and exploration, allowing oneself to see and hear things more deeply and fully, rather than just superficially. This approach can help to quiet the mind and reveal new insights and perspectives, much like the way that Issa's haikus seem to be more coherent and efficient in their use of language. The speaker encourages listeners to come up with their own ideas and approaches, without feeling bound by traditional forms or rules, and to simply observe and experience reality as it is, rather than trying to shape it into something else.", "themes": ["Acceptance", "Interconnection"], "texts": [], "minutes": 6}, {"id": "2011-02-07 - Shuko Edie Norton - Zen and Creativity Class 2 Part 3", "title": "Zen and Creativity Class 2 Part 3", "speaker": "Shuko Edie Norton", "date": "2011-02-07", "series": "Zen and Creativity", "summary": "The speaker's talk centered on the importance of observation and mindfulness in capturing the essence of nature through writing. By focusing first on what can be seen and then exploring the unseen, including emotions and sensations, one can tap into the underlying philosophy and sentiment that exists in the natural world. This process is also reflective of the principles of meditation, which helps cultivate close observation and awareness.", "themes": ["Gratitude", "Interconnection"], "texts": [], "minutes": 18}, {"id": "2011-02-05 - Shuko Edie Norton - Wayseeking Mind", "title": "Wayseeking Mind", "speaker": "Shuko Edie Norton", "date": "2011-02-05", "series": "", "summary": "The speaker shares that through their Zen practice, they've come to understand that true fulfillment and purpose come from being fully engaged with the present moment, rather than seeking external validation or attachment to specific relationships. They've let go of attachments and ego, recognizing that even long-term practitioners can struggle with partiality, but can work towards greater wholeness through practice and self-reflection. By embracing the present moment, they've found a sense of peace and relief from suffering, allowing them to cultivate a deeper understanding of reality and find liberation from long-held beliefs about themselves.", "themes": ["Acceptance", "Suffering", "Vulnerability"], "texts": [], "minutes": 39}, {"id": "2011-01-29 - Shuko Edie Norton - Zen and Creativity Class 1", "title": "Zen and Creativity Class 1", "speaker": "Shuko Edie Norton", "date": "2011-01-29", "series": "Zen and Creativity", "summary": "The talk's main teaching is that true creativity and expression come from tapping into our inner resources and letting go of mental distractions, rather than striving for perfection or control. By cultivating mindfulness and awareness, we can access a deeper sense of freedom and spontaneity in our creative pursuits. This involves embracing the process itself, rather than just the end result, and allowing ourselves to be guided by intuition and instinct.", "themes": ["Interconnection"], "texts": [], "minutes": 99}, {"id": "2011-01-07 - Zenshin Florence Caplow and Jean LaValley - Awakening in A Female Form", "title": "Awakening in A Female Form", "speaker": "Zenshin Florence Caplow and Jean LaValley", "date": "2011-01-07", "series": "", "summary": "The Soto Zen teacher emphasizes the importance of acknowledging and honoring women's contributions to Buddhist tradition, which has often been overlooked or marginalized throughout history. The teacher encourages the audience to consider how non-dualistic teachings like Buddhism can help break down patriarchal attitudes and promote greater understanding and acceptance of women's experiences and perspectives. By exploring stories of women who have achieved spiritual growth despite facing unique challenges, the teacher aims to inspire a more inclusive and compassionate approach to Buddhist practice.", "themes": ["No-self", "Social engagement"], "texts": ["Lotus Sutra"], "minutes": 76}, {"id": "2010-12-08 - Yuzan Nancy Welch - Buddhas Enlightenment", "title": "Buddhas Enlightenment", "speaker": "Yuzan Nancy Welch", "date": "2010-12-08", "series": "", "summary": "The talk emphasizes the importance of cultivating equanimity and mindfulness through meditation (Zazen) to access true understanding and awakening, which is not something external to oneself, but rather an inner realization available to all beings. This awakening is not a fixed state, but a continuous process of growth and transformation that can be reenacted with each sitting in meditation. By embracing this perspective, we can deepen our connection to ourselves and others, and bring forth the teachings of Buddha anew with each practice.", "themes": ["Acceptance", "Buddha-nature", "Suffering"], "texts": [], "minutes": 23}, {"id": "2010-12-04 - Nomon Tim Burnett - The Stories of Awakening", "title": "The Stories of Awakening", "speaker": "Nomon Tim Burnett", "date": "2010-12-04", "series": "", "summary": "The speaker's talk explores the idea that our sense of self is not fixed, but rather a process or habit that can be transformed through mindfulness and awareness. By letting go of attachments and preconceptions, we can discover a more authentic and peaceful way of being, one that is rooted in the present moment. This understanding is inspired by the stories of Bodhidharma and other Buddhist teachers who embodied the concept of \"vast emptiness,\" or the idea that true wisdom lies in releasing our grasping and embracing the unknown.", "themes": ["Buddha-nature", "No-self"], "texts": [], "minutes": 44}, {"id": "2010-12-03 - Eko Jeff Kelley - Rohatsu 2010", "title": "Rohatsu 2010", "speaker": "Eko Jeff Kelley", "date": "2010-12-03", "series": "", "summary": "The main teaching of the talk is that our sense of self can be a source of suffering by adding unnecessary layers and expectations to our experience during meditation or sesshin. We often carry around an identity that we think will bring us affirmation and validation, but this can actually create more suffering when things don't meet our expectations. By letting go of this identity and simply observing our experiences without judgment, we can tap into a more authentic and bare essence of ourselves, allowing for greater clarity and understanding. This talk invites the listener to explore how their own sense of self is constructed and how it may be contributing to their suffering, with the goal of finding a more essential and peaceful way of being.", "themes": ["No-self", "Suffering"], "texts": [], "minutes": 10}, {"id": "2010-11-10 - Eko Jeff Kelley - Finding A Balance", "title": "Finding A Balance", "speaker": "Eko Jeff Kelley", "date": "2010-11-10", "series": "", "summary": "The speaker's main teaching emphasizes the importance of cultivating equanimity and radical acceptance in order to live a life of compassion and virtue. By letting go of preconceptions and attachments, we can respond skillfully and authentically to the present moment, creating opportunities for growth and connection with others. This requires embracing our natural tendencies and allowing ourselves to be guided by our hearts, rather than being controlled by self-centered desires or outcomes.", "themes": ["Acceptance", "Buddha-nature", "Compassion"], "texts": [], "minutes": 63}, {"id": "2010-10-27 - Kusho Terry Thompson - Wilderness Basketball", "title": "Wilderness Basketball", "speaker": "Kusho Terry Thompson", "date": "2010-10-27", "series": "", "summary": "The speaker's talk explores how their experiences on a solo retreat in nature have influenced their Zen practice, particularly through the lens of basketball, which has been a significant part of their life. They reflect on how this unexpected connection can help them connect with others who may not be familiar with Zen, and how it can deepen their own understanding of the interconnectedness of all things. By sharing their personal story, they aim to inspire others to explore the beauty and simplicity of Zen practice in their own lives.", "themes": ["Interconnection", "Suffering"], "texts": ["Shōbōgenzō"], "minutes": 34}, {"id": "2010-10-20 - Burai Rick Spencer - Koan Practice", "title": "Koan Practice", "speaker": "Burai Rick Spencer", "date": "2010-10-20", "series": "", "summary": "The speaker shares their personal experience with koan practice, highlighting the importance of letting go of conceptual thinking and ego-based perspectives in order to truly understand a koan like \"Mu.\" Through their own struggles and eventual breakthroughs, they illustrate that the goal of koan study is not to arrive at a definitive answer, but rather to transcend conceptual boundaries and experience reality directly. By doing so, one can see the world as an interconnected whole, where our individual sense of self dissolves into the vastness of existence.", "themes": ["Emptiness", "Interconnection", "No-self"], "texts": [], "minutes": 38}, {"id": "2010-10-13 - Nomon Tim Burnett - Colliding Worlds", "title": "Colliding Worlds", "speaker": "Nomon Tim Burnett", "date": "2010-10-13", "series": "", "summary": "The speaker reflects on how recognizing women practitioners within their Soto Zen community has rejuvenated them, reminding them of the importance of connection and being part of a broader movement. This experience has also made them realize that their own group may be more focused on individual practice than community activities, prompting them to consider whether they should continue as a sitting group or expand into a Zen center with more events.", "themes": ["Sangha", "Social engagement"], "texts": [], "minutes": 52}, {"id": "2010-09-16 - Nomon Tim Burnett - Honoring our Ancestors", "title": "Honoring our Ancestors", "speaker": "Nomon Tim Burnett", "date": "2010-09-16", "series": "", "summary": "The talk's main teaching emphasizes the importance of simplicity, humility, and connection with one's ancestors in Zen practice. Drawing inspiration from American Zen teacher Robert Aitken Roshi, the speaker encourages students to focus on basic practices like breath counting meditation, which cultivates releasing and inquiring, rather than elaborate rituals or intellectual pursuits. By embracing the impermanence of all things and finding freedom in the present moment, we can deepen our practice and connect with a sense of reverence and respect for those who have come before us.", "themes": ["Gratitude"], "texts": ["Shōbōgenzō"], "minutes": 41}, {"id": "2010-07-28 - Seishu John Wiley - Our Practice Affects Others", "title": "Our Practice Affects Others", "speaker": "Seishu John Wiley", "date": "2010-07-28", "series": "", "summary": "The speaker shares that when struggling with resistance or doubts in their meditation practice, they can transform their understanding by examining their own mind's opinions and not being swayed by them. Instead of comparing themselves unfavorably to others, they focus on asking \"what is this?\" and \"where is the joy?\" to cultivate a sense of curiosity and openness. By doing so, they've been able to find joy in their practice and apply mindfulness principles to everyday life, including deeper communication with loved ones through writing letters.", "themes": ["Sangha", "Vulnerability"], "texts": [], "minutes": 22}, {"id": "2010-07-14 - Reizan Bob Penny - Wilderness Dharma Practice", "title": "Wilderness Dharma Practice", "speaker": "Reizan Bob Penny", "date": "2010-07-14", "series": "", "summary": "The talk's main teaching emphasizes the importance of connecting with nature as a means of deepening one's spiritual practice in Zen. By spending time in solitude or community in natural environments, individuals can simplify their lives, cultivate a sense of connection with their true nature, and discover a deeper reality that transcends the fleeting moments of life. This approach to wilderness Dharma practice aims to create a sense of renewal, community, and connection with the natural world, allowing participants to explore their spiritual lives in a way that is both personal and communal.", "themes": ["Interconnection", "Sangha"], "texts": [], "minutes": 48}, {"id": "2010-06-02 - James Baraz and Shoshana Alexander - Awakening Joy", "title": "Awakening Joy", "speaker": "James Baraz and Shoshana Alexander", "date": "2010-06-02", "series": "", "summary": "The talk emphasizes the importance of cultivating well-being and ease in our daily lives, rather than just going through the motions or feeling obligated to do so. It suggests that even small, subtle shifts in our approach can lead to significant positive change - for example, being open to new experiences like meditation, which may initially feel unappealing but ultimately bring benefits. The speaker encourages us to be mindful of our own desires and interests, rather than simply following societal norms or expectations. By doing so, we can develop greater self-awareness and kindness towards ourselves, leading to a more authentic and fulfilling life.", "themes": ["Acceptance"], "texts": [], "minutes": 10}, {"id": "2010-05-27 - Nomon Tim Burnett - Mindfulness Seminar 6", "title": "Mindfulness Seminar 6", "speaker": "Nomon Tim Burnett", "date": "2010-05-27", "series": "Mindfulness Seminar", "summary": "The speaker's main teaching emphasizes the importance of understanding and accepting the concept of \"no self\" (anatta), which means recognizing that our sense of self is a temporary and conditioned fabrication. Rather than trying to deny or eliminate it, we should approach ourselves with softness and non-clinging, allowing us to be open to whatever arises without attachment or resistance. By embracing this understanding, we can cultivate equanimity and find calmness and liberation in the present moment, even in the face of difficult emotions or challenges.", "themes": ["Acceptance", "Impermanence", "No-self", "Suffering"], "texts": ["Heart Sutra"], "minutes": 56}, {"id": "2010-05-19 - Nomon Tim Burnett - Mindfulness Seminar 5", "title": "Mindfulness Seminar 5", "speaker": "Nomon Tim Burnett", "date": "2010-05-19", "series": "Mindfulness Seminar", "summary": "The speaker emphasizes the importance of cultivating mindfulness by being present with one's feelings, body sensations, and thoughts, rather than getting caught up in analysis or intellectualization. This involves taking responsibility for one's own practice, staying with difficult experiences, and trusting one's intuition to guide the way. By doing so, one can develop greater awareness, clarity, and freedom from mental activity, allowing for a more authentic and peaceful experience of life.", "themes": ["Impermanence"], "texts": [], "minutes": 64}, {"id": "2010-05-12 - Nomon Tim Burnett - Mindfulness Seminar 4", "title": "Mindfulness Seminar 4", "speaker": "Nomon Tim Burnett", "date": "2010-05-12", "series": "Mindfulness Seminar", "summary": "The talk's main teaching emphasizes the importance of cultivating awareness of our feelings, or vedana, as a way to bring mindfulness into daily life. By paying attention to how we react to different experiences, we can begin to see through patterns of desire and aversion that contribute to suffering. This practice involves developing a baseline feeling tone beneath emotions and thoughts, allowing us to interact with our experiences in a more skillful and aware way.", "themes": ["Interconnection", "Suffering"], "texts": [], "minutes": 52}, {"id": "2010-05-05 - Nomon Tim Burnett - Mindfulness Seminar 3", "title": "Mindfulness Seminar 3", "speaker": "Nomon Tim Burnett", "date": "2010-05-05", "series": "Mindfulness Seminar", "summary": "The main teaching of the Soto Zen dharma talk emphasizes the importance of cultivating mindfulness in everyday life by being fully present with whatever task or situation you're in at that moment. This involves not just sitting in stillness, but also applying awareness and attention to all aspects of your daily experiences, from simple tasks like driving or listening to a child to more complex activities. By doing so, you can develop a sense of respect for your life and its various aspects, and maintain a clear and present awareness even as you move between different postures or activities.", "themes": [], "texts": [], "minutes": 24}, {"id": "2010-04-21 - Nomon Tim Burnett - Mindfulness Seminar 1", "title": "Mindfulness Seminar 1", "speaker": "Nomon Tim Burnett", "date": "2010-04-21", "series": "Mindfulness Seminar", "summary": "The talk's main teaching emphasizes the importance of cultivating mindfulness in everyday life by paying attention to the present moment without judgment or distraction. This can be done through simple exercises like focusing on one raisin, observing body sensations, or listening to guided recordings, allowing us to tap into our core roots and experience a deeper sense of awareness and understanding. By practicing mindfulness, we can develop greater self-awareness, reduce mental chatter, and improve both physical and mental well-being.", "themes": [], "texts": [], "minutes": 79}, {"id": "2010-04-21 - Nomon Tim Burnett - Mindfulness Seminar 2", "title": "Mindfulness Seminar 2", "speaker": "Nomon Tim Burnett", "date": "2010-04-21", "series": "Mindfulness Seminar", "summary": "The main teaching of this Soto Zen dharma talk emphasizes the importance of cultivating mindfulness by simply paying attention to the present moment without trying to change or fix anything. This involves noticing physical sensations, breathing, and emotions without judgment, allowing participants to settle into the present and develop greater awareness of their bodies and experiences. By practicing mindfulness in a non-judgmental way, individuals can gain a deeper understanding of themselves and the world around them, leading to greater clarity and insight in daily life.", "themes": ["Impermanence"], "texts": [], "minutes": 50}, {"id": "2010-04-14 - Nomon Tim Burnett - The Second Arrow", "title": "The Second Arrow", "speaker": "Nomon Tim Burnett", "date": "2010-04-14", "series": "", "summary": "The talk's main teaching emphasizes the importance of observing our experiences without judgment or attachment, allowing us to see things as they are rather than getting caught up in our conditioned thoughts and reactions. By recognizing this process, we can learn to let go of suffering caused by our reactivity and cultivate greater freedom and understanding. This involves developing mindfulness practices such as zazen and carefully considering teachings on faith, with the goal of creating a more authentic and peaceful way of living.", "themes": ["Impermanence", "Suffering"], "texts": [], "minutes": 69}, {"id": "2010-03-24 - Yuzan Nancy Welch - Tasting the Flavor", "title": "Tasting the Flavor", "speaker": "Yuzan Nancy Welch", "date": "2010-03-24", "series": "", "summary": "The speaker's main teaching is that even in the midst of life's challenges and mundane routines, we have the opportunity to cultivate gratitude and appreciation for the present moment. By recognizing that things can lose their flavor over time, we can learn to approach our experiences with curiosity and compassion, rather than trying to escape or numb them. This involves embracing the beauty in difficult situations, such as illness or boredom, and finding ways to add flavor back into our lives when they become stale.", "themes": ["Acceptance", "Gratitude", "Suffering"], "texts": [], "minutes": 45}, {"id": "2010-03-10 - Nomon Tim Burnett - Jukai and Susho Rituals", "title": "Jukai and Susho Rituals", "speaker": "Nomon Tim Burnett", "date": "2010-03-10", "series": "", "summary": "The speaker emphasized that true spiritual growth and understanding can only be achieved through a deep commitment to one's own practice, rather than seeking external validation or recognition within the community. They encouraged students to focus on skillfulness and dedication in their daily sitting meditation and other activities, rather than comparing themselves to others or striving for special status. By doing so, individuals can cultivate a sense of belonging and connection with others while also staying true to their own unique path.", "themes": ["Sangha"], "texts": [], "minutes": 31}, {"id": "2010-03-10 - Nomon Tim Burnett - Non Abiding", "title": "Non Abiding", "speaker": "Nomon Tim Burnett", "date": "2010-03-10", "series": "", "summary": "The talk's main teaching emphasizes the importance of embracing simplicity in spiritual practice, allowing us to release our need for structures and concepts that create suffering. By letting go of dualistic thinking and perceiving reality as it truly is, we can directly experience the present moment without conceptual elaboration, revealing a simple and interconnected world where everything is empty of inherent existence. This approach requires balance, as it must be tempered with a systematic understanding of the Buddha's teachings to avoid falling into extremes.", "themes": ["Emptiness", "No-self"], "texts": [], "minutes": 31}, {"id": "2010-03-06 - Reizan Bob Penny - Master Ma is Unwell", "title": "Master Ma is Unwell", "speaker": "Reizan Bob Penny", "date": "2010-03-06", "series": "", "summary": "The speaker's dharma talk emphasizes the importance of embracing grief and sadness as a natural part of life, rather than trying to avoid or escape them. By confronting our own history of grief and accepting both the pain and the beauty that come with it, we can find intimacy and healing through shared concern and connection with others. This acceptance is not about avoiding difficult emotions, but about surrendering to them in a way that allows us to heal and transform.", "themes": ["Acceptance", "Impermanence", "Suffering"], "texts": [], "minutes": 28}, {"id": "2010-03-05 - Nomon Tim Burnett - Bridge to Mindfulness", "title": "Bridge to Mindfulness", "speaker": "Nomon Tim Burnett", "date": "2010-03-05", "series": "", "summary": "The talk emphasizes the importance of looking beyond our preconceived notions and expectations to discover true understanding. It encourages us to approach life with a sense of simplicity and universality, just like the ordinary log bridge that can accommodate all beings. By doing so, we can cultivate awareness and clarity in our daily lives through mindfulness practices, such as body scan meditation and focusing on the breath, allowing us to be present in the moment and let go of distractions.", "themes": [], "texts": [], "minutes": 32}, {"id": "2010-02-27 - Reizan Bob Penny - Grief Class 4", "title": "Grief Class 4", "speaker": "Reizan Bob Penny", "date": "2010-02-27", "series": "Grief Class", "summary": "The talk emphasizes that healing from grief and finding hope for the future requires acknowledging our interconnectedness with others and the world around us. Rather than isolating ourselves or focusing solely on individual emotional pain, we need to address the collective suffering of humanity and the Earth as a whole. This involves recognizing the global nature of our problems, such as climate change, and working together towards a more compassionate and wise future.", "themes": ["Interconnection", "Social engagement", "Suffering"], "texts": [], "minutes": 27}, {"id": "2010-02-20 - Reizan Bob Penny - Grief Class 3", "title": "Grief Class 3", "speaker": "Reizan Bob Penny", "date": "2010-02-20", "series": "Grief Class", "summary": "The speaker discusses how Buddhism offers a framework for healing after loss by acknowledging the interconnectedness of all things and the impermanence of life. They note that individuals may adopt various \"grieving styles\" in response to their loss, such as numbing or memorializing, but also encourage exploring other approaches like stability and normalization. By embracing the complexity of grief and incorporating different healing styles, one can cultivate greater awareness, acceptance, and ultimately, liberation from the pain of loss.", "themes": ["Impermanence", "Suffering"], "texts": [], "minutes": 33}, {"id": "2010-02-13 - Reizan Bob Penny - Wayseeking Mind Part 1", "title": "Wayseeking Mind Part 1", "speaker": "Reizan Bob Penny", "date": "2010-02-13", "series": "Wayseeking Mind (Reizan Bob Penny)", "summary": "The speaker shares their personal journey of self-discovery and spiritual exploration, reflecting on how childhood experiences shaped their perspective on life, death, and the human condition. Growing up in Oregon, they struggled with traditional teachings and found solace in nature and running, which helped them develop a sense of style and creativity. Through meditation and reading Buddhist texts, they began to find meaning and purpose in life, ultimately developing a more consistent practice that allowed them to cultivate a deeper understanding of themselves and the world around them.", "themes": ["Impermanence"], "texts": [], "minutes": 49}, {"id": "2010-02-13 - Reizan Bob Penny - Wayseeking Mind Part 2", "title": "Wayseeking Mind Part 2", "speaker": "Reizan Bob Penny", "date": "2010-02-13", "series": "Wayseeking Mind (Reizan Bob Penny)", "summary": "The speaker's talk explores the complexities of spiritual growth and the importance of embracing imperfection and uncertainty in one's journey. They reflect on how life's challenges, including personal struggles, loss, and trauma, have shaped their path and helped them develop a deeper understanding of themselves and the world around them. Through sharing stories of resilience, kindness, and transformation, the speaker invites listeners to approach their own spiritual journeys with compassion, curiosity, and an openness to the unknown.", "themes": ["Impermanence", "Suffering"], "texts": [], "minutes": 60}, {"id": "2010-02-06 - Reizan Bob Penny - Grief Class 2", "title": "Grief Class 2", "speaker": "Reizan Bob Penny", "date": "2010-02-06", "series": "Grief Class", "summary": "The speaker's talk invites listeners to explore the true nature of grief by confronting and embracing their underlying emotions rather than trying to numb or avoid them. Through this process, they discovered that true healing comes from surrendering into one's pain and fears, rather than trying to suppress them. By doing so, we can release resistance and self-protection, making space for a deeper sense of connection and compassion with ourselves and others, ultimately leading to a more open and loving heart.", "themes": ["Compassion", "Suffering", "Vulnerability"], "texts": [], "minutes": 34}, {"id": "2010-01-30 - Reizan Bob Penny - Grief Class 1", "title": "Grief Class 1", "speaker": "Reizan Bob Penny", "date": "2010-01-30", "series": "Grief Class", "summary": "The speaker's talk focuses on the importance of acknowledging and working through grief, rather than trying to suppress or avoid it. They encourage individuals to recognize that grief is a unique experience for each person, and by being aware of one's own process, they can better manage difficult emotions. By exploring their grief in a safe and reflective space, individuals can gain a deeper understanding of themselves and begin the healing process, rather than trying to fit into societal expectations or avoid painful emotions.", "themes": ["Impermanence", "Suffering"], "texts": [], "minutes": 32}, {"id": "2010-01-23 - Reizan Bob Penny - Wayseeking Mind", "title": "Wayseeking Mind", "speaker": "Reizan Bob Penny", "date": "2010-01-23", "series": "", "summary": "The speaker shares how their personal experiences of struggle, loss, and self-discovery ultimately led them to find guidance in Buddhism and Zen practice, allowing them to cultivate a deeper understanding of the impermanence of life and the importance of embracing the present moment. Through sharing stories from their childhood, adolescence, and young adulthood, they reveal how these formative experiences continue to shape their perspective on life today. By exploring themes of community, identity, and human connection, the speaker offers a personal and relatable account of how Zen practice can help individuals find meaning, purpose, and inner peace in an ever-changing world.", "themes": ["Impermanence", "Suffering"], "texts": [], "minutes": 64}, {"id": "2010-01-13 - Nomon Tim Burnett - Preparing for Practice Period", "title": "Preparing for Practice Period", "speaker": "Nomon Tim Burnett", "date": "2010-01-13", "series": "", "summary": "The speaker invites the group to reflect on how to integrate mindfulness into daily life by exploring what kind of committed practice each individual can commit to, drawing from their experience teaching meditation to veterans who found it profoundly healing. They share stories about Bodhidharma's student Uweka, highlighting the importance of steady and patient presence, humility, and radical acceptance in cultivating a strong practice. The speaker encourages discussion and exploration during practice period on how to create space for mindfulness in daily life, considering new approaches and attitudes that can benefit both individuals and their communities.", "themes": ["Acceptance", "Sangha"], "texts": [], "minutes": 38}, {"id": "2010-01-10 - Nomon Tim Burnett - Life is Not A Featurette", "title": "Life is Not A Featurette", "speaker": "Nomon Tim Burnett", "date": "2010-01-10", "series": "", "summary": "The talk emphasizes the importance of embracing our true nature through mindfulness practice, rather than trying to change or escape ourselves. By letting go of idealized notions of happiness and success, we can develop a deeper acceptance of ourselves and our experiences, allowing us to work with our thoughts and emotions in a more authentic way. This approach is reflected in the stories of early Zen masters, who embodied humility, devotion, and intimacy in their relationships and practice, and is exemplified by the simple yet powerful practice of Zazen, which allows for healing to happen without forced control or effort.", "themes": ["Acceptance", "Sangha"], "texts": [], "minutes": 46}, {"id": "2009-12-23 - Seishu John Wiley - Continuous Practice", "title": "Continuous Practice", "speaker": "Seishu John Wiley", "date": "2009-12-23", "series": "", "summary": "The speaker emphasizes the importance of embracing impermanence and letting go of attachments during Zen meditation, encouraging practitioners to focus on staying present and grounded in the moment rather than seeking specific states or outcomes. This approach allows for a deeper connection with the universe and brings balance to oneself and the world. By cultivating mindfulness and attention in daily life, we can create positive ripples that impact those around us, just as Dr. Benjamin Spock's actions were inspired by a woman standing alone in the rain.", "themes": ["Interconnection", "Suffering"], "texts": [], "minutes": 23}, {"id": "2009-12-09 - Nomon Tim Burnett - The Geometry of Self", "title": "The Geometry of Self", "speaker": "Nomon Tim Burnett", "date": "2009-12-09", "series": "", "summary": "The talk's main teaching emphasizes the importance of recognizing our mistaken understanding of reality and cultivating awareness of our own patterns and tendencies, which often cause suffering. By letting go of our need for reassurance and social interaction, we can develop greater insight into ourselves and others, leading to liberation from intense emotions and a more authentic way of being. This involves embracing the impermanence of all things, including our sense of self, and finding freedom in the present moment, rather than seeking it in external forms or structures.", "themes": ["No-self", "Suffering"], "texts": [], "minutes": 51}, {"id": "2009-12-05 - Nomon Tim Burnett - Rohatsu 2009", "title": "Rohatsu 2009", "speaker": "Nomon Tim Burnett", "date": "2009-12-05", "series": "", "summary": "The speaker emphasizes the importance of letting go of control and trying to organize one's mind during a sesshin experience, instead trusting that everything will unfold naturally. They encourage practitioners to focus on touching the heart of the matter, rather than getting caught up in thoughts or distractions. By doing so, they can find freedom from suffering and cultivate greater understanding, compassion, and awareness.", "themes": ["No-self", "Suffering"], "texts": [], "minutes": 52}, {"id": "2009-11-11 - Nomon Tim Burnett - All is Burning", "title": "All is Burning", "speaker": "Nomon Tim Burnett", "date": "2009-11-11", "series": "", "summary": "The talk's main teaching is that true freedom from suffering doesn't come from being detached or uninvolved with the world, but rather from understanding and embracing our interconnectedness with all things. The Buddha's teachings encourage us to cultivate a sense of awe and wonder at the complexity and impermanence of life, rather than trying to suppress or deny it. By letting go of our narrow, separate views of the world, we can develop a more nuanced and compassionate understanding of reality, which allows us to engage with the world in a more loving and engaged way. This means embracing the beauty and fragility of life, including its impermanence and potential for suffering, rather than trying to escape or avoid it.", "themes": ["Impermanence", "Interconnection", "Suffering"], "texts": [], "minutes": 49}, {"id": "2009-10-17 - Nomon Tim Burnett - All Things Are our Teacher", "title": "All Things Are our Teacher", "speaker": "Nomon Tim Burnett", "date": "2009-10-17", "series": "", "summary": "The speaker's main teaching is that true freedom and happiness come not from trying to fix or avoid life's challenges, but from creating space for transformation to occur. This involves letting go of attachments and aversions, cultivating a sense of neutrality and openness, and embracing the present moment with an open heart and mind. By doing so, we can learn from difficult experiences, find freedom in our relationships with others, and discover a deeper sense of purpose and responsibility in our lives.", "themes": ["Acceptance", "Interconnection", "No-self"], "texts": [], "minutes": 46}, {"id": "2009-09-23 - Yuzan Nancy Welch - Zen and Conflict", "title": "Zen and Conflict", "speaker": "Yuzan Nancy Welch", "date": "2009-09-23", "series": "", "summary": "The speaker's main teaching is that when we're in conflict with others, our reactions are often driven by fear and a desire to control or fix the situation, which only leads to further conflict. Instead, they suggest focusing on understanding the present moment and the other person's intentions, rather than getting caught up in strong emotions or trying to change them. By letting go of our need to correct others and instead approaching the situation with curiosity and compassion, we can respond more thoughtfully and peacefully, even in difficult situations.", "themes": ["Ethics", "Sangha"], "texts": [], "minutes": 18}, {"id": "2009-09-09 - Nomon Tim Burnett - Rethinking Joy", "title": "Rethinking Joy", "speaker": "Nomon Tim Burnett", "date": "2009-09-09", "series": "", "summary": "The speaker's main teaching emphasizes the importance of letting go of expectations and striving for perfection, instead embracing the natural unfolding of practice and recognizing one's own limitations and imperfections. By cultivating humility, taking refuge in community, and committing to a path that is both gentle and urgent, we can find joy in the process of awakening rather than getting caught up in ego or competition. This involves releasing attachment to the self and embracing emptiness, allowing us to experience joy and liberation as we let go of our attachments and find freedom in being present with our experiences.", "themes": ["Acceptance", "No-self", "Sangha"], "texts": [], "minutes": 48}, {"id": "2009-08-12 - Nomon Tim Burnett - The Fruits of Practice", "title": "The Fruits of Practice", "speaker": "Nomon Tim Burnett", "date": "2009-08-12", "series": "", "summary": "Here is a summary paragraph summarizing the main teaching of the Soto Zen dharma talk:\n\nThe speaker emphasizes the importance of cultivating steadiness, mindfulness, and devotion in daily life through regular Zazen practice, even when motivation or distractions are lacking. They draw inspiration from Sojun Mel Weitsman's example of ordinary, straightforward Zen practice that embodies humility, openness, and a willingness to work with difficulties. By embracing this approach, we can develop qualities such as inner peace, faith, and warmth, and find joy in simple things like walking, ultimately leading to a more authentic and fulfilling life.", "themes": ["Acceptance", "Sangha"], "texts": [], "minutes": 52}, {"id": "2009-08-07 - Nomon Tim Burnett - Metta Sutta 4", "title": "Metta Sutta 4", "speaker": "Nomon Tim Burnett", "date": "2009-08-07", "series": "Metta Sutta", "summary": "The speaker discusses how cultivating loving-kindness meditation can help shift one's perspective on self and reality, allowing for a more open and accepting approach to life. By practicing metta, or loving-kindness, individuals can begin to let go of attachments and ego, and instead cultivate a sense of boundless appreciation and equanimity towards all aspects of existence. This practice can lead to a deeper understanding of the nature of consciousness and individual identity, ultimately allowing for greater freedom from suffering and a more awakened way of being.", "themes": ["Acceptance", "Compassion", "No-self"], "texts": ["Heart Sutra", "Metta Sutta"], "minutes": 62}, {"id": "2009-08-01 - Nomon Tim Burnett - Steadfast and Patient", "title": "Steadfast and Patient", "speaker": "Nomon Tim Burnett", "date": "2009-08-01", "series": "", "summary": "The speaker emphasizes that true Zen practice is simple and fundamental, focusing on turning towards the present moment without attachment or expectation. By studying the qualities of long-time practitioners like Sojun Roshi, who embodied humility, steadiness, and endurance in their practice, we can gain insight into the nature of true practice. This approach encourages us to let go of external goals and expectations, instead cultivating contentment and sharing that gift with others through our own direct experience.", "themes": ["Acceptance", "Sangha"], "texts": [], "minutes": 41}, {"id": "2009-07-31 - Nomon Tim Burnett - Metta Sutta 2", "title": "Metta Sutta 2", "speaker": "Nomon Tim Burnett", "date": "2009-07-31", "series": "Metta Sutta", "summary": "The main teaching of the Soto Zen dharma talk emphasizes the importance of humility, awareness, and freedom in spiritual practice. Even in ideal circumstances, spiritual growth can be challenging due to one's own limitations and tendencies. By acknowledging these limitations and approaching life with a sense of clarity and openness, practitioners can cultivate genuine connection, understanding, and well-being, both for themselves and others.", "themes": ["Compassion"], "texts": ["Metta Sutta"], "minutes": 47}, {"id": "2009-07-31 - Nomon Tim Burnett - Metta Sutta 3", "title": "Metta Sutta 3", "speaker": "Nomon Tim Burnett", "date": "2009-07-31", "series": "Metta Sutta", "summary": "The Soto Zen dharma talk emphasizes the importance of cultivating loving-kindness (metta) as a practice in itself, rather than just a set of instructions. The teacher encourages listeners to approach metta with an open heart and mind, and to apply its principles in daily life, particularly towards those who may be overlooked or difficult to relate to. By doing so, individuals can cultivate a boundless sense of love and kindness, leading to greater happiness, safety, and inner peace for themselves and others.", "themes": ["Compassion"], "texts": ["Metta Sutta"], "minutes": 55}, {"id": "2009-07-10 - Nomon Tim Burnett - Metta Sutta 1", "title": "Metta Sutta 1", "speaker": "Nomon Tim Burnett", "date": "2009-07-10", "series": "Metta Sutta", "summary": "The teacher explores the Metta Sutta, an ancient Buddhist text that emphasizes cultivating universal love and affection beyond condition, as a way to overcome defilements and realize one's natural goodness and wholeness. This practice is seen as an antidote to complacency and encourages individuals to approach life with humility, prudence, and contentment, letting go of desires for external validation. By embracing these qualities, practitioners can cultivate mindfulness and compassion, even in the midst of challenging situations.", "themes": ["Compassion", "Ethics"], "texts": ["Metta Sutta"], "minutes": 56}, {"id": "2009-07-08 - Nomon Tim Burnett - Metta Sutta 1", "title": "Metta Sutta 1", "speaker": "Nomon Tim Burnett", "date": "2009-07-08", "series": "Metta Sutta", "summary": "The speaker's talk on the Metta Sutta emphasizes that true loving-kindness is not just about following rules or rituals, but rather about cultivating awareness and recognizing our own motivations. The Buddha taught that practicing metta can be a powerful way to break free from suffering and disease, and it involves examining our actions and thoughts to identify areas where we may be hiding behind justification or excuses. By turning towards self-reflection and improvement, we can develop a positive mindset towards all beings and find greater contentment and peace in life.", "themes": ["Compassion", "Ethics"], "texts": ["Metta Sutta"], "minutes": 58}, {"id": "2009-06-10 - Nomon Tim Burnett - Towards Wholeness", "title": "Towards Wholeness", "speaker": "Nomon Tim Burnett", "date": "2009-06-10", "series": "", "summary": "The speaker emphasizes that spiritual growth and self-realization cannot be achieved by ignoring fundamental human needs, such as safety, love, and belonging. Rather, these needs must be acknowledged and addressed before one can focus on spiritual practice. By recognizing and meeting our basic needs, we create space for spiritual growth and self-awareness to emerge, rather than trying to suppress or avoid pain and suffering.", "themes": ["Buddha-nature", "Impermanence", "Suffering"], "texts": [], "minutes": 61}, {"id": "2009-05-29 - Nomon Tim Burnett - Teachers and Students 2", "title": "Teachers and Students 2", "speaker": "Nomon Tim Burnett", "date": "2009-05-29", "series": "Teachers and Students", "summary": "The talk's main teaching emphasizes the importance of direct experience and practice in understanding the Zen tradition, rather than relying solely on concepts or reading about it. It encourages students to appreciate the effort and continuity of their own practice, as well as recognizing that teachers are human beings who can be learned from while also taking responsibility for one's own life. This approach values simplicity, dignity, and quiet presence in teaching and learning, and seeks to overcome traditional barriers such as gender exclusions in Zen ordination.", "themes": ["Sangha"], "texts": [], "minutes": 42}, {"id": "2009-05-27 - Nomon Tim Burnett - Teachers and Students 1", "title": "Teachers and Students 1", "speaker": "Nomon Tim Burnett", "date": "2009-05-27", "series": "Teachers and Students", "summary": "The speaker reflects on the importance of humility and simplicity in teaching and practice, drawing inspiration from their teacher Sojun Mel Weitsman's unassuming yet transformative approach to Zen. Mel's emphasis on physical presence, quiet contemplation, and constancy in practice has had a profound impact on the speaker's own understanding of the tradition, encouraging them to focus on lived experience and devotion to simple practice rather than seeking external explanations or perfection from their teachers. This approach allows for a deeper connection with the Zen tradition and its emphasis on personal growth and transformation through everyday life.", "themes": ["Sangha"], "texts": [], "minutes": 31}, {"id": "2009-05-13 - Nomon Tim Burnett - This is Us", "title": "This is Us", "speaker": "Nomon Tim Burnett", "date": "2009-05-13", "series": "", "summary": "The talk's main teaching is that true freedom and contentment come from embracing our interconnectedness with others and the world around us, rather than trying to control or separate ourselves from it. By letting go of our attachment to a fixed sense of self and instead cultivating mindfulness and awareness, we can find joy and happiness in life, even in difficult times. This involves being present with our bodies and emotions, seeking support from others when needed, and embracing the uncertainty and impermanence of life.", "themes": ["Interconnection", "No-self", "Vulnerability"], "texts": ["Diamond Sutra"], "minutes": 47}, {"id": "2009-04-01 - Nomon Tim Burnett - Lojong Teaching 3", "title": "Lojong Teaching 3", "speaker": "Nomon Tim Burnett", "date": "2009-04-01", "series": "Lojong Teaching", "summary": "The main teaching of tonight's Soto Zen dharma talk emphasizes the importance of cultivating a mindful and humble approach to life, letting go of ego-driven motivations and conditioning. By practicing mindfulness, developing bodhicitta, and focusing on benefiting all beings without exception, individuals can overcome their habitual patterns and find space in their lives. This involves acknowledging our limitations, taking responsibility for our actions, and interacting with the world in a more open and compassionate way.", "themes": ["Acceptance", "Compassion"], "texts": [], "minutes": 76}, {"id": "2009-03-25 - Nomon Tim Burnett - Lojong Teaching 2", "title": "Lojong Teaching 2", "speaker": "Nomon Tim Burnett", "date": "2009-03-25", "series": "Lojong Teaching", "summary": "The main teaching of this Soto Zen dharma talk emphasizes the importance of cultivating mindfulness, bodhicitta, and self-awareness in daily life. By recognizing the impermanence of experiences and the interconnectedness of all things, we can develop a more compassionate and intelligent approach to reality. This involves taking responsibility for our actions, trusting our own intelligence, and embracing qualities like humility, humor, and self-trust, which allow us to navigate challenging situations with greater ease and wisdom.", "themes": ["Acceptance", "Compassion", "Suffering"], "texts": [], "minutes": 51}, {"id": "2009-03-18 - Nomon Tim Burnett - Lojong Teaching 1", "title": "Lojong Teaching 1", "speaker": "Nomon Tim Burnett", "date": "2009-03-18", "series": "Lojong Teaching", "summary": "The main teaching of the Soto Zen dharma talk emphasizes the importance of cultivating a mind that can approach life with kindness, compassion, and acceptance, rather than resistance or aversion. By practicing mindfulness and letting go of fixed notions, we can reduce suffering and increase freedom, particularly in times of turmoil. This involves taking responsibility for our actions, embracing adversity, and finding ways to connect with others and show love and care, even when faced with challenges.", "themes": ["Compassion", "Gratitude", "Suffering"], "texts": [], "minutes": 66}, {"id": "2009-03-07 - Nomon Tim Burnett - Pacing the Cage", "title": "Pacing the Cage", "speaker": "Nomon Tim Burnett", "date": "2009-03-07", "series": "", "summary": "The main teaching of the talk emphasizes the importance of experiencing life honestly and fully, rather than just trying to achieve new ideas or solutions. This involves feeling our real feelings, including pain and suffering, and learning to accept and understand our conditioned human experiences. By doing so, we can find a sense of solid ground and dignity in our imperfections, and awaken to a deeper reality that includes compassion, wisdom, and the beauty of life's complexity.", "themes": ["Acceptance", "Suffering", "Vulnerability"], "texts": [], "minutes": 47}, {"id": "2008-07-09 - Nomon Tim Burnett - Ambition", "title": "Ambition", "speaker": "Nomon Tim Burnett", "date": "2008-07-09", "series": "", "summary": "The teacher shares a personal story of re-examining their relationship with ambition and career, realizing they had been holding onto a non-career identity for too long. This realization has helped them see the importance of learning to let go of ambition and work with it more skillfully, rather than being tightly attached to it. By doing so, they aim to cultivate humility, adaptability, and a greater sense of freedom in their life, allowing them to approach challenges with a fresh perspective and a deeper understanding of themselves.", "themes": ["Acceptance", "No-self", "Suffering"], "texts": [], "minutes": 49}, {"id": "2008-03-12 - Nomon Tim Burnett - Vimalakirti Nonduality", "title": "Vimalakirti Nonduality", "speaker": "Nomon Tim Burnett", "date": "2008-03-12", "series": "", "summary": "The talk explores the concept of non-duality in Zen practice, highlighting its importance in transcending dualistic thinking and conceptual knots. Through a koan from the \"Vimalakirti Sutra,\" the speaker illustrates that true understanding and freedom can only be achieved by acknowledging and letting go of ideals and seeking silence and stillness instead. This approach allows for the direct experience of non-duality, which is not about achieving a specific state or goal, but rather about cultivating awareness in everyday life.", "themes": ["Emptiness", "Sangha", "Suffering"], "texts": ["Blue Cliff Record"], "minutes": 54}, {"id": "2008-02-23 - Red Pine - Heart Sutra", "title": "Heart Sutra", "speaker": "Red Pine", "date": "2008-02-23", "series": "", "summary": "The talk's main teaching is that true freedom and awakening come not from intellectual understanding or emotional transformation alone, but from transcending our conceptual thinking and ego boundaries. By letting go of our attachments to things and ourselves, we can see through the illusion of separation and discover a deeper unity and interconnectedness with all phenomena. This allows us to experience reality in its pure form, unfiltered by our dualistic perceptions, and ultimately reveals our true nature as it is.", "themes": ["Emptiness"], "texts": ["Diamond Sutra", "Heart Sutra"], "minutes": 66}, {"id": "2008-02-10 - John Bailes - Wayseeking Mind", "title": "Wayseeking Mind", "speaker": "John Bailes", "date": "2008-02-10", "series": "", "summary": "The speaker reflects on how their life has been shaped by various experiences and relationships that have contributed to their understanding of themselves and the world. They share stories about their journey, including being involved in an accident, exploring alternative interests like poetry and philosophy, and meeting influential figures in Buddhism, which ultimately led them to discover Zen Buddhism and find a sense of fulfillment and transformation through their practice. Through these experiences, they have come to understand that their path has been one of opening to love, heart, gratitude, and generosity, and that this experience is always present, but only now is it fully accessible.", "themes": ["Gratitude", "Impermanence", "Interconnection"], "texts": ["Diamond Sutra"], "minutes": 54}, {"id": "2007-11-13 - Zoketsu Norman Fischer - Ritual 2", "title": "Ritual 2", "speaker": "Zoketsu Norman Fischer", "date": "2007-11-13", "series": "Ritual (2007 Loon Lake retreat)", "summary": "In this Soto Zen dharma talk, the main teaching emphasizes the transformative power of silence and mindfulness practice. Rather than seeing silence as an absence of sound, it's seen as a positive and powerful experience that allows us to tap into ultimate safety, healing, and peace. By engaging fully with Zazen and participating in rituals like prostrations and incense offerings, we can connect with the Buddha's awakening and cultivate goodness in our lives, ultimately finding freedom from suffering and compassion for ourselves and others.", "themes": ["Acceptance", "Buddha-nature", "Sangha"], "texts": [], "minutes": 35}, {"id": "2007-11-12 - Zoketsu Norman Fischer - Ritual 1", "title": "Ritual 1", "speaker": "Zoketsu Norman Fischer", "date": "2007-11-12", "series": "Ritual (2007 Loon Lake retreat)", "summary": "The speaker suggests that our daily lives, including our meditation practice, are actually rituals that can help us connect with ourselves and the world on a deeper level. Rather than seeing these practices as a means to an end or a way to achieve some external goal, we should approach them as a way to cultivate awareness, inner peace, and compassion for ourselves and others. By embracing our daily rituals in this way, we can tap into a deeper reality and live more mindfully, bringing benefit not just to ourselves, but also to those around us.", "themes": ["Gratitude", "Interconnection", "Sangha"], "texts": [], "minutes": 48}, {"id": "2007-07-12 - Nomon Tim Burnett - Dongshans Hot and Cold", "title": "Dongshan's Hot and Cold", "speaker": "Nomon Tim Burnett", "date": "2007-07-12", "series": "", "summary": "The main teaching of this Soto Zen dharma talk is that true freedom and liberation come from embracing our own preferences and desires, rather than trying to escape or control them. By fully experiencing and accepting what arises in life, we can burn up or freeze in a way that allows us to live more authentically and without resistance. This approach requires letting go of judgment and attachment, and instead trusting in the mind's ability to straighten itself out, allowing us to meet each moment with greater ease and awareness.", "themes": ["Acceptance", "Suffering"], "texts": ["Heart Sutra"], "minutes": 39}, {"id": "2007-06-22 - Zoketsu Norman Fischer - Land of the Dead", "title": "Land of the Dead", "speaker": "Zoketsu Norman Fischer", "date": "2007-06-22", "series": "", "summary": "The talk explores the importance of confronting our own darkness and imperfections as a means of finding peace and resolution, using stories from Homer's Odyssey and personal experiences to illustrate this point. It highlights that death is not an escape but rather an unknown limit point of life, and that visiting the \"land of the dead\" can be a transformative experience that allows us to see our lives and ourselves in a new light. By facing our fears and unresolved emotions, we can cultivate compassion, humility, and patience, leading to a deeper understanding of ourselves and the world around us.", "themes": ["Compassion", "Impermanence", "Suffering"], "texts": [], "minutes": 79}, {"id": "2007-06-20 - Shinmon Michael Newton - Mind in Zazen", "title": "Mind in Zazen", "speaker": "Shinmon Michael Newton", "date": "2007-06-20", "series": "", "summary": "The talk highlights that Zen is not about transcending words, but rather finding nourishment in them when they resonate with our hearts and souls. This idea is illustrated through stories of Zen ancestors who turned away from book learning to focus on meditation, and how this approach can help us connect with the present moment. By embracing emptiness and openness, we can express wisdom and compassion for all beings, and find freshness and simplicity in each moment.", "themes": ["Emptiness", "Wisdom"], "texts": ["Diamond Sutra", "Heart Sutra", "Shōbōgenzō"], "minutes": 37}, {"id": "2007-06-16 - Zoketsu Norman Fischer - Sense Perceptions", "title": "Sense Perceptions", "speaker": "Zoketsu Norman Fischer", "date": "2007-06-16", "series": "", "summary": "The speaker's main teaching emphasizes the importance of approaching zazen with an open mind, letting go of desire and ambition, and simply being present in each moment. They encourage us to cultivate a deeper awareness of our senses and experience life fully, without distraction or expectation. By doing so, we can discover that true understanding is not something we grasp intellectually, but rather it arises from our direct experience of the world, unfiltered by our own consciousness.", "themes": ["Interconnection", "No-self", "Suffering"], "texts": [], "minutes": 45}, {"id": "2006-11-04 - Jason Ruvelson - Buddhisms Two Truths QA", "title": "Buddhisms Two Truths Q&A", "speaker": "Jason Ruvelson", "date": "2006-11-04", "series": "", "summary": "The talk's main teaching is that ultimate reality, often referred to as emptiness or dharmakaya, cannot be fully understood through intellectual means alone; it requires direct experience and practice. The speaker emphasizes the importance of not getting caught up in abstract concepts, but rather embracing the actuality of reality, which includes both form and emptiness. They also highlight the value of community (Sangha) as a crucial aspect of Buddhist practice, where individuals come together to support and illuminate each other's understanding, and recognize that Sangha can encompass not just enlightened beings, but all human beings and even all beings in the universe.", "themes": ["Buddha-nature", "Emptiness", "Sangha"], "texts": [], "minutes": 11}, {"id": "2006-11-04 - Jason Ruvelson - Buddhisms Two Truths", "title": "Buddhisms Two Truths", "speaker": "Jason Ruvelson", "date": "2006-11-04", "series": "", "summary": "Meditation in Buddhism is not about achieving a specific state or disconnecting from the world, but rather about developing stability and mindfulness in daily life, allowing one to be present and aware in all aspects of existence. Through practice, this stability can lead to fearlessness, clarity, and a greater understanding of oneself and others. By recognizing our interconnectedness and letting go of conceptual thinking, we can gain a deeper appreciation for the world and develop a more direct experience of reality, leading to relaxation, clarity, and connection with all things.", "themes": ["Buddha-nature", "Emptiness", "No-self"], "texts": [], "minutes": 50}, {"id": "2006-10-21 - Eileen Kiera - The Root of the Matter", "title": "The Root of the Matter", "speaker": "Eileen Kiera", "date": "2006-10-21", "series": "", "summary": "Here is a summary paragraph summarizing the main teaching of the Soto Zen dharma talk:\n\nThe speaker invites the audience to cultivate mindfulness and presence in their daily lives, using meditation as a tool to connect with themselves and the world around them. By focusing on their breath and being fully present, they can transcend individual limitations and experience life as it unfolds in each moment. This practice allows us to tap into our essential nature, which is often lost when we focus on self-judgment or external circumstances, and instead discover a sense of connection and interconnectedness with all things.", "themes": ["Compassion", "Interconnection"], "texts": [], "minutes": 50}, {"id": "2006-10-14 - Nomon Tim Burnett - Wash your Bowl", "title": "Wash your Bowl", "speaker": "Nomon Tim Burnett", "date": "2006-10-14", "series": "", "summary": "The speaker's main teaching emphasizes the importance of cultivating awareness and detachment from our thoughts, emotions, and desires. By paying attention to our inner lives and letting go of distractions, we can find peace and contentment in the present moment. This involves recognizing that our minds are not a single entity, but rather a complex web of sensations and experiences that can be explored and understood through mindfulness and contemplation.", "themes": ["Acceptance", "Suffering"], "texts": [], "minutes": 37}, {"id": "2006-10-07 - John Robinson - Who Suffers When There is No Self QA", "title": "Who Suffers When There is No Self Q&A", "speaker": "John Robinson", "date": "2006-10-07", "series": "", "summary": "The talk emphasizes the importance of cultivating mindfulness, generosity, and non-judgmental awareness in order to overcome defilements like greed, aversion, and delusion. It encourages listeners to experiment with different practices, including meditation, to find what works best for them, and to use these practices as a foundation for further exploration and application in the world. The speaker also highlights the need for balance and moderation in engaging with life, promoting a sense of boundless goodwill towards all beings while avoiding harm and promoting non-judgmental awareness.", "themes": ["Compassion", "No-self", "Social engagement"], "texts": ["Heart Sutra"], "minutes": 30}, {"id": "2006-10-07 - John Robinson - Who Suffers When There is No Self", "title": "Who Suffers When There is No Self", "speaker": "John Robinson", "date": "2006-10-07", "series": "", "summary": "The teacher emphasized the importance of direct experience and personal understanding over external authority or dogma, encouraging participants to explore their own experiences with suffering and the concept of self. They noted that our experience of self is often tied to concepts and strategies that can perpetuate suffering, but that by practicing mindfulness and developing skillful habits, we can let go of these patterns and find freedom from angst and confusion. Ultimately, the goal is to cultivate a state of calm contentment, where one feels satisfied with what they have and doesn't desire anything more, leading to discerning choices and relationships that promote happiness and harmony.", "themes": ["Compassion", "No-self", "Suffering"], "texts": [], "minutes": 36}, {"id": "2006-09-30 - Zoketsu Norman Fischer - Zen and Two Worlds QA", "title": "Zen and Two Worlds Q&A", "speaker": "Zoketsu Norman Fischer", "date": "2006-09-30", "series": "", "summary": "The talk's main teaching emphasizes the importance of understanding and dialogue in addressing complex social issues, particularly when it comes to conflicts rooted in fundamentalist beliefs or extremist ideologies. Rather than resorting to force or simplistic solutions, the speaker suggests that we should strive to comprehend the motivations behind such acts and engage with those who may be driven by these beliefs. By revisiting our traditional understanding of religion and embracing a more inclusive and compassionate approach, Buddhism can play a vital role in fostering tolerance, interfaith dialogue, and a more just society.", "themes": ["Social engagement"], "texts": [], "minutes": 27}, {"id": "2006-09-30 - Zoketsu Norman Fischer - Zen and Two Worlds", "title": "Zen and Two Worlds", "speaker": "Zoketsu Norman Fischer", "date": "2006-09-30", "series": "", "summary": "The speaker reflects on how their personal experiences in Japan challenged their preconceptions about Zen Buddhism, revealing a deeper understanding of its culture and spirituality. They share stories of connecting with ordinary people who embodied the spirit of politeness and quiet courtesy that is at the heart of Japanese culture, highlighting the importance of looking beyond formal aspects to truly understand the tradition. This experience led them to question America's spiritual landscape, where they argue that a lack of a shared spiritual foundation has resulted in American religions becoming either overly ideological or domesticated, losing their healing power.", "themes": ["Social engagement"], "texts": [], "minutes": 49}, {"id": "2004-10 - Zoketsu Norman Fischer - Lotus Sutra 1", "title": "Lotus Sutra 1", "speaker": "Zoketsu Norman Fischer", "date": "2004-10", "series": "Lotus Sutra (2004 seminar)", "summary": "The speaker discusses how the Lotus Sutra teaches that true enlightenment is not something we achieve through our own efforts, but rather it is already present within us as an infinite, timeless reality. This reality is beyond human comprehension and requires compassion and shared understanding between two Buddhas. The Buddha's teachings emphasize using expedient means and parables to convey complex ideas, with the ultimate goal of universal salvation and the enlightenment of all beings.", "themes": ["Buddha-nature"], "texts": ["Lotus Sutra", "Shōbōgenzō"], "minutes": 60}, {"id": "2004-10 - Zoketsu Norman Fischer - Lotus Sutra 2", "title": "Lotus Sutra 2", "speaker": "Zoketsu Norman Fischer", "date": "2004-10", "series": "Lotus Sutra (2004 seminar)", "summary": "The speaker suggests that the Lotus Sutra's teachings on bodhisattvas receiving prophecies of Buddhahood can be seen as a \"skillful means\" - a clever trick or expedient action used to help others escape suffering and find true liberation. This teaching challenges our conventional understanding of truth and reality, much like the intricate social structures of nature, such as that of the weaver ants. By using this approach, the Buddha is able to tailor his teachings to each individual's unique circumstances and growth habits, ultimately revealing a universal Dharma that transcends limitations and conceptual frameworks.", "themes": ["Buddha-nature", "Suffering"], "texts": ["Lotus Sutra"], "minutes": 65}, {"id": "2004-10 - Zoketsu Norman Fischer - Lotus Sutra 3", "title": "Lotus Sutra 3", "speaker": "Zoketsu Norman Fischer", "date": "2004-10", "series": "Lotus Sutra (2004 seminar)", "summary": "The talk highlights the importance of personal motivation in Buddhist practice, particularly in Soto Zen. Rather than trying to achieve enlightenment for the benefit of others, individuals should focus on their own suffering and dissatisfaction as a catalyst for spiritual growth. This approach allows compassion and universal benefit to emerge naturally from one's own awakening, rather than being forced or artificial. By grounding practice in personal experience, individuals can develop a more authentic and spontaneous path to liberation.", "themes": ["Compassion", "Suffering"], "texts": ["Lotus Sutra"], "minutes": 13}, {"id": "2004-10 - Zoketsu Norman Fischer - Lotus Sutra 4", "title": "Lotus Sutra 4", "speaker": "Zoketsu Norman Fischer", "date": "2004-10", "series": "Lotus Sutra (2004 seminar)", "summary": "The talk's main teaching is that even in our spiritual journey, we often don't realize who has been guiding us along the way. The Buddha shares a story from his past life about how he was taught the Lotus Sutra by his teacher Devadatta, who later became his nemesis. This teaches us to look beyond our ego and recognize the role that others have played in our spiritual growth, even if they may not be immediately apparent or pleasant to acknowledge. By understanding this dynamic, we can deepen our appreciation for the interconnectedness of all beings and cultivate a sense of humility and gratitude for the guidance we've received. This insight can help us navigate our own spiritual journeys with greater awareness and compassion.", "themes": [], "texts": ["Lotus Sutra"], "minutes": 4}, {"id": "2004-10 - Zoketsu Norman Fischer - Lotus Sutra 5", "title": "Lotus Sutra 5", "speaker": "Zoketsu Norman Fischer", "date": "2004-10", "series": "Lotus Sutra (2004 seminar)", "summary": "The talk's main teaching is about the importance of humility and respect in spiritual practice, as exemplified by the Bodhisattva Never Disparaging. This bodhisattva's practice of bowing to everyone he met and speaking words of praise and reverence, even to those who were arrogant and powerful, shows that true wisdom and compassion come from a place of humility and recognition of the inherent goodness in all beings. By embracing this approach, we can cultivate a more open and inclusive heart, rather than one marked by arrogance and superiority. This teaching is meant to inspire us to let go of our own ego and pride, and instead, treat others with kindness, respect, and reverence, just as Never Disparaging did.", "themes": ["Buddha-nature"], "texts": ["Lotus Sutra"], "minutes": 5}, {"id": "2003 - Zoketsu Norman Fischer - TATB 3", "title": "TATB 3", "speaker": "Zoketsu Norman Fischer", "date": "2003", "series": "", "summary": "The talk emphasizes the importance of understanding Buddhist teachings as a way to challenge our existing notions of reality, rather than literal descriptions of entities. It suggests that these teachings are meant to be antidotes to our preconceived ideas, which can lead to suffering, and instead aim to reveal a more neutral and liberating truth about the nature of consciousness. By questioning our assumptions about what it means to be human or conscious, we may discover a more authentic understanding that is free from conceptual frameworks and allows for greater freedom and living in the present moment.", "themes": ["Suffering", "Wisdom"], "texts": [], "minutes": 3}, {"id": "2001-05-08 - Zoketsu Norman Fischer - Basic Zen Ethics 2", "title": "Basic Zen Ethics 2", "speaker": "Zoketsu Norman Fischer", "date": "2001-05-08", "series": "Basic Zen Ethics", "summary": "The talk's main teaching emphasizes that true liberation from suffering comes not from trying to escape or avoid our past actions, but rather from embracing them fully, including their difficulties and challenges. This approach involves cultivating a sense of shame and fear of wrongdoing, as well as a desire to avoid causing harm to others, in order to develop wholesome conduct and ultimately achieve freedom from the cycle of suffering. By recognizing that karma is complex and influenced by various factors, we can find joy and meaning in even the most difficult circumstances, rather than trying to escape or deny them.", "themes": ["Acceptance", "Ethics"], "texts": [], "minutes": 34}, {"id": "2001-04-01 - Zoketsu Norman Fischer - Basic Zen Ethics 1", "title": "Basic Zen Ethics 1", "speaker": "Zoketsu Norman Fischer", "date": "2001-04-01", "series": "Basic Zen Ethics", "summary": "The talk's main teaching emphasizes that true understanding of the Buddha comes from allowing awareness to simply be present with each moment, rather than trying to achieve a specific state or outcome in meditation. This approach cultivates a spaciousness and acceptance of life's difficulties, leading to greater ease, compassion, and freedom in daily life. By letting go of ego and attachment, individuals can develop a more nuanced perspective on right and wrong, recognizing that true wisdom lies in compassion rather than absolute certainty.", "themes": ["Compassion", "Ethics", "No-self"], "texts": [], "minutes": 43}, {"id": "2001 - Zoketsu Norman Fischer - Precepts 1", "title": "Precepts 1", "speaker": "Zoketsu Norman Fischer", "date": "2001", "series": "Precepts (2001 seminar)", "summary": "The talk's main teaching emphasizes that the 16 Bodhisattva precepts are not just rules to follow, but rather a way of life that cultivates compassion, kindness, and wisdom. By embracing these precepts with diligence and seriousness, we can develop a sense of righteousness that motivates us to act with compassion and wisdom in our daily lives. Ultimately, the precepts guide us towards living in the present moment, letting go of attachments and ego, and connecting with something greater than ourselves through every action we take.", "themes": ["Compassion", "Ethics"], "texts": [], "minutes": 41}, {"id": "2001 - Zoketsu Norman Fischer - Precepts 3", "title": "Precepts 3", "speaker": "Zoketsu Norman Fischer", "date": "2001", "series": "Precepts (2001 seminar)", "summary": "The talk emphasizes the importance of a reciprocal relationship between teacher and student in Zen practice, where both parties learn from each other and grow together. A good teacher helps the student become self-reliant while also nurturing and maturing them, ultimately guiding them towards wisdom, compassion, and simplicity. By embracing this reciprocal relationship, students can cultivate a deeper understanding of themselves and the world around them, leading to a more authentic and meaningful practice of Zen.", "themes": ["Ethics", "Sangha"], "texts": [], "minutes": 40}];
